import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { useEffect } from 'react';

import { useSettings } from '../../context/SettingsContext';
import { getPaperPageSize } from '../../utils/pageSizes';

const PX_PER_INCH = 96;
// Tolerance (in px) so a tiny rounding offset from a page top still counts as
// being "on" that page top rather than triggering an extra partial jump.
const PAGE_SNAP_EPSILON = 1;

function findScrollContainer(rootElement: HTMLElement): HTMLElement | null {
  let current: HTMLElement | null = rootElement.parentElement;

  while (current !== null) {
    if (current.classList.contains('editor-container')) {
      return current;
    }

    current = current.parentElement;
  }

  return null;
}

function getZoomFactor(rootElement: HTMLElement): number {
  const zoomValue = getComputedStyle(rootElement)
    .getPropertyValue('--playground-editor-content-zoom')
    .trim();
  const parsed = Number.parseFloat(zoomValue);

  return Number.isFinite(parsed) && parsed > 0 ? parsed : 1;
}

export default function PaperPageNavigationPlugin(): null {
  const [editor] = useLexicalComposerContext();
  const {
    settings: { pageSize },
  } = useSettings();

  useEffect(() => {
    const paperPageSize = getPaperPageSize(pageSize);

    if (paperPageSize === null) {
      return;
    }

    let rootElement = editor.getRootElement();

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'PageDown' && event.key !== 'PageUp') {
        return;
      }

      if (
        event.altKey ||
        event.ctrlKey ||
        event.metaKey ||
        event.shiftKey ||
        event.defaultPrevented
      ) {
        return;
      }

      if (rootElement === null) {
        return;
      }

      const scrollContainer = findScrollContainer(rootElement);

      if (scrollContainer === null) {
        return;
      }

      const zoom = getZoomFactor(rootElement);
      const pageHeight = paperPageSize.heightIn * PX_PER_INCH * zoom;

      if (pageHeight <= 0) {
        return;
      }

      const rootRect = rootElement.getBoundingClientRect();
      const containerRect = scrollContainer.getBoundingClientRect();
      const scrollTop = scrollContainer.scrollTop;
      // Scroll position that aligns the top of the first page to the top of
      // the scroll viewport.
      const pageOrigin = rootRect.top - containerRect.top + scrollTop;
      const distanceIntoPages = scrollTop - pageOrigin;

      const targetPageIndex =
        event.key === 'PageDown'
          ? Math.floor((distanceIntoPages + PAGE_SNAP_EPSILON) / pageHeight) + 1
          : Math.ceil((distanceIntoPages - PAGE_SNAP_EPSILON) / pageHeight) - 1;

      const maxScroll = Math.max(
        0,
        scrollContainer.scrollHeight - scrollContainer.clientHeight,
      );
      const targetScrollTop = Math.max(
        0,
        Math.min(pageOrigin + targetPageIndex * pageHeight, maxScroll),
      );

      event.preventDefault();
      scrollContainer.scrollTo({ behavior: 'smooth', top: targetScrollTop });
    };

    // registerRootListener fires immediately with the current root element,
    // so the initial keydown listener is attached here too.
    const unregisterRootListener = editor.registerRootListener(
      (nextRootElement, prevRootElement) => {
        prevRootElement?.removeEventListener('keydown', handleKeyDown);
        nextRootElement?.addEventListener('keydown', handleKeyDown);
        rootElement = nextRootElement;
      },
    );

    return () => {
      unregisterRootListener();
      rootElement?.removeEventListener('keydown', handleKeyDown);
    };
  }, [editor, pageSize]);

  return null;
}
