console.warn(
  'If you are profiling the playground app, please ensure you turn off the ' +
    'debug view. You can disable it by pressing on the settings control in ' +
    'the bottom-left of your screen and toggling the debug view setting.',
);

type PlaygroundAppProps = {
  detectTextLanguage?: (text: string) => string;
  editorController?: BibleNoteEditorControllerOwner;
  editorExtraFontFamilies?: ReadonlyArray<ExtraFontFamilyOption>;
  excalidrawClearLibrariesFileList?: () => void;
  excalidrawLibraryItems?: LibraryItems;
  excalidrawLoadLibrariesFileList?: () => string[];
  excalidrawSaveLibrariesFile?: (librariesFile: string) => void;
  footerActionButtonController?: BibleNoteFooterActionButtonControllerOwner;
  isMinimize: boolean;
  isOnApp: boolean;
  print?: () => void;
  resolveFilePath?: FilePathResolver;
  revealFile?: FileRevealer;
  settings?: ReactNode;
  settingsContainerElement?: Element | DocumentFragment;
  settingsController?: BibleNoteSettingsControllerOwner;
  stickyNoteExtraFontFamilies?: ReadonlyArray<string>;
  storageManager?: BibleNoteStorageManager;
  shortToVerseData?: (
    shortText: string,
  ) => Promise<{ title: string; fullText: string } | null>;
  verseFullTextToListShorts?: (fullText: string) => Promise<string[] | null>;
  changeBibleKey?: (
    event: React.MouseEvent<HTMLButtonElement>,
    verseFullText: string,
  ) => Promise<{ title: string; fullText: string } | null>;
};

type BibleNoteSettingsController = {
  setColorScheme: (mode: BibleNoteColorScheme) => void;
};

export type BibleNoteSettingsControllerOwner = {
  connectSettingsController: (
    controller: BibleNoteSettingsController,
    currentColorScheme: BibleNoteColorScheme,
  ) => () => void;
  syncColorSchemeFromSettings: (mode: BibleNoteColorScheme) => void;
};

type BibleNoteEditorController = {
  addText: (text: string) => void;
  getContent: () => string;
  getIsFocusing: () => boolean;
  getIsReadOnly: () => boolean;
  searchText: (query: string | null) => void;
  setContent: (value: string) => void;
  setReadOnly: (value: boolean) => void;
};

export type BibleNoteEditorControllerOwner = {
  connectEditorController: (
    controller: BibleNoteEditorController,
  ) => () => void;
};

type InitialEditorState =
  typeof $initializePlaygroundRichText | null | string | undefined;

type PasswordProtectedInitialEditorState =
  | { status: 'idle' | 'loading'; value: null }
  | { status: 'loaded'; value: InitialEditorState };

function getFallbackInitialEditorState(
  emptyEditor: boolean,
): InitialEditorState {
  const storedEditorState = getStoredEditorState();

  if (storedEditorState !== null) {
    return storedEditorState;
  }

  return emptyEditor ? undefined : $initializePlaygroundRichText;
}

export function BibleNoteApp({
  detectTextLanguage,
  editorController,
  editorExtraFontFamilies = [],
  excalidrawClearLibrariesFileList,
  excalidrawLibraryItems = [],
  excalidrawLoadLibrariesFileList,
  excalidrawSaveLibrariesFile,
  footerActionButtonController,
  isMinimize = false,
  isOnApp,
  print,
  resolveFilePath,
  revealFile,
  settings,
  settingsContainerElement,
  settingsController,
  stickyNoteExtraFontFamilies = [],
  shortToVerseData,
  verseFullTextToListShorts,
  changeBibleKey,
}: PlaygroundAppProps): JSX.Element {
  const {
    settings: { isDarkMode, emptyEditor, measureTypingPerf, pageSize },
  } = useSettings();
  const [
    passwordProtectedInitialEditorState,
    setPasswordProtectedInitialEditorState,
  ] = useState<PasswordProtectedInitialEditorState>(() =>
    hasPasswordProtectedSharedEditorStateParam()
      ? { status: 'loading', value: null }
      : { status: 'idle', value: null },
  );
  const [footerActionButtons, setFooterActionButtons] =
    useState<BibleNoteFooterActionButtons>(
      EMPTY_BIBLE_NOTE_FOOTER_ACTION_BUTTONS,
    );
  const [forceReadOnly, setForceReadOnly] = useState(false);

  useEffect(() => {
    if (editorController === undefined) {
      setForceReadOnly(false);
    }
  }, [editorController]);

  useEffect(() => {
    if (!hasPasswordProtectedSharedEditorStateParam()) {
      return;
    }

    let isActive = true;

    setPasswordProtectedInitialEditorState({ status: 'loading', value: null });

    void getStoredEditorStateAsync().then((storedEditorState) => {
      if (!isActive) {
        return;
      }

      setPasswordProtectedInitialEditorState({
        status: 'loaded',
        value:
          storedEditorState ??
          (emptyEditor ? undefined : $initializePlaygroundRichText),
      });
    });

    return () => {
      isActive = false;
    };
  }, [emptyEditor]);

  const synchronousInitialEditorState = useMemo(
    () => getFallbackInitialEditorState(emptyEditor),
    [emptyEditor],
  );
  const initialEditorState =
    passwordProtectedInitialEditorState.status === 'loaded'
      ? passwordProtectedInitialEditorState.value
      : synchronousInitialEditorState;

  const app = useMemo(
    () =>
      defineExtension({
        $initialEditorState: initialEditorState,
        html: buildHTMLConfig(),
        name: '@lexical/playground',
        namespace: 'Playground',
        nodes: PlaygroundNodes,
        theme: PlaygroundEditorTheme,
      }),
    [initialEditorState],
  );
  const settingsElement =
    settings !== undefined && settingsContainerElement !== undefined
      ? createPortal(settings, settingsContainerElement)
      : settings;

  useEffect(() => {
    applyBibleNoteColorScheme(isDarkMode ? 'dark' : 'light');

    return () => {
      clearBibleNoteColorScheme();
    };
  }, [isDarkMode]);

  useEffect(() => {
    const { body } = document;
    const paperPageSize = getPaperPageSize(pageSize);

    if (paperPageSize === null) {
      delete body.dataset.playgroundPageSize;
      body.style.removeProperty('--playground-paper-width');
      body.style.removeProperty('--playground-paper-height');
      return;
    }

    body.dataset.playgroundPageSize = 'paper';
    body.style.setProperty(
      '--playground-paper-width',
      `${paperPageSize.widthIn}in`,
    );
    body.style.setProperty(
      '--playground-paper-height',
      `${paperPageSize.heightIn}in`,
    );

    return () => {
      delete body.dataset.playgroundPageSize;
      body.style.removeProperty('--playground-paper-width');
      body.style.removeProperty('--playground-paper-height');
    };
  }, [pageSize]);

  if (passwordProtectedInitialEditorState.status === 'loading') {
    return (
      <div className="d-flex h-100 w-100 align-items-center justify-content-center text-body-secondary">
        Opening password-protected shared link...
      </div>
    );
  }

  return (
    <>
      <BibleNoteSettingsControllerBridge
        currentColorScheme={isDarkMode ? 'dark' : 'light'}
        settingsController={settingsController}
      />
      <BibleNoteFooterActionButtonControllerBridge
        footerActionButtonController={footerActionButtonController}
        setFooterActionButtons={setFooterActionButtons}
      />
      <ExcalidrawConfigProvider
        clearLibrariesFileList={excalidrawClearLibrariesFileList}
        detectTextLanguage={detectTextLanguage}
        extraFontFamilies={editorExtraFontFamilies}
        loadLibrariesFileList={excalidrawLoadLibrariesFileList}
        libraryItems={excalidrawLibraryItems}
        saveLibrariesFile={excalidrawSaveLibrariesFile}
      >
        <StickyNotesContext extraFontFamilies={stickyNoteExtraFontFamilies}>
          <MediaFileActionsProvider revealFile={revealFile}>
            <BibleVerseActionsProvider
              shortToVerseData={shortToVerseData}
              verseFullTextToListShorts={verseFullTextToListShorts}
              changeBibleKey={changeBibleKey}
            >
              <LexicalExtensionComposer extension={app} contentEditable={null}>
                {editorController !== undefined ? (
                  <BibleNoteEditorControllerBridge
                    editorController={editorController}
                    setForceReadOnly={setForceReadOnly}
                  />
                ) : null}
                <SharedHistoryContext>
                  <TableContext>
                    <ToolbarContext>
                      <Editor
                        detectTextLanguage={detectTextLanguage}
                        excalidrawClearLibrariesFileList={
                          excalidrawClearLibrariesFileList
                        }
                        excalidrawLibraryItems={excalidrawLibraryItems}
                        excalidrawLoadLibrariesFileList={
                          excalidrawLoadLibrariesFileList
                        }
                        excalidrawSaveLibrariesFile={
                          excalidrawSaveLibrariesFile
                        }
                        extraFontFamilies={editorExtraFontFamilies}
                        forceReadOnly={forceReadOnly}
                        footerActionButtons={footerActionButtons}
                        isMinimize={isMinimize}
                        isOnApp={isOnApp}
                        print={print}
                        resolveFilePath={resolveFilePath}
                      />
                      {settingsElement}
                      {isDevPlayground ? <DocsPlugin /> : null}
                      {isDevPlayground ? <PasteLogPlugin /> : null}
                      {isDevPlayground ? <TestRecorderPlugin /> : null}

                      {measureTypingPerf ? <TypingPerfPlugin /> : null}
                    </ToolbarContext>
                  </TableContext>
                </SharedHistoryContext>
              </LexicalExtensionComposer>
            </BibleVerseActionsProvider>
          </MediaFileActionsProvider>
        </StickyNotesContext>
      </ExcalidrawConfigProvider>
    </>
  );
}

function BibleNoteSettingsControllerBridge({
  currentColorScheme,
  settingsController,
}: {
  currentColorScheme: BibleNoteColorScheme;
  settingsController?: BibleNoteSettingsControllerOwner;
}): null {
  const { setOption } = useSettings();

  useEffect(() => {
    if (settingsController === undefined) {
      return;
    }

    return settingsController.connectSettingsController(
      {
        setColorScheme: (mode) => {
          setOption('isDarkMode', mode === 'dark');
        },
      },
      currentColorScheme,
    );
  }, [currentColorScheme, setOption, settingsController]);

  useEffect(() => {
    settingsController?.syncColorSchemeFromSettings(currentColorScheme);
  }, [currentColorScheme, settingsController]);

  return null;
}

function BibleNoteFooterActionButtonControllerBridge({
  footerActionButtonController,
  setFooterActionButtons,
}: {
  footerActionButtonController?: BibleNoteFooterActionButtonControllerOwner;
  setFooterActionButtons: (actionButtons: BibleNoteFooterActionButtons) => void;
}): null {
  useEffect(() => {
    if (footerActionButtonController === undefined) {
      setFooterActionButtons(EMPTY_BIBLE_NOTE_FOOTER_ACTION_BUTTONS);
      return;
    }

    return footerActionButtonController.connectFooterActionButtonController({
      setFooterActionButtons,
    });
  }, [footerActionButtonController, setFooterActionButtons]);

  return null;
}

function BibleNoteEditorControllerBridge({
  editorController,
  setForceReadOnly,
}: {
  editorController: BibleNoteEditorControllerOwner;
  setForceReadOnly: Dispatch<SetStateAction<boolean>>;
}): null {
  const [editor] = useLexicalComposerContext();
  const forceReadOnlyRef = useRef(false);

  useEffect(() => {
    const unregisterEditableListener = editor.registerEditableListener(
      (editable) => {
        if (forceReadOnlyRef.current && editable) {
          queueMicrotask(() => {
            if (forceReadOnlyRef.current && editor.isEditable()) {
              editor.setEditable(false);
            }
          });
        }
      },
    );
    const disconnectEditorController = editorController.connectEditorController(
      {
        addText: (text) => {
          if (forceReadOnlyRef.current || !editor.isEditable()) {
            return;
          }

          editor.update(() => {
            if ($getSelection() === null) {
              $getRoot().selectEnd();
            }
          });

          editor.dispatchCommand(
            PASTE_COMMAND,
            createPlainTextPasteEvent(text),
          );
        },
        getContent: () =>
          JSON.stringify(editor.getEditorState().toJSON()) ?? '',
        getIsFocusing: () => {
          const rootElement = editor.getRootElement();

          if (rootElement === null) {
            return false;
          }

          const selection = rootElement.ownerDocument.getSelection();
          const anchorNode = selection?.anchorNode ?? null;
          const focusNode = selection?.focusNode ?? null;

          return (
            rootElement.ownerDocument.hasFocus() &&
            rootElement.ownerDocument.activeElement === rootElement &&
            selection !== null &&
            selection.isCollapsed &&
            anchorNode !== null &&
            focusNode !== null &&
            rootElement.contains(anchorNode) &&
            rootElement.contains(focusNode)
          );
        },
        getIsReadOnly: () => forceReadOnlyRef.current || !editor.isEditable(),
        searchText: (query) => {
          editor.dispatchCommand(SET_FIND_QUERY_COMMAND, query);
        },
        setContent: (value) => {
          if (value.length === 0) {
            editor.update(() => {
              $getRoot().clear();
            });
            return;
          }

          editor.setEditorState(editor.parseEditorState(value));
        },
        setReadOnly: (value) => {
          forceReadOnlyRef.current = value;
          setForceReadOnly(value);
          editor.setEditable(!value);
        },
      },
    );

    return () => {
      disconnectEditorController();
      unregisterEditableListener();
    };
  }, [editor, editorController, setForceReadOnly]);

  return null;
}

function createPlainTextPasteEvent(text: string): ClipboardEvent {
  const event = {
    clipboardData: createPlainTextDataTransfer(text),
    preventDefault() {},
    target: null,
    type: 'paste',
  } as ClipboardEvent;

  if (typeof ClipboardEvent === 'function') {
    Object.setPrototypeOf(event, ClipboardEvent.prototype);
  }

  return event;
}

function createPlainTextDataTransfer(text: string): DataTransfer {
  if (typeof DataTransfer === 'function') {
    const dataTransfer = new DataTransfer();

    dataTransfer.setData('text/plain', text);

    return dataTransfer;
  }

  return {
    files: [],
    getData: (format) => (format === 'text/plain' ? text : ''),
    types: ['text/plain'],
  } as unknown as DataTransfer;
}

export function AppComp({
  detectTextLanguage,
  editorController,
  editorExtraFontFamilies = [],
  excalidrawClearLibrariesFileList,
  excalidrawLibraryItems = [],
  excalidrawLoadLibrariesFileList,
  excalidrawSaveLibrariesFile,
  footerActionButtonController,
  print,
  resolveFilePath,
  revealFile,
  settings,
  settingsContainerElement,
  settingsController,
  stickyNoteExtraFontFamilies = [],
  storageManager,
  isMinimize,
  isOnApp,
  shortToVerseData,
  verseFullTextToListShorts,
  changeBibleKey,
}: PlaygroundAppProps): JSX.Element {
  return (
    <BibleNoteStorageManagerGate storageManager={storageManager}>
      <SettingsContext>
        <FlashMessageContext>
          <BibleNoteApp
            detectTextLanguage={detectTextLanguage}
            editorController={editorController}
            editorExtraFontFamilies={editorExtraFontFamilies}
            excalidrawClearLibrariesFileList={excalidrawClearLibrariesFileList}
            excalidrawLibraryItems={excalidrawLibraryItems}
            excalidrawLoadLibrariesFileList={excalidrawLoadLibrariesFileList}
            excalidrawSaveLibrariesFile={excalidrawSaveLibrariesFile}
            footerActionButtonController={footerActionButtonController}
            isMinimize={isMinimize}
            print={print}
            resolveFilePath={resolveFilePath}
            revealFile={revealFile}
            settings={settings}
            settingsContainerElement={settingsContainerElement}
            settingsController={settingsController}
            stickyNoteExtraFontFamilies={stickyNoteExtraFontFamilies}
            isOnApp={isOnApp}
            shortToVerseData={shortToVerseData}
            verseFullTextToListShorts={verseFullTextToListShorts}
            changeBibleKey={changeBibleKey}
          />
        </FlashMessageContext>
      </SettingsContext>
    </BibleNoteStorageManagerGate>
  );
}

function BibleNoteStorageManagerGate({
  children,
  storageManager,
}: {
  children: ReactNode;
  storageManager?: BibleNoteStorageManager;
}): JSX.Element {
  const [isStorageReady, setIsStorageReady] = useState(() => {
    configureBibleNoteStorageManager(storageManager);

    return storageManager === undefined;
  });

  useEffect(() => {
    let isActive = true;

    configureBibleNoteStorageManager(storageManager);

    if (storageManager === undefined) {
      setIsStorageReady(true);
      return;
    }

    setIsStorageReady(false);

    void hydrateBibleNoteStorageManager(BIBLE_NOTE_STORAGE_MANAGER_KEYS).then(
      () => {
        if (isActive) {
          setIsStorageReady(true);
        }
      },
    );

    return () => {
      isActive = false;
    };
  }, [storageManager]);

  if (!isStorageReady) {
    return (
      <div className="d-flex h-100 w-100 align-items-center justify-content-center text-body-secondary">
        Loading saved Bible note...
      </div>
    );
  }

  return <>{children}</>;
}
