import type { LibraryItems } from '@excalidraw/excalidraw/types';
import type { JSX, ReactNode } from 'react';

import { createContext, useContext, useMemo } from 'react';

import type { ExtraFontFamilyOption } from '../utils/fontFamilyOptions';

type ExcalidrawConfig = {
  clearLibrariesFileList?: () => void;
  detectTextLanguage?: (text: string) => string;
  extraFontFamilies: ReadonlyArray<ExtraFontFamilyOption>;
  loadLibrariesFileList?: () => string[];
  libraryItems: LibraryItems;
  saveLibrariesFile?: (librariesFile: string) => void;
};

const EMPTY_EXTRA_FONT_FAMILIES: ReadonlyArray<ExtraFontFamilyOption> = [];
const EMPTY_LIBRARY_ITEMS: LibraryItems = [];

const ExcalidrawConfigContext = createContext<ExcalidrawConfig>({
  extraFontFamilies: EMPTY_EXTRA_FONT_FAMILIES,
  libraryItems: EMPTY_LIBRARY_ITEMS,
});

export function ExcalidrawConfigProvider({
  children,
  clearLibrariesFileList,
  detectTextLanguage,
  extraFontFamilies = EMPTY_EXTRA_FONT_FAMILIES,
  loadLibrariesFileList,
  libraryItems = EMPTY_LIBRARY_ITEMS,
  saveLibrariesFile,
}: {
  children: ReactNode;
  clearLibrariesFileList?: () => void;
  detectTextLanguage?: (text: string) => string;
  extraFontFamilies?: ReadonlyArray<ExtraFontFamilyOption>;
  loadLibrariesFileList?: () => string[];
  libraryItems?: LibraryItems;
  saveLibrariesFile?: (librariesFile: string) => void;
}): JSX.Element {
  const value = useMemo(
    () => ({
      clearLibrariesFileList,
      detectTextLanguage,
      extraFontFamilies,
      libraryItems,
      loadLibrariesFileList,
      saveLibrariesFile,
    }),
    [
      clearLibrariesFileList,
      detectTextLanguage,
      extraFontFamilies,
      libraryItems,
      loadLibrariesFileList,
      saveLibrariesFile,
    ],
  );

  return (
    <ExcalidrawConfigContext.Provider value={value}>
      {children}
    </ExcalidrawConfigContext.Provider>
  );
}

export function useExcalidrawConfig(): ExcalidrawConfig {
  return useContext(ExcalidrawConfigContext);
}
