import type { SettingName, Settings } from '../appSettings';
import type { JSX } from 'react';

import * as React from 'react';
import {
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
} from 'react';

import {
  DEFAULT_SETTINGS,
  getInitialSettingsFromEnvironment,
  hasSettingOverrides,
  SETTING_NAMES,
  writeStoredSettings,
} from '../appSettings';

type SettingsContextShape = {
  resetOptions: () => void;
  setOption: <Setting extends SettingName>(
    name: Setting,
    value: Settings[Setting],
  ) => void;
  settings: Settings;
};

const Context: React.Context<SettingsContextShape> = createContext({
  resetOptions: () => {
    return;
  },
  setOption: <Setting extends SettingName>(
    _name: Setting,
    _value: Settings[Setting],
  ) => {
    return;
  },
  settings: getInitialSettingsFromEnvironment(),
});

export const SettingsContext = ({
  children,
}: {
  children: ReactNode;
}): JSX.Element => {
  const [settings, setSettings] = useState(() =>
    getInitialSettingsFromEnvironment(),
  );
  const settingsRef = useRef(settings);

  settingsRef.current = settings;

  const commitSettings = useCallback((nextSettings: Settings) => {
    settingsRef.current = nextSettings;
    setSettings(nextSettings);
    writeStoredSettings(nextSettings);
    syncURLParams(nextSettings);
  }, []);

  const setOption = useCallback(
    <Setting extends SettingName>(
      setting: Setting,
      value: Settings[Setting],
    ) => {
      const currentSettings = settingsRef.current;

      if (currentSettings[setting] === value) {
        return;
      }

      commitSettings({
        ...currentSettings,
        [setting]: value,
      });
    },
    [commitSettings],
  );

  const resetOptions = useCallback(() => {
    const currentSettings = settingsRef.current;

    if (!hasSettingOverrides(currentSettings)) {
      return;
    }

    commitSettings({ ...DEFAULT_SETTINGS });
  }, [commitSettings]);

  const contextValue = useMemo(() => {
    return { resetOptions, setOption, settings };
  }, [resetOptions, setOption, settings]);

  return <Context.Provider value={contextValue}>{children}</Context.Provider>;
};

export const useSettings = (): SettingsContextShape => {
  return useContext(Context);
};

function syncURLParams(settings: Settings) {
  const url = new URL(window.location.href);
  const params = new URLSearchParams(url.search);

  for (const setting of SETTING_NAMES) {
    if (settings[setting] !== DEFAULT_SETTINGS[setting]) {
      params.set(setting, String(settings[setting]));
    } else {
      params.delete(setting);
    }
  }

  url.search = params.toString();
  window.history.pushState(null, '', url.toString());
}
