import type { JSX, ReactNode } from 'react';

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react';

export const STICKY_NOTES_HIDDEN_CLASS = 'playground-sticky-notes-hidden';

type StickyNotesContextShape = {
  extraFontFamilies: ReadonlyArray<string>;
  showStickyNotes: boolean;
  toggleStickyNotesVisibility: () => void;
};

const Context = createContext<StickyNotesContextShape>({
  extraFontFamilies: [],
  showStickyNotes: true,
  toggleStickyNotesVisibility: () => {
    return;
  },
});

export const StickyNotesContext = ({
  children,
  extraFontFamilies = [],
}: {
  children: ReactNode;
  extraFontFamilies?: ReadonlyArray<string>;
}): JSX.Element => {
  const [showStickyNotes, setShowStickyNotes] = useState(true);

  const toggleStickyNotesVisibility = useCallback(() => {
    setShowStickyNotes((currentShowStickyNotes) => !currentShowStickyNotes);
  }, []);

  useEffect(() => {
    document.body.classList.toggle(STICKY_NOTES_HIDDEN_CLASS, !showStickyNotes);

    return () => {
      document.body.classList.remove(STICKY_NOTES_HIDDEN_CLASS);
    };
  }, [showStickyNotes]);

  const contextValue = useMemo(() => {
    return { extraFontFamilies, showStickyNotes, toggleStickyNotesVisibility };
  }, [extraFontFamilies, showStickyNotes, toggleStickyNotesVisibility]);
  return <Context.Provider value={contextValue}>{children}</Context.Provider>;
};

export const useStickyNotesVisibility = (): StickyNotesContextShape => {
  return useContext(Context);
};

export const useStickyNoteFontFamilies = (): ReadonlyArray<string> => {
  const context = useContext(Context);
  return context.extraFontFamilies;
};
