import './Collapsible.scss';

import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import {
  $findMatchingParent,
  $insertNodeToNearestRoot,
  mergeRegister,
} from '@lexical/utils';
import {
  $addUpdateTag,
  $createParagraphNode,
  $createTextNode,
  $getNodeByKey,
  $getSelection,
  $insertNodes,
  $isRangeSelection,
  $isTextNode,
  COMMAND_PRIORITY_LOW,
  createCommand,
  HISTORY_PUSH_TAG,
  INSERT_PARAGRAPH_COMMAND,
  KEY_ARROW_DOWN_COMMAND,
  KEY_ARROW_LEFT_COMMAND,
  KEY_ARROW_RIGHT_COMMAND,
  KEY_ARROW_UP_COMMAND,
  PASTE_COMMAND,
} from 'lexical';
import { useEffect, useMemo } from 'react';

import { $createMentionNode, type MentionNode } from '../../nodes/MentionNode';
import {
  DEFAULT_FONT_LANGUAGE,
  type ExtraFontFamilyOption,
  type FontFamilyOption,
  getFontFamilyForLanguage,
  getFontFamilyOptions,
} from '../../utils/fontFamilyOptions';
import {
  type BibleTextParts,
  getBibleTextBodyLines,
  getBibleTextPartsFromPlainText,
  getBibleTextPlainText,
} from '../../utils/bibleTextPaste';

import {
  $createCollapsibleContainerNode,
  $isCollapsibleContainerNode,
  CollapsibleContainerNode,
} from './CollapsibleContainerNode';
import {
  $createCollapsibleContentNode,
  $isCollapsibleContentNode,
  CollapsibleContentNode,
} from './CollapsibleContentNode';
import {
  $createCollapsibleTitleNode,
  $isCollapsibleTitleNode,
  CollapsibleTitleNode,
} from './CollapsibleTitleNode';

export const INSERT_COLLAPSIBLE_COMMAND = createCommand<void>(
  'INSERT_COLLAPSIBLE_COMMAND',
);

const EMPTY_FONT_FAMILIES: ReadonlyArray<ExtraFontFamilyOption> = [];
const DEFAULT_DETECT_TEXT_LANGUAGE = () => DEFAULT_FONT_LANGUAGE;

function getBibleTextCollapsibleParts(
  event: ClipboardEvent | InputEvent | KeyboardEvent,
): BibleTextParts | null {
  if (event.type !== 'paste' || !('clipboardData' in event)) {
    return null;
  }

  const text = event.clipboardData?.getData('text/plain');

  if (!text) {
    return null;
  }

  return getBibleTextPartsFromPlainText(text);
}

function getBibleTextFontFamilyStyle(
  bibleText: BibleTextParts,
  detectTextLanguage: (text: string) => string,
  fontFamilyOptions: ReadonlyArray<FontFamilyOption>,
): string {
  const language = detectTextLanguage(getBibleTextPlainText(bibleText));

  if (language === DEFAULT_FONT_LANGUAGE) {
    return '';
  }

  const fontFamily = getFontFamilyForLanguage(fontFamilyOptions, language);

  return fontFamily === null ? '' : `font-family: ${fontFamily};`;
}

function $createStyledTextNode(text: string, style: string) {
  const textNode = $createTextNode(text);

  if (style !== '') {
    textNode.setStyle(style);
  }

  return textNode;
}

function $createBibleTextParagraph(text: string, style: string) {
  return $createParagraphNode().append($createStyledTextNode(text, style));
}

function $createBibleTextCollapsible(
  bibleText: BibleTextParts,
  fontFamilyStyle: string,
) {
  const title = $createCollapsibleTitleNode();
  const content = $createCollapsibleContentNode();

  return $createCollapsibleContainerNode(true).append(
    title.append($createBibleTextParagraph(bibleText.header, fontFamilyStyle)),
    content.append(
      ...getBibleTextBodyLines(bibleText).map((bodyLine) =>
        $createBibleTextParagraph(bodyLine, fontFamilyStyle),
      ),
    ),
  );
}

function getBibleVerseMentionText(bibleText: BibleTextParts): string {
  return bibleText.title || bibleText.header;
}

function $createBibleVerseMention(
  bibleText: BibleTextParts,
  fontFamilyStyle: string,
): MentionNode {
  const mentionNode = $createMentionNode(
    bibleText.header,
    getBibleVerseMentionText(bibleText),
    null,
    'bible-verse',
    bibleText.body,
  );

  if (fontFamilyStyle !== '') {
    mentionNode.setStyle(fontFamilyStyle);
  }

  return mentionNode;
}

function $insertBibleVerseMentionAfterTrigger(
  bibleText: BibleTextParts,
  fontFamilyStyle: string,
): boolean {
  const selection = $getSelection();

  if (
    selection === null ||
    !$isRangeSelection(selection) ||
    !selection.isCollapsed()
  ) {
    return false;
  }

  const anchorNode = selection.anchor.getNode();
  const triggerOffset = selection.anchor.offset - 1;

  if (!$isTextNode(anchorNode) || triggerOffset < 0) {
    return false;
  }

  if (anchorNode.getTextContent().charAt(triggerOffset) !== '^') {
    return false;
  }

  anchorNode.spliceText(triggerOffset, 1, '', true);
  $insertNodes([
    $createBibleVerseMention(bibleText, fontFamilyStyle),
    $createTextNode(' '),
  ]);
  return true;
}

export default function CollapsiblePlugin({
  detectTextLanguage = DEFAULT_DETECT_TEXT_LANGUAGE,
  extraFontFamilies = EMPTY_FONT_FAMILIES,
}: {
  detectTextLanguage?: (text: string) => string;
  extraFontFamilies?: ReadonlyArray<ExtraFontFamilyOption>;
}): null {
  const [editor] = useLexicalComposerContext();
  const fontFamilyOptions = useMemo(
    () => getFontFamilyOptions(extraFontFamilies),
    [extraFontFamilies],
  );

  useEffect(() => {
    if (
      !editor.hasNodes([
        CollapsibleContainerNode,
        CollapsibleTitleNode,
        CollapsibleContentNode,
      ])
    ) {
      throw new Error(
        'CollapsiblePlugin: CollapsibleContainerNode, CollapsibleTitleNode, or CollapsibleContentNode not registered on editor',
      );
    }

    const $onEscapeUp = () => {
      const selection = $getSelection();
      if (
        $isRangeSelection(selection) &&
        selection.isCollapsed() &&
        selection.anchor.offset === 0
      ) {
        const container = $findMatchingParent(
          selection.anchor.getNode(),
          $isCollapsibleContainerNode,
        );

        if ($isCollapsibleContainerNode(container)) {
          const parent = container.getParent();
          if (
            parent !== null &&
            parent.getFirstChild() === container &&
            selection.anchor.key === container.getFirstDescendant()?.getKey()
          ) {
            container.insertBefore($createParagraphNode());
          }
        }
      }

      return false;
    };

    const $onEscapeDown = () => {
      const selection = $getSelection();
      if ($isRangeSelection(selection) && selection.isCollapsed()) {
        const container = $findMatchingParent(
          selection.anchor.getNode(),
          $isCollapsibleContainerNode,
        );

        if ($isCollapsibleContainerNode(container)) {
          const parent = container.getParent();
          if (parent !== null && parent.getLastChild() === container) {
            const titleParagraph = container.getFirstDescendant();
            const contentParagraph = container.getLastDescendant();

            if (
              (contentParagraph !== null &&
                selection.anchor.key === contentParagraph.getKey() &&
                selection.anchor.offset ===
                  contentParagraph.getTextContentSize()) ||
              (titleParagraph !== null &&
                selection.anchor.key === titleParagraph.getKey() &&
                selection.anchor.offset === titleParagraph.getTextContentSize())
            ) {
              container.insertAfter($createParagraphNode());
            }
          }
        }
      }

      return false;
    };

    return mergeRegister(
      // Structure enforcing transformers for each node type. In case nesting structure is not
      // "Container > Title + Content" it'll unwrap nodes and convert it back
      // to regular content.
      editor.registerNodeTransform(CollapsibleContentNode, (node) => {
        const parent = node.getParent();
        if (!$isCollapsibleContainerNode(parent)) {
          const children = node.getChildren();
          for (const child of children) {
            node.insertBefore(child);
          }
          node.remove();
        }
      }),

      editor.registerNodeTransform(CollapsibleTitleNode, (node) => {
        const parent = node.getParent();
        if (!$isCollapsibleContainerNode(parent)) {
          node.replace($createParagraphNode().append(...node.getChildren()));
          return;
        }
      }),

      editor.registerNodeTransform(CollapsibleContainerNode, (node) => {
        const children = node.getChildren();
        if (
          children.length !== 2 ||
          !$isCollapsibleTitleNode(children[0]) ||
          !$isCollapsibleContentNode(children[1])
        ) {
          for (const child of children) {
            node.insertBefore(child);
          }
          node.remove();
        }
      }),

      // When collapsible is the last child pressing down/right arrow will insert paragraph
      // below it to allow adding more content. It's similar what $insertBlockNode
      // (mainly for decorators), except it'll always be possible to continue adding
      // new content even if trailing paragraph is accidentally deleted
      editor.registerCommand(
        KEY_ARROW_DOWN_COMMAND,
        $onEscapeDown,
        COMMAND_PRIORITY_LOW,
      ),

      editor.registerCommand(
        KEY_ARROW_RIGHT_COMMAND,
        $onEscapeDown,
        COMMAND_PRIORITY_LOW,
      ),

      // When collapsible is the first child pressing up/left arrow will insert paragraph
      // above it to allow adding more content. It's similar what $insertBlockNode
      // (mainly for decorators), except it'll always be possible to continue adding
      // new content even if leading paragraph is accidentally deleted
      editor.registerCommand(
        KEY_ARROW_UP_COMMAND,
        $onEscapeUp,
        COMMAND_PRIORITY_LOW,
      ),

      editor.registerCommand(
        KEY_ARROW_LEFT_COMMAND,
        $onEscapeUp,
        COMMAND_PRIORITY_LOW,
      ),

      // Enter goes from Title to Content rather than a new line inside Title
      editor.registerCommand(
        INSERT_PARAGRAPH_COMMAND,
        () => {
          const selection = $getSelection();
          if ($isRangeSelection(selection)) {
            const titleNode = $findMatchingParent(
              selection.anchor.getNode(),
              (node) => $isCollapsibleTitleNode(node),
            );

            if ($isCollapsibleTitleNode(titleNode)) {
              const container = titleNode.getParent();
              if (container && $isCollapsibleContainerNode(container)) {
                if (!container.getOpen()) {
                  container.toggleOpen();
                }
                titleNode.getNextSibling()?.selectEnd();
                return true;
              }
            }
          }

          return false;
        },
        COMMAND_PRIORITY_LOW,
      ),
      editor.registerCommand(
        PASTE_COMMAND,
        (event) => {
          const bibleText = getBibleTextCollapsibleParts(event);

          if (bibleText === null) {
            return false;
          }

          event.preventDefault();
          $addUpdateTag(HISTORY_PUSH_TAG);

          const fontFamilyStyle = getBibleTextFontFamilyStyle(
            bibleText,
            detectTextLanguage,
            fontFamilyOptions,
          );

          if (
            $insertBibleVerseMentionAfterTrigger(bibleText, fontFamilyStyle)
          ) {
            return true;
          }

          const headerParagraph = $createBibleTextParagraph(
            bibleText.header,
            fontFamilyStyle,
          );
          const bodyParagraphs = getBibleTextBodyLines(bibleText).map(
            (bodyLine) => $createBibleTextParagraph(bodyLine, fontFamilyStyle),
          );
          const headerKey = headerParagraph.getKey();
          const bodyKeys = bodyParagraphs.map((bodyParagraph) =>
            bodyParagraph.getKey(),
          );

          $insertNodes([headerParagraph, ...bodyParagraphs]);

          setTimeout(() => {
            editor.update(
              () => {
                const latestHeaderParagraph = $getNodeByKey(headerKey);
                const latestBodyParagraphs = bodyKeys.map((bodyKey) =>
                  $getNodeByKey(bodyKey),
                );

                if (
                  latestHeaderParagraph === null ||
                  latestBodyParagraphs.some(
                    (bodyParagraph) => bodyParagraph === null,
                  )
                ) {
                  return;
                }

                const trailingParagraph = $createParagraphNode();
                const collapsible = $createBibleTextCollapsible(
                  bibleText,
                  fontFamilyStyle,
                );

                latestHeaderParagraph.insertBefore(collapsible);
                collapsible.insertAfter(trailingParagraph);
                latestHeaderParagraph.remove();
                for (const latestBodyParagraph of latestBodyParagraphs) {
                  latestBodyParagraph?.remove();
                }
                trailingParagraph.selectEnd();
              },
              { tag: HISTORY_PUSH_TAG },
            );
          });

          return true;
        },
        COMMAND_PRIORITY_LOW,
      ),

      editor.registerCommand(
        INSERT_COLLAPSIBLE_COMMAND,
        () => {
          editor.update(() => {
            const title = $createCollapsibleTitleNode();
            const paragraph = $createParagraphNode();
            $insertNodeToNearestRoot(
              $createCollapsibleContainerNode(true).append(
                title.append(paragraph),
                $createCollapsibleContentNode().append($createParagraphNode()),
              ),
            );
            paragraph.select();
          });
          return true;
        },
        COMMAND_PRIORITY_LOW,
      ),
    );
  }, [detectTextLanguage, editor, fontFamilyOptions]);

  return null;
}
