import type {
  DOMConversionMap,
  DOMConversionOutput,
  DOMExportOutput,
  EditorConfig,
  LexicalEditor,
  LexicalNode,
  LexicalUpdateJSON,
  NodeKey,
  RangeSelection,
  SerializedEditor,
  SerializedLexicalNode,
  Spread,
} from 'lexical';
import type { JSX } from 'react';

import { $insertGeneratedNodes } from '@lexical/clipboard';
import { $generateHtmlFromNodes, $generateNodesFromDOM } from '@lexical/html';
import { LinkNode } from '@lexical/link';
import {
  $applyNodeReplacement,
  $createRangeSelection,
  $extendCaretToRange,
  $getChildCaret,
  $getEditor,
  $getRoot,
  $isElementNode,
  $isParagraphNode,
  $selectAll,
  $setSelection,
  createEditor,
  DecoratorNode,
  LineBreakNode,
  ParagraphNode,
  RootNode,
  SKIP_DOM_SELECTION_TAG,
  TextNode,
} from 'lexical';
import * as React from 'react';

import { EmojiNode } from './EmojiNode';
import { KeywordNode } from './KeywordNode';
import { MentionNode } from './MentionNode';

const MediaComponent = React.lazy(() => import('./MediaComponent'));

export interface MediaPayload {
  altText: string;
  caption?: LexicalEditor;
  height?: number;
  key?: NodeKey;
  maxWidth?: number;
  mediaType?: MediaType;
  previewSrc?: string;
  showCaption?: boolean;
  src: string;
  width?: number;
  captionsEnabled?: boolean;
}

export type MediaType = 'image' | 'video' | 'pdf' | 'audio';

function isGoogleDocCheckboxImg(img: HTMLImageElement): boolean {
  return (
    img.parentElement != null &&
    img.parentElement.tagName === 'LI' &&
    img.previousSibling === null &&
    img.getAttribute('aria-roledescription') === 'checkbox'
  );
}

function $convertImageElement(domNode: Node): null | DOMConversionOutput {
  const img = domNode as HTMLImageElement;
  const src = img.getAttribute('src');
  if (!src || src.startsWith('file:///') || isGoogleDocCheckboxImg(img)) {
    return null;
  }
  const { alt: altText, width, height } = img;
  const node = $createMediaNode({ altText, height, src, width });
  return { node };
}

function $convertVideoElement(domNode: Node): null | DOMConversionOutput {
  const video = domNode as HTMLVideoElement;
  const src = video.getAttribute('src') || video.currentSrc;
  if (!src) {
    return null;
  }
  const node = $createMediaNode({
    altText: video.getAttribute('title') || '',
    height: video.height,
    mediaType: 'video',
    src,
    width: video.width,
  });
  return { node };
}

function $convertAudioElement(domNode: Node): null | DOMConversionOutput {
  const audio = domNode as HTMLAudioElement;
  const src = audio.getAttribute('src') || audio.currentSrc;
  if (!src) {
    return null;
  }
  const node = $createMediaNode({
    altText: audio.getAttribute('title') || '',
    height: Number(audio.getAttribute('height')) || undefined,
    mediaType: 'audio',
    src,
    width: Number(audio.getAttribute('width')) || undefined,
  });
  return { node };
}

function isPdfElement(domNode: HTMLElement): boolean {
  const src = domNode.getAttribute('src') || domNode.getAttribute('data') || '';
  const type = domNode.getAttribute('type') || '';
  const mediaType = domNode.getAttribute('data-lexical-media-type') || '';
  return (
    mediaType === 'pdf' ||
    type === 'application/pdf' ||
    src.toLowerCase().split(/[?#]/)[0].endsWith('.pdf')
  );
}

function $convertPdfElement(domNode: Node): null | DOMConversionOutput {
  const element = domNode as HTMLElement;
  const src = element.getAttribute('src') || element.getAttribute('data');
  if (!src || !isPdfElement(element)) {
    return null;
  }
  const node = $createMediaNode({
    altText: element.getAttribute('title') || '',
    height: Number(element.getAttribute('height')) || undefined,
    mediaType: 'pdf',
    src,
    width: Number(element.getAttribute('width')) || undefined,
  });
  return { node };
}

export function $isCaptionEditorEmpty(): boolean {
  // Search the document for any non-element node
  // to determine if it's empty or not
  for (const { origin } of $extendCaretToRange(
    $getChildCaret($getRoot(), 'next'),
  )) {
    if (!$isElementNode(origin)) {
      return false;
    }
  }
  return true;
}

export type SerializedMediaNode = Spread<
  {
    altText: string;
    caption: SerializedEditor;
    height?: number;
    maxWidth: number;
    mediaType?: MediaType;
    showCaption: boolean;
    src: string;
    width?: number;
  },
  SerializedLexicalNode
>;

export class MediaNode extends DecoratorNode<JSX.Element> {
  __src: string;
  __altText: string;
  __width: 'inherit' | number;
  __height: 'inherit' | number;
  __maxWidth: number;
  __mediaType: MediaType;
  __previewSrc?: string;
  __showCaption: boolean;
  __caption: LexicalEditor;
  // Captions cannot yet be used within editor cells
  __captionsEnabled: boolean;

  static getType(): string {
    return 'image';
  }

  static clone(node: MediaNode): MediaNode {
    return new MediaNode(
      node.__src,
      node.__altText,
      node.__maxWidth,
      node.__width,
      node.__height,
      node.__showCaption,
      node.__caption,
      node.__captionsEnabled,
      node.__key,
      node.__mediaType,
      node.__previewSrc,
    );
  }

  static importJSON(serializedNode: SerializedMediaNode): MediaNode {
    const { altText, height, mediaType, width, maxWidth, src, showCaption } =
      serializedNode;
    return $createMediaNode({
      altText,
      height,
      maxWidth,
      mediaType,
      showCaption,
      src,
      width,
    }).updateFromJSON(serializedNode);
  }

  updateFromJSON(serializedNode: LexicalUpdateJSON<SerializedMediaNode>): this {
    const node = super.updateFromJSON(serializedNode);
    const { caption } = serializedNode;

    const nestedEditor = node.__caption;
    const editorState = nestedEditor.parseEditorState(caption.editorState);
    if (!editorState.isEmpty()) {
      nestedEditor.setEditorState(editorState);
    }
    return node;
  }

  exportDOM(): DOMExportOutput {
    const mediaElement = this.createMediaDOMElement();

    if (this.__showCaption && this.__caption) {
      const captionEditor = this.__caption;
      const captionHtml = captionEditor.read(() => {
        if ($isCaptionEditorEmpty()) {
          return null;
        }
        // Don't serialize the wrapping paragraph if there is only one
        let selection: null | RangeSelection = null;
        const firstChild = $getRoot().getFirstChild();
        if (
          $isParagraphNode(firstChild) &&
          firstChild.getNextSibling() === null
        ) {
          selection = $createRangeSelection();
          selection.anchor.set(firstChild.getKey(), 0, 'element');
          selection.focus.set(
            firstChild.getKey(),
            firstChild.getChildrenSize(),
            'element',
          );
        }
        return $generateHtmlFromNodes(captionEditor, selection);
      });
      if (captionHtml) {
        const figureElement = document.createElement('figure');
        const figcaptionElement = document.createElement('figcaption');
        figcaptionElement.innerHTML = captionHtml;

        figureElement.appendChild(mediaElement);
        figureElement.appendChild(figcaptionElement);

        return { element: figureElement };
      }
    }

    return { element: mediaElement };
  }

  createMediaDOMElement(): HTMLElement {
    if (this.__mediaType === 'video') {
      const videoElement = document.createElement('video');
      videoElement.setAttribute('src', this.__src);
      videoElement.setAttribute('title', this.__altText);
      videoElement.setAttribute('width', this.__width.toString());
      videoElement.setAttribute('height', this.__height.toString());
      videoElement.setAttribute('controls', 'true');
      videoElement.setAttribute('data-lexical-media-type', 'video');
      return videoElement;
    }

    if (this.__mediaType === 'pdf') {
      const iframeElement = document.createElement('iframe');
      iframeElement.setAttribute('src', this.__src);
      iframeElement.setAttribute('title', this.__altText || 'PDF');
      iframeElement.setAttribute('width', this.__width.toString());
      iframeElement.setAttribute('height', this.__height.toString());
      iframeElement.setAttribute('data-lexical-media-type', 'pdf');
      return iframeElement;
    }

    if (this.__mediaType === 'audio') {
      const audioElement = document.createElement('audio');
      audioElement.setAttribute('src', this.__src);
      audioElement.setAttribute('title', this.__altText);
      audioElement.setAttribute('controls', 'true');
      audioElement.setAttribute('data-lexical-media-type', 'audio');
      if (this.__width !== 'inherit') {
        audioElement.setAttribute('width', this.__width.toString());
      }
      if (this.__height !== 'inherit') {
        audioElement.setAttribute('height', this.__height.toString());
      }
      return audioElement;
    }

    const imgElement = document.createElement('img');
    imgElement.setAttribute('src', this.__src);
    imgElement.setAttribute('alt', this.__altText);
    imgElement.setAttribute('width', this.__width.toString());
    imgElement.setAttribute('height', this.__height.toString());
    return imgElement;
  }

  static importDOM(): DOMConversionMap | null {
    return {
      audio: () => ({
        conversion: $convertAudioElement,
        priority: 0,
      }),
      embed: () => ({
        conversion: $convertPdfElement,
        priority: 0,
      }),
      figcaption: () => ({
        conversion: () => ({ node: null }),
        priority: 0,
      }),
      figure: () => ({
        conversion: (node) => {
          return {
            after: (childNodes) => {
              const mediaNodes = childNodes.filter($isMediaNode);
              const figcaption = node.querySelector('figcaption');
              if (figcaption) {
                for (const mediaNode of mediaNodes) {
                  mediaNode.setShowCaption(true);
                  mediaNode.__caption.update(
                    () => {
                      const editor = $getEditor();
                      $insertGeneratedNodes(
                        editor,
                        $generateNodesFromDOM(editor, figcaption),
                        $selectAll(),
                      );
                      $setSelection(null);
                    },
                    { tag: SKIP_DOM_SELECTION_TAG },
                  );
                }
              }
              return mediaNodes;
            },
            node: null,
          };
        },
        priority: 0,
      }),
      img: () => ({
        conversion: $convertImageElement,
        priority: 0,
      }),
      iframe: (domNode: HTMLElement) => {
        if (!isPdfElement(domNode)) {
          return null;
        }
        return {
          conversion: $convertPdfElement,
          priority: 0,
        };
      },
      object: () => ({
        conversion: $convertPdfElement,
        priority: 0,
      }),
      video: () => ({
        conversion: $convertVideoElement,
        priority: 0,
      }),
    };
  }

  constructor(
    src: string,
    altText: string,
    maxWidth: number,
    width?: 'inherit' | number,
    height?: 'inherit' | number,
    showCaption?: boolean,
    caption?: LexicalEditor,
    captionsEnabled?: boolean,
    key?: NodeKey,
    mediaType: MediaType = 'image',
    previewSrc?: string,
  ) {
    super(key);
    this.__src = src;
    this.__altText = altText;
    this.__maxWidth = maxWidth;
    this.__width = width || 'inherit';
    this.__height = height || 'inherit';
    this.__mediaType = mediaType;
    this.__previewSrc = previewSrc;
    this.__showCaption = showCaption || false;
    this.__caption =
      caption ||
      createEditor({
        namespace: 'Playground/MediaNodeCaption',
        nodes: [
          RootNode,
          TextNode,
          LineBreakNode,
          ParagraphNode,
          LinkNode,
          EmojiNode,
          KeywordNode,
          MentionNode,
        ],
      });
    this.__captionsEnabled = captionsEnabled || captionsEnabled === undefined;
  }

  exportJSON(): SerializedMediaNode {
    return {
      ...super.exportJSON(),
      altText: this.getAltText(),
      caption: this.__caption.toJSON(),
      height: this.__height === 'inherit' ? 0 : this.__height,
      maxWidth: this.__maxWidth,
      mediaType: this.__mediaType,
      showCaption: this.__showCaption,
      src: this.getSrc(),
      width: this.__width === 'inherit' ? 0 : this.__width,
    };
  }

  setWidthAndHeight(
    width: 'inherit' | number,
    height: 'inherit' | number,
  ): void {
    const writable = this.getWritable();
    writable.__width = width;
    writable.__height = height;
  }

  setShowCaption(showCaption: boolean): void {
    const writable = this.getWritable();
    writable.__showCaption = showCaption;
  }

  // View

  createDOM(config: EditorConfig): HTMLElement {
    const span = document.createElement('span');
    const theme = config.theme;
    const className = theme.image;
    if (className !== undefined) {
      span.className = className;
    }
    return span;
  }

  updateDOM(): false {
    return false;
  }

  getSrc(): string {
    return this.__src;
  }

  getAltText(): string {
    return this.__altText;
  }

  getMediaType(): MediaType {
    return this.__mediaType;
  }

  decorate(): JSX.Element {
    return (
      <MediaComponent
        src={this.__src}
        altText={this.__altText}
        mediaType={this.__mediaType}
        previewSrc={this.__previewSrc}
        width={this.__width}
        height={this.__height}
        maxWidth={this.__maxWidth}
        nodeKey={this.getKey()}
        showCaption={this.__showCaption}
        caption={this.__caption}
        captionsEnabled={this.__captionsEnabled}
        resizable={true}
      />
    );
  }
}

export function $createMediaNode({
  altText,
  height,
  maxWidth = 500,
  captionsEnabled,
  mediaType,
  previewSrc,
  src,
  width,
  showCaption,
  caption,
  key,
}: MediaPayload): MediaNode {
  return $applyNodeReplacement(
    new MediaNode(
      src,
      altText,
      maxWidth,
      width,
      height,
      showCaption,
      caption,
      captionsEnabled,
      key,
      mediaType,
      previewSrc,
    ),
  );
}

export function $isMediaNode(
  node: LexicalNode | null | undefined,
): node is MediaNode {
  return node instanceof MediaNode;
}
