import { dispatchOpenMentionPersonAdvancedPanelEvent } from '../MentionNamePlugin/openPersonAdvancedPanelEvent';
import locationsMapData from '../MentionLocationsPlugin/locationsMap.json';
import { dispatchOpenMentionLocationAdvancedPanelEvent } from '../MentionLocationsPlugin/openLocationAdvancedPanelEvent';
import {
  OPEN_MENTION_BIBLE_VERSE_ADVANCED_PANEL_EVENT,
  type OpenMentionBibleVerseAdvancedPanelDetail,
} from './openBibleVerseAdvancedPanelEvent';
