import type { CSSProperties, ReactNode } from 'react';

import { createContext, useContext, useMemo } from 'react';

type ShortToVerseData = (
  shortText: string,
) => Promise<{ title: string; fullText: string; style?: CSSProperties } | null>;

type ChangeBibleKey = (
  event: React.MouseEvent<HTMLButtonElement>,
  verseFullText: string,
) => Promise<{ title: string; fullText: string; style?: CSSProperties } | null>;

type BibleVerseActionsContextShape = Readonly<{
  shortToVerseData?: ShortToVerseData;
  verseFullTextToListShorts?: (fullText: string) => Promise<string[] | null>;
  changeBibleKey?: ChangeBibleKey;
}>;

const Context = createContext<BibleVerseActionsContextShape>({});

export function BibleVerseActionsProvider({
  children,
  shortToVerseData,
  verseFullTextToListShorts,
  changeBibleKey,
}: {
  children: ReactNode;
  shortToVerseData?: ShortToVerseData;
  verseFullTextToListShorts?: (fullText: string) => Promise<string[] | null>;
  changeBibleKey?: ChangeBibleKey;
}) {
  const contextValue = useMemo<BibleVerseActionsContextShape>(
    () => ({ shortToVerseData, verseFullTextToListShorts, changeBibleKey }),
    [shortToVerseData, verseFullTextToListShorts, changeBibleKey],
  );

  return <Context.Provider value={contextValue}>{children}</Context.Provider>;
}

export function useBibleVerseActions(): BibleVerseActionsContextShape {
  return useContext(Context);
}
