import { getBibleNoteStorage } from './storageManager';

export const BLOCK_TEXT_LINKS_LOCAL_STORAGE_KEY =
  'lexical-playground-block-text-links';

export type StoredBlockTextLinkKind =
  | 'direction-to'
  | 'direction-from'
  | 'no-direction'
  | 'weak-direction-to'
  | 'weak-direction-from'
  | 'weak-no-direction';

export type StoredBlockTextPoint = {
  offset: number;
  path: number[];
};

export type StoredBlockTextRange = {
  anchor: StoredBlockTextPoint;
  blockPaths: number[][];
  focus: StoredBlockTextPoint;
};

export type StoredBlockTextLink = {
  from: StoredBlockTextRange;
  id: string;
  kind: StoredBlockTextLinkKind;
  to: StoredBlockTextRange;
};

export function getStoredBlockTextLinks(): StoredBlockTextLink[] {
  const storage = getBlockTextLinkStorage();

  if (storage === null) {
    return [];
  }

  const serializedLinks = storage.getItem(BLOCK_TEXT_LINKS_LOCAL_STORAGE_KEY);

  if (serializedLinks === null) {
    return [];
  }

  try {
    const parsedLinks: unknown = JSON.parse(serializedLinks);

    if (!Array.isArray(parsedLinks)) {
      storage.removeItem(BLOCK_TEXT_LINKS_LOCAL_STORAGE_KEY);
      return [];
    }

    const links = parsedLinks.filter(isStoredBlockTextLink);

    if (links.length !== parsedLinks.length) {
      if (links.length === 0) {
        storage.removeItem(BLOCK_TEXT_LINKS_LOCAL_STORAGE_KEY);
      } else {
        storage.setItem(
          BLOCK_TEXT_LINKS_LOCAL_STORAGE_KEY,
          JSON.stringify(links),
        );
      }
    }

    return links;
  } catch {
    storage.removeItem(BLOCK_TEXT_LINKS_LOCAL_STORAGE_KEY);
    return [];
  }
}

export function writeStoredBlockTextLinks(links: StoredBlockTextLink[]): void {
  const storage = getBlockTextLinkStorage();

  if (storage === null) {
    return;
  }

  if (links.length === 0) {
    storage.removeItem(BLOCK_TEXT_LINKS_LOCAL_STORAGE_KEY);
    return;
  }

  storage.setItem(BLOCK_TEXT_LINKS_LOCAL_STORAGE_KEY, JSON.stringify(links));
}

export function clearStoredBlockTextLinks(): void {
  const storage = getBlockTextLinkStorage();

  if (storage === null) {
    return;
  }

  storage.removeItem(BLOCK_TEXT_LINKS_LOCAL_STORAGE_KEY);
}

function getBlockTextLinkStorage(): Storage | null {
  return getBibleNoteStorage() as Storage | null;
}

function isStoredBlockTextLink(value: unknown): value is StoredBlockTextLink {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }

  const link = value as Record<string, unknown>;

  return (
    typeof link.id === 'string' &&
    isStoredBlockTextLinkKind(link.kind) &&
    isStoredBlockTextRange(link.from) &&
    isStoredBlockTextRange(link.to)
  );
}

function isStoredBlockTextLinkKind(
  value: unknown,
): value is StoredBlockTextLinkKind {
  return (
    value === 'direction-to' ||
    value === 'direction-from' ||
    value === 'no-direction' ||
    value === 'weak-direction-to' ||
    value === 'weak-direction-from' ||
    value === 'weak-no-direction'
  );
}

function isStoredBlockTextRange(value: unknown): value is StoredBlockTextRange {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }

  const range = value as Record<string, unknown>;

  return (
    isStoredBlockTextPoint(range.anchor) &&
    Array.isArray(range.blockPaths) &&
    range.blockPaths.every(isNodePath) &&
    isStoredBlockTextPoint(range.focus)
  );
}

function isStoredBlockTextPoint(value: unknown): value is StoredBlockTextPoint {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }

  const point = value as Record<string, unknown>;

  return Number.isInteger(point.offset) && isNodePath(point.path);
}

function isNodePath(value: unknown): value is number[] {
  return (
    Array.isArray(value) &&
    value.length > 0 &&
    value.every((index) => Number.isInteger(index) && index >= 0)
  );
}
