export type FontFamilyOption = readonly [
  fontFamily: string,
  label: string,
  language: string,
];

export type ExtraFontFamilyOption = readonly [
  fontFamily: string,
  language: string,
];

export const DEFAULT_FONT_LANGUAGE = 'en';

export const DEFAULT_FONT_FAMILY_OPTIONS: ReadonlyArray<FontFamilyOption> = [
  ['Arial', 'Arial', DEFAULT_FONT_LANGUAGE],
  ['Courier New', 'Courier New', DEFAULT_FONT_LANGUAGE],
  ['Georgia', 'Georgia', DEFAULT_FONT_LANGUAGE],
  ['Times New Roman', 'Times New Roman', DEFAULT_FONT_LANGUAGE],
  ['Trebuchet MS', 'Trebuchet MS', DEFAULT_FONT_LANGUAGE],
  ['Verdana', 'Verdana', DEFAULT_FONT_LANGUAGE],
];

export function getFontFamilyOptions(
  extraFontFamilies: ReadonlyArray<ExtraFontFamilyOption>,
): Array<FontFamilyOption> {
  const options: Array<FontFamilyOption> = [...DEFAULT_FONT_FAMILY_OPTIONS];
  const existingOptions = new Set(
    DEFAULT_FONT_FAMILY_OPTIONS.map(([fontFamily]) => fontFamily),
  );

  extraFontFamilies.forEach(([fontFamily, language]) => {
    if (!existingOptions.has(fontFamily)) {
      options.push([fontFamily, fontFamily, language]);
      existingOptions.add(fontFamily);
    }
  });

  return options.sort(([, firstLabel], [, secondLabel]) =>
    firstLabel.localeCompare(secondLabel),
  );
}

export function getFontFamilyForLanguage(
  fontFamilyOptions: ReadonlyArray<FontFamilyOption>,
  language: string,
): string | null {
  return (
    fontFamilyOptions.find(
      ([, , optionLanguage]) => optionLanguage === language,
    )?.[0] ?? null
  );
}
