import type {
  LexicalEditor,
  LexicalNode,
  TextFormatType,
  TextNode,
} from 'lexical';

import { $createCodeNode } from '@lexical/code';
import { $createLinkNode } from '@lexical/link';
import { $createListItemNode, $createListNode } from '@lexical/list';
import { $createMarkNode } from '@lexical/mark';
import { $createHorizontalRuleNode } from '@lexical/react/LexicalHorizontalRuleNode';
import { $createHeadingNode, $createQuoteNode } from '@lexical/rich-text';
import {
  $createTableCellNode,
  $createTableNode,
  $createTableRowNode,
  TableCellHeaderStates,
} from '@lexical/table';
import {
  $createLineBreakNode,
  $createParagraphNode,
  $createTextNode,
  $getRoot,
  CLEAR_HISTORY_COMMAND,
} from 'lexical';

import { writeStoredBlockTextLinks } from './blockTextLinkStorage';
import { writeStoredComments } from './commentStorage';
import { $createCollapsibleContainerNode } from './plugins/CollapsiblePlugin/CollapsibleContainerNode';
import { $createCollapsibleContentNode } from './plugins/CollapsiblePlugin/CollapsibleContentNode';
import { $createCollapsibleTitleNode } from './plugins/CollapsiblePlugin/CollapsibleTitleNode';
import { $createDateTimeNode } from './nodes/DateTimeNode/DateTimeNode';
import { $createEquationNode } from './nodes/EquationNode';
import { $createLayoutContainerNode } from './nodes/LayoutContainerNode';
import { $createLayoutItemNode } from './nodes/LayoutItemNode';
import { $createMentionNode } from './nodes/MentionNode';
import { $createStickyNode } from './nodes/StickyNode';
import { $createYouTubeNode } from './nodes/YouTubeNode';

const DEFAULT_DOCUMENT_HEADING = 'Khmer BibleNote Study: Genesis 1';
const GENESIS_REFERENCE = '(KJV) Genesis 1:1-3';
const GENESIS_1_1_3_KJV =
  '(1): In the beginning God created the heaven and the earth. (2): And the earth was without form, and void; and darkness was upon the face of the deep. And the Spirit of God moved upon the face of the waters. (3): And God said, Let there be light: and there was light.';
const MOSES_ID = 'fff825ad-31e8-4843-a7dc-cd82e9878d73';
const JERUSALEM_ID = '00000000-0000-4000-8000-000000000117';
const DEFAULT_COMMENT_THREAD_ID = 'default-genesis-light-thread';
const DEFAULT_COMMENT_ID = 'default-genesis-light-comment';
const DEFAULT_COMMENT_TIMESTAMP = new Date(2026, 4, 9, 9).getTime();
const BLOCK_TEXT_LINK_ID = 'default-genesis-block-text-link';
const BLOCK_TEXT_LINK_SOURCE =
  'Block link source: God speaks light into the first day.';
const BLOCK_TEXT_LINK_TARGET =
  'Block link target: Application notes trace that light into prayer.';
const YOUTUBE_VIDEO_ID = 'afVN-7vY0KA';

function $formatText(
  textContent: string,
  formats: ReadonlyArray<TextFormatType>,
): TextNode {
  const textNode = $createTextNode(textContent);

  formats.forEach((format) => {
    textNode.toggleFormat(format);
  });

  return textNode;
}

function $paragraph(...nodes: LexicalNode[]) {
  return $createParagraphNode().append(...nodes);
}

function $heading(tag: 'h1' | 'h2' | 'h3', textContent: string) {
  return $createHeadingNode(tag).append($createTextNode(textContent));
}

function $listItem(...nodes: LexicalNode[]) {
  return $createListItemNode().append(...nodes);
}

function $checkListItem(checked: boolean, ...nodes: LexicalNode[]) {
  return $createListItemNode(checked).append(...nodes);
}

function $tableCell(
  textContent: string,
  headerState: number = TableCellHeaderStates.NO_STATUS,
) {
  return $createTableCellNode(headerState).append(
    $paragraph($createTextNode(textContent)),
  );
}

function $bibleVerseMention() {
  return $createMentionNode(
    GENESIS_REFERENCE,
    GENESIS_REFERENCE,
    'kjv-genesis-1-1-3',
    'bible-verse',
    GENESIS_1_1_3_KJV,
  );
}

function $commentedText(textContent: string): LexicalNode {
  return $createMarkNode([DEFAULT_COMMENT_THREAD_ID]).append(
    $createTextNode(textContent),
  );
}

function seedPlaygroundRichTextCompanionData(): void {
  writeStoredComments([
    {
      comments: [
        {
          author: 'BibleNote',
          content:
            'Connect this phrase to Genesis 1:3, creation light, and the Khmer application note.',
          deleted: false,
          id: DEFAULT_COMMENT_ID,
          timeStamp: DEFAULT_COMMENT_TIMESTAMP,
          type: 'comment',
        },
      ],
      id: DEFAULT_COMMENT_THREAD_ID,
      quote: 'Let there be light',
      quoteSegments: [{ text: 'Let there be light' }],
      type: 'thread',
    },
  ]);

  writeStoredBlockTextLinks([
    {
      from: {
        anchor: { offset: 0, path: [9, 0] },
        blockPaths: [[9]],
        focus: { offset: BLOCK_TEXT_LINK_SOURCE.length, path: [9, 0] },
      },
      id: BLOCK_TEXT_LINK_ID,
      kind: 'direction-to',
      to: {
        anchor: { offset: 0, path: [10, 0] },
        blockPaths: [[10]],
        focus: { offset: BLOCK_TEXT_LINK_TARGET.length, path: [10, 0] },
      },
    },
  ]);
}

export function $createPlaygroundRichTextNodes(): LexicalNode[] {
  const scriptureQuote = $createQuoteNode().append(
    $bibleVerseMention(),
    $createLineBreakNode(),
    $createTextNode(GENESIS_1_1_3_KJV),
  );

  const scriptureCollapsible = $createCollapsibleContainerNode(true).append(
    $createCollapsibleTitleNode().append($paragraph($bibleVerseMention())),
    $createCollapsibleContentNode().append(
      $paragraph($createTextNode(GENESIS_1_1_3_KJV)),
    ),
  );

  const observationList = $createListNode('bullet').append(
    $listItem(
      $formatText('Created', ['bold']),
      $createTextNode(
        ' names God as the first actor and sets the whole note under worship.',
      ),
    ),
    $listItem(
      $formatText('Without form, and void', ['italic']),
      $createTextNode(' marks the need for order before beauty appears.'),
    ),
    $listItem(
      $formatText('Let there be light', ['underline']),
      $createTextNode(
        ' becomes the first quoted command to trace through the study.',
      ),
    ),
  );

  const studyFlowList = $createListNode('number').append(
    $listItem($createTextNode('Read the passage aloud in KJV and Khmer.')),
    $listItem(
      $createTextNode(
        'Tag people, places, and Bible references while outlining.',
      ),
    ),
    $listItem(
      $createTextNode('Turn observations into application and prayer.'),
    ),
  );

  const checklist = $createListNode('check').append(
    $checkListItem(true, $createTextNode('KJV quotation added')),
    $checkListItem(false, $createTextNode('Khmer translation note added')),
    $checkListItem(false, $createTextNode('Map, image, or drawing attached')),
    $checkListItem(false, $createTextNode('Final outline ready for sharing')),
  );

  const table = $createTableNode().append(
    $createTableRowNode().append(
      $tableCell('Layer', TableCellHeaderStates.COLUMN),
      $tableCell('Current note', TableCellHeaderStates.COLUMN),
      $tableCell('Next action', TableCellHeaderStates.COLUMN),
    ),
    $createTableRowNode().append(
      $tableCell('Scripture'),
      $tableCell('Genesis 1:1-3, KJV'),
      $tableCell('Compare Khmer wording'),
    ),
    $createTableRowNode().append(
      $tableCell('Person'),
      $tableCell('Moses'),
      $tableCell('Add author note'),
    ),
    $createTableRowNode().append(
      $tableCell('Place'),
      $tableCell('Jerusalem'),
      $tableCell('Trace worship echoes'),
    ),
  );

  const codeBlock = $createCodeNode('markdown').append(
    $createTextNode(
      [
        '# Genesis 1 Study',
        '^Genesis 1:1-3',
        '@Moses #Jerusalem',
        '- creation, light, word, worship',
      ].join('\n'),
    ),
  );

  const layout = $createLayoutContainerNode('1fr 1fr').append(
    $createLayoutItemNode().append(
      $heading('h3', 'Observation'),
      $paragraph(
        $createTextNode(
          'God creates before anything else is named, and the first command brings light.',
        ),
      ),
    ),
    $createLayoutItemNode().append(
      $heading('h3', 'Application'),
      $paragraph(
        $createTextNode(
          'Begin the study by naming what is dark, empty, and waiting for the word of God.',
        ),
      ),
    ),
  );

  const collapsible = $createCollapsibleContainerNode(true).append(
    $createCollapsibleTitleNode().append(
      $paragraph($createTextNode('Sermon seed')),
    ),
    $createCollapsibleContentNode().append(
      $paragraph(
        $createTextNode(
          'Creation begins with God, moves by the Spirit, and answers to the spoken word.',
        ),
      ),
    ),
  );

  return [
    $heading('h1', DEFAULT_DOCUMENT_HEADING),
    scriptureQuote,
    scriptureCollapsible,
    $heading('h2', 'Observation Notes'),
    $paragraph(
      $formatText('Theme: ', ['bold']),
      $createTextNode('God '),
      $formatText('creates', ['bold']),
      $createTextNode(', orders, and speaks light into darkness. Keep '),
      $formatText('uncertain wording', ['highlight']),
      $createTextNode(' visible, mark '),
      $formatText('discarded angles', ['strikethrough']),
      $createTextNode(', and preserve short tags like '),
      $formatText('creation-light', ['code']),
      $createTextNode('.'),
    ),
    $paragraph(
      $createTextNode('Cross-reference '),
      $createMentionNode('Moses', '@Moses', MOSES_ID, 'mention'),
      $createTextNode(', '),
      $createMentionNode('Jerusalem', 'Jerusalem', JERUSALEM_ID, 'location'),
      $createTextNode(', and '),
      $bibleVerseMention(),
      $createTextNode(' before adding the Khmer translation note.'),
    ),
    $paragraph(
      $createTextNode('Prepared on '),
      $createDateTimeNode(new Date(2026, 4, 9)),
      $createTextNode(' with this structure marker: '),
      $createEquationNode(
        '\\text{day}_1 = \\text{light} + \\text{separation}',
        true,
      ),
      $createTextNode('.'),
    ),
    $paragraph(
      $createTextNode('Source note: compare the '),
      $createLinkNode(
        'https://www.kingjamesbibleonline.org/Genesis-Chapter-1/',
      ).append($createTextNode('KJV text for Genesis 1')),
      $createTextNode(' while drafting local Khmer notes.'),
    ),
    $paragraph(
      $createTextNode('Comment anchor: '),
      $commentedText('Let there be light'),
      $createTextNode(' is the phrase to revisit while applying the passage.'),
    ),
    $paragraph($createTextNode(BLOCK_TEXT_LINK_SOURCE)),
    $paragraph($createTextNode(BLOCK_TEXT_LINK_TARGET)),
    observationList,
    $heading('h2', 'Study Flow'),
    studyFlowList,
    checklist,
    $heading('h2', 'Study Tracker'),
    table,
    $heading('h2', 'Reference Scratchpad'),
    codeBlock,
    $heading('h2', 'Media Notes'),
    $paragraph(
      $createTextNode('Video reference: '),
      $createLinkNode('https://youtu.be/afVN-7vY0KA').append(
        $createTextNode('https://youtu.be/afVN-7vY0KA'),
      ),
    ),
    $createYouTubeNode(YOUTUBE_VIDEO_ID),
    $createStickyNode(48, 144),
    layout,
    collapsible,
    $createHorizontalRuleNode(),
    $paragraph(
      $createTextNode(
        'Prayer: Lord, speak light into every empty place and make this note faithful, clear, and useful.',
      ),
    ),
  ];
}

export function $prepopulatePlaygroundRichText(): void {
  const root = $getRoot();

  root.append(...$createPlaygroundRichTextNodes());
  seedPlaygroundRichTextCompanionData();
}

export function $initializePlaygroundRichText(): void {
  const root = $getRoot();

  if (root.getFirstChild() === null) {
    $prepopulatePlaygroundRichText();
  }
}

export function resetPlaygroundEditorContent(
  editor: LexicalEditor,
  options?: {
    emptyEditor?: boolean;
  },
): void {
  editor.update(() => {
    const root = $getRoot();

    root.clear();

    if (!options?.emptyEditor) {
      $prepopulatePlaygroundRichText();
    }
  });
  editor.dispatchCommand(CLEAR_HISTORY_COMMAND, undefined);
}
