import type { JSX } from 'react';

import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { useLexicalEditable } from '@lexical/react/useLexicalEditable';
import { createDOMRange, createRectsFromDOMRange } from '@lexical/selection';
import { mergeRegister } from '@lexical/utils';
import {
  $getNodeByKey,
  $getRoot,
  $getSelection,
  $isElementNode,
  $isRangeSelection,
  $isTextNode,
  CAN_REDO_COMMAND,
  CAN_UNDO_COMMAND,
  CLEAR_EDITOR_COMMAND,
  COMMAND_PRIORITY_CRITICAL,
  COMMAND_PRIORITY_EDITOR,
  createCommand,
  KEY_ESCAPE_COMMAND,
  REDO_COMMAND,
  type LexicalCommand,
  type LexicalEditor,
  type LexicalNode,
  type NodeKey,
  SELECTION_CHANGE_COMMAND,
  UNDO_COMMAND,
} from 'lexical';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';

import {
  getStoredBlockTextLinks,
  type StoredBlockTextLink,
  type StoredBlockTextPoint,
  type StoredBlockTextRange,
  writeStoredBlockTextLinks,
} from '../../blockTextLinkStorage';
import { getClientRectZoomScale } from '../../utils/zoomCompensation';

type BlockTextLinkKind =
  | 'direction-to'
  | 'direction-from'
  | 'no-direction'
  | 'weak-direction-to'
  | 'weak-direction-from'
  | 'weak-no-direction';

type BlockTextPoint = {
  key: NodeKey;
  offset: number;
  path?: number[];
};

type BlockTextRange = {
  anchor?: BlockTextPoint;
  blockKeys: NodeKey[];
  blockPaths?: number[][];
  focus?: BlockTextPoint;
};

type BlockTextLink = {
  from: BlockTextRange;
  id: string;
  kind: BlockTextLinkKind;
  to: BlockTextRange;
};

type LinkGeometry = {
  fromRect: DOMRect;
  fromRects: DOMRect[];
  link: BlockTextLink;
  midpoint: { x: number; y: number };
  toRect: DOMRect;
  toRects: DOMRect[];
};

type BlockTextLinkSnapshot = BlockTextLink[];

type PointerPosition = {
  x: number;
  y: number;
};

export const START_BLOCK_TEXT_LINK_COMMAND: LexicalCommand<void> =
  createCommand('START_BLOCK_TEXT_LINK_COMMAND');

const LINK_KIND_OPTIONS: ReadonlyArray<{
  kind: BlockTextLinkKind;
  label: string;
}> = [
  { kind: 'no-direction', label: 'No direction' },
  { kind: 'direction-to', label: 'Direction to second' },
  { kind: 'direction-from', label: 'Direction from second' },
  { kind: 'weak-no-direction', label: 'Weak no direction' },
  { kind: 'weak-direction-to', label: 'Weak direction to second' },
  { kind: 'weak-direction-from', label: 'Weak direction from second' },
];

function areRangesEqual(
  first: BlockTextRange,
  second: BlockTextRange,
): boolean {
  return (
    first.anchor?.key === second.anchor?.key &&
    first.anchor?.offset === second.anchor?.offset &&
    first.focus?.key === second.focus?.key &&
    first.focus?.offset === second.focus?.offset &&
    first.blockKeys.length === second.blockKeys.length &&
    first.blockKeys.every((key, index) => key === second.blockKeys[index])
  );
}

function areLinksEqual(
  firstLinks: BlockTextLink[],
  secondLinks: BlockTextLink[],
): boolean {
  return (
    firstLinks.length === secondLinks.length &&
    firstLinks.every((firstLink, index) => {
      const secondLink = secondLinks[index];
      return (
        secondLink !== undefined &&
        firstLink.id === secondLink.id &&
        firstLink.kind === secondLink.kind &&
        areRangesEqual(firstLink.from, secondLink.from) &&
        areRangesEqual(firstLink.to, secondLink.to)
      );
    })
  );
}

function buildId(): string {
  return `block-text-link-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

function getNodePath(node: LexicalNode): number[] | null {
  const path: number[] = [];
  let currentNode: LexicalNode = node;
  let parent = currentNode.getParent();

  while (parent !== null) {
    const siblings = parent.getChildren();
    const index = siblings.findIndex(
      (sibling) => sibling.getKey() === currentNode.getKey(),
    );

    if (index === -1) {
      return null;
    }

    path.unshift(index);
    currentNode = parent;
    parent = currentNode.getParent();
  }

  return path.length === 0 ? null : path;
}

function getPointPath(point: { getNode: () => LexicalNode }): number[] | null {
  return getNodePath(point.getNode());
}

function resolveNodePath(path: number[]): LexicalNode | null {
  let node: LexicalNode = $getRoot();

  for (const index of path) {
    if (!$isElementNode(node)) {
      return null;
    }

    const child = node.getChildAtIndex(index);
    if (child === null) {
      return null;
    }

    node = child;
  }

  return node;
}

function getClampedPointOffset(node: LexicalNode, offset: number): number {
  if ($isTextNode(node)) {
    return Math.max(0, Math.min(offset, node.getTextContentSize()));
  }

  if ($isElementNode(node)) {
    return Math.max(0, Math.min(offset, node.getChildrenSize()));
  }

  return offset;
}

function toStoredPoint(
  point: BlockTextPoint | undefined,
): StoredBlockTextPoint | null {
  if (point?.path === undefined) {
    return null;
  }

  return {
    offset: point.offset,
    path: point.path,
  };
}

function toStoredRange(range: BlockTextRange): StoredBlockTextRange | null {
  const anchor = toStoredPoint(range.anchor);
  const focus = toStoredPoint(range.focus);

  if (
    anchor === null ||
    focus === null ||
    range.blockPaths === undefined ||
    range.blockPaths.length === 0
  ) {
    return null;
  }

  return {
    anchor,
    blockPaths: range.blockPaths,
    focus,
  };
}

function toStoredLinks(links: BlockTextLink[]): StoredBlockTextLink[] {
  return links.flatMap((link): StoredBlockTextLink[] => {
    const from = toStoredRange(link.from);
    const to = toStoredRange(link.to);

    if (from === null || to === null) {
      return [];
    }

    return [
      {
        from,
        id: link.id,
        kind: link.kind,
        to,
      },
    ];
  });
}

function fromStoredPoint(point: StoredBlockTextPoint): BlockTextPoint | null {
  const node = resolveNodePath(point.path);

  if (node === null) {
    return null;
  }

  return {
    key: node.getKey(),
    offset: getClampedPointOffset(node, point.offset),
    path: point.path,
  };
}

function fromStoredRange(range: StoredBlockTextRange): BlockTextRange | null {
  const anchor = fromStoredPoint(range.anchor);
  const focus = fromStoredPoint(range.focus);
  const blockKeys = range.blockPaths.flatMap((path): NodeKey[] => {
    const node = resolveNodePath(path);
    return node === null ? [] : [node.getKey()];
  });

  if (anchor === null || focus === null || blockKeys.length === 0) {
    return null;
  }

  return {
    anchor,
    blockKeys,
    blockPaths: range.blockPaths,
    focus,
  };
}

function fromStoredLinks(links: StoredBlockTextLink[]): BlockTextLink[] {
  return links.flatMap((link): BlockTextLink[] => {
    const from = fromStoredRange(link.from);
    const to = fromStoredRange(link.to);

    if (from === null || to === null) {
      return [];
    }

    return [
      {
        from,
        id: link.id,
        kind: link.kind,
        to,
      },
    ];
  });
}

export function $getSelectedBlockTextRange(): BlockTextRange | null {
  const selection = $getSelection();

  if (
    !$isRangeSelection(selection) ||
    typeof selection.isCollapsed !== 'function' ||
    selection.isCollapsed() ||
    selection.anchor === undefined ||
    selection.focus === undefined
  ) {
    return null;
  }

  const blockKeys: NodeKey[] = [];
  const blockPaths: number[][] = [];
  const seenKeys = new Set<NodeKey>();
  const anchorPath = getPointPath(selection.anchor);
  const focusPath = getPointPath(selection.focus);

  if (anchorPath === null || focusPath === null) {
    return null;
  }

  for (const selectedNode of selection.getNodes()) {
    const topLevelElement = $isElementNode(selectedNode)
      ? selectedNode.getTopLevelElementOrThrow()
      : selectedNode.getTopLevelElement();

    if (topLevelElement === null) {
      continue;
    }

    const key = topLevelElement.getKey();
    if (!seenKeys.has(key)) {
      const path = getNodePath(topLevelElement);
      if (path === null) {
        continue;
      }

      seenKeys.add(key);
      blockKeys.push(key);
      blockPaths.push(path);
    }
  }

  return blockKeys.length === 0
    ? null
    : {
        anchor: {
          key: selection.anchor.key,
          offset: selection.anchor.offset,
          path: anchorPath,
        },
        blockKeys,
        blockPaths,
        focus: {
          key: selection.focus.key,
          offset: selection.focus.offset,
          path: focusPath,
        },
      };
}

function getCollapsedFallbackTitleElement(
  element: HTMLElement,
): HTMLElement | null {
  const contentElement = getCollapsedContentElement(element);
  if (!(contentElement instanceof HTMLElement)) {
    return null;
  }

  const contentRect = contentElement.getBoundingClientRect();
  const isHidden =
    contentElement.hidden ||
    contentRect.width === 0 ||
    contentRect.height === 0 ||
    window.getComputedStyle(contentElement).display === 'none';

  if (!isHidden) {
    return null;
  }

  const container = contentElement.closest('.Collapsible__container');
  if (!(container instanceof HTMLElement)) {
    return null;
  }

  const title = container.querySelector('.Collapsible__title');
  return title instanceof HTMLElement ? title : container;
}

function getCollapsedContentElement(element: HTMLElement): HTMLElement | null {
  if (element.classList.contains('Collapsible__content')) {
    return element;
  }

  const closestContent = element.closest('.Collapsible__content');
  if (closestContent instanceof HTMLElement) {
    return closestContent;
  }

  const container = element.classList.contains('Collapsible__container')
    ? element
    : element.closest('.Collapsible__container');

  if (!(container instanceof HTMLElement)) {
    return null;
  }

  const content = container.querySelector('.Collapsible__content');
  return content instanceof HTMLElement ? content : null;
}

function unionRects(rects: DOMRect[]): DOMRect | null {
  if (rects.length === 0) {
    return null;
  }

  let top = rects[0].top;
  let right = rects[0].right;
  let bottom = rects[0].bottom;
  let left = rects[0].left;

  for (const rect of rects.slice(1)) {
    top = Math.min(top, rect.top);
    right = Math.max(right, rect.right);
    bottom = Math.max(bottom, rect.bottom);
    left = Math.min(left, rect.left);
  }

  return new DOMRect(left, top, right - left, bottom - top);
}

function getElementTextRect(element: HTMLElement): DOMRect | null {
  const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT);
  const rects: DOMRect[] = [];
  let textNode = walker.nextNode();

  while (textNode !== null) {
    if (textNode.textContent?.trim()) {
      const range = document.createRange();
      range.selectNodeContents(textNode);
      rects.push(
        ...Array.from(range.getClientRects()).map(
          (rect) => new DOMRect(rect.left, rect.top, rect.width, rect.height),
        ),
      );
      range.detach();
    }

    textNode = walker.nextNode();
  }

  return unionRects(rects.filter((rect) => rect.width > 0 && rect.height > 0));
}

function getCollapsedFallbackRect(element: HTMLElement): DOMRect | null {
  const fallbackElement = getCollapsedFallbackTitleElement(element);
  if (fallbackElement === null) {
    return null;
  }

  return (
    getElementTextRect(fallbackElement) ??
    fallbackElement.getBoundingClientRect()
  );
}

function getVisibleElementRect(element: HTMLElement): DOMRect {
  return getCollapsedFallbackRect(element) ?? element.getBoundingClientRect();
}

function getCollapsedRangeFallbackRects(
  editor: LexicalEditor,
  range: BlockTextRange,
): DOMRect[] {
  return range.blockKeys
    .map((key) => editor.getElementByKey(key))
    .filter((element): element is HTMLElement => element instanceof HTMLElement)
    .map(getCollapsedFallbackRect)
    .filter((rect): rect is DOMRect => rect !== null)
    .filter((rect) => rect.width > 0 && rect.height > 0);
}

function getBlockFallbackRects(
  editor: LexicalEditor,
  range: BlockTextRange,
): DOMRect[] {
  return range.blockKeys
    .map((key) => editor.getElementByKey(key))
    .filter((element): element is HTMLElement => element instanceof HTMLElement)
    .map(getVisibleElementRect)
    .filter((rect) => rect.width > 0 && rect.height > 0);
}

function getRangeRects(
  editor: LexicalEditor,
  range: BlockTextRange,
): DOMRect[] {
  if (range.anchor === undefined || range.focus === undefined) {
    return getBlockFallbackRects(editor, range);
  }

  const rects = editor.getEditorState().read(() => {
    const anchorNode = $getNodeByKey(range.anchor?.key);
    const focusNode = $getNodeByKey(range.focus?.key);

    if (anchorNode === null || focusNode === null) {
      return [];
    }

    const domRange = createDOMRange(
      editor,
      anchorNode,
      range.anchor?.offset ?? 0,
      focusNode,
      range.focus?.offset ?? 0,
    );

    if (domRange === null) {
      return [];
    }

    return createRectsFromDOMRange(editor, domRange).map(
      (rect) => new DOMRect(rect.left, rect.top, rect.width, rect.height),
    );
  });

  const visibleRects = rects.filter(
    (rect) => rect.width > 0 && rect.height > 0,
  );

  return visibleRects.length > 0
    ? visibleRects
    : getCollapsedRangeFallbackRects(editor, range);
}

function toAnchorRects(
  rects: DOMRect[],
  anchorRect: DOMRect,
  scale: number = 1,
): DOMRect[] {
  return rects.map((rect) => toAnchorRect(rect, anchorRect, scale));
}

function toAnchorRect(
  rect: DOMRect,
  anchorRect: DOMRect,
  scale: number = 1,
): DOMRect {
  return new DOMRect(
    (rect.left - anchorRect.left) / scale,
    (rect.top - anchorRect.top) / scale,
    rect.width / scale,
    rect.height / scale,
  );
}

function rectCenter(rect: DOMRect): { x: number; y: number } {
  return {
    x: rect.left + rect.width / 2,
    y: rect.top + rect.height / 2,
  };
}

function isPointInRect(point: PointerPosition, rect: DOMRect): boolean {
  return (
    point.x >= rect.left &&
    point.x <= rect.right &&
    point.y >= rect.top &&
    point.y <= rect.bottom
  );
}

function getHoveredRangeLinkId(
  geometries: LinkGeometry[],
  point: PointerPosition,
): string | null {
  const geometry = geometries.find((linkGeometry) =>
    [...linkGeometry.fromRects, ...linkGeometry.toRects].some((rect) =>
      isPointInRect(point, rect),
    ),
  );

  return geometry?.link.id ?? null;
}

function getDistanceToLineSegment(
  point: PointerPosition,
  linePoints: ReturnType<typeof getLinePoints>,
): number {
  const deltaX = linePoints.x2 - linePoints.x1;
  const deltaY = linePoints.y2 - linePoints.y1;
  const segmentLengthSquared = deltaX * deltaX + deltaY * deltaY;

  if (segmentLengthSquared === 0) {
    return Math.hypot(point.x - linePoints.x1, point.y - linePoints.y1);
  }

  const segmentPosition = Math.max(
    0,
    Math.min(
      1,
      ((point.x - linePoints.x1) * deltaX +
        (point.y - linePoints.y1) * deltaY) /
        segmentLengthSquared,
    ),
  );
  const closestX = linePoints.x1 + segmentPosition * deltaX;
  const closestY = linePoints.y1 + segmentPosition * deltaY;

  return Math.hypot(point.x - closestX, point.y - closestY);
}

function getClickedLineLinkId(
  geometries: LinkGeometry[],
  point: PointerPosition,
): string | null {
  const geometry = geometries.find((linkGeometry) => {
    const isOnLinkedText = [
      ...linkGeometry.fromRects,
      ...linkGeometry.toRects,
    ].some((rect) => isPointInRect(point, rect));

    return (
      !isOnLinkedText &&
      getDistanceToLineSegment(
        point,
        getLinePoints(linkGeometry.fromRect, linkGeometry.toRect),
      ) <= 7
    );
  });

  return geometry?.link.id ?? null;
}

function getLinePoints(fromRect: DOMRect, toRect: DOMRect) {
  const fromCenter = rectCenter(fromRect);
  const toCenter = rectCenter(toRect);

  return {
    x1: fromCenter.x,
    x2: toCenter.x,
    y1: fromCenter.y,
    y2: toCenter.y,
  };
}

function isWeakKind(kind: BlockTextLinkKind): boolean {
  return kind === 'weak-no-direction' || kind.startsWith('weak-direction');
}

function getMarkerStart(kind: BlockTextLinkKind): string | undefined {
  return kind === 'direction-from' || kind === 'weak-direction-from'
    ? 'url(#block-text-link-arrow)'
    : undefined;
}

function getMarkerEnd(kind: BlockTextLinkKind): string | undefined {
  return kind === 'direction-to' || kind === 'weak-direction-to'
    ? 'url(#block-text-link-arrow)'
    : undefined;
}

function getAnchorPointerPosition(
  anchorElem: HTMLElement,
  clientX: number,
  clientY: number,
): PointerPosition {
  const anchorRect = anchorElem.getBoundingClientRect();
  const scale = getClientRectZoomScale(anchorElem);

  return {
    x: (clientX - anchorRect.left) / scale,
    y: (clientY - anchorRect.top) / scale,
  };
}

function BlockTextLinkControls({
  activeLink,
  editor,
  onChangeKind,
  onClose,
  onReplaceRange,
  onRemove,
}: {
  activeLink: LinkGeometry;
  editor: LexicalEditor;
  onChangeKind: (id: string, kind: BlockTextLinkKind) => void;
  onClose: () => void;
  onReplaceRange: (
    id: string,
    side: 'from' | 'to',
    range: BlockTextRange,
  ) => void;
  onRemove: (id: string) => void;
}): JSX.Element {
  const controlsRef = useRef<HTMLDivElement | null>(null);
  const currentSelectionRange = editor
    .getEditorState()
    .read(() => $getSelectedBlockTextRange());

  useEffect(() => {
    controlsRef.current?.focus({ preventScroll: true });
  }, [activeLink.link.id]);

  const replaceRange = (side: 'from' | 'to') => {
    if (currentSelectionRange !== null) {
      onReplaceRange(activeLink.link.id, side, currentSelectionRange);
    }
  };

  return (
    <div
      className="block-text-link-controls"
      onBlur={(event) => {
        const nextFocusedElement = event.relatedTarget;
        if (
          !(nextFocusedElement instanceof Node) ||
          !event.currentTarget.contains(nextFocusedElement)
        ) {
          onClose();
        }
      }}
      onKeyDown={(event) => {
        if (event.key === 'Escape') {
          event.stopPropagation();
          onClose();
        }
      }}
      ref={controlsRef}
      style={{
        left: activeLink.midpoint.x,
        top: activeLink.midpoint.y,
      }}
      tabIndex={-1}
    >
      <div className="block-text-link-controls-section">
        {LINK_KIND_OPTIONS.map((option) => (
          <button
            className={
              option.kind === activeLink.link.kind ? 'active' : undefined
            }
            key={option.kind}
            onClick={() => onChangeKind(activeLink.link.id, option.kind)}
            type="button"
          >
            {option.label}
          </button>
        ))}
      </div>
      <div className="block-text-link-controls-section">
        <button
          disabled={currentSelectionRange === null}
          onClick={() => replaceRange('from')}
          type="button"
        >
          Use selection as first
        </button>
        <button
          disabled={currentSelectionRange === null}
          onClick={() => replaceRange('to')}
          type="button"
        >
          Use selection as second
        </button>
      </div>
      <button
        className="danger"
        onClick={() => onRemove(activeLink.link.id)}
        type="button"
      >
        Remove link
      </button>
    </div>
  );
}

export default function BlockTextLinkPlugin({
  anchorElem,
}: {
  anchorElem: HTMLElement;
}): JSX.Element {
  const [editor] = useLexicalComposerContext();
  const isEditable = useLexicalEditable();
  const [links, setLinks] = useState<BlockTextLink[]>([]);
  const [geometries, setGeometries] = useState<LinkGeometry[]>([]);
  const [hoveredLinkId, setHoveredLinkId] = useState<string | null>(null);
  const [selectedLinkId, setSelectedLinkId] = useState<string | null>(null);
  const [pendingRange, setPendingRange] = useState<BlockTextRange | null>(null);
  const [pendingCursorPosition, setPendingCursorPosition] =
    useState<PointerPosition | null>(null);
  const lastPointerPositionRef = useRef<PointerPosition | null>(null);
  const linksRef = useRef<BlockTextLink[]>([]);
  const pendingRangeRef = useRef<BlockTextRange | null>(null);
  const redoStackRef = useRef<BlockTextLinkSnapshot[]>([]);
  const undoStackRef = useRef<BlockTextLinkSnapshot[]>([]);

  const setPending = useCallback(
    (range: BlockTextRange | null) => {
      pendingRangeRef.current = range;
      setPendingRange(range);
      setPendingCursorPosition(
        range === null || lastPointerPositionRef.current === null
          ? null
          : getAnchorPointerPosition(
              anchorElem,
              lastPointerPositionRef.current.x,
              lastPointerPositionRef.current.y,
            ),
      );
    },
    [anchorElem],
  );

  const publishHistoryAvailability = useCallback(() => {
    editor.dispatchCommand(CAN_UNDO_COMMAND, undoStackRef.current.length > 0);
    editor.dispatchCommand(CAN_REDO_COMMAND, redoStackRef.current.length > 0);
  }, [editor]);

  const syncLinks = useCallback(
    (nextLinks: BlockTextLink[]) => {
      linksRef.current = nextLinks;
      writeStoredBlockTextLinks(toStoredLinks(nextLinks));
      setLinks(nextLinks);
      setSelectedLinkId((currentId) =>
        currentId !== null && nextLinks.some((link) => link.id === currentId)
          ? currentId
          : null,
      );
      setHoveredLinkId((currentId) =>
        currentId !== null && nextLinks.some((link) => link.id === currentId)
          ? currentId
          : null,
      );
      setPending(null);
      publishHistoryAvailability();
    },
    [publishHistoryAvailability, setPending],
  );

  useEffect(() => {
    const storedLinks = getStoredBlockTextLinks();
    if (storedLinks.length === 0) {
      return;
    }

    const restoredLinks = editor
      .getEditorState()
      .read(() => fromStoredLinks(storedLinks));

    if (restoredLinks.length > 0) {
      syncLinks(restoredLinks);
    }
  }, [editor, syncLinks]);

  const commitLinks = useCallback(
    (updater: (currentLinks: BlockTextLink[]) => BlockTextLink[]) => {
      if (!editor.isEditable()) {
        return;
      }

      const currentLinks = linksRef.current;
      const nextLinks = updater(currentLinks);

      if (
        nextLinks === currentLinks ||
        areLinksEqual(currentLinks, nextLinks)
      ) {
        return;
      }

      undoStackRef.current.push(currentLinks);
      redoStackRef.current = [];
      syncLinks(nextLinks);
    },
    [editor, syncLinks],
  );

  const undoBlockTextLinkChange = useCallback((): boolean => {
    if (!editor.isEditable()) {
      return false;
    }

    const previousLinks = undoStackRef.current.pop();
    if (previousLinks === undefined) {
      return false;
    }

    redoStackRef.current.push(linksRef.current);
    syncLinks(previousLinks);
    return true;
  }, [editor, syncLinks]);

  const redoBlockTextLinkChange = useCallback((): boolean => {
    if (!editor.isEditable()) {
      return false;
    }

    const nextLinks = redoStackRef.current.pop();
    if (nextLinks === undefined) {
      return false;
    }

    undoStackRef.current.push(linksRef.current);
    syncLinks(nextLinks);
    return true;
  }, [editor, syncLinks]);

  useEffect(() => {
    if (!isEditable) {
      setPending(null);
      setSelectedLinkId(null);
    }
  }, [isEditable, setPending]);

  const updateGeometry = useCallback(() => {
    const anchorRect = anchorElem.getBoundingClientRect();
    const scale = getClientRectZoomScale(anchorElem);
    const nextGeometries = links.flatMap((link): LinkGeometry[] => {
      const fromRects = getRangeRects(editor, link.from);
      const toRects = getRangeRects(editor, link.to);
      const fromRect = unionRects(fromRects);
      const toRect = unionRects(toRects);

      if (fromRect === null || toRect === null) {
        return [];
      }

      const anchoredFromRect = toAnchorRect(fromRect, anchorRect, scale);
      const anchoredToRect = toAnchorRect(toRect, anchorRect, scale);
      const anchoredFromRects = toAnchorRects(fromRects, anchorRect, scale);
      const anchoredToRects = toAnchorRects(toRects, anchorRect, scale);
      const fromCenter = rectCenter(anchoredFromRect);
      const toCenter = rectCenter(anchoredToRect);

      return [
        {
          fromRect: anchoredFromRect,
          fromRects: anchoredFromRects,
          link,
          midpoint: {
            x: (fromCenter.x + toCenter.x) / 2,
            y: (fromCenter.y + toCenter.y) / 2,
          },
          toRect: anchoredToRect,
          toRects: anchoredToRects,
        },
      ];
    });

    setGeometries(nextGeometries);
  }, [anchorElem, editor, links]);

  useEffect(() => {
    updateGeometry();
  }, [updateGeometry]);

  useEffect(() => {
    const scrollerElem = anchorElem.parentElement;
    const update = () => updateGeometry();

    window.addEventListener('resize', update);
    if (scrollerElem !== null) {
      scrollerElem.addEventListener('scroll', update);
    }

    return () => {
      window.removeEventListener('resize', update);
      if (scrollerElem !== null) {
        scrollerElem.removeEventListener('scroll', update);
      }
    };
  }, [anchorElem, updateGeometry]);

  useEffect(() => {
    const handleMouseMove = (event: MouseEvent) => {
      lastPointerPositionRef.current = {
        x: event.clientX,
        y: event.clientY,
      };

      if (pendingRangeRef.current !== null) {
        setPendingCursorPosition(
          getAnchorPointerPosition(anchorElem, event.clientX, event.clientY),
        );
      }

      setHoveredLinkId(
        getHoveredRangeLinkId(
          geometries,
          getAnchorPointerPosition(anchorElem, event.clientX, event.clientY),
        ),
      );
    };

    const handleClick = (event: MouseEvent) => {
      const clickedLinkId = getClickedLineLinkId(
        geometries,
        getAnchorPointerPosition(anchorElem, event.clientX, event.clientY),
      );

      if (clickedLinkId !== null) {
        setSelectedLinkId(clickedLinkId);
      }
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('click', handleClick);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('click', handleClick);
    };
  }, [anchorElem, geometries]);

  useEffect(() => {
    if (pendingRange === null) {
      return;
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();
        setPending(null);
      }
    };

    document.addEventListener('keydown', handleKeyDown, true);

    return () => {
      document.removeEventListener('keydown', handleKeyDown, true);
    };
  }, [pendingRange, setPending]);

  useEffect(() => {
    if (!isEditable) {
      return;
    }

    const rootElement = editor.getRootElement();
    if (rootElement === null) {
      return;
    }

    const handleMouseUp = () => {
      const firstRange = pendingRangeRef.current;
      if (firstRange === null) {
        return;
      }

      window.setTimeout(() => {
        const secondRange = editor
          .getEditorState()
          .read(() => $getSelectedBlockTextRange());

        if (secondRange === null || areRangesEqual(firstRange, secondRange)) {
          return;
        }

        commitLinks((currentLinks) => [
          ...currentLinks,
          {
            from: firstRange,
            id: buildId(),
            kind: 'no-direction',
            to: secondRange,
          },
        ]);
      }, 0);
    };

    rootElement.addEventListener('mouseup', handleMouseUp);

    return () => {
      rootElement.removeEventListener('mouseup', handleMouseUp);
    };
  }, [commitLinks, editor, isEditable]);

  useEffect(() => {
    return mergeRegister(
      editor.registerCommand(
        START_BLOCK_TEXT_LINK_COMMAND,
        () => {
          if (!editor.isEditable()) {
            setPending(null);
            return true;
          }

          const range = $getSelectedBlockTextRange();
          if (range === null) {
            setPending(null);
            return true;
          }

          setSelectedLinkId(null);
          setPending(range);
          return true;
        },
        COMMAND_PRIORITY_EDITOR,
      ),
      editor.registerCommand(
        CLEAR_EDITOR_COMMAND,
        () => {
          undoStackRef.current = [];
          redoStackRef.current = [];
          syncLinks([]);
          return false;
        },
        COMMAND_PRIORITY_EDITOR,
      ),
      editor.registerCommand(
        UNDO_COMMAND,
        () => undoBlockTextLinkChange(),
        COMMAND_PRIORITY_CRITICAL,
      ),
      editor.registerCommand(
        REDO_COMMAND,
        () => redoBlockTextLinkChange(),
        COMMAND_PRIORITY_CRITICAL,
      ),
      editor.registerCommand(
        KEY_ESCAPE_COMMAND,
        (event) => {
          if (pendingRangeRef.current === null) {
            return false;
          }

          event.preventDefault();
          event.stopPropagation();
          setPending(null);
          return true;
        },
        COMMAND_PRIORITY_CRITICAL,
      ),
      editor.registerCommand(
        SELECTION_CHANGE_COMMAND,
        () => {
          updateGeometry();
          return false;
        },
        COMMAND_PRIORITY_EDITOR,
      ),
      editor.registerUpdateListener(() => {
        updateGeometry();
      }),
    );
  }, [
    editor,
    isEditable,
    redoBlockTextLinkChange,
    setPending,
    syncLinks,
    undoBlockTextLinkChange,
    updateGeometry,
  ]);

  const activeLink = useMemo(
    () => geometries.find((geometry) => geometry.link.id === selectedLinkId),
    [geometries, selectedLinkId],
  );

  const changeKind = (id: string, kind: BlockTextLinkKind) => {
    commitLinks((currentLinks) =>
      currentLinks.map((link) =>
        link.id === id && link.kind !== kind ? { ...link, kind } : link,
      ),
    );
  };

  const replaceRange = (
    id: string,
    side: 'from' | 'to',
    range: BlockTextRange,
  ) => {
    commitLinks((currentLinks) =>
      currentLinks.map((link) =>
        link.id === id
          ? {
              ...link,
              [side]: range,
            }
          : link,
      ),
    );
  };

  const removeLink = (id: string) => {
    commitLinks((currentLinks) =>
      currentLinks.filter((link) => link.id !== id),
    );
  };

  return createPortal(
    <>
      <svg className="block-text-link-layer">
        <defs>
          <marker
            id="block-text-link-arrow"
            markerHeight="8"
            markerWidth="10"
            orient="auto-start-reverse"
            refX="9"
            refY="4"
          >
            <path d="M 0 0 L 10 4 L 0 8 z" />
          </marker>
        </defs>
        {geometries.map((geometry) => {
          const { x1, x2, y1, y2 } = getLinePoints(
            geometry.fromRect,
            geometry.toRect,
          );
          const isSelected = geometry.link.id === selectedLinkId;
          const isFocused = isSelected || geometry.link.id === hoveredLinkId;

          return (
            <g
              className={
                'block-text-link ' +
                (isSelected ? 'selected ' : '') +
                (isFocused ? 'focused' : 'dimmed')
              }
              key={geometry.link.id}
            >
              {geometry.fromRects.map((rect, index) => (
                <rect
                  className="range-outline"
                  height={rect.height}
                  key={`from-${index}`}
                  width={rect.width}
                  x={rect.left}
                  y={rect.top}
                />
              ))}
              {geometry.toRects.map((rect, index) => (
                <rect
                  className="range-outline"
                  height={rect.height}
                  key={`to-${index}`}
                  width={rect.width}
                  x={rect.left}
                  y={rect.top}
                />
              ))}
              <line
                className={isWeakKind(geometry.link.kind) ? 'weak' : undefined}
                markerEnd={getMarkerEnd(geometry.link.kind)}
                markerStart={getMarkerStart(geometry.link.kind)}
                x1={x1}
                x2={x2}
                y1={y1}
                y2={y2}
              />
            </g>
          );
        })}
      </svg>
      {pendingRange !== null ? (
        <div
          className="block-text-link-pending"
          style={
            pendingCursorPosition === null
              ? undefined
              : {
                  left: pendingCursorPosition.x,
                  top: pendingCursorPosition.y,
                }
          }
        >
          <i className="bi bi-bezier2" />
          <span>Select second range</span>
        </div>
      ) : null}
      {activeLink !== undefined && isEditable ? (
        <BlockTextLinkControls
          activeLink={activeLink}
          editor={editor}
          onChangeKind={changeKind}
          onClose={() => setSelectedLinkId(null)}
          onRemove={removeLink}
          onReplaceRange={replaceRange}
        />
      ) : null}
    </>,
    anchorElem,
  );
}
