import type { JSX } from 'react';
import type { BibleNoteColorScheme } from './colorScheme';

import Settings from '../Settings';

export type BibleNoteSettingsProps = {
  setColorScheme: (mode: BibleNoteColorScheme) => void;
};

export default function BibleNoteSettings({
  setColorScheme,
}: BibleNoteSettingsProps): JSX.Element {
  return (
    <Settings
      onColorSchemeChange={(mode) => {
        setColorScheme(mode);
      }}
    />
  );
}
