import type { JSX } from 'react';

import * as React from 'react';
import { useId } from 'react';

export default function Switch({
  checked,
  onClick,
  text,
  id,
}: Readonly<{
  checked: boolean;
  id?: string;
  onClick: (e: React.MouseEvent<HTMLButtonElement, MouseEvent>) => void;
  text: string;
}>): JSX.Element {
  // Random ids collide once a panel renders enough switches, which silently
  // breaks the label/button association, so lean on React for unique ids.
  const buttonId = useId();
  return (
    <div className="switch d-block my-1 px-2 py-1 rounded-3" id={id}>
      <label className="mb-0 me-1" htmlFor={buttonId}>
        {text}
      </label>
      <button
        role="switch"
        aria-checked={checked}
        id={buttonId}
        onClick={onClick}
      >
        <span />
      </button>
    </div>
  );
}
