export type BibleTextParts = {
  body: string;
  header: string;
  title: string;
};

const BIBLE_TEXT_COLLAPSIBLE_REGEX = /^(\(.+\)\s(.+))\n([\s\S]+)$/;
const BIBLE_TEXT_VERSE_NUMBER_BOUNDARY_REGEX =
  /(?=\([\p{Decimal_Number}]+\):\s+)/u;

function splitBibleTextBodyPerVerseNumber(body: string): Array<string> {
  const bodyLines = body
    .trimEnd()
    .split(BIBLE_TEXT_VERSE_NUMBER_BOUNDARY_REGEX)
    .map((line) => line.trim())
    .filter((line) => line !== '');

  return bodyLines.length > 0 ? bodyLines : [body.trimEnd()];
}

export function getBibleTextPartsFromPlainText(
  text: string,
): BibleTextParts | null {
  const match = BIBLE_TEXT_COLLAPSIBLE_REGEX.exec(
    text.replace(/\r\n?/g, '\n').trimEnd(),
  );

  if (match === null) {
    return null;
  }

  return {
    body: match[3].trimEnd(),
    header: match[1].trim(),
    title: match[2].trim(),
  };
}

export function getBibleTextPlainTextWithVerseLineBreaks(
  bibleText: BibleTextParts,
): string {
  return `${bibleText.header}\n${splitBibleTextBodyPerVerseNumber(
    bibleText.body,
  ).join('\n')}`;
}

export function getBibleTextBodyLines(
  bibleText: BibleTextParts,
): ReadonlyArray<string> {
  return bibleText.body.split('\n');
}

export function getBibleTextPlainText(bibleText: BibleTextParts): string {
  return `${bibleText.header}\n${bibleText.body}`;
}
