import type { CSSProperties, JSX } from 'react';

import './index.scss';

import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { useCallback, useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';

type InvisibleCharacterMarkerType =
  'line-break' | 'paragraph' | 'space' | 'tab' | 'zero-width-space';

export type InvisibleCharacterMarker = {
  id: string;
  label: string;
  type: InvisibleCharacterMarkerType;
  x: number;
  y: number;
};

const BLOCK_SELECTOR = [
  '.PlaygroundEditorTheme__paragraph',
  '.PlaygroundEditorTheme__h1',
  '.PlaygroundEditorTheme__h2',
  '.PlaygroundEditorTheme__h3',
  '.PlaygroundEditorTheme__h4',
  '.PlaygroundEditorTheme__h5',
  '.PlaygroundEditorTheme__h6',
  '.PlaygroundEditorTheme__quote',
  '.PlaygroundEditorTheme__listItem',
  '.PlaygroundEditorTheme__code',
  '[role="paragraph"]',
].join(',');

const SKIP_SELECTOR = [
  '.ContentEditable__placeholder',
  '.InvisibleCharactersPlugin__overlay',
  'script',
  'style',
].join(',');
const READ_ONLY_SELECTOR = '[contenteditable="false"]';

const MARKER_LABELS: Record<InvisibleCharacterMarkerType, string> = {
  'line-break': '\u21b5',
  paragraph: '\u00b6',
  space: '\u00b7',
  tab: '\u2192',
  'zero-width-space': '|',
};

const PARAGRAPH_MARK_OFFSET = 4;

function getVisibleRect(range: Range): DOMRect | DOMRectReadOnly | null {
  for (const rect of Array.from(range.getClientRects())) {
    if (rect.width > 0 || rect.height > 0) {
      return rect;
    }
  }

  const boundingRect = range.getBoundingClientRect();

  if (boundingRect.width > 0 || boundingRect.height > 0) {
    return boundingRect;
  }

  return null;
}

function getTextMarkerType(
  character: string,
): InvisibleCharacterMarkerType | null {
  if (character === ' ' || character === '\u00a0') {
    return 'space';
  }

  if (character === '\t') {
    return 'tab';
  }

  if (character === '\n') {
    return 'line-break';
  }

  if (character === '\u200b') {
    return 'zero-width-space';
  }

  return null;
}

function createMarker(
  type: InvisibleCharacterMarkerType,
  rect: DOMRect | DOMRectReadOnly,
  anchorRect: DOMRect,
  id: string,
): InvisibleCharacterMarker {
  const x =
    type === 'paragraph'
      ? rect.left - anchorRect.left + PARAGRAPH_MARK_OFFSET
      : rect.left - anchorRect.left + rect.width / 2;

  return {
    id,
    label: MARKER_LABELS[type],
    type,
    x,
    y: rect.top - anchorRect.top + rect.height / 2,
  };
}

function createParagraphMarker(
  rect: DOMRect | DOMRectReadOnly,
  anchorRect: DOMRect,
  id: string,
  placement: 'after-text' | 'block-start',
): InvisibleCharacterMarker {
  const x =
    placement === 'after-text'
      ? rect.right - anchorRect.left + PARAGRAPH_MARK_OFFSET
      : rect.left - anchorRect.left + PARAGRAPH_MARK_OFFSET;

  return {
    id,
    label: MARKER_LABELS.paragraph,
    type: 'paragraph',
    x,
    y: rect.top - anchorRect.top + rect.height / 2,
  };
}

function collectTextMarkers(
  textNode: Text,
  anchorRect: DOMRect,
  markers: InvisibleCharacterMarker[],
): void {
  const document = textNode.ownerDocument;
  const text = textNode.nodeValue ?? '';

  for (let index = 0; index < text.length; index++) {
    const type = getTextMarkerType(text[index]);

    if (type === null) {
      continue;
    }

    const range = document.createRange();
    range.setStart(textNode, index);
    range.setEnd(textNode, index + 1);

    const rect = getVisibleRect(range);
    range.detach();

    if (rect === null) {
      continue;
    }

    markers.push(
      createMarker(type, rect, anchorRect, `text-${markers.length}`),
    );
  }
}

function getFallbackBlockRect(element: Element): DOMRect {
  return element.getBoundingClientRect();
}

function isSkippedElement(element: Element, rootElement: HTMLElement): boolean {
  if (element.closest(SKIP_SELECTOR) !== null) {
    return true;
  }

  const readOnlyElement = element.closest(READ_ONLY_SELECTOR);

  return readOnlyElement !== null && readOnlyElement !== rootElement;
}

function isSkippedTextNode(node: Node, rootElement: HTMLElement): boolean {
  const parentElement = node.parentElement;

  return (
    parentElement === null ||
    node.textContent === '' ||
    isSkippedElement(parentElement, rootElement)
  );
}

function getLastTextNode(
  element: Element,
  rootElement: HTMLElement,
): Text | null {
  const view = element.ownerDocument.defaultView;

  if (view === null) {
    return null;
  }

  let lastTextNode: Text | null = null;
  const treeWalker = element.ownerDocument.createTreeWalker(
    element,
    view.NodeFilter.SHOW_TEXT,
    {
      acceptNode(node) {
        return isSkippedTextNode(node, rootElement)
          ? view.NodeFilter.FILTER_REJECT
          : view.NodeFilter.FILTER_ACCEPT;
      },
    },
  );

  while (treeWalker.nextNode()) {
    lastTextNode = treeWalker.currentNode as Text;
  }

  return lastTextNode;
}

function getLastTextRect(
  element: Element,
  rootElement: HTMLElement,
): DOMRect | DOMRectReadOnly | null {
  const lastTextNode = getLastTextNode(element, rootElement);

  if (lastTextNode === null) {
    return null;
  }

  const text = lastTextNode.nodeValue ?? '';

  if (text.length === 0) {
    return null;
  }

  const range = element.ownerDocument.createRange();
  range.setStart(lastTextNode, text.length - 1);
  range.setEnd(lastTextNode, text.length);

  const rect = getVisibleRect(range);
  range.detach();

  return rect;
}

function collectBlockEndMarkers(
  rootElement: HTMLElement,
  anchorRect: DOMRect,
  markers: InvisibleCharacterMarker[],
): void {
  const blockElements = Array.from(
    rootElement.querySelectorAll(BLOCK_SELECTOR),
  );

  for (const blockElement of blockElements) {
    if (isSkippedElement(blockElement, rootElement)) {
      continue;
    }

    const lastTextRect = getLastTextRect(blockElement, rootElement);
    const rect = lastTextRect ?? getFallbackBlockRect(blockElement);

    if (rect.width === 0 && rect.height === 0) {
      continue;
    }

    markers.push(
      createParagraphMarker(
        rect,
        anchorRect,
        `paragraph-${markers.length}`,
        lastTextRect === null ? 'block-start' : 'after-text',
      ),
    );
  }
}

function collectLineBreakMarkers(
  rootElement: HTMLElement,
  anchorRect: DOMRect,
  markers: InvisibleCharacterMarker[],
): void {
  const document = rootElement.ownerDocument;
  const lineBreaks = Array.from(rootElement.querySelectorAll('br'));

  for (const lineBreak of lineBreaks) {
    if (isSkippedElement(lineBreak, rootElement)) {
      continue;
    }

    const range = document.createRange();
    range.selectNode(lineBreak);

    const rect = getVisibleRect(range) ?? lineBreak.getBoundingClientRect();
    range.detach();

    if (rect.width === 0 && rect.height === 0) {
      continue;
    }

    markers.push(
      createMarker(
        'line-break',
        rect,
        anchorRect,
        `line-break-${markers.length}`,
      ),
    );
  }
}

function collectInvisibleCharacterMarkers(
  rootElement: HTMLElement,
  anchorElement: HTMLElement,
): InvisibleCharacterMarker[] {
  const view = rootElement.ownerDocument.defaultView;

  if (view === null) {
    return [];
  }

  const markers: InvisibleCharacterMarker[] = [];
  const anchorRect = anchorElement.getBoundingClientRect();
  const treeWalker = rootElement.ownerDocument.createTreeWalker(
    rootElement,
    view.NodeFilter.SHOW_TEXT,
    {
      acceptNode(node) {
        if (isSkippedTextNode(node, rootElement)) {
          return view.NodeFilter.FILTER_REJECT;
        }

        return view.NodeFilter.FILTER_ACCEPT;
      },
    },
  );

  while (treeWalker.nextNode()) {
    collectTextMarkers(treeWalker.currentNode as Text, anchorRect, markers);
  }

  collectLineBreakMarkers(rootElement, anchorRect, markers);
  collectBlockEndMarkers(rootElement, anchorRect, markers);

  return markers;
}

function scheduleAnimationFrame(
  window: Window,
  callback: () => void,
): () => void {
  let cancelled = false;

  if (typeof window.requestAnimationFrame === 'function') {
    const frame = window.requestAnimationFrame(() => {
      if (!cancelled) {
        callback();
      }
    });

    return () => {
      cancelled = true;
      window.cancelAnimationFrame(frame);
    };
  }

  const timeout = window.setTimeout(() => {
    if (!cancelled) {
      callback();
    }
  }, 16);

  return () => {
    cancelled = true;
    window.clearTimeout(timeout);
  };
}

function getScrollElement(rootElement: HTMLElement): HTMLElement | null {
  return rootElement.closest('.editor-scroller') ?? rootElement.parentElement;
}

export default function InvisibleCharactersPlugin({
  anchorElem,
  enabled,
}: {
  anchorElem?: HTMLElement | null;
  enabled: boolean;
}): JSX.Element | null {
  const [editor] = useLexicalComposerContext();
  const [markers, setMarkers] = useState<InvisibleCharacterMarker[]>([]);
  const [portalElement, setPortalElement] = useState<HTMLElement | null>(null);
  const cancelScheduledUpdateRef = useRef<null | (() => void)>(null);

  const cancelScheduledUpdate = useCallback(() => {
    cancelScheduledUpdateRef.current?.();
    cancelScheduledUpdateRef.current = null;
  }, []);

  const updateMarkers = useCallback(() => {
    const rootElement = editor.getRootElement();

    if (!enabled || rootElement === null) {
      setMarkers([]);
      setPortalElement(null);
      return;
    }

    const nextPortalElement =
      anchorElem ?? rootElement.parentElement ?? rootElement;

    setPortalElement(nextPortalElement);
    setMarkers(
      collectInvisibleCharacterMarkers(rootElement, nextPortalElement),
    );
  }, [anchorElem, editor, enabled]);

  const scheduleUpdate = useCallback(() => {
    const rootElement = editor.getRootElement();
    const window = rootElement?.ownerDocument.defaultView;

    if (window === null || window === undefined) {
      updateMarkers();
      return;
    }

    cancelScheduledUpdate();
    cancelScheduledUpdateRef.current = scheduleAnimationFrame(
      window,
      updateMarkers,
    );
  }, [cancelScheduledUpdate, editor, updateMarkers]);

  useEffect(() => {
    if (!enabled) {
      cancelScheduledUpdate();
      setMarkers([]);
      setPortalElement(null);
      return;
    }

    scheduleUpdate();

    const unregisterUpdateListener =
      editor.registerUpdateListener(scheduleUpdate);
    const rootElement = editor.getRootElement();
    const window = rootElement?.ownerDocument.defaultView;
    const scrollElement = rootElement ? getScrollElement(rootElement) : null;
    const resizeObserver =
      rootElement && window && 'ResizeObserver' in window
        ? new window.ResizeObserver(scheduleUpdate)
        : null;

    window?.addEventListener('resize', scheduleUpdate);
    scrollElement?.addEventListener('scroll', scheduleUpdate, {
      passive: true,
    });
    resizeObserver?.observe(rootElement as HTMLElement);

    return () => {
      cancelScheduledUpdate();
      unregisterUpdateListener();
      window?.removeEventListener('resize', scheduleUpdate);
      scrollElement?.removeEventListener('scroll', scheduleUpdate);
      resizeObserver?.disconnect();
    };
  }, [cancelScheduledUpdate, editor, enabled, scheduleUpdate]);

  if (!enabled || portalElement === null || markers.length === 0) {
    return null;
  }

  return createPortal(
    <div className="InvisibleCharactersPlugin__overlay" aria-hidden="true">
      {markers.map((marker) => {
        const style: CSSProperties = {
          left: `${marker.x}px`,
          top: `${marker.y}px`,
        };

        return (
          <span
            className={`InvisibleCharactersPlugin__marker InvisibleCharactersPlugin__marker--${marker.type}`}
            data-invisible-character={marker.type}
            key={marker.id}
            style={style}
          >
            {marker.label}
          </span>
        );
      })}
    </div>,
    portalElement,
  );
}
