export const OPEN_MENTION_PERSON_ADVANCED_PANEL_EVENT =
  'bible-note:open-mention-person-advanced-panel';

export type OpenMentionPersonAdvancedPanelDetail = {
  anchorElement: HTMLElement;
  id: string | null;
  name: string;
};

export function dispatchOpenMentionPersonAdvancedPanelEvent(
  detail: OpenMentionPersonAdvancedPanelDetail,
): void {
  window.dispatchEvent(
    new CustomEvent<OpenMentionPersonAdvancedPanelDetail>(
      OPEN_MENTION_PERSON_ADVANCED_PANEL_EVENT,
      { detail },
    ),
  );
}
