export type FilePathSource = 'drop' | 'file-input';

export type FilePathResolverContext = Readonly<{
  source: FilePathSource;
}>;

export type FilePathResolver = (
  file: File,
  context: FilePathResolverContext,
) => Promise<string | null> | string | null;

export type FileRevealer = (filePath: string) => Promise<void> | void;

const URI_SCHEME_PATTERN = /^[a-z][a-z\d+.-]*:/i;
const NON_FILE_URI_SCHEME_PATTERN = /^(?:blob|data|https?):/i;

type FileWithPath = File & { path?: string };

function normalizeResolvedFilePath(value: unknown): string | null {
  if (typeof value !== 'string') {
    return null;
  }

  return value.trim() === '' ? null : value;
}

export function getFallbackFilePath(file: File): string {
  return (file as FileWithPath).path || file.webkitRelativePath || file.name;
}

export async function resolveMediaFilePath(
  resolver: FilePathResolver | undefined,
  file: File,
  source: FilePathSource,
): Promise<string | null> {
  if (resolver === undefined) {
    return null;
  }

  try {
    return normalizeResolvedFilePath(await resolver(file, { source }));
  } catch {
    return null;
  }
}

export function isRevealableFilePath(value: string): boolean {
  const filePath = value.trim();

  if (filePath === '' || NON_FILE_URI_SCHEME_PATTERN.test(filePath)) {
    return false;
  }

  return (
    filePath.startsWith('file://') ||
    /^[a-z]:[\\/]/i.test(filePath) ||
    filePath.startsWith('\\\\') ||
    /^\.{1,2}[\\/]/.test(filePath) ||
    filePath.startsWith('/') ||
    (!URI_SCHEME_PATTERN.test(filePath) && /[\\/]/.test(filePath))
  );
}
