/**
 * Trailing-edge debounce, replacing the single `lodash-es` import the app had.
 *
 * Only the behaviour the call sites rely on is implemented: a trailing
 * invocation after `wait` ms of quiet, an optional `maxWait` ceiling so a
 * continuous stream of calls still fires periodically, and `cancel()`.
 */

export type DebouncedFunction<Args extends unknown[]> = {
  (...args: Args): void;
  cancel: () => void;
};

export type DebounceOptions = {
  /**
   * Maximum time the invocation may be deferred. Without it a caller that
   * fires faster than `wait` would starve the callback indefinitely.
   */
  maxWait?: number;
};

export function debounce<Args extends unknown[]>(
  fn: (...args: Args) => void,
  wait: number,
  options: DebounceOptions = {},
): DebouncedFunction<Args> {
  const { maxWait } = options;

  let waitTimeout: ReturnType<typeof setTimeout> | null = null;
  let maxWaitTimeout: ReturnType<typeof setTimeout> | null = null;
  let pendingArgs: Args | null = null;

  const clearTimers = (): void => {
    if (waitTimeout !== null) {
      clearTimeout(waitTimeout);
      waitTimeout = null;
    }

    if (maxWaitTimeout !== null) {
      clearTimeout(maxWaitTimeout);
      maxWaitTimeout = null;
    }
  };

  const invoke = (): void => {
    const args = pendingArgs;
    pendingArgs = null;
    clearTimers();

    if (args !== null) {
      fn(...args);
    }
  };

  const debounced = (...args: Args): void => {
    pendingArgs = args;

    if (waitTimeout !== null) {
      clearTimeout(waitTimeout);
    }

    waitTimeout = setTimeout(invoke, wait);

    // The max-wait timer is started on the leading call of a burst and is not
    // reset by subsequent calls -- that is what bounds the total delay.
    if (maxWait !== undefined && maxWaitTimeout === null) {
      maxWaitTimeout = setTimeout(invoke, maxWait);
    }
  };

  debounced.cancel = (): void => {
    pendingArgs = null;
    clearTimers();
  };

  return debounced;
}
