import * as ExcalidrawProdChunk from '@excalidraw-prod-font-chunk';

type ExcalidrawFontModule = Record<string, unknown>;

export type ExcalidrawFontInternals = {
  FONT_FAMILY: unknown;
  Fonts: unknown;
};

let fontInternalsPromise: Promise<ExcalidrawFontInternals> | null = null;

function isRecord(value: unknown): value is Record<string, unknown> {
  // Excalidraw's `Fonts` registry is exposed as a class (typeof 'function'),
  // while `FONT_FAMILY` is a plain object, so accept both shapes here.
  return (
    (typeof value === 'object' || typeof value === 'function') && value !== null
  );
}

function isFontFamily(value: unknown): boolean {
  return (
    isRecord(value) &&
    typeof value.Excalifont === 'number' &&
    typeof value.Nunito === 'number'
  );
}

function isFontsRegistry(value: unknown): boolean {
  return (
    isRecord(value) &&
    value.registered instanceof Map &&
    typeof value.register === 'function'
  );
}

function getFontInternals(
  module: ExcalidrawFontModule,
): ExcalidrawFontInternals | null {
  let FONT_FAMILY: unknown;
  let Fonts: unknown;

  Object.values(module).forEach((value) => {
    if (FONT_FAMILY === undefined && isFontFamily(value)) {
      FONT_FAMILY = value;
    }

    if (Fonts === undefined && isFontsRegistry(value)) {
      Fonts = value;
    }
  });

  if (FONT_FAMILY === undefined || Fonts === undefined) {
    return null;
  }

  return { FONT_FAMILY, Fonts };
}

async function loadFontInternals(): Promise<ExcalidrawFontInternals> {
  const fontInternals = getFontInternals(ExcalidrawProdChunk);

  if (fontInternals !== null) {
    return fontInternals;
  }

  throw new Error('Unable to resolve Excalidraw font internals.');
}

export function getExcalidrawFontInternals(): Promise<ExcalidrawFontInternals> {
  fontInternalsPromise ??= loadFontInternals();
  return fontInternalsPromise;
}
