/**
 * The set of name "types" carried by biblical name records. Each type maps to a
 * distinct icon so mentions can be told apart at a glance in the editor pills,
 * the typeahead menu, the hover card, and the advanced panel.
 *
 * When adding a new type here, add a matching `data-lexical-mention-name-type`
 * mask rule in `AppComp.scss` so the editor pill icon stays in sync.
 */
export type MentionNameType =
  | 'person'
  | 'concept'
  | 'place'
  | 'group'
  | 'deity'
  | 'month'
  | 'supernatural'
  | 'life'
  | 'unknown';

const NAME_TYPE_ICON_CLASS: Record<MentionNameType, string> = {
  concept: 'bi-lightbulb-fill',
  deity: 'bi-brightness-high-fill',
  group: 'bi-people-fill',
  life: 'bi-heart-fill',
  month: 'bi-calendar-event-fill',
  person: 'bi-person-fill',
  place: 'bi-geo-alt-fill',
  supernatural: 'bi-stars',
  unknown: 'bi-question-circle-fill',
};

/**
 * Normalizes a raw record `type` value to one of the known {@link MentionNameType}
 * keys. Unrecognized or empty values fall back to `person`, the neutral default
 * used for untyped name records.
 */
export function normalizeMentionNameType(
  type: string | null | undefined,
): MentionNameType {
  const normalized = (type ?? '').trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(NAME_TYPE_ICON_CLASS, normalized)
    ? (normalized as MentionNameType)
    : 'person';
}

/**
 * Returns the Bootstrap Icons class string for a name record `type`, ready to
 * drop onto an `<i>` element (e.g. the typeahead menu, hover card, or panel).
 */
export function getMentionNameTypeIconClass(
  type: string | null | undefined,
): string {
  return `bi ${NAME_TYPE_ICON_CLASS[normalizeMentionNameType(type)]} icon`;
}
