import type { JSX } from 'react';

import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { mergeRegister } from '@lexical/utils';
import {
  $createParagraphNode,
  $getNodeByKey,
  $getRoot,
  $getSelection,
  $isElementNode,
  $isRangeSelection,
  $nodesOfType,
  COMMAND_PRIORITY_CRITICAL,
  DELETE_CHARACTER_COMMAND,
  KEY_BACKSPACE_COMMAND,
  KEY_DELETE_COMMAND,
  type LexicalEditor,
  REMOVE_TEXT_COMMAND,
  SELECT_ALL_COMMAND,
  type LexicalNode,
} from 'lexical';
import { useEffect } from 'react';

import {
  $isStickyNode,
  StickyNode,
  type SerializedStickyNode,
} from '../../nodes/StickyNode';

type StickyNodeSnapshot = {
  index: number;
  key: string;
  serializedNode: SerializedStickyNode;
};

function $getAttachedStickyNodes(): Array<StickyNode> {
  return $nodesOfType(StickyNode).filter((node) => node.isAttached());
}

/**
 * Sticky notes are top-level nodes, but documents saved before they became
 * block-level nodes keep them wrapped inside a paragraph. Such a wrapper holds
 * nothing but sticky notes, so it has to be treated as a sticky note itself.
 */
function $isStickyOnlyNode(node: LexicalNode): boolean {
  if ($isStickyNode(node)) {
    return true;
  }

  return (
    $isElementNode(node) &&
    node.getChildrenSize() > 0 &&
    node.getChildren().every($isStickyOnlyNode)
  );
}

function $getRootChildIndex(node: LexicalNode): number {
  const topLevelNode = node.getTopLevelElement() ?? node;
  return Math.max(0, topLevelNode.getIndexWithinParent());
}

function $insertEditableParagraphIfNeeded(): void {
  const root = $getRoot();
  const children = root.getChildren();

  if (children.some((node) => !$isStickyOnlyNode(node))) {
    return;
  }

  const paragraph = $createParagraphNode();
  const firstStickyIndex = children.findIndex($isStickyOnlyNode);
  root.splice(firstStickyIndex === -1 ? 0 : firstStickyIndex, 0, [paragraph]);
  paragraph.select();
}

export function $deleteSelectedTextPreservingStickyNodes(): boolean {
  const selection = $getSelection();

  if (!$isRangeSelection(selection) || selection.isCollapsed()) {
    return false;
  }

  const root = $getRoot();
  const stickyNodes = $getAttachedStickyNodes();

  if (stickyNodes.length === 0) {
    return false;
  }

  const stickyNodeSnapshots: Array<StickyNodeSnapshot> = stickyNodes.map(
    (node) => ({
      index: $getRootChildIndex(node),
      key: node.getKey(),
      serializedNode: node.exportJSON(),
    }),
  );

  selection.removeText();

  for (const { index, key, serializedNode } of stickyNodeSnapshots) {
    const existingNode = $getNodeByKey(key);

    if ($isStickyNode(existingNode) && existingNode.isAttached()) {
      continue;
    }

    root.splice(Math.min(index, root.getChildrenSize()), 0, [
      StickyNode.importJSON(serializedNode),
    ]);
  }

  $insertEditableParagraphIfNeeded();

  return true;
}

export function $selectAllTextBeforeTrailingStickyNodes(): boolean {
  const root = $getRoot();
  const children = root.getChildren();
  const firstStickyIndex = children.findIndex($isStickyOnlyNode);

  if (firstStickyIndex === -1) {
    return false;
  }

  const hasTextAfterSticky = children
    .slice(firstStickyIndex)
    .some((node) => !$isStickyOnlyNode(node));

  if (hasTextAfterSticky) {
    return false;
  }

  if (firstStickyIndex === 0) {
    return true;
  }

  root.select(0, firstStickyIndex);
  return true;
}

function $deleteSelectedTextPreservingStickyNodesFromKeyboard(
  event: KeyboardEvent,
): boolean {
  const handled = $deleteSelectedTextPreservingStickyNodes();
  if (handled) {
    event.preventDefault();
  }
  return handled;
}

export function registerStickyNodeSelectionGuards(
  editor: LexicalEditor,
): () => void {
  return mergeRegister(
    editor.registerCommand(
      SELECT_ALL_COMMAND,
      () => $selectAllTextBeforeTrailingStickyNodes(),
      COMMAND_PRIORITY_CRITICAL,
    ),
    editor.registerCommand(
      KEY_BACKSPACE_COMMAND,
      (event) => $deleteSelectedTextPreservingStickyNodesFromKeyboard(event),
      COMMAND_PRIORITY_CRITICAL,
    ),
    editor.registerCommand(
      KEY_DELETE_COMMAND,
      (event) => $deleteSelectedTextPreservingStickyNodesFromKeyboard(event),
      COMMAND_PRIORITY_CRITICAL,
    ),
    editor.registerCommand(
      DELETE_CHARACTER_COMMAND,
      () => $deleteSelectedTextPreservingStickyNodes(),
      COMMAND_PRIORITY_CRITICAL,
    ),
    editor.registerCommand(
      REMOVE_TEXT_COMMAND,
      () => $deleteSelectedTextPreservingStickyNodes(),
      COMMAND_PRIORITY_CRITICAL,
    ),
  );
}

export default function StickyPlugin(): JSX.Element | null {
  const [editor] = useLexicalComposerContext();
  useEffect(() => {
    if (!editor.hasNodes([StickyNode])) {
      throw new Error('StickyPlugin: StickyNode not registered on editor');
    }

    return registerStickyNodeSelectionGuards(editor);
  }, [editor]);
  return null;
}
