import type { JSX } from 'react';

import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { $insertNodeToNearestRoot } from '@lexical/utils';
import {
  COMMAND_PRIORITY_EDITOR,
  createCommand,
  type LexicalCommand,
} from 'lexical';
import { useEffect } from 'react';

import { $createWebsiteNode, WebsiteNode } from '../../nodes/WebsiteNode';

export const INSERT_WEBSITE_COMMAND: LexicalCommand<string> = createCommand(
  'INSERT_WEBSITE_COMMAND',
);

export default function WebsitePlugin(): JSX.Element | null {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    if (!editor.hasNodes([WebsiteNode])) {
      throw new Error('WebsitePlugin: WebsiteNode not registered on editor');
    }

    return editor.registerCommand<string>(
      INSERT_WEBSITE_COMMAND,
      (payload) => {
        const websiteNode = $createWebsiteNode(payload);
        $insertNodeToNearestRoot(websiteNode);

        return true;
      },
      COMMAND_PRIORITY_EDITOR,
    );
  }, [editor]);

  return null;
}
