import type { CSSProperties, JSX } from 'react';
import type { LibraryItems } from '@excalidraw/excalidraw/types';

import { AutoFocusPlugin } from '@lexical/react/LexicalAutoFocusPlugin';
import { CharacterLimitPlugin } from '@lexical/react/LexicalCharacterLimitPlugin';
import { CheckListPlugin } from '@lexical/react/LexicalCheckListPlugin';
import { ClearEditorPlugin } from '@lexical/react/LexicalClearEditorPlugin';
import { ClickableLinkPlugin } from '@lexical/react/LexicalClickableLinkPlugin';
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { LexicalErrorBoundary } from '@lexical/react/LexicalErrorBoundary';
import { HistoryPlugin } from '@lexical/react/LexicalHistoryPlugin';
import { HorizontalRulePlugin } from '@lexical/react/LexicalHorizontalRulePlugin';
import { ListPlugin } from '@lexical/react/LexicalListPlugin';
import { PlainTextPlugin } from '@lexical/react/LexicalPlainTextPlugin';
import { RichTextPlugin } from '@lexical/react/LexicalRichTextPlugin';
import { SelectionAlwaysOnDisplay } from '@lexical/react/LexicalSelectionAlwaysOnDisplay';
import { TabIndentationPlugin } from '@lexical/react/LexicalTabIndentationPlugin';
import { TablePlugin } from '@lexical/react/LexicalTablePlugin';
import { useLexicalEditable } from '@lexical/react/useLexicalEditable';
import { CAN_USE_DOM } from '@lexical/utils';
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from 'react';

import { ExcalidrawConfigProvider } from './context/ExcalidrawConfigContext';
import { useSettings } from './context/SettingsContext';
import { useSharedHistoryContext } from './context/SharedHistoryContext';
import { getStoredCommentsPanelOpen } from './commentStorage';
import {
  getStoredEditorZoomPercent,
  writeStoredEditorZoomPercent,
} from './zoomStorage';
import {
  EMPTY_BIBLE_NOTE_FOOTER_ACTION_BUTTONS,
  type BibleNoteFooterActionButtons,
} from './footerActionButtons';
import ActionsPlugin from './plugins/ActionsPlugin';
import AutocompletePlugin from './plugins/AutocompletePlugin';
import AutoEmbedPlugin from './plugins/AutoEmbedPlugin';
import AutoLinkPlugin from './plugins/AutoLinkPlugin';
import BlockTextLinkPlugin from './plugins/BlockTextLinkPlugin';
import CodeActionMenuPlugin from './plugins/CodeActionMenuPlugin';
import CodeHighlightPrismPlugin from './plugins/CodeHighlightPrismPlugin';
import CodeHighlightShikiPlugin from './plugins/CodeHighlightShikiPlugin';
import CollapsiblePlugin from './plugins/CollapsiblePlugin';
import CommentPlugin from './plugins/CommentPlugin';
import ComponentPickerPlugin from './plugins/ComponentPickerPlugin';
import ContextMenuPlugin from './plugins/ContextMenuPlugin';
import DateTimePlugin from './plugins/DateTimePlugin';
import DragDropPaste from './plugins/DragDropPastePlugin';
import DraggableBlockPlugin from './plugins/DraggableBlockPlugin';
import EditorStatePersistencePlugin from './plugins/EditorStatePersistencePlugin';
import EmojiPickerPlugin from './plugins/EmojiPickerPlugin';
import EmojisPlugin from './plugins/EmojisPlugin';
import EquationsPlugin from './plugins/EquationsPlugin';
import ExcalidrawPlugin from './plugins/ExcalidrawPlugin';
import FindPlugin, { TOGGLE_FIND_COMMAND } from './plugins/FindPlugin';
import FloatingLinkEditorPlugin from './plugins/FloatingLinkEditorPlugin';
import FloatingTextFormatToolbarPlugin from './plugins/FloatingTextFormatToolbarPlugin';
import MediaPlugin from './plugins/MediaPlugin';
import InvisibleCharactersPlugin from './plugins/InvisibleCharactersPlugin';
import KeywordsPlugin from './plugins/KeywordsPlugin';
import { LayoutPlugin } from './plugins/LayoutPlugin/LayoutPlugin';
import LinkPlugin from './plugins/LinkPlugin';
import LookupPlugin from './plugins/LookupPlugin';
import MarkdownShortcutPlugin from './plugins/MarkdownShortcutPlugin';
import { MaxLengthPlugin } from './plugins/MaxLengthPlugin';
import MentionBibleVersesPlugin from './plugins/MentionBibleVersesPlugin';
import MentionLocationsPlugin from './plugins/MentionLocationsPlugin';
import MentionNamePlugin from './plugins/MentionNamePlugin';
import PageBreakPlugin from './plugins/PageBreakPlugin';
import PageSizePreviewPlugin from './plugins/PageSizePreviewPlugin';
import PaperPageNavigationPlugin from './plugins/PaperPageNavigationPlugin';
import PollPlugin from './plugins/PollPlugin';
import ShortcutsPlugin from './plugins/ShortcutsPlugin';
import { SHORTCUTS } from './plugins/ShortcutsPlugin/shortcuts';
import SpecialTextPlugin from './plugins/SpecialTextPlugin';
import StickyPlugin from './plugins/StickyPlugin';
import TabFocusPlugin from './plugins/TabFocusPlugin';
import TableCellActionMenuPlugin from './plugins/TableActionMenuPlugin';
import TableCellResizer from './plugins/TableCellResizer';
import TableHoverActionsV2Plugin from './plugins/TableHoverActionsV2Plugin';
import TableOfContentsPlugin from './plugins/TableOfContentsPlugin';
import TableScrollShadowPlugin from './plugins/TableScrollShadowPlugin';
import ToolbarPlugin from './plugins/ToolbarPlugin';
import TreeViewPlugin from './plugins/TreeViewPlugin';
import WebsitePlugin from './plugins/WebsitePlugin';
import YouTubePlugin from './plugins/YouTubePlugin';
import ContentEditable from './ui/ContentEditable';
import type { FilePathResolver } from './utils/filePathResolver';
import type { ExtraFontFamilyOption } from './utils/fontFamilyOptions';
import { getPaperPageSize } from './utils/pageSizes';
import useModal from './hooks/useModal';

const DEFAULT_EDITOR_ZOOM_PERCENT = 100;
const MIN_EDITOR_ZOOM_PERCENT = 50;
const MAX_EDITOR_ZOOM_PERCENT = 500;
const EDITOR_ZOOM_STEP_PERCENT = 1;
const EDITOR_ZOOM_WHEEL_STEP_PERCENT = 3;
const EDITOR_ZOOM_PINCH_MIN_DISTANCE_PX = 8;
const PX_PER_INCH = 96;
const EXCALIDRAW_ZOOM_TARGET_SELECTOR = [
  '.excalidraw',
  '.excalidraw-button',
  '.ExcalidrawModal__overlay',
  '.ExcalidrawModal__modal',
  '.ExcalidrawModal__row',
].join(',');

function clampEditorZoomPercent(zoomPercent: number): number {
  if (!Number.isFinite(zoomPercent)) {
    return DEFAULT_EDITOR_ZOOM_PERCENT;
  }

  return Math.min(
    MAX_EDITOR_ZOOM_PERCENT,
    Math.max(MIN_EDITOR_ZOOM_PERCENT, zoomPercent),
  );
}

function getElementFromEventTarget(target: EventTarget | null): Element | null {
  if (target instanceof Element) {
    return target;
  }

  if (target instanceof Node) {
    return target.parentElement;
  }

  return null;
}

function isExcalidrawZoomTarget(target: EventTarget | null): boolean {
  return (
    getElementFromEventTarget(target)?.closest(
      EXCALIDRAW_ZOOM_TARGET_SELECTOR,
    ) !== null
  );
}

function getTouchPairMetrics(touches: TouchList): {
  clientX: number;
  clientY: number;
  distance: number;
} | null {
  if (touches.length !== 2) {
    return null;
  }

  const firstTouch = touches[0];
  const secondTouch = touches[1];
  const distance = Math.hypot(
    secondTouch.clientX - firstTouch.clientX,
    secondTouch.clientY - firstTouch.clientY,
  );

  if (distance < EDITOR_ZOOM_PINCH_MIN_DISTANCE_PX) {
    return null;
  }

  return {
    clientX: (firstTouch.clientX + secondTouch.clientX) / 2,
    clientY: (firstTouch.clientY + secondTouch.clientY) / 2,
    distance,
  };
}

type EditorProps = {
  detectTextLanguage?: (text: string) => string;
  excalidrawClearLibrariesFileList?: () => void;
  excalidrawLibraryItems?: LibraryItems;
  excalidrawLoadLibrariesFileList?: () => string[];
  excalidrawSaveLibrariesFile?: (librariesFile: string) => void;
  extraFontFamilies?: ReadonlyArray<ExtraFontFamilyOption>;
  forceReadOnly?: boolean;
  footerActionButtons?: BibleNoteFooterActionButtons;
  isMinimize: boolean;
  isOnApp: boolean;
  print?: () => void;
  resolveFilePath?: FilePathResolver;
};

export default function Editor({
  detectTextLanguage,
  excalidrawClearLibrariesFileList,
  excalidrawLibraryItems = [],
  excalidrawLoadLibrariesFileList,
  excalidrawSaveLibrariesFile,
  extraFontFamilies = [],
  forceReadOnly = false,
  footerActionButtons = EMPTY_BIBLE_NOTE_FOOTER_ACTION_BUTTONS,
  isMinimize,
  isOnApp,
  print,
  resolveFilePath,
}: EditorProps): JSX.Element {
  const [modal, showModal] = useModal();
  const { historyState } = useSharedHistoryContext();
  const {
    settings: {
      isCodeHighlighted,
      isCodeShiki,
      isAutocomplete,
      isMaxLength,
      isCharLimit,
      hasLinkAttributes,
      hasNestedTables,
      isCharLimitUtf8,
      isRichText,
      showTreeView,
      showTableOfContents,
      shouldUseLexicalContextMenu,
      shouldPreserveNewLinesInMarkdown,
      tableCellMerge,
      tableCellBackgroundColor,
      tableHorizontalScroll,
      shouldAllowHighlightingWithBrackets,
      showInvisibleCharacters,
      selectionAlwaysOnDisplay,
      listStrictIndent,
      pageSize,
    },
  } = useSettings();
  const isEditable = useLexicalEditable();
  const placeholder = isRichText
    ? 'Enter some rich text...'
    : 'Enter some plain text...';
  const [floatingAnchorElem, setFloatingAnchorElem] =
    useState<HTMLDivElement | null>(null);
  const [isSmallWidthViewport, setIsSmallWidthViewport] =
    useState<boolean>(false);
  const [editor] = useLexicalComposerContext();
  const [activeEditor, setActiveEditor] = useState(editor);
  const [isLinkEditMode, setIsLinkEditMode] = useState<boolean>(false);
  const [showComments, setShowComments] = useState(() =>
    getStoredCommentsPanelOpen(),
  );
  const [showLookup, setShowLookup] = useState(false);
  // The comments and lookup panels share the same fixed slot, so track which
  // was activated most recently and raise it above the other.
  const [topPanel, setTopPanel] = useState<'comments' | 'lookup'>('comments');
  const [isFullView, setIsFullView] = useState(false);
  const [isFullViewHeaderVisible, setIsFullViewHeaderVisible] = useState(false);
  const [isFullViewFooterVisible, setIsFullViewFooterVisible] = useState(false);
  const [editorZoomPercent, setEditorZoomPercent] = useState(() =>
    clampEditorZoomPercent(
      getStoredEditorZoomPercent() ?? DEFAULT_EDITOR_ZOOM_PERCENT,
    ),
  );
  const editorShellRef = useRef<HTMLDivElement | null>(null);
  const editorContainerRef = useRef<HTMLDivElement | null>(null);
  const editorZoomPercentRef = useRef(editorZoomPercent);
  editorZoomPercentRef.current = editorZoomPercent;
  const zoomAnchorRef = useRef<{
    clientX: number;
    clientY: number;
    previousZoomPercent: number;
  } | null>(null);
  const pinchZoomGestureRef = useRef<{
    initialDistance: number;
    initialZoomPercent: number;
  } | null>(null);
  const editorShellStyle = {
    '--playground-editor-content-zoom': String(editorZoomPercent / 100),
    overflow: 'hidden',
    touchAction: 'pan-x pan-y',
  } as CSSProperties;
  const updateEditorZoomPercent = (nextZoomPercent: number) => {
    setEditorZoomPercent(clampEditorZoomPercent(nextZoomPercent));
  };

  useEffect(() => {
    writeStoredEditorZoomPercent(editorZoomPercent);
  }, [editorZoomPercent]);

  useLayoutEffect(() => {
    const anchor = zoomAnchorRef.current;
    zoomAnchorRef.current = null;

    if (anchor === null || anchor.previousZoomPercent === editorZoomPercent) {
      return;
    }

    const containerElement = editorContainerRef.current;

    if (containerElement === null) {
      return;
    }

    const containerRect = containerElement.getBoundingClientRect();
    const pointerOffsetX = anchor.clientX - containerRect.left;
    const pointerOffsetY = anchor.clientY - containerRect.top;
    const zoomRatio = editorZoomPercent / anchor.previousZoomPercent;

    containerElement.scrollLeft =
      (containerElement.scrollLeft + pointerOffsetX) * zoomRatio -
      pointerOffsetX;
    containerElement.scrollTop =
      (containerElement.scrollTop + pointerOffsetY) * zoomRatio -
      pointerOffsetY;
  }, [editorZoomPercent]);

  const paperPageSize = getPaperPageSize(pageSize);
  const fitEditorZoomToPaper = (dimension: 'width' | 'height') => {
    const containerElement = editorContainerRef.current;

    if (containerElement === null || paperPageSize === null) {
      return;
    }

    const containerStyles = getComputedStyle(containerElement);

    if (dimension === 'width') {
      const pageWidthPx = paperPageSize.widthIn * PX_PER_INCH;

      if (pageWidthPx <= 0) {
        return;
      }

      const availableWidth =
        containerElement.clientWidth -
        (Number.parseFloat(containerStyles.paddingLeft) || 0) -
        (Number.parseFloat(containerStyles.paddingRight) || 0);

      updateEditorZoomPercent(Math.round((availableWidth / pageWidthPx) * 100));
      return;
    }

    const pageHeightPx = paperPageSize.heightIn * PX_PER_INCH;

    if (pageHeightPx <= 0) {
      return;
    }

    const availableHeight =
      containerElement.clientHeight -
      (Number.parseFloat(containerStyles.paddingTop) || 0) -
      (Number.parseFloat(containerStyles.paddingBottom) || 0);

    updateEditorZoomPercent(Math.round((availableHeight / pageHeightPx) * 100));
  };

  const onRef = (_floatingAnchorElem: HTMLDivElement) => {
    if (_floatingAnchorElem !== null) {
      setFloatingAnchorElem(_floatingAnchorElem);
    }
  };

  useEffect(() => {
    const updateViewPortWidth = () => {
      const isNextSmallWidthViewport =
        CAN_USE_DOM && window.matchMedia('(max-width: 1025px)').matches;

      if (isNextSmallWidthViewport !== isSmallWidthViewport) {
        setIsSmallWidthViewport(isNextSmallWidthViewport);
      }
    };
    updateViewPortWidth();
    window.addEventListener('resize', updateViewPortWidth);

    return () => {
      window.removeEventListener('resize', updateViewPortWidth);
    };
  }, [isSmallWidthViewport]);

  // Raise whichever panel was most recently opened. Watching the `show*` flags
  // (rather than only the toggle handlers) also covers panels opened
  // indirectly — e.g. the comments panel auto-opening when a commented range
  // is selected.
  const previousShowCommentsRef = useRef(showComments);
  useEffect(() => {
    if (showComments && !previousShowCommentsRef.current) {
      setTopPanel('comments');
    }
    previousShowCommentsRef.current = showComments;
  }, [showComments]);

  const previousShowLookupRef = useRef(showLookup);
  useEffect(() => {
    if (showLookup && !previousShowLookupRef.current) {
      setTopPanel('lookup');
    }
    previousShowLookupRef.current = showLookup;
  }, [showLookup]);

  // The footer toggles behave like taskbar buttons: open (and raise) when
  // closed, raise to the front when open but hidden behind the other panel,
  // and only close when already frontmost.
  const handleToggleComments = useCallback(() => {
    if (!showComments) {
      setShowComments(true);
    } else if (topPanel !== 'comments') {
      setTopPanel('comments');
    } else {
      setShowComments(false);
    }
  }, [showComments, topPanel]);

  const handleToggleLookup = useCallback(() => {
    if (!showLookup) {
      setShowLookup(true);
    } else if (topPanel !== 'lookup') {
      setTopPanel('lookup');
    } else {
      setShowLookup(false);
    }
  }, [showLookup, topPanel]);

  // Comments (25) and lookup (26) share the same fixed slot; give the active
  // one the higher z-index. Both stay below the draggable mention panels.
  const commentsPanelZIndex = topPanel === 'comments' ? 26 : 25;
  const lookupPanelZIndex = topPanel === 'lookup' ? 26 : 25;

  useEffect(() => {
    const onFullscreenChange = () => {
      const isFullscreenNow =
        document.fullscreenElement === editorShellRef.current;

      if (!isFullscreenNow) {
        setIsFullView(false);
      }
    };

    document.addEventListener('fullscreenchange', onFullscreenChange);

    return () => {
      document.removeEventListener('fullscreenchange', onFullscreenChange);
    };
  }, []);

  const handleToggleFullscreen = useCallback(() => {
    const editorShellElement = editorShellRef.current;

    if (editorShellElement === null) {
      return;
    }

    if (document.fullscreenElement === editorShellElement) {
      setIsFullView(false);
      void document.exitFullscreen?.().catch(() => {});
      return;
    }

    setIsFullView(true);

    if (editorShellElement.requestFullscreen !== undefined) {
      void editorShellElement.requestFullscreen().catch(() => {});
    }
  }, []);

  useEffect(() => {
    const editorShellElement = editorShellRef.current;

    if (editorShellElement === null) {
      return;
    }

    const handleEditorZoomWheel = (event: WheelEvent) => {
      if (
        !event.ctrlKey ||
        event.deltaY === 0 ||
        isExcalidrawZoomTarget(event.target)
      ) {
        return;
      }

      event.preventDefault();

      const currentZoomPercent = editorZoomPercentRef.current;
      const nextZoomPercent = clampEditorZoomPercent(
        currentZoomPercent +
          (event.deltaY < 0
            ? EDITOR_ZOOM_WHEEL_STEP_PERCENT
            : -EDITOR_ZOOM_WHEEL_STEP_PERCENT),
      );

      if (nextZoomPercent === currentZoomPercent) {
        return;
      }

      zoomAnchorRef.current = {
        clientX: event.clientX,
        clientY: event.clientY,
        previousZoomPercent: currentZoomPercent,
      };
      setEditorZoomPercent(nextZoomPercent);
    };

    const handleEditorZoomTouchStart = (event: TouchEvent) => {
      if (isExcalidrawZoomTarget(event.target)) {
        pinchZoomGestureRef.current = null;
        return;
      }

      const metrics = getTouchPairMetrics(event.touches);

      if (metrics === null) {
        pinchZoomGestureRef.current = null;
        return;
      }

      pinchZoomGestureRef.current = {
        initialDistance: metrics.distance,
        initialZoomPercent: editorZoomPercentRef.current,
      };
    };

    const handleEditorZoomTouchMove = (event: TouchEvent) => {
      const gesture = pinchZoomGestureRef.current;

      if (gesture === null || isExcalidrawZoomTarget(event.target)) {
        return;
      }

      const metrics = getTouchPairMetrics(event.touches);

      if (metrics === null) {
        pinchZoomGestureRef.current = null;
        return;
      }

      event.preventDefault();

      const currentZoomPercent = editorZoomPercentRef.current;
      const nextZoomPercent = clampEditorZoomPercent(
        Math.round(
          gesture.initialZoomPercent *
            (metrics.distance / gesture.initialDistance),
        ),
      );

      if (nextZoomPercent === currentZoomPercent) {
        return;
      }

      zoomAnchorRef.current = {
        clientX: metrics.clientX,
        clientY: metrics.clientY,
        previousZoomPercent: currentZoomPercent,
      };
      setEditorZoomPercent(nextZoomPercent);
    };

    const resetEditorZoomTouchGesture = () => {
      pinchZoomGestureRef.current = null;
    };

    editorShellElement.addEventListener('wheel', handleEditorZoomWheel, {
      passive: false,
    });
    editorShellElement.addEventListener(
      'touchstart',
      handleEditorZoomTouchStart,
    );
    editorShellElement.addEventListener(
      'touchmove',
      handleEditorZoomTouchMove,
      {
        passive: false,
      },
    );
    editorShellElement.addEventListener(
      'touchend',
      resetEditorZoomTouchGesture,
    );
    editorShellElement.addEventListener(
      'touchcancel',
      resetEditorZoomTouchGesture,
    );

    return () => {
      editorShellElement.removeEventListener('wheel', handleEditorZoomWheel);
      editorShellElement.removeEventListener(
        'touchstart',
        handleEditorZoomTouchStart,
      );
      editorShellElement.removeEventListener(
        'touchmove',
        handleEditorZoomTouchMove,
      );
      editorShellElement.removeEventListener(
        'touchend',
        resetEditorZoomTouchGesture,
      );
      editorShellElement.removeEventListener(
        'touchcancel',
        resetEditorZoomTouchGesture,
      );
    };
  }, []);

  useEffect(() => {
    const handleFullViewToggle = (event: KeyboardEvent) => {
      if (event.key !== 'F5') {
        return;
      }

      event.preventDefault();
      setIsFullView((currentIsFullView) => !currentIsFullView);
    };

    window.addEventListener('keydown', handleFullViewToggle);

    return () => {
      window.removeEventListener('keydown', handleFullViewToggle);
    };
  }, []);

  useEffect(() => {
    if (!isFullView) {
      setIsFullViewHeaderVisible(false);
      setIsFullViewFooterVisible(false);
    }
  }, [isFullView]);

  return (
    <ExcalidrawConfigProvider
      clearLibrariesFileList={excalidrawClearLibrariesFileList}
      detectTextLanguage={detectTextLanguage}
      extraFontFamilies={extraFontFamilies}
      loadLibrariesFileList={excalidrawLoadLibrariesFileList}
      libraryItems={excalidrawLibraryItems}
      saveLibrariesFile={excalidrawSaveLibrariesFile}
    >
      <div
        className={`w-100 h-100 card editor-shell${
          isFullView ? ' full-view' : ''
        }`}
        ref={editorShellRef}
        style={editorShellStyle}
      >
        {isFullView && (
          <div
            className="full-view-hover-zone full-view-hover-zone-top"
            onMouseEnter={() => setIsFullViewHeaderVisible(true)}
          />
        )}
        <div
          className={`w-100 card-header p-0${
            isFullView && isFullViewHeaderVisible ? ' full-view-visible' : ''
          }`}
          onMouseEnter={
            isFullView ? () => setIsFullViewHeaderVisible(true) : undefined
          }
          onMouseLeave={
            isFullView ? () => setIsFullViewHeaderVisible(false) : undefined
          }
        >
          {isRichText && (
            <ToolbarPlugin
              editor={editor}
              extraFontFamilies={extraFontFamilies}
              activeEditor={activeEditor}
              resolveFilePath={resolveFilePath}
              setActiveEditor={setActiveEditor}
              setIsLinkEditMode={setIsLinkEditMode}
            />
          )}
          {isRichText && (
            <ShortcutsPlugin
              editor={activeEditor}
              setIsLinkEditMode={setIsLinkEditMode}
            />
          )}
        </div>
        <div
          className={`w-100 card-body editor-container p-0 ${showTreeView ? 'tree-view' : ''} ${
            !isRichText ? 'plain-text' : ''
          }`}
          ref={editorContainerRef}
        >
          <div className="editor-zoom-surface">
            {isMaxLength && <MaxLengthPlugin maxLength={30} />}
            <DragDropPaste resolveFilePath={resolveFilePath} />
            <AutoFocusPlugin />
            <EditorStatePersistencePlugin />
            {selectionAlwaysOnDisplay && <SelectionAlwaysOnDisplay />}
            <ClearEditorPlugin />
            <FindPlugin />
            <ComponentPickerPlugin resolveFilePath={resolveFilePath} />
            <EmojiPickerPlugin />
            <AutoEmbedPlugin />
            <MentionNamePlugin />
            <MentionLocationsPlugin />
            <MentionBibleVersesPlugin />
            <EmojisPlugin />
            <KeywordsPlugin />
            <AutoLinkPlugin />
            <DateTimePlugin />
            <CommentPlugin
              setShowComments={setShowComments}
              showComments={showComments}
              panelZIndex={commentsPanelZIndex}
            />
            <LookupPlugin
              showLookup={showLookup}
              setShowLookup={setShowLookup}
              zIndex={lookupPanelZIndex}
            />
            {isRichText ? (
              <>
                <HistoryPlugin externalHistoryState={historyState} />
                <RichTextPlugin
                  contentEditable={
                    <div
                      className={`editor-scroller${
                        showComments ? ' comment-panel-open' : ''
                      }`}
                    >
                      <div className="editor" ref={onRef}>
                        <ContentEditable
                          placeholder={placeholder}
                          data-test-id="playground-editor"
                        />
                      </div>
                    </div>
                  }
                  ErrorBoundary={LexicalErrorBoundary}
                />
                <StickyPlugin />
                <MarkdownShortcutPlugin />
                {isCodeHighlighted &&
                  (isCodeShiki ? (
                    <CodeHighlightShikiPlugin />
                  ) : (
                    <CodeHighlightPrismPlugin />
                  ))}
                <ListPlugin hasStrictIndent={listStrictIndent} />
                <CheckListPlugin />
                <TablePlugin
                  hasCellMerge={tableCellMerge}
                  hasCellBackgroundColor={tableCellBackgroundColor}
                  hasHorizontalScroll={tableHorizontalScroll}
                  hasNestedTables={hasNestedTables}
                />
                <TableCellResizer />
                <TableScrollShadowPlugin />
                <MediaPlugin />
                <LinkPlugin hasLinkAttributes={hasLinkAttributes} />
                <PollPlugin />
                <YouTubePlugin />
                <WebsitePlugin />
                <ClickableLinkPlugin disabled={isEditable} />
                <HorizontalRulePlugin />
                <EquationsPlugin />
                <ExcalidrawPlugin
                  clearLibrariesFileList={excalidrawClearLibrariesFileList}
                  detectTextLanguage={detectTextLanguage}
                  extraFontFamilies={extraFontFamilies}
                  loadLibrariesFileList={excalidrawLoadLibrariesFileList}
                  libraryItems={excalidrawLibraryItems}
                  saveLibrariesFile={excalidrawSaveLibrariesFile}
                />
                <TabFocusPlugin />
                <TabIndentationPlugin maxIndent={7} />
                <CollapsiblePlugin
                  detectTextLanguage={detectTextLanguage}
                  extraFontFamilies={extraFontFamilies}
                />
                <PageBreakPlugin />
                <LayoutPlugin />
                {floatingAnchorElem && (
                  <>
                    <FloatingLinkEditorPlugin
                      anchorElem={floatingAnchorElem}
                      isLinkEditMode={isLinkEditMode}
                      setIsLinkEditMode={setIsLinkEditMode}
                    />
                    <BlockTextLinkPlugin anchorElem={floatingAnchorElem} />
                    <TableCellActionMenuPlugin
                      anchorElem={floatingAnchorElem}
                      cellMerge={true}
                    />
                  </>
                )}
                {floatingAnchorElem && !isSmallWidthViewport && (
                  <>
                    <DraggableBlockPlugin anchorElem={floatingAnchorElem} />
                    <CodeActionMenuPlugin anchorElem={floatingAnchorElem} />
                    <TableHoverActionsV2Plugin
                      anchorElem={floatingAnchorElem}
                    />
                    <FloatingTextFormatToolbarPlugin
                      anchorElem={floatingAnchorElem}
                    />
                  </>
                )}
              </>
            ) : (
              <>
                <PlainTextPlugin
                  contentEditable={
                    <ContentEditable
                      placeholder={placeholder}
                      data-test-id="playground-editor"
                    />
                  }
                  ErrorBoundary={LexicalErrorBoundary}
                />
                <HistoryPlugin externalHistoryState={historyState} />
              </>
            )}
            <InvisibleCharactersPlugin
              anchorElem={floatingAnchorElem}
              enabled={showInvisibleCharacters}
            />
            {(isCharLimit || isCharLimitUtf8) && (
              <CharacterLimitPlugin
                charset={isCharLimit ? 'UTF-16' : 'UTF-8'}
                maxLength={5}
              />
            )}
            {isAutocomplete && <AutocompletePlugin />}
            <PageSizePreviewPlugin />
            <PaperPageNavigationPlugin />
            <div>{showTableOfContents && <TableOfContentsPlugin />}</div>
            {shouldUseLexicalContextMenu && <ContextMenuPlugin />}
            {shouldAllowHighlightingWithBrackets && <SpecialTextPlugin />}
          </div>
        </div>
        <div
          className={`w-100 card-footer p-0 px-1${
            isFullView && isFullViewFooterVisible ? ' full-view-visible' : ''
          }`}
          onMouseEnter={
            isFullView ? () => setIsFullViewFooterVisible(true) : undefined
          }
          onMouseLeave={
            isFullView ? () => setIsFullViewFooterVisible(false) : undefined
          }
        >
          <div className="editor-footer">
            <EditorZoomControls
              onZoomPercentChange={updateEditorZoomPercent}
              zoomPercent={editorZoomPercent}
            />
            <EditorViewOptionsMenu
              isDefaultZoom={editorZoomPercent === DEFAULT_EDITOR_ZOOM_PERCENT}
              isFullView={isFullView}
              onFitHeight={() => fitEditorZoomToPaper('height')}
              onFitWidth={() => fitEditorZoomToPaper('width')}
              onOpenFind={() =>
                editor.dispatchCommand(TOGGLE_FIND_COMMAND, undefined)
              }
              onResetZoom={() =>
                updateEditorZoomPercent(DEFAULT_EDITOR_ZOOM_PERCENT)
              }
              onToggleFullView={() => setIsFullView((current) => !current)}
              showFitButtons={paperPageSize !== null}
            />
            <ActionsPlugin
              forceReadOnly={forceReadOnly}
              footerActionButtons={footerActionButtons}
              isMinimize={isMinimize}
              isOnApp={isOnApp}
              onToggleFullscreen={handleToggleFullscreen}
              print={print}
              setShowComments={setShowComments}
              setShowLookup={setShowLookup}
              onToggleComments={handleToggleComments}
              onToggleLookup={handleToggleLookup}
              shouldPreserveNewLinesInMarkdown={
                shouldPreserveNewLinesInMarkdown
              }
              showComments={showComments}
              showLookup={showLookup}
              showModal={showModal}
            />
          </div>
        </div>
        {isFullView && (
          <div
            className="full-view-hover-zone full-view-hover-zone-bottom"
            onMouseEnter={() => setIsFullViewFooterVisible(true)}
          />
        )}
        {showTreeView && <TreeViewPlugin />}
        {modal}
      </div>
    </ExcalidrawConfigProvider>
  );
}

function EditorZoomControls({
  onZoomPercentChange,
  zoomPercent,
}: {
  onZoomPercentChange: (zoomPercent: number) => void;
  zoomPercent: number;
}): JSX.Element {
  return (
    <div className="editor-zoom-controls" aria-label="Editor zoom controls">
      <button
        aria-label="Zoom out"
        className="action-button editor-zoom-button"
        disabled={zoomPercent <= MIN_EDITOR_ZOOM_PERCENT}
        onClick={() => {
          onZoomPercentChange(zoomPercent - EDITOR_ZOOM_STEP_PERCENT);
        }}
        title="Zoom out"
        type="button"
      >
        <i className="bi bi-dash" aria-hidden="true" />
      </button>
      <input
        aria-label="Editor zoom"
        className="editor-zoom-range"
        max={MAX_EDITOR_ZOOM_PERCENT}
        min={MIN_EDITOR_ZOOM_PERCENT}
        onChange={(event) => {
          onZoomPercentChange(event.target.valueAsNumber);
        }}
        step={EDITOR_ZOOM_STEP_PERCENT}
        title="Editor zoom"
        type="range"
        value={zoomPercent}
      />
      <button
        aria-label="Zoom in"
        className="action-button editor-zoom-button"
        disabled={zoomPercent >= MAX_EDITOR_ZOOM_PERCENT}
        onClick={() => {
          onZoomPercentChange(zoomPercent + EDITOR_ZOOM_STEP_PERCENT);
        }}
        title="Zoom in"
        type="button"
      >
        <i className="bi bi-plus" aria-hidden="true" />
      </button>
      <span className="editor-zoom-percent" aria-live="polite">
        {zoomPercent}%
      </span>
    </div>
  );
}

function EditorViewOptionsMenu({
  isDefaultZoom,
  isFullView,
  onFitHeight,
  onFitWidth,
  onOpenFind,
  onResetZoom,
  onToggleFullView,
  showFitButtons,
}: {
  isDefaultZoom: boolean;
  isFullView: boolean;
  onFitHeight: () => void;
  onFitWidth: () => void;
  onOpenFind: () => void;
  onResetZoom: () => void;
  onToggleFullView: () => void;
  showFitButtons: boolean;
}): JSX.Element {
  return (
    <div className="editor-view-options-menu">
      <button
        aria-haspopup="true"
        aria-label="View options"
        className="action-button editor-view-options-button"
        title="View options"
        type="button"
      >
        <i className="bi bi-three-dots-vertical" aria-hidden="true" />
      </button>
      <div className="editor-view-options-popover" role="menu">
        <button
          aria-label="Find in note"
          className="action-button editor-find-button"
          onClick={onOpenFind}
          title={`Find in note (${SHORTCUTS.FIND})`}
          type="button"
        >
          <i className="bi bi-search" aria-hidden="true" />
        </button>
        <button
          aria-label="Reset zoom"
          className="action-button editor-zoom-button"
          disabled={isDefaultZoom}
          onClick={onResetZoom}
          title="Reset zoom"
          type="button"
        >
          <i className="bi bi-arrow-counterclockwise" aria-hidden="true" />
        </button>
        <button
          aria-label="Toggle full view"
          aria-pressed={isFullView}
          className="action-button editor-full-view-button"
          onClick={onToggleFullView}
          title="Toggle full view (F5)"
          type="button"
        >
          <i className="bi bi-square" aria-hidden="true" />
        </button>
        {showFitButtons && (
          <>
            <button
              aria-label="Fit page width"
              className="action-button editor-fit-button"
              onClick={onFitWidth}
              title="Fit page width"
              type="button"
            >
              <i className="bi bi-arrows" aria-hidden="true" />
            </button>
            <button
              aria-label="Fit page height"
              className="action-button editor-fit-button"
              onClick={onFitHeight}
              title="Fit page height"
              type="button"
            >
              <i className="bi bi-arrows-vertical" aria-hidden="true" />
            </button>
          </>
        )}
      </div>
    </div>
  );
}
