function MentionNameBasicInfo({
  includeTitle = true,
  mentionPerson,
}: {
  includeTitle?: boolean;
  mentionPerson: MentionNamePreview;
}): JSX.Element {
  const basicFacts = [
    mentionPerson.type,
    mentionPerson.gender,
    mentionPerson.age,
  ].filter((value) => value !== '' && value.toLowerCase() !== 'unknown');

  return (
    <div className="mention-person-basic-info">
      {includeTitle && mentionPerson.title ? (
        <div className="mention-person-basic-info__title">
          <MentionReferenceText value={mentionPerson.title} />
        </div>
      ) : null}
      {mentionPerson.description ? (
        <p className="mention-person-basic-info__description">
          <MentionReferenceText value={mentionPerson.description} />
        </p>
      ) : null}
      {basicFacts.length > 0 ? (
        <div className="mention-person-basic-info__facts">
          {basicFacts.map((fact) => (
            <span key={fact}>{fact}</span>
          ))}
        </div>
      ) : null}
    </div>
  );
}

function MentionNameDetails({
  includeTitle = true,
  mentionPerson,
  onOpenPersonReference,
}: {
  includeTitle?: boolean;
  mentionPerson: MentionNamePreview;
  onOpenPersonReference: (
    mentionPerson: MentionNameMatch,
    anchorElement: HTMLElement,
  ) => void;
}): JSX.Element {
  const [hasExpanded, setHasExpanded] = useState(false);

  return (
    <details className="mention-person-details">
      <summary
        className="mention-person-details__summary"
        onClick={() => {
          setHasExpanded(true);
        }}
      >
        <i
          className="bi bi-chevron-right mention-person-details__summary-icon"
          aria-hidden="true"
        />
        <span>Details</span>
      </summary>
      <div className="mention-person-details__body">
        {mentionPerson.description ? (
          <p className="mention-person-details__description">
            <MentionReferenceText value={mentionPerson.description} />
          </p>
        ) : null}
        <dl className="mention-person-details__grid">
          {includeTitle && hasMentionNameDetailValue(mentionPerson.title) ? (
            <MentionNameDetailRow
              inline
              label="Title"
              value={<MentionReferenceText value={mentionPerson.title} />}
            />
          ) : null}
          <MentionNameOptionalTextRow
            label="Also called"
            value={mentionPerson.oldName}
          />
          <MentionNameOptionalTextRow label="Type" value={mentionPerson.type} />
          <MentionNameOptionalTextRow
            label="Gender"
            value={mentionPerson.gender}
          />
          <MentionNameOptionalTextRow label="Age" value={mentionPerson.age} />
          <MentionNameOptionalTextListRow
            label="Years"
            values={mentionPerson.years.map(getFormattedYearRange)}
          />
          <MentionNameOptionalLocationListRow
            locations={mentionPerson.locations}
          />
          <MentionNameOptionalReferenceListRow
            label="Parents"
            ids={mentionPerson.parents}
            onOpenPersonReference={onOpenPersonReference}
          />
          <MentionNameOptionalReferenceListRow
            label="Spouses"
            ids={mentionPerson.spouses}
            onOpenPersonReference={onOpenPersonReference}
          />
          <MentionNameOptionalReferenceListRow
            label="Children"
            ids={mentionPerson.children}
            onOpenPersonReference={onOpenPersonReference}
          />
          <MentionNameOptionalReferenceListRow
            label="Siblings"
            ids={mentionPerson.siblings}
            onOpenPersonReference={onOpenPersonReference}
          />
          <MentionNameOptionalReferenceListRow
            label="Cousins"
            ids={mentionPerson.cousin}
            onOpenPersonReference={onOpenPersonReference}
          />
          <MentionNameOptionalVersesRow
            enabled={hasExpanded}
            values={mentionPerson.verses}
          />
          <MentionNameOptionalLinkRow
            links={getMentionNameDisplayLinks(mentionPerson)}
          />
        </dl>
      </div>
    </details>
  );
}

function isMentionNameInteractiveTarget(target: EventTarget | null): boolean {
  return (
    target instanceof Element &&
    target.closest('a, button, .mention-person-details') !== null
  );
}

function getMentionNameElement(target: EventTarget | null): HTMLElement | null {
  if (!(target instanceof Element)) {
    return null;
  }

  const mentionElement = target.closest('[data-lexical-mention]');
  return mentionElement instanceof HTMLElement ? mentionElement : null;
}

function getMentionNameHoverCardElement(
  target: EventTarget | null,
): HTMLElement | null {
  if (!(target instanceof Element)) {
    return null;
  }

  const hoverCardElement = target.closest('[data-mention-name-hover-card]');
  return hoverCardElement instanceof HTMLElement ? hoverCardElement : null;
}

function getMentionNamePreview(target: HTMLElement): MentionNamePreview | null {
  const mentionText = target.textContent?.trim() ?? '';
  const mentionKind = target.getAttribute('data-lexical-mention-kind');

  if (
    mentionKind === 'location' ||
    mentionKind === 'bible-verse' ||
    mentionKind === 'hashtag' ||
    mentionText.startsWith('#')
  ) {
    return null;
  }

  const mentionId = target.getAttribute('data-lexical-mention-id');

  if (mentionId !== null) {
    const mention = mentionNameById.get(mentionId);

    if (mention !== undefined) {
      return mention;
    }
  }

  const mentionName =
    target.getAttribute('data-lexical-mention-name')?.trim() ??
    mentionText ??
    '';

  if (mentionName === '') {
    return null;
  }

  const matches = mentionNameByName.get(mentionName) ?? [];

  return createFallbackMentionNamePreview(
    mentionId,
    mentionName,
    matches.length === 1 ? matches[0].title : '',
  );
}

function getHoverCardStyle(element: HTMLElement): React.CSSProperties {
  return getMentionHoverCardStyle(element, 360);
}

function getMentionNameAdvancedPanelKey(
  mentionPerson: MentionNamePreview,
): string {
  return `person:${mentionPerson.id ?? mentionPerson.name}`;
}

function getMentionNamePreviewFromOpenDetail(
  detail: OpenMentionPersonAdvancedPanelDetail,
): MentionNamePreview | null {
  const id = getNullableTrimmedString(detail.id);
  const name = getTrimmedString(detail.name);

  if (id !== null) {
    const mentionPerson = mentionNameById.get(id);

    if (mentionPerson !== undefined) {
      return mentionPerson;
    }
  }

  if (name === '') {
    return null;
  }

  const matches = mentionNameByName.get(name) ?? [];

  if (matches.length >= 1) {
    return matches[0];
  }

  return null;
}

// Ranks how well a name matches the query so better matches sort first.
// Lower is better: exact name, then name prefix, then name substring. Mirrors
// the ranking used by the Lookup panel so both lists order matches the same way.
function getMentionNameMatchRank(
  name: string,
  normalizedQuery: string,
): number {
  const nameLower = name.toLowerCase();

  if (nameLower === normalizedQuery) {
    return 0;
  }

  if (nameLower.startsWith(normalizedQuery)) {
    return 1;
  }

  return 2;
}

const mentionNameLookupService = {
  search(
    string: string,
    callback: (results: Array<MentionNameMatch>) => void,
  ): void {
    setTimeout(() => {
      const normalizedQuery = string.toLowerCase();
      const results = mentionNameData
        .filter((mentionPerson) =>
          mentionPerson.name.toLowerCase().includes(normalizedQuery),
        )
        .map((mentionPerson) => ({
          mentionPerson,
          rank: getMentionNameMatchRank(mentionPerson.name, normalizedQuery),
        }))
        // Array#sort is stable, so records within a rank tier keep their
        // existing (alphabetical) order; better matches float to the top.
        .sort((a, b) => a.rank - b.rank)
        .map((entry) => entry.mentionPerson);
      callback(results);
    }, 500);
  },
};

function useMentionNameLookupService(mentionString: string | null) {
  const [results, setResults] = useState<Array<MentionNameMatch>>([]);

  useEffect(() => {
    const cachedResults = mentionNameCache.get(mentionString);

    if (mentionString == null) {
      setResults([]);
      return;
    }

    if (cachedResults === null) {
      return;
    } else if (cachedResults !== undefined) {
      setResults(cachedResults);
      return;
    }

    mentionNameCache.set(mentionString, null);
    mentionNameLookupService.search(mentionString, (newResults) => {
      mentionNameCache.set(mentionString, newResults);
      setResults(newResults);
    });
  }, [mentionString]);

  return results;
}

function checkForAtSignMentions(
  text: string,
  minMatchLength: number,
): MenuTextMatch | null {
  let match = AtSignMentionsRegex.exec(text);

  if (match === null) {
    match = AtSignMentionsRegexAliasRegex.exec(text);
  }
  if (match !== null) {
    // The strategy ignores leading whitespace but we need to know it's
    // length to add it to the leadOffset
    const maybeLeadingWhitespace = match[1];

    const matchingString = match[3];
    if (matchingString.length >= minMatchLength) {
      return {
        leadOffset: match.index + maybeLeadingWhitespace.length,
        matchingString,
        replaceableString: match[2],
      };
    }
  }
  return null;
}

function getPossibleQueryMatch(text: string): MenuTextMatch | null {
  return checkForAtSignMentions(text, 1);
}

class MentionNameTypeaheadOption extends MenuOption {
  id: string;
  name: string;
  declare title: string;
  picture: JSX.Element;

  constructor(mentionPerson: MentionNameMatch, picture: JSX.Element) {
    super(mentionPerson.id);
    this.id = mentionPerson.id;
    this.name = mentionPerson.name;
    this.title = getPlainReferenceText(mentionPerson.title);
    this.picture = picture;
  }
}

function MentionNameTypeaheadMenuItem({
  index,
  isSelected,
  onClick,
  onMouseEnter,
  option,
}: {
  index: number;
  isSelected: boolean;
  onClick: () => void;
  onMouseEnter: () => void;
  option: MentionNameTypeaheadOption;
}) {
  let className =
    'item mx-2 p-2 d-flex flex-row align-items-center flex-shrink-0';
  if (isSelected) {
    className += ' selected';
  }
  return (
    <li
      key={option.key}
      tabIndex={-1}
      className={className}
      ref={option.setRefElement}
      role="option"
      aria-selected={isSelected}
      id={'typeahead-item-' + index}
      onMouseEnter={onMouseEnter}
      onClick={onClick}
    >
      {option.picture}
      <span className="text flex-column">
        <span>{option.name}</span>
        {option.title ? (
          <span className="small opacity-75">({option.title})</span>
        ) : null}
      </span>
    </li>
  );
}

export default function MentionNamePlugin(): JSX.Element | null {
  const [editor] = useLexicalComposerContext();
  const hoverCardShowTimeoutRef = useRef<ReturnType<
    typeof window.setTimeout
  > | null>(null);
  const hoverCardHideTimeoutRef = useRef<ReturnType<
    typeof window.setTimeout
  > | null>(null);

  const [queryString, setQueryString] = useState<string | null>(null);
  const [hoveredMentionPerson, setHoveredMentionPerson] =
    useState<MentionNamePreview | null>(null);
  const [hoveredMentionNameElement, setHoveredMentionNameElement] =
    useState<HTMLElement | null>(null);
  const [hoverCardStyle, setHoverCardStyle] =
    useState<React.CSSProperties | null>(null);
  const [advancedPanels, setAdvancedPanels] = useState<
    Array<MentionNameAdvancedPanel>
  >([]);

  const { shortToVerseData } = useBibleVerseActions();
  const resolveVerseLabel = useCallback(
    async (shortVerse: string): Promise<string> => {
      if (shortToVerseData === undefined) {
        return shortVerse;
      }

      try {
        const data = await shortToVerseData(shortVerse);
        return data?.title ?? shortVerse;
      } catch {
        return shortVerse;
      }
    },
    [shortToVerseData],
  );

  const results = useMentionNameLookupService(queryString);

  const checkForSlashTriggerMatch = useBasicTypeaheadTriggerMatch('/', {
    minLength: 0,
  });

  const options = useMemo(
    () =>
      results
        .map(
          (result) =>
            new MentionNameTypeaheadOption(
              result,
              <i className={getMentionNameTypeIconClass(result.type)} />,
            ),
        )
        .slice(0, SUGGESTION_LIST_LENGTH_LIMIT),
    [results],
  );

  const onSelectOption = useCallback(
    (
      selectedOption: MentionNameTypeaheadOption,
      nodeToReplace: TextNode | null,
      closeMenu: () => void,
    ) => {
      editor.update(() => {
        const mentionNode = $createMentionNode(
          selectedOption.name,
          selectedOption.name,
          selectedOption.id,
        );
        if (nodeToReplace) {
          nodeToReplace.replace(mentionNode);
        }
        mentionNode.select();
        closeMenu();
      });
    },
    [editor],
  );

  const checkForMentionNameMatch = useCallback(
    (text: string) => {
      const slashMatch = checkForSlashTriggerMatch(text, editor);
      if (slashMatch !== null) {
        return null;
      }
      return getPossibleQueryMatch(text);
    },
    [checkForSlashTriggerMatch, editor],
  );

  const clearHoverCardShowTimeout = useCallback(() => {
    if (hoverCardShowTimeoutRef.current !== null) {
      window.clearTimeout(hoverCardShowTimeoutRef.current);
      hoverCardShowTimeoutRef.current = null;
    }
  }, []);

  const clearHoverCardHideTimeout = useCallback(() => {
    if (hoverCardHideTimeoutRef.current !== null) {
      window.clearTimeout(hoverCardHideTimeoutRef.current);
      hoverCardHideTimeoutRef.current = null;
    }
  }, []);

  const hideHoverCard = useCallback(() => {
    clearHoverCardShowTimeout();
    clearHoverCardHideTimeout();
    setHoveredMentionNameElement(null);
    setHoveredMentionPerson(null);
  }, [clearHoverCardHideTimeout, clearHoverCardShowTimeout]);

  const scheduleHideHoverCard = useCallback(() => {
    clearHoverCardShowTimeout();
    clearHoverCardHideTimeout();
    hoverCardHideTimeoutRef.current = window.setTimeout(() => {
      setHoveredMentionNameElement(null);
      setHoveredMentionPerson(null);
      hoverCardHideTimeoutRef.current = null;
    }, HOVER_CARD_CLOSE_DELAY_MS);
  }, [clearHoverCardHideTimeout, clearHoverCardShowTimeout]);

  const openAdvancedPanel = useCallback(
    (mentionPerson: MentionNamePreview, anchorElement: HTMLElement) => {
      const panelKey = getMentionNameAdvancedPanelKey(mentionPerson);
      const zIndex = getNextMentionAdvancedPanelZIndex();
      const position = getMentionAdvancedPanelInitialPosition(anchorElement);

      setAdvancedPanels((currentPanels) => {
        const existingPanel = currentPanels.find(
          (panel) => panel.panelKey === panelKey,
        );
        const nextPanel = {
          ...mentionPerson,
          anchorElement,
          panelKey,
          position: existingPanel?.position ?? position,
          zIndex,
        };

        if (existingPanel !== undefined) {
          return currentPanels.map((panel) =>
            panel.panelKey === panelKey ? nextPanel : panel,
          );
        }

        return [...currentPanels, nextPanel];
      });
      hideHoverCard();
    },
    [hideHoverCard],
  );

  const closeAdvancedPanel = useCallback((panelKey: string) => {
    setAdvancedPanels((currentPanels) =>
      currentPanels.filter((panel) => panel.panelKey !== panelKey),
    );
  }, []);

  const bringAdvancedPanelToFront = useCallback((panelKey: string) => {
    const zIndex = getNextMentionAdvancedPanelZIndex();

    setAdvancedPanels((currentPanels) =>
      currentPanels.map((panel) =>
        panel.panelKey === panelKey ? { ...panel, zIndex } : panel,
      ),
    );
  }, []);

  const updateAdvancedPanelPosition = useCallback(
    (panelKey: string, position: MentionAdvancedPanelPosition) => {
      setAdvancedPanels((currentPanels) => {
        let hasChanged = false;
        const nextPanels = currentPanels.map((panel) => {
          if (panel.panelKey !== panelKey) {
            return panel;
          }

          if (
            panel.position.left === position.left &&
            panel.position.top === position.top
          ) {
            return panel;
          }

          hasChanged = true;
          return { ...panel, position };
        });

        return hasChanged ? nextPanels : currentPanels;
      });
    },
    [],
  );

  useEffect(() => {
    const applyMentionNameType = (element: HTMLElement) => {
      if (element.getAttribute('data-lexical-mention-kind') !== 'mention') {
        element.removeAttribute('data-lexical-mention-name-type');
        return;
      }

      const mentionId = element.getAttribute('data-lexical-mention-id');
      const mention =
        mentionId !== null ? mentionNameById.get(mentionId) : undefined;

      if (mention === undefined) {
        element.removeAttribute('data-lexical-mention-name-type');
        return;
      }

      element.setAttribute(
        'data-lexical-mention-name-type',
        normalizeMentionNameType(mention.type),
      );
    };

    return editor.registerMutationListener(
      MentionNode,
      (mutations) => {
        editor.getEditorState().read(() => {
          for (const [key, mutation] of mutations) {
            if (mutation === 'destroyed') {
              continue;
            }

            const element = editor.getElementByKey(key);

            if (element instanceof HTMLElement) {
              applyMentionNameType(element);
            }
          }
        });
      },
      { skipInitialization: false },
    );
  }, [editor]);

  useEffect(() => {
    const handleMentionIconPointerDown = (event: PointerEvent) => {
      if (event.button !== 0) {
        return;
      }

      const mentionElement = getMentionNameElement(event.target);

      if (
        mentionElement === null ||
        !isMentionIconPointerEvent(event, mentionElement)
      ) {
        return;
      }

      const mention = getMentionNamePreview(mentionElement);

      if (mention === null) {
        return;
      }

      openAdvancedPanel(mention, mentionElement);
      event.preventDefault();
      event.stopPropagation();
    };

    document.addEventListener(
      'pointerdown',
      handleMentionIconPointerDown,
      true,
    );

    return () => {
      document.removeEventListener(
        'pointerdown',
        handleMentionIconPointerDown,
        true,
      );
    };
  }, [openAdvancedPanel]);

  useEffect(() => {
    const handleOpenPersonAdvancedPanel = (event: Event) => {
      const detail = (
        event as CustomEvent<OpenMentionPersonAdvancedPanelDetail>
      ).detail;

      if (
        typeof detail !== 'object' ||
        detail === null ||
        !(detail.anchorElement instanceof HTMLElement)
      ) {
        return;
      }

      const mentionPerson = getMentionNamePreviewFromOpenDetail(detail);

      if (mentionPerson === null) {
        return;
      }

      openAdvancedPanel(mentionPerson, detail.anchorElement);
    };

    window.addEventListener(
      OPEN_MENTION_PERSON_ADVANCED_PANEL_EVENT,
      handleOpenPersonAdvancedPanel,
    );

    return () => {
      window.removeEventListener(
        OPEN_MENTION_PERSON_ADVANCED_PANEL_EVENT,
        handleOpenPersonAdvancedPanel,
      );
    };
  }, [openAdvancedPanel]);

  useEffect(() => {
    const handleMouseOver = (event: MouseEvent) => {
      const hoverCardElement = getMentionNameHoverCardElement(event.target);

      if (hoverCardElement !== null) {
        clearHoverCardHideTimeout();
        return;
      }

      const mentionElement = getMentionNameElement(event.target);
      const previousMentionElement = getMentionNameElement(event.relatedTarget);

      if (mentionElement === null) {
        return;
      }

      if (mentionElement === hoveredMentionNameElement) {
        clearHoverCardHideTimeout();
        return;
      }

      if (mentionElement === previousMentionElement) {
        return;
      }

      const mention = getMentionNamePreview(mentionElement);

      if (mention === null) {
        return;
      }

      hideHoverCard();
      hoverCardShowTimeoutRef.current = window.setTimeout(() => {
        setHoveredMentionNameElement(mentionElement);
        setHoveredMentionPerson(mention);
        hoverCardShowTimeoutRef.current = null;
      }, HOVER_CARD_DELAY_MS);
    };

    const handleMouseOut = (event: MouseEvent) => {
      const mentionElement = getMentionNameElement(event.target);
      const hoverCardElement = getMentionNameHoverCardElement(event.target);
      const nextMentionElement = getMentionNameElement(event.relatedTarget);
      const nextHoverCardElement = getMentionNameHoverCardElement(
        event.relatedTarget,
      );

      if (mentionElement === null && hoverCardElement === null) {
        return;
      }

      if (nextMentionElement !== null || nextHoverCardElement !== null) {
        clearHoverCardHideTimeout();
        return;
      }

      scheduleHideHoverCard();
    };

    document.addEventListener('mouseover', handleMouseOver);
    document.addEventListener('mouseout', handleMouseOut);

    return () => {
      clearHoverCardShowTimeout();
      clearHoverCardHideTimeout();
      document.removeEventListener('mouseover', handleMouseOver);
      document.removeEventListener('mouseout', handleMouseOut);
    };
  }, [
    clearHoverCardHideTimeout,
    clearHoverCardShowTimeout,
    hideHoverCard,
    hoveredMentionNameElement,
    scheduleHideHoverCard,
  ]);

  useEffect(() => {
    if (hoveredMentionNameElement === null) {
      setHoverCardStyle(null);
      return;
    }

    const updateHoverCardStyle = () => {
      if (!hoveredMentionNameElement.isConnected) {
        hideHoverCard();
        setHoverCardStyle(null);
        return;
      }

      setHoverCardStyle(getHoverCardStyle(hoveredMentionNameElement));
    };

    updateHoverCardStyle();
    window.addEventListener('resize', updateHoverCardStyle);
    window.addEventListener('scroll', updateHoverCardStyle, true);

    return () => {
      window.removeEventListener('resize', updateHoverCardStyle);
      window.removeEventListener('scroll', updateHoverCardStyle, true);
    };
  }, [hideHoverCard, hoveredMentionNameElement]);

  return (
    <>
      <LexicalTypeaheadMenuPlugin<MentionNameTypeaheadOption>
        onQueryChange={setQueryString}
        onSelectOption={onSelectOption}
        triggerFn={checkForMentionNameMatch}
        options={options}
        menuRenderFn={(
          anchorElementRef,
          { selectedIndex, selectOptionAndCleanUp, setHighlightedIndex },
        ) =>
          anchorElementRef.current && results.length
            ? ReactDOM.createPortal(
                <div className="typeahead-popover mention-name-menu">
                  <ul className="list-unstyled m-0 p-0">
                    {options.map((option, i: number) => (
                      <MentionNameTypeaheadMenuItem
                        index={i}
                        isSelected={selectedIndex === i}
                        onClick={() => {
                          setHighlightedIndex(i);
                          selectOptionAndCleanUp(option);
                        }}
                        onMouseEnter={() => {
                          setHighlightedIndex(i);
                        }}
                        key={option.key}
                        option={option}
                      />
                    ))}
                  </ul>
                </div>,
                anchorElementRef.current,
              )
            : null
        }
      />
      {hoveredMentionPerson !== null && hoverCardStyle !== null
        ? ReactDOM.createPortal(
            <div
              className="mention-hover-card"
              data-mention-name-hover-card="true"
              role="tooltip"
              style={hoverCardStyle}
              tabIndex={0}
              onClick={(event) => {
                if (isMentionNameInteractiveTarget(event.target)) {
                  return;
                }

                if (hoveredMentionNameElement !== null) {
                  openAdvancedPanel(
                    hoveredMentionPerson,
                    hoveredMentionNameElement,
                  );
                }
              }}
              onKeyDown={(event) => {
                if (
                  (event.key === 'Enter' || event.key === ' ') &&
                  hoveredMentionNameElement !== null &&
                  !isMentionNameInteractiveTarget(event.target)
                ) {
                  openAdvancedPanel(
                    hoveredMentionPerson,
                    hoveredMentionNameElement,
                  );
                  event.preventDefault();
                }
              }}
            >
              <div className="mention-hover-card__name d-inline-flex align-items-center gap-2">
                <i
                  className={getMentionNameTypeIconClass(
                    hoveredMentionPerson.type,
                  )}
                  aria-hidden="true"
                />
                <span className="mention-hover-card__name-text">
                  {hoveredMentionPerson.name}
                </span>
                <button
                  aria-label="Copy mentioned person name"
                  className="mention-hover-card__copy"
                  title="Copy name"
                  type="button"
                  onClick={(event) => {
                    event.preventDefault();
                    event.stopPropagation();
                    void copyTextToClipboard(hoveredMentionPerson.name);
                  }}
                >
                  <i className="bi bi-copy" aria-hidden="true" />
                </button>
              </div>
              {hoveredMentionPerson.title ? (
                <div className="mention-hover-card__title">
                  <MentionReferenceText value={hoveredMentionPerson.title} />
                </div>
              ) : null}
              <MentionNameBasicInfo
                includeTitle={false}
                mentionPerson={hoveredMentionPerson}
              />
              <MentionNameDetails
                includeTitle={false}
                mentionPerson={hoveredMentionPerson}
                onOpenPersonReference={openAdvancedPanel}
              />
            </div>,
            document.body,
          )
        : null}
      {advancedPanels.map((panel) => (
        <MentionAdvancedPanel
          anchorElement={panel.anchorElement}
          copyLabel="Copy mentioned person details"
          iconClassName={getMentionNameTypeIconClass(panel.type)}
          key={panel.panelKey}
          name={panel.name}
          panelKind="mentioned person"
          position={panel.position}
          title={
            <>
              <MentionNameBasicInfo mentionPerson={panel} />
              <MentionNameDetails
                mentionPerson={panel}
                onOpenPersonReference={openAdvancedPanel}
              />
            </>
          }
          zIndex={panel.zIndex}
          onCopy={async () => {
            const { plainText, html } = await buildMentionPersonSummary(
              panel,
              resolveVerseLabel,
            );
            return copyMentionRecordToClipboard(plainText, html);
          }}
          onBringToFront={() => {
            bringAdvancedPanelToFront(panel.panelKey);
          }}
          onClose={() => {
            closeAdvancedPanel(panel.panelKey);
          }}
          onPositionChange={(position) => {
            updateAdvancedPanelPosition(panel.panelKey, position);
          }}
        />
      ))}
    </>
  );
}
