import type { CSSProperties, JSX } from 'react';
import { useEffect, useState } from 'react';

import { useBibleVerseActions } from '../context/BibleVerseActionsContext';
import { dispatchOpenMentionBibleVerseAdvancedPanelEvent } from './MentionBibleVersesPlugin/openBibleVerseAdvancedPanelEvent';

type MentionVerseTitle = { label: string; style?: CSSProperties };

export default function MentionVerseReferenceList({
  buttonClassName,
  enabled = true,
  listClassName,
  values,
}: {
  buttonClassName: string;
  enabled?: boolean;
  listClassName: string;
  values: ReadonlyArray<string>;
}): JSX.Element {
  const { shortToVerseData } = useBibleVerseActions();
  const [titles, setTitles] = useState<Record<string, MentionVerseTitle>>({});

  useEffect(() => {
    if (!enabled || shortToVerseData === undefined) {
      return;
    }

    let isActive = true;

    void Promise.all(
      values.map(async (value) => {
        try {
          const data = await shortToVerseData(value);
          return [
            value,
            { label: data?.title ?? value, style: data?.style },
          ] as const;
        } catch {
          return [value, { label: value }] as const;
        }
      }),
    ).then((entries) => {
      if (isActive) {
        setTitles(Object.fromEntries(entries));
      }
    });

    return () => {
      isActive = false;
    };
  }, [enabled, shortToVerseData, values]);

  return (
    <ul className={listClassName}>
      {values.map((value) => {
        const title = titles[value];
        const label = title?.label ?? value;

        return (
          <li key={value}>
            <button
              className={buttonClassName}
              style={title?.style}
              type="button"
              onClick={(event) => {
                event.preventDefault();
                event.stopPropagation();
                dispatchOpenMentionBibleVerseAdvancedPanelEvent({
                  anchorElement: event.currentTarget,
                  shortVerse: value,
                });
              }}
            >
              {label}
            </button>
          </li>
        );
      })}
    </ul>
  );
}
