// Inserted between text runs that belong to different blocks so a query can
// never match across a block boundary (the end of one paragraph and the start
// of the next).
export const BLOCK_SEPARATOR = '\n';

export type FindOptions = {
  caseSensitive: boolean;
  wholeWord: boolean;
};

export type FindMatch = {
  start: number;
  end: number;
};

// One contiguous run of text contributed by a single Lexical text node.
export type SearchSegment = {
  key: string;
  // Offset of the run inside the combined searchable text.
  start: number;
  length: number;
};

// The part of a match that falls inside a single segment. A match has more
// than one slice when it crosses a formatting boundary, as in "**bo**ld".
export type SearchSlice = {
  key: string;
  startOffset: number;
  endOffset: number;
};

const WORD_CHARACTER = /[\p{L}\p{N}_]/u;

/**
 * Lowercases `text` without changing its length, so offsets into the folded
 * string stay valid for the original. A few characters (`İ` for one) lowercase
 * to more than one code unit; those are left alone.
 */
export function foldCase(text: string): string {
  let folded = '';

  for (let index = 0; index < text.length; index++) {
    const character = text[index];
    const lowered = character.toLowerCase();

    folded += lowered.length === 1 ? lowered : character;
  }

  return folded;
}

function isWholeWord(text: string, start: number, end: number): boolean {
  const before = start > 0 ? text[start - 1] : '';
  const after = end < text.length ? text[end] : '';

  return !WORD_CHARACTER.test(before) && !WORD_CHARACTER.test(after);
}

/**
 * Every non-overlapping occurrence of `query` in `text`, in document order.
 */
export function findMatches(
  text: string,
  query: string,
  options: FindOptions,
): FindMatch[] {
  if (query === '') {
    return [];
  }

  const haystack = options.caseSensitive ? text : foldCase(text);
  const needle = options.caseSensitive ? query : foldCase(query);
  const matches: FindMatch[] = [];
  let searchFrom = 0;

  for (;;) {
    const start = haystack.indexOf(needle, searchFrom);

    if (start === -1) {
      return matches;
    }

    const end = start + needle.length;

    if (!options.wholeWord || isWholeWord(haystack, start, end)) {
      matches.push({ end, start });
    }

    searchFrom = end;
  }
}

/**
 * Maps each match back onto the text nodes it covers. Both `segments` and
 * `matches` are in document order, so a single cursor over the segments is
 * enough for the whole list.
 */
export function sliceMatches(
  segments: ReadonlyArray<SearchSegment>,
  matches: ReadonlyArray<FindMatch>,
): SearchSlice[][] {
  const sliced: SearchSlice[][] = [];
  let firstSegmentIndex = 0;

  for (const match of matches) {
    while (
      firstSegmentIndex < segments.length &&
      segments[firstSegmentIndex].start + segments[firstSegmentIndex].length <=
        match.start
    ) {
      firstSegmentIndex++;
    }

    const slices: SearchSlice[] = [];

    for (let index = firstSegmentIndex; index < segments.length; index++) {
      const segment = segments[index];

      if (segment.start >= match.end) {
        break;
      }

      const startOffset = Math.max(match.start - segment.start, 0);
      const endOffset = Math.min(match.end - segment.start, segment.length);

      if (endOffset > startOffset) {
        slices.push({ endOffset, key: segment.key, startOffset });
      }
    }

    sliced.push(slices);
  }

  return sliced;
}

/**
 * The match the user most likely means when the find bar opens: the first one
 * at or after the caret, wrapping back to the top when the caret is past the
 * last match.
 */
export function findMatchIndexAtOrAfter(
  matches: ReadonlyArray<FindMatch>,
  offset: number,
): number {
  const index = matches.findIndex((match) => match.start >= offset);

  return index === -1 ? 0 : index;
}
