function getDocxPageSize(pageSize: PageSizeKey) {
  return getPaperPageSize(pageSize) ?? PAPER_PAGE_SIZES.letter;
}

function formatInches(value: number): string {
  return String(Number(value.toFixed(4)));
}

function getDocxContentSize(pageSize: PageSizeKey) {
  const docxPageSize = getDocxPageSize(pageSize);

  return {
    heightIn: formatInches(
      Math.max(0.1, docxPageSize.heightIn - WORD_PAGE_MARGIN_IN * 2),
    ),
    widthIn: formatInches(
      Math.max(0.1, docxPageSize.widthIn - WORD_PAGE_MARGIN_IN * 2),
    ),
  };
}

