function createCrcTable(): Uint32Array {
  const table = new Uint32Array(256);

  for (let index = 0; index < table.length; index++) {
    let value = index;

    for (let bit = 0; bit < 8; bit++) {
      value = value & 1 ? 0xedb88320 ^ (value >>> 1) : value >>> 1;
    }

    table[index] = value >>> 0;
  }

  return table;
}

function crc32(data: Uint8Array): number {
  let crc = 0xffffffff;

  for (const byte of data) {
    crc = crcTable[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  }

  return (crc ^ 0xffffffff) >>> 0;
}

function encodeText(value: string): Uint8Array {
  return textEncoder.encode(value);
}

function concatChunks(chunks: Uint8Array[]): Uint8Array {
  const length = chunks.reduce((total, chunk) => total + chunk.length, 0);
  const output = new Uint8Array(length);
  let offset = 0;

  for (const chunk of chunks) {
    output.set(chunk, offset);
    offset += chunk.length;
  }

  return output;
}

function createZip(entries: ZipEntry[]): Uint8Array {
  const localFileChunks: Uint8Array[] = [];
  const centralDirectoryChunks: Uint8Array[] = [];
  let localFileOffset = 0;

  for (const entry of entries) {
    const fileNameData = encodeText(entry.name);
    const fileCrc = crc32(entry.data);
    const localHeader = new Uint8Array(30 + fileNameData.length);
    const localHeaderView = new DataView(localHeader.buffer);

    localHeaderView.setUint32(0, 0x04034b50, true);
    localHeaderView.setUint16(4, 20, true);
    localHeaderView.setUint16(6, 0, true);
    localHeaderView.setUint16(8, 0, true);
    localHeaderView.setUint16(10, DOS_TIME_MIDNIGHT, true);
    localHeaderView.setUint16(12, DOS_DATE_JAN_1_1980, true);
    localHeaderView.setUint32(14, fileCrc, true);
    localHeaderView.setUint32(18, entry.data.length, true);
    localHeaderView.setUint32(22, entry.data.length, true);
    localHeaderView.setUint16(26, fileNameData.length, true);
    localHeaderView.setUint16(28, 0, true);
    localHeader.set(fileNameData, 30);

    localFileChunks.push(localHeader, entry.data);

    const centralHeader = new Uint8Array(46 + fileNameData.length);
    const centralHeaderView = new DataView(centralHeader.buffer);

    centralHeaderView.setUint32(0, 0x02014b50, true);
    centralHeaderView.setUint16(4, 20, true);
    centralHeaderView.setUint16(6, 20, true);
    centralHeaderView.setUint16(8, 0, true);
    centralHeaderView.setUint16(10, 0, true);
    centralHeaderView.setUint16(12, DOS_TIME_MIDNIGHT, true);
    centralHeaderView.setUint16(14, DOS_DATE_JAN_1_1980, true);
    centralHeaderView.setUint32(16, fileCrc, true);
    centralHeaderView.setUint32(20, entry.data.length, true);
    centralHeaderView.setUint32(24, entry.data.length, true);
    centralHeaderView.setUint16(28, fileNameData.length, true);
    centralHeaderView.setUint16(30, 0, true);
    centralHeaderView.setUint16(32, 0, true);
    centralHeaderView.setUint16(34, 0, true);
    centralHeaderView.setUint16(36, 0, true);
    centralHeaderView.setUint32(38, 0, true);
    centralHeaderView.setUint32(42, localFileOffset, true);
    centralHeader.set(fileNameData, 46);

    centralDirectoryChunks.push(centralHeader);
    localFileOffset += localHeader.length + entry.data.length;
  }

  const centralDirectory = concatChunks(centralDirectoryChunks);
  const endOfCentralDirectory = new Uint8Array(22);
  const endOfCentralDirectoryView = new DataView(endOfCentralDirectory.buffer);

  endOfCentralDirectoryView.setUint32(0, 0x06054b50, true);
  endOfCentralDirectoryView.setUint16(4, 0, true);
  endOfCentralDirectoryView.setUint16(6, 0, true);
  endOfCentralDirectoryView.setUint16(8, entries.length, true);
  endOfCentralDirectoryView.setUint16(10, entries.length, true);
  endOfCentralDirectoryView.setUint32(12, centralDirectory.length, true);
  endOfCentralDirectoryView.setUint32(16, localFileOffset, true);
  endOfCentralDirectoryView.setUint16(20, 0, true);

  return concatChunks([
    ...localFileChunks,
    centralDirectory,
    endOfCentralDirectory,
  ]);
}

function encodeBase64(data: Uint8Array): string {
  let binary = '';

  for (let index = 0; index < data.length; index += 0x8000) {
    binary += String.fromCharCode(...data.subarray(index, index + 0x8000));
  }

  return btoa(binary)
    .replace(/.{1,76}/g, '$&\r\n')
    .trimEnd();
}

function encodeBase64Inline(data: Uint8Array): string {
  return encodeBase64(data).replace(/\s/g, '');
}

function wrapBase64(value: string): string {
  return value.replace(/.{1,76}/g, '$&\r\n').trimEnd();
}

function escapeXml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function parsePixelValue(value: string | null | undefined): number | null {
  if (!value) {
    return null;
  }

  const match = value.trim().match(/^(-?\d+(?:\.\d+)?)px$/);

  return match ? Number.parseFloat(match[1]) : null;
}

function formatPixelValue(value: number): string {
  return `${Number(value.toFixed(2))}px`;
}

function formatSvgNumber(value: number): string {
  return String(Number(value.toFixed(2)));
}

function isVisibleColor(value: string): boolean {
  return (
    value !== '' && value !== 'transparent' && value !== 'rgba(0, 0, 0, 0)'
  );
}

function getStickyNotePalette(element: HTMLElement): StickyNotePalette {
  const colorClass = Object.keys(STICKY_NOTE_PALETTES).find((className) =>
    element.classList.contains(className),
  );

  return STICKY_NOTE_PALETTES[colorClass ?? 'yellow'];
}

function getStickyNoteText(element: HTMLElement): string {
  return (
    element
      .querySelector<HTMLElement>('.StickyNode__contentEditable')
      ?.textContent?.trim() ||
    element.textContent?.trim() ||
    'Sticky note'
  );
}

function getElementDimension(
  element: HTMLElement,
  propertyName: 'height' | 'width',
  fallback: number,
): number {
  const rect = element.getBoundingClientRect();
  const rectValue = propertyName === 'width' ? rect.width : rect.height;

  if (Number.isFinite(rectValue) && rectValue > 0) {
    return rectValue;
  }

  return (
    parsePixelValue(element.style.getPropertyValue(propertyName)) ??
    parsePixelValue(
      window.getComputedStyle(element).getPropertyValue(propertyName),
    ) ??
    fallback
  );
}

function getStickyNoteOffset(
  container: HTMLElement,
  sourceRootElement: HTMLElement | null | undefined,
  propertyName: 'left' | 'top',
): number {
  const inlineValue = parsePixelValue(
    container.style.getPropertyValue(propertyName),
  );

  if (inlineValue !== null) {
    return inlineValue;
  }

  const computedValue = parsePixelValue(
    window.getComputedStyle(container).getPropertyValue(propertyName),
  );

  if (computedValue !== null) {
    return computedValue;
  }

  if (sourceRootElement) {
    const containerRect = container.getBoundingClientRect();
    const rootRect = sourceRootElement.getBoundingClientRect();
    const offset =
      propertyName === 'left'
        ? containerRect.left - rootRect.left
        : containerRect.top - rootRect.top;

    if (Number.isFinite(offset)) {
      return offset;
    }
  }

  return 0;
}

function wrapStickyNoteText(
  text: string,
  maxCharactersPerLine: number,
): string[] {
  const lines: string[] = [];

  for (const rawLine of text.split(/\r?\n/)) {
    const words = rawLine.trim().split(/\s+/).filter(Boolean);

    if (words.length === 0) {
      lines.push('');
      continue;
    }

    let currentLine = '';

    for (const word of words) {
      if (word.length > maxCharactersPerLine) {
        if (currentLine) {
          lines.push(currentLine);
          currentLine = '';
        }

        for (
          let index = 0;
          index < word.length;
          index += maxCharactersPerLine
        ) {
          lines.push(word.slice(index, index + maxCharactersPerLine));
        }
        continue;
      }

      const nextLine = currentLine ? `${currentLine} ${word}` : word;

      if (nextLine.length > maxCharactersPerLine && currentLine) {
        lines.push(currentLine);
        currentLine = word;
      } else {
        currentLine = nextLine;
      }
    }

    if (currentLine) {
      lines.push(currentLine);
    }
  }

  return lines;
}

function createStickyNoteSvg(element: HTMLElement): string {
  const computedStyle = window.getComputedStyle(element);
  const contentElement =
    element.querySelector<HTMLElement>('.StickyNode__contentEditable') ??
    element;
  const contentStyle = window.getComputedStyle(contentElement);
  const palette = getStickyNotePalette(element);
  const width = getElementDimension(
    element,
    'width',
    DEFAULT_STICKY_NOTE_IMAGE_WIDTH,
  );
  const height = getElementDimension(
    element,
    'height',
    DEFAULT_STICKY_NOTE_IMAGE_HEIGHT,
  );
  const background = isVisibleColor(computedStyle.backgroundColor)
    ? computedStyle.backgroundColor
    : palette.background;
  const border = isVisibleColor(computedStyle.borderLeftColor)
    ? computedStyle.borderLeftColor
    : palette.border;
  const textColor = isVisibleColor(contentStyle.color)
    ? contentStyle.color
    : '#1f2328';
  const fontFamily =
    contentStyle.fontFamily || computedStyle.fontFamily || 'cursive';
  const fontSize =
    parsePixelValue(contentStyle.fontSize) ??
    parsePixelValue(computedStyle.fontSize) ??
    16;
  const lineHeight =
    parsePixelValue(contentStyle.lineHeight) ?? Math.max(fontSize * 1.25, 16);
  const text = getStickyNoteText(element);
  const maxCharactersPerLine = Math.max(
    8,
    Math.floor((width - 28) / (fontSize * 0.56)),
  );
  const maxLines = Math.max(1, Math.floor((height - 34) / lineHeight));
  const textLines = wrapStickyNoteText(text, maxCharactersPerLine).slice(
    0,
    maxLines,
  );

  if (
    textLines.length === maxLines &&
    textLines.join('\n').length < text.length
  ) {
    textLines[textLines.length - 1] =
      `${textLines[textLines.length - 1].replace(/\.{3}$/, '')}...`;
  }

  const ruledLines = Array.from(
    { length: Math.max(0, Math.floor((height - 22) / 8)) },
    (_, index) => 18 + index * 8,
  );
  const noteBodyWidth = Math.max(1, width - 10);
  const noteBodyHeight = Math.max(1, height - 12);
  const curlLeft = Math.max(0, width - 44);
  const curlTop = Math.max(0, height - 42);
  const curlRight = Math.max(0, width - 10);
  const curlBottom = Math.max(0, height - 10);
  const curlInnerLeft = Math.max(0, width - 36);

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${formatPixelValue(width)}" height="${formatPixelValue(height)}" viewBox="0 0 ${formatSvgNumber(width)} ${formatSvgNumber(height)}">
  <defs>
    <filter id="paper-shadow" x="-20%" y="-20%" width="150%" height="160%">
      <feDropShadow dx="0" dy="10" stdDeviation="7" flood-color="#0d141f" flood-opacity="0.18"/>
      <feDropShadow dx="0" dy="1" stdDeviation="1" flood-color="#0d141f" flood-opacity="0.15"/>
    </filter>
    <linearGradient id="paper-highlight" x1="0" x2="0" y1="0" y2="1">
      <stop offset="0" stop-color="#ffffff" stop-opacity="0.42"/>
      <stop offset="0.34" stop-color="#ffffff" stop-opacity="0.06"/>
      <stop offset="1" stop-color="#372400" stop-opacity="0.1"/>
    </linearGradient>
  </defs>
  <rect x="1" y="1" width="${formatSvgNumber(noteBodyWidth)}" height="${formatSvgNumber(noteBodyHeight)}" rx="4" fill="${escapeXml(background)}" stroke="${escapeXml(border)}" filter="url(#paper-shadow)"/>
  <rect x="1" y="1" width="${formatSvgNumber(noteBodyWidth)}" height="${formatSvgNumber(noteBodyHeight)}" rx="4" fill="url(#paper-highlight)" opacity="0.9"/>
  ${ruledLines
    .map(
      (lineY) =>
        `<line x1="8" x2="${formatSvgNumber(Math.max(8, width - 14))}" y1="${formatSvgNumber(lineY)}" y2="${formatSvgNumber(lineY)}" stroke="${escapeXml(palette.fiber)}" stroke-width="1"/>`,
    )
    .join('\n  ')}
  <path d="M ${formatSvgNumber(curlLeft)} ${formatSvgNumber(curlTop)} L ${formatSvgNumber(curlRight)} ${formatSvgNumber(curlBottom)} L ${formatSvgNumber(curlInnerLeft)} ${formatSvgNumber(curlBottom)} Z" fill="${escapeXml(palette.curl)}" opacity="0.82"/>
  <text x="12" y="${formatSvgNumber(Math.max(18, fontSize + 10))}" fill="${escapeXml(textColor)}" font-family="${escapeXml(fontFamily)}" font-size="${formatSvgNumber(fontSize)}">
    ${textLines
      .map(
        (line, index) =>
          `<tspan x="12" dy="${index === 0 ? 0 : formatSvgNumber(lineHeight)}">${escapeXml(line)}</tspan>`,
      )
      .join('\n    ')}
  </text>
</svg>`;
}

function escapeAttribute(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function formatDataAttributeName(name: string): string {
  return name.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);
}

function buildBodyAttributes(context: WordExportContext = {}): string {
  const bodyClassName = context.bodyClassName ?? 'playground-theme-light';
  const bodyDataset = { bsTheme: 'light', ...context.bodyDataset };
  const classAttribute = bodyClassName
    ? ` class="${escapeAttribute(bodyClassName)}"`
    : '';
  const dataAttributes = Object.entries(bodyDataset)
    .map(
      ([name, value]) =>
        ` data-${formatDataAttributeName(name)}="${escapeAttribute(value)}"`,
    )
    .join('');

  return `${classAttribute}${dataAttributes}`;
}

function normalizeEditorHtmlForWord(editorHtml: string): string {
  const trimmedEditorHtml = editorHtml.trim();
  const normalizedHtml =
    trimmedEditorHtml.includes('ContentEditable__root') ||
    trimmedEditorHtml.includes('editor-scroller')
      ? trimmedEditorHtml
      : `<div class="editor-scroller"><div class="editor"><div class="ContentEditable__root">${trimmedEditorHtml}</div></div></div>`;

  return convertStickyNotesInHtml(normalizedHtml);
}

function copyComputedLayoutStyles(
  sourceElement: HTMLElement,
  targetElement: HTMLElement,
): void {
  const computedStyle = window.getComputedStyle(sourceElement);

  for (const propertyName of ['font-family']) {
    const value = computedStyle.getPropertyValue(propertyName);

    if (value) {
      targetElement.style.setProperty(propertyName, value);
    }
  }
}

function copyComputedContentStyles(
  sourceElement: HTMLElement,
  targetElement: HTMLElement,
): void {
  const computedStyle = window.getComputedStyle(sourceElement);

  for (const propertyName of ['font-family', 'font-size', 'line-height']) {
    const value = computedStyle.getPropertyValue(propertyName);

    if (value) {
      targetElement.style.setProperty(propertyName, value);
    }
  }

  targetElement.style.backgroundColor = '#fff';
  targetElement.style.backgroundImage = 'none';
  targetElement.style.border = '0';
  targetElement.style.boxShadow = 'none';
  targetElement.style.color = '#111827';
  targetElement.style.padding = '0';
  targetElement.style.width = '';
  targetElement.style.minHeight = '';
}

function getStickyNoteImageSource(element: HTMLElement): string {
  return `data:image/svg+xml;base64,${encodeBase64Inline(
    encodeText(createStickyNoteSvg(element)),
  )}`;
}

function createStickyNoteImageElement(
  cloneContainer: HTMLElement,
  sourceContainer: HTMLElement,
  sourceRootElement?: HTMLElement | null,
): HTMLImageElement | null {
  const sourceNote = sourceContainer.querySelector<HTMLElement>('.sticky-note');
  const cloneNote = cloneContainer.querySelector<HTMLElement>('.sticky-note');
  const noteElement = sourceNote ?? cloneNote;

  if (!noteElement) {
    return null;
  }

  const width = getElementDimension(
    noteElement,
    'width',
    DEFAULT_STICKY_NOTE_IMAGE_WIDTH,
  );
  const height = getElementDimension(
    noteElement,
    'height',
    DEFAULT_STICKY_NOTE_IMAGE_HEIGHT,
  );
  const left = getStickyNoteOffset(sourceContainer, sourceRootElement, 'left');
  const top = getStickyNoteOffset(sourceContainer, sourceRootElement, 'top');
  const zIndex =
    sourceContainer.style.zIndex ||
    window.getComputedStyle(sourceContainer).zIndex ||
    cloneContainer.style.zIndex ||
    window.getComputedStyle(cloneContainer).zIndex;
  const image = document.createElement('img');
  const styleDeclarations = [
    'position:absolute',
    `left:${formatPixelValue(left)}`,
    `top:${formatPixelValue(top)}`,
    `width:${formatPixelValue(width)}`,
    `height:${formatPixelValue(height)}`,
    'border:0',
    'max-width:none',
    'mso-position-horizontal-relative:text',
    'mso-position-vertical-relative:text',
    'mso-wrap-style:square',
  ];

  if (zIndex && zIndex !== 'auto') {
    styleDeclarations.push(`z-index:${zIndex}`);
  }

  image.className = 'docx-sticky-note-image';
  image.src = getStickyNoteImageSource(noteElement);
  image.alt = `Sticky note: ${getStickyNoteText(noteElement)}`;
  image.setAttribute('width', String(Math.round(width)));
  image.setAttribute('height', String(Math.round(height)));
  image.setAttribute('style', styleDeclarations.join('; '));

  return image;
}

function convertStickyNotesToImages(
  root: ParentNode,
  sourceRootElement?: HTMLElement | null,
): void {
  const cloneContainers = Array.from(
    root.querySelectorAll<HTMLElement>('.sticky-note-container'),
  );
  const sourceScope =
    sourceRootElement?.closest<HTMLElement>('.editor-scroller') ??
    sourceRootElement;
  const sourceContainers = sourceScope
    ? Array.from(
        sourceScope.querySelectorAll<HTMLElement>('.sticky-note-container'),
      )
    : [];

  cloneContainers.forEach((cloneContainer, index) => {
    const sourceContainer = sourceContainers[index] ?? cloneContainer;
    const image = createStickyNoteImageElement(
      cloneContainer,
      sourceContainer,
      sourceRootElement,
    );

    if (image) {
      cloneContainer.replaceWith(image);
    }
  });
}

function convertStickyNotesInHtml(html: string): string {
  const template = document.createElement('template');

  template.innerHTML = html;
  convertStickyNotesToImages(template.content);

  return template.innerHTML;
}

function prepareWordExportClone(
  clone: HTMLElement,
  sourceRootElement: HTMLElement,
): void {
  const sourceScroller =
    sourceRootElement.closest<HTMLElement>('.editor-scroller');
  const cloneScroller = clone.matches('.editor-scroller')
    ? clone
    : clone.querySelector<HTMLElement>('.editor-scroller');
  const cloneRootElement = clone.matches('.ContentEditable__root')
    ? clone
    : clone.querySelector<HTMLElement>('.ContentEditable__root');

  if (sourceScroller && cloneScroller) {
    copyComputedLayoutStyles(sourceScroller, cloneScroller);
  }

  if (cloneRootElement) {
    copyComputedContentStyles(sourceRootElement, cloneRootElement);
  }

  convertStickyNotesToImages(clone, sourceRootElement);

  clone
    .querySelectorAll<HTMLElement>('[contenteditable]')
    .forEach((element) => {
      element.removeAttribute('contenteditable');
      element.removeAttribute('spellcheck');
      element.removeAttribute('role');
      element.removeAttribute('aria-autocomplete');
      element.removeAttribute('aria-describedby');
      element.removeAttribute('aria-multiline');
    });

  clone
    .querySelectorAll<HTMLElement>(DOCX_EDITING_ONLY_SELECTOR)
    .forEach((element) => element.remove());
}

function getVisibleEditorHtml(editor: LexicalEditor): string | null {
  const rootElement = editor.getRootElement();

  if (!rootElement) {
    return null;
  }

  const sourceElement =
    rootElement.closest<HTMLElement>('.editor-scroller') ?? rootElement;
  const clone = sourceElement.cloneNode(true) as HTMLElement;

  prepareWordExportClone(clone, rootElement);

  return clone.outerHTML;
}

function getLightWordBodyClassName(): string {
  const bodyClassList = Array.from(document.body.classList).filter(
    (className) =>
      className !== 'playground-theme-dark' && className !== 'dark',
  );

  if (!bodyClassList.includes('playground-theme-light')) {
    bodyClassList.push('playground-theme-light');
  }

  return bodyClassList.join(' ');
}

function getLightWordBodyDataset(): Record<string, string> {
  return { ...document.body.dataset, bsTheme: 'light' };
}

function getEditorStateHtml(editor: LexicalEditor): string {
  return editor
    .getEditorState()
    .read(() => $generateHtmlFromNodes(editor, null));
}

