function extractMhtmlResources(html: string): {
  html: string;
  resources: MhtmlResource[];
} {
  const resources: MhtmlResource[] = [];
  const htmlWithResourceLocations = html.replace(
    /src="data:(image\/svg\+xml);base64,([^"\s]+)"/g,
    (_match, contentType: string, encodedData: string) => {
      const contentLocation = `word-export-sticky-note-${resources.length + 1}.svg`;

      resources.push({
        contentLocation,
        contentType,
        encodedData: encodedData.replace(/\s/g, ''),
      });

      return `src="${contentLocation}"`;
    },
  );

  return { html: htmlWithResourceLocations, resources };
}

function buildMhtmlDocument(html: string): string {
  const boundary = '----=_NextPart_LexicalDocxExport';
  const { html: htmlWithResourceLocations, resources } =
    extractMhtmlResources(html);
  const encodedHtml = encodeBase64(encodeText(htmlWithResourceLocations));

  return [
    'MIME-Version: 1.0',
    `Content-Type: multipart/related; boundary="${boundary}"; type="text/html"`,
    '',
    `--${boundary}`,
    'Content-Type: text/html; charset="utf-8"',
    'Content-Transfer-Encoding: base64',
    'Content-Location: file:///lexical-document.html',
    '',
    encodedHtml,
    ...resources.flatMap((resource) => [
      `--${boundary}`,
      `Content-Type: ${resource.contentType}`,
      'Content-Transfer-Encoding: base64',
      `Content-Location: ${resource.contentLocation}`,
      '',
      wrapBase64(resource.encodedData),
    ]),
    `--${boundary}--`,
  ].join('\r\n');
}

function createDocxFileName(): string {
  return `BibleNote ${new Date().toISOString().replace(/[:.]/g, '-')}.docx`;
}

function downloadBlob(blob: Blob, fileName: string): void {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');

  anchor.href = url;
  anchor.download = fileName;
  anchor.style.display = 'none';
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 0);
}

export function createWordDocxBlob(
  editorHtml: string,
  pageSize: PageSizeKey = 'web',
  context?: WordExportContext,
): Blob {
  const wordHtml = buildWordHtml(editorHtml, pageSize, context);
  const mhtmlDocument = buildMhtmlDocument(wordHtml);
  const docxBytes = createZip([
    { name: '[Content_Types].xml', data: encodeText(contentTypesXml) },
    { name: '_rels/.rels', data: encodeText(packageRelsXml) },
    { name: 'word/document.xml', data: encodeText(buildDocumentXml(pageSize)) },
    { name: 'word/_rels/document.xml.rels', data: encodeText(documentRelsXml) },
    { name: 'word/afchunk.mht', data: encodeText(mhtmlDocument) },
  ]);

  return new Blob([docxBytes as any], { type: DOCX_MIME_TYPE });
}

export function exportEditorStateAsDocx(
  editor: LexicalEditor,
  pageSize: PageSizeKey = 'web',
): void {
  const editorHtml = getVisibleEditorHtml(editor) ?? getEditorStateHtml(editor);

  downloadBlob(
    createWordDocxBlob(editorHtml, pageSize, {
      bodyClassName: getLightWordBodyClassName(),
      bodyDataset: getLightWordBodyDataset(),
    }),
    createDocxFileName(),
  );
}
