import {
  type Comment,
  type Comments,
  normalizeThreadQuoteSegments,
  type Thread,
} from './commenting';
import { getBibleNoteStorage } from './storageManager';

export const COMMENTS_LOCAL_STORAGE_KEY = 'lexical-playground-comments';
export const COMMENTS_PANEL_OPEN_LOCAL_STORAGE_KEY =
  'lexical-playground-comments-panel-open';

export function getStoredComments(): Comments {
  const storage = getCommentStorage();

  if (storage === null) {
    return [];
  }

  const serializedComments = storage.getItem(COMMENTS_LOCAL_STORAGE_KEY);

  if (serializedComments === null) {
    return [];
  }

  const normalizedComments = normalizeSerializedComments(serializedComments);

  if (normalizedComments === null) {
    storage.removeItem(COMMENTS_LOCAL_STORAGE_KEY);
    return [];
  }

  if (normalizedComments !== serializedComments) {
    storage.setItem(COMMENTS_LOCAL_STORAGE_KEY, normalizedComments);
  }

  return JSON.parse(normalizedComments) as Comments;
}

export function writeStoredComments(comments: Comments): void {
  const storage = getCommentStorage();

  if (storage === null) {
    return;
  }

  const normalizedComments = normalizeComments(comments);

  if (normalizedComments === null || normalizedComments.length === 0) {
    storage.removeItem(COMMENTS_LOCAL_STORAGE_KEY);
    return;
  }

  storage.setItem(
    COMMENTS_LOCAL_STORAGE_KEY,
    JSON.stringify(normalizedComments),
  );
}

export function getStoredCommentsPanelOpen(): boolean {
  const storage = getCommentStorage();

  if (storage === null) {
    return false;
  }

  const serializedPanelOpenState = storage.getItem(
    COMMENTS_PANEL_OPEN_LOCAL_STORAGE_KEY,
  );

  if (serializedPanelOpenState === null) {
    return false;
  }

  const normalizedPanelOpenState = normalizeSerializedPanelOpenState(
    serializedPanelOpenState,
  );

  if (normalizedPanelOpenState === null) {
    storage.removeItem(COMMENTS_PANEL_OPEN_LOCAL_STORAGE_KEY);
    return false;
  }

  if (normalizedPanelOpenState !== serializedPanelOpenState) {
    storage.setItem(
      COMMENTS_PANEL_OPEN_LOCAL_STORAGE_KEY,
      normalizedPanelOpenState,
    );
  }

  return normalizedPanelOpenState === 'true';
}

export function writeStoredCommentsPanelOpen(isOpen: boolean): void {
  const storage = getCommentStorage();

  if (storage === null) {
    return;
  }

  storage.setItem(
    COMMENTS_PANEL_OPEN_LOCAL_STORAGE_KEY,
    JSON.stringify(isOpen),
  );
}

export function clearStoredComments(): void {
  const storage = getCommentStorage();

  if (storage === null) {
    return;
  }

  storage.removeItem(COMMENTS_LOCAL_STORAGE_KEY);
  storage.removeItem(COMMENTS_PANEL_OPEN_LOCAL_STORAGE_KEY);
}

function getCommentStorage(): Storage | null {
  return getBibleNoteStorage() as Storage | null;
}

function normalizeSerializedComments(
  serializedComments: string,
): null | string {
  try {
    const parsedComments: unknown = JSON.parse(serializedComments);
    const normalizedComments = normalizeComments(parsedComments);

    return normalizedComments === null
      ? null
      : JSON.stringify(normalizedComments);
  } catch {
    return null;
  }
}

function normalizeSerializedPanelOpenState(
  serializedPanelOpenState: string,
): null | string {
  try {
    const parsedPanelOpenState: unknown = JSON.parse(serializedPanelOpenState);

    return typeof parsedPanelOpenState === 'boolean'
      ? JSON.stringify(parsedPanelOpenState)
      : null;
  } catch {
    return null;
  }
}

function normalizeComments(value: unknown): null | Comments {
  if (!Array.isArray(value)) {
    return null;
  }

  const normalizedComments: Comments = [];

  for (let i = 0; i < value.length; i++) {
    const normalizedCommentOrThread = normalizeCommentOrThread(value[i]);

    if (normalizedCommentOrThread === null) {
      return null;
    }

    normalizedComments.push(normalizedCommentOrThread);
  }

  return normalizedComments;
}

function normalizeCommentOrThread(value: unknown): null | Comment | Thread {
  const record = asRecord(value);

  if (record === null) {
    return null;
  }

  return record.type === 'thread'
    ? normalizeThread(record)
    : record.type === 'comment'
      ? normalizeComment(record)
      : null;
}

function normalizeComment(value: unknown): null | Comment {
  const record = asRecord(value);

  if (
    record === null ||
    typeof record.author !== 'string' ||
    typeof record.content !== 'string' ||
    typeof record.deleted !== 'boolean' ||
    typeof record.id !== 'string' ||
    typeof record.timeStamp !== 'number' ||
    !Number.isFinite(record.timeStamp) ||
    record.type !== 'comment'
  ) {
    return null;
  }

  return {
    author: record.author,
    content: record.content,
    deleted: record.deleted,
    id: record.id,
    timeStamp: record.timeStamp,
    type: 'comment',
  };
}

function normalizeThread(value: Record<string, unknown>): null | Thread {
  if (
    !Array.isArray(value.comments) ||
    typeof value.id !== 'string' ||
    typeof value.quote !== 'string' ||
    value.type !== 'thread'
  ) {
    return null;
  }

  const normalizedReplies: Array<Comment> = [];

  for (let i = 0; i < value.comments.length; i++) {
    const normalizedComment = normalizeComment(value.comments[i]);

    if (normalizedComment === null) {
      return null;
    }

    normalizedReplies.push(normalizedComment);
  }

  const quoteSegments = normalizeThreadQuoteSegments(value.quoteSegments);

  return {
    comments: normalizedReplies,
    id: value.id,
    quote: value.quote,
    ...(quoteSegments === undefined ? {} : { quoteSegments }),
    type: 'thread',
  };
}

function asRecord(value: unknown): null | Record<string, unknown> {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return null;
  }

  return value as Record<string, unknown>;
}
