export const OPEN_MENTION_BIBLE_VERSE_ADVANCED_PANEL_EVENT =
  'bible-note:open-mention-bible-verse-advanced-panel';

export type OpenMentionBibleVerseAdvancedPanelDetail = {
  anchorElement: HTMLElement;
  shortVerse: string;
};

export function dispatchOpenMentionBibleVerseAdvancedPanelEvent(
  detail: OpenMentionBibleVerseAdvancedPanelDetail,
): void {
  window.dispatchEvent(
    new CustomEvent<OpenMentionBibleVerseAdvancedPanelDetail>(
      OPEN_MENTION_BIBLE_VERSE_ADVANCED_PANEL_EVENT,
      { detail },
    ),
  );
}
