export const OPEN_MENTION_LOCATION_ADVANCED_PANEL_EVENT =
  'bible-note:open-mention-location-advanced-panel';

export type OpenMentionLocationAdvancedPanelDetail = {
  anchorElement: HTMLElement;
  id: string | null;
  name: string;
};

export function dispatchOpenMentionLocationAdvancedPanelEvent(
  detail: OpenMentionLocationAdvancedPanelDetail,
): void {
  window.dispatchEvent(
    new CustomEvent<OpenMentionLocationAdvancedPanelDetail>(
      OPEN_MENTION_LOCATION_ADVANCED_PANEL_EVENT,
      { detail },
    ),
  );
}
