export type PageSizeKey =
  | 'web'
  | 'a4'
  | 'a4Landscape'
  | 'a5'
  | 'a5Landscape'
  | 'a3'
  | 'a3Landscape'
  | 'letter'
  | 'letterLandscape'
  | 'legal'
  | 'legalLandscape'
  | 'tabloid'
  | 'tabloidLandscape'
  | 'size1024x768'
  | 'size1280x720';

export type PaperPageSizeKey = Exclude<PageSizeKey, 'web'>;

type PaperPageOrientation = 'portrait' | 'landscape';

type PaperPageSize = {
  cssSize: string;
  heightIn: number;
  heightTwips: number;
  key: PaperPageSizeKey;
  label: string;
  orientation: PaperPageOrientation;
  widthIn: number;
  widthTwips: number;
};

type WebPageSize = {
  key: 'web';
  label: string;
};

export type PageSize = PaperPageSize | WebPageSize;

export const WEB_PAGE_SIZE: WebPageSize = {
  key: 'web',
  label: 'Web view',
};

function createPortraitPageSize(
  pageSize: Omit<PaperPageSize, 'orientation'>,
): PaperPageSize {
  return { ...pageSize, orientation: 'portrait' };
}

function createLandscapePageSize(
  portraitPageSize: PaperPageSize,
  key: PaperPageSizeKey,
): PaperPageSize {
  return {
    cssSize: `${portraitPageSize.cssSize} landscape`,
    heightIn: portraitPageSize.widthIn,
    heightTwips: portraitPageSize.widthTwips,
    key,
    label: `${portraitPageSize.label} landscape`,
    orientation: 'landscape',
    widthIn: portraitPageSize.heightIn,
    widthTwips: portraitPageSize.heightTwips,
  };
}

