export const PAGE_SIZE_OPTIONS: PageSize[] = [
  WEB_PAGE_SIZE,
  PAPER_PAGE_SIZES.a4,
  PAPER_PAGE_SIZES.a4Landscape,
  PAPER_PAGE_SIZES.a5,
  PAPER_PAGE_SIZES.a5Landscape,
  PAPER_PAGE_SIZES.a3,
  PAPER_PAGE_SIZES.a3Landscape,
  PAPER_PAGE_SIZES.letter,
  PAPER_PAGE_SIZES.letterLandscape,
  PAPER_PAGE_SIZES.legal,
  PAPER_PAGE_SIZES.legalLandscape,
  PAPER_PAGE_SIZES.tabloid,
  PAPER_PAGE_SIZES.tabloidLandscape,
  PAPER_PAGE_SIZES.size1024x768,
  PAPER_PAGE_SIZES.size1280x720,
];

export function getPageSize(pageSize: PageSizeKey): PageSize {
  return pageSize === 'web' ? WEB_PAGE_SIZE : PAPER_PAGE_SIZES[pageSize];
}

export function getPaperPageSize(pageSize: PageSizeKey): PaperPageSize | null {
  return pageSize === 'web' ? null : PAPER_PAGE_SIZES[pageSize];
}

export function getPageSizeOptions(): PageSize[] {
  return PAGE_SIZE_OPTIONS;
}

export function isPageSizeKey(value: unknown): value is PageSizeKey {
  return (
    typeof value === 'string' &&
    PAGE_SIZE_OPTIONS.some((pageSize) => pageSize.key === value)
  );
}
