import type { JSX } from 'react';
import type { BibleNoteColorScheme } from './params/colorScheme';

import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { CAN_USE_BEFORE_INPUT } from '@lexical/utils';
import { useEffect, useMemo, useState } from 'react';

import {
  DEFAULT_SETTINGS,
  hasSettingOverrides,
  INITIAL_SETTINGS,
  isDevPlayground,
} from './appSettings';
import { clearStoredComments } from './commentStorage';
import { useSettings } from './context/SettingsContext';
import { clearStoredEditorState } from './editorStateStorage';
import { resetPlaygroundEditorContent } from './playgroundEditorState';
import Switch from './ui/Switch';

type SettingsProps = {
  onColorSchemeChange?: (mode: BibleNoteColorScheme) => void;
};

export default function Settings({
  onColorSchemeChange,
}: SettingsProps = {}): JSX.Element {
  const windowLocation = window.location;
  const [editor] = useLexicalComposerContext();
  const { resetOptions, setOption, settings } = useSettings();
  const {
    measureTypingPerf,
    isDarkMode,
    isRichText,
    hasNestedTables,
    isMaxLength,
    hasLinkAttributes,
    isCharLimit,
    isCharLimitUtf8,
    isAutocomplete,
    showTreeView,
    showNestedEditorTreeView,
    // disableBeforeInput,
    showTableOfContents,
    shouldUseLexicalContextMenu,
    shouldPreserveNewLinesInMarkdown,
    shouldAllowHighlightingWithBrackets,
    showInvisibleCharacters,
    // tableHorizontalScroll,
    selectionAlwaysOnDisplay,
    isCodeHighlighted,
    isCodeShiki,
  } = settings;
  useEffect(() => {
    if (INITIAL_SETTINGS.disableBeforeInput && CAN_USE_BEFORE_INPUT) {
      console.error(
        `Legacy events are enabled (disableBeforeInput) but CAN_USE_BEFORE_INPUT is true`,
      );
    }
  }, []);
  const [showSettings, setShowSettings] = useState(false);
  const [isSplitScreen, search] = useMemo(() => {
    const parentWindow = window.parent;
    const _search = windowLocation.search;
    const _isSplitScreen =
      parentWindow && parentWindow.location.pathname === '/split/';
    return [_isSplitScreen, _search];
  }, [windowLocation]);
  const hasCustomSettings = hasSettingOverrides(settings);

  const handleResetToDefaults = () => {
    clearStoredComments();
    clearStoredEditorState();
    resetOptions();
    resetPlaygroundEditorContent(editor, {
      emptyEditor: DEFAULT_SETTINGS.emptyEditor,
    });
  };

  const handleColorSchemeChange = () => {
    const nextColorScheme = isDarkMode ? 'light' : 'dark';

    if (onColorSchemeChange) {
      onColorSchemeChange(nextColorScheme);
      return;
    }

    setOption('isDarkMode', nextColorScheme === 'dark');
  };

  return (
    <>
      <button
        id="options-button"
        data-test-id="options-button"
        className={`editor-dev-button ${showSettings ? 'active' : ''}`}
        onClick={() => setShowSettings(!showSettings)}
      >
        <i className="bi bi-gear" />
      </button>
      {showSettings ? (
        <div className="switches p-1">
          {isDevPlayground && (
            <Switch
              onClick={() => {
                if (isSplitScreen) {
                  window.parent.location.href = `/${search}`;
                } else {
                  window.location.href = `/split/${search}`;
                }
              }}
              checked={isSplitScreen}
              text="Split Screen"
            />
          )}
          <Switch
            onClick={() => setOption('measureTypingPerf', !measureTypingPerf)}
            checked={measureTypingPerf}
            text="Measure Perf"
          />
          <Switch
            onClick={() => setOption('showTreeView', !showTreeView)}
            checked={showTreeView}
            text="Debug View"
          />
          <Switch
            onClick={handleColorSchemeChange}
            checked={isDarkMode}
            text="Dark Mode"
          />
          <Switch
            onClick={() => {
              setOption('showInvisibleCharacters', !showInvisibleCharacters);
            }}
            checked={showInvisibleCharacters}
            text="Show invisible characters"
          />
          <Switch
            onClick={() =>
              setOption('showNestedEditorTreeView', !showNestedEditorTreeView)
            }
            checked={showNestedEditorTreeView}
            text="Nested Editors Debug View"
          />
          <Switch
            onClick={() => {
              setOption('isRichText', !isRichText);
            }}
            checked={isRichText}
            text="Rich Text"
          />
          <Switch
            onClick={() => {
              setOption('hasNestedTables', !hasNestedTables);
            }}
            checked={hasNestedTables}
            text="Nested Tables"
          />
          <Switch
            onClick={() => setOption('isCharLimit', !isCharLimit)}
            checked={isCharLimit}
            text="Char Limit"
          />
          <Switch
            onClick={() => setOption('isCharLimitUtf8', !isCharLimitUtf8)}
            checked={isCharLimitUtf8}
            text="Char Limit (UTF-8)"
          />
          <Switch
            onClick={() => setOption('hasLinkAttributes', !hasLinkAttributes)}
            checked={hasLinkAttributes}
            text="Link Attributes"
          />
          <Switch
            onClick={() => setOption('isMaxLength', !isMaxLength)}
            checked={isMaxLength}
            text="Max Length"
          />
          <Switch
            onClick={() => setOption('isAutocomplete', !isAutocomplete)}
            checked={isAutocomplete}
            text="Autocomplete"
          />
          {/* <Switch
            onClick={() => {
              setOption('disableBeforeInput', !disableBeforeInput);
              setTimeout(() => window.location.reload(), 500);
            }}
            checked={disableBeforeInput}
            text="Legacy Events"
          /> */}
          <Switch
            onClick={() => {
              setOption('showTableOfContents', !showTableOfContents);
            }}
            checked={showTableOfContents}
            text="Table Of Contents"
          />
          <Switch
            onClick={() => {
              setOption(
                'shouldUseLexicalContextMenu',
                !shouldUseLexicalContextMenu,
              );
            }}
            checked={shouldUseLexicalContextMenu}
            text="Use Lexical Context Menu"
          />
          <Switch
            onClick={() => {
              setOption(
                'shouldPreserveNewLinesInMarkdown',
                !shouldPreserveNewLinesInMarkdown,
              );
            }}
            checked={shouldPreserveNewLinesInMarkdown}
            text="Preserve newlines in Markdown"
          />
          {/* <Switch
            onClick={() => {
              setOption('tableHorizontalScroll', !tableHorizontalScroll);
            }}
            checked={tableHorizontalScroll}
            text="Tables have horizontal scroll"
          /> */}
          <Switch
            onClick={() => {
              setOption(
                'shouldAllowHighlightingWithBrackets',
                !shouldAllowHighlightingWithBrackets,
              );
            }}
            checked={shouldAllowHighlightingWithBrackets}
            text="Use Brackets for Highlighting"
          />

          <Switch
            onClick={() => {
              setOption('selectionAlwaysOnDisplay', !selectionAlwaysOnDisplay);
            }}
            checked={selectionAlwaysOnDisplay}
            text="Retain selection"
          />

          <Switch
            onClick={() => {
              setOption('isCodeHighlighted', !isCodeHighlighted);
            }}
            checked={isCodeHighlighted}
            text="Enable Code Highlighting"
          />

          <Switch
            onClick={() => {
              setOption('isCodeShiki', !isCodeShiki);
            }}
            checked={isCodeShiki}
            text="Use Shiki for Code Highlighting"
          />
          <button
            type="button"
            className="settings-reset"
            disabled={!hasCustomSettings}
            onClick={handleResetToDefaults}
          >
            Reset to Defaults
          </button>
        </div>
      ) : null}
    </>
  );
}
