import type { CSSProperties } from 'react';

import { getClientRectZoomScale } from '../utils/zoomCompensation';

export type MentionAdvancedPanelPosition = {
  left: number;
  top: number;
};

type MentionAdvancedPanelBounds = {
  bottom: number;
  height: number;
  left: number;
  right: number;
  top: number;
  width: number;
};

const DEFAULT_PANEL_WIDTH = 320;
const DEFAULT_PANEL_HEIGHT = 120;
const MIN_PANEL_WIDTH = 220;
export const MIN_MENTION_ADVANCED_PANEL_HEIGHT = 96;
const PANEL_GAP = 10;
const DEFAULT_MENTION_ICON_HIT_WIDTH = 22;
const MAX_MENTION_ICON_HIT_WIDTH = 32;

let advancedMentionPanelZIndex = 1000;

export function getNextMentionAdvancedPanelZIndex(): number {
  advancedMentionPanelZIndex += 1;
  return advancedMentionPanelZIndex;
}

export function escapeMentionAdvancedPanelHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function copyPlainTextFallback(plainText: string): void {
  const textarea = document.createElement('textarea');
  textarea.value = plainText;
  textarea.setAttribute('readonly', '');
  textarea.style.position = 'fixed';
  textarea.style.top = '-9999px';
  document.body.appendChild(textarea);
  textarea.select();
  document.execCommand('copy');
  textarea.remove();
}

// Writes both an HTML and a plain-text representation to the clipboard so
// pasting into rich-text targets (e.g. Microsoft Word) keeps paragraph
// breaks and bold labels, while plain-text targets still get readable text.
export async function copyMentionRecordToClipboard(
  plainText: string,
  html: string,
): Promise<void> {
  if (
    typeof ClipboardItem !== 'undefined' &&
    navigator.clipboard !== undefined &&
    typeof navigator.clipboard.write === 'function'
  ) {
    try {
      await navigator.clipboard.write([
        new ClipboardItem({
          'text/html': new Blob([html], { type: 'text/html' }),
          'text/plain': new Blob([plainText], { type: 'text/plain' }),
        }),
      ]);
      return;
    } catch {
      // Some browsers restrict multi-format clipboard writes; fall back to
      // plain text below instead of leaving the copy silently failed.
    }
  }

  if (
    navigator.clipboard !== undefined &&
    typeof navigator.clipboard.writeText === 'function'
  ) {
    await navigator.clipboard.writeText(plainText);
    return;
  }

  copyPlainTextFallback(plainText);
}

export function isMentionIconPointerEvent(
  event: MouseEvent | PointerEvent,
  element: HTMLElement,
): boolean {
  const rect = element.getBoundingClientRect();

  if (
    event.clientX < rect.left ||
    event.clientX > rect.right ||
    event.clientY < rect.top ||
    event.clientY > rect.bottom
  ) {
    return false;
  }

  const computedStyle = window.getComputedStyle(element);
  const paddingLeft = Number.parseFloat(computedStyle.paddingLeft);
  const iconHitWidth =
    Number.isFinite(paddingLeft) && paddingLeft > 0
      ? Math.min(paddingLeft + 6, MAX_MENTION_ICON_HIT_WIDTH)
      : DEFAULT_MENTION_ICON_HIT_WIDTH;

  return event.clientX <= rect.left + iconHitWidth;
}

function getViewportBounds(): MentionAdvancedPanelBounds {
  return {
    bottom: window.innerHeight,
    height: window.innerHeight,
    left: 0,
    right: window.innerWidth,
    top: 0,
    width: window.innerWidth,
  };
}

export function getMentionAdvancedPanelBounds(
  anchorElement: HTMLElement | null,
): MentionAdvancedPanelBounds {
  const editorAreaElement =
    anchorElement?.closest('.editor-container') ??
    document.querySelector('.editor-container');

  if (editorAreaElement instanceof HTMLElement) {
    const rect = editorAreaElement.getBoundingClientRect();

    if (rect.width > 0 && rect.height > 0) {
      return rect;
    }
  }

  return getViewportBounds();
}

function clampValue(value: number, minimum: number, maximum: number): number {
  return Math.min(Math.max(value, minimum), maximum);
}

// Resolves the CSS `zoom` scale applied to the advanced panel. The panel is
// rendered inside the editor's `.editor-zoom-surface`, so it is magnified by
// that surface's zoom. The scale must come from the panel itself (or its
// surface) — never the anchor, which may live outside the surface (the lookup
// list is portaled to `document.body`, where the zoom scale is 1).
export function getMentionAdvancedPanelZoomScale(
  panelElement: HTMLElement | null,
  anchorElement: HTMLElement | null,
): number {
  const reference =
    panelElement ??
    anchorElement?.closest('.editor-zoom-surface') ??
    document.querySelector('.editor-zoom-surface');

  return getClientRectZoomScale(reference);
}

// The CSS `width` of `.mention-hover-card` (kept in sync with AppComp.scss).
const HOVER_CARD_WIDTH = 420;
const HOVER_CARD_GAP = 10;
const HOVER_CARD_MARGIN = 12;

// Builds the inline style for a mention hover card. The card is portaled to
// `document.body` (outside the editor's CSS `zoom` surface), so it is given the
// surface's zoom to scale with the zoomed content. Placement/size are computed
// in visual (post-zoom) pixels — clamped to stay fully within the viewport —
// then divided by the scale, because CSS `zoom` multiplies an element's own
// position and box sizes back up. `overflow: auto` on the card lets content
// scroll when the magnified card is capped to the available space.
export function getMentionHoverCardStyle(
  anchorElement: HTMLElement,
  estimatedCardHeight: number,
): CSSProperties {
  const zoomScale = getMentionAdvancedPanelZoomScale(null, anchorElement);
  const rect = anchorElement.getBoundingClientRect();
  const estimatedVisualHeight = estimatedCardHeight * zoomScale;
  const maxWidth = Math.min(
    HOVER_CARD_WIDTH * zoomScale,
    window.innerWidth - HOVER_CARD_MARGIN * 2,
  );
  const maxLeft = Math.max(
    HOVER_CARD_MARGIN,
    window.innerWidth - maxWidth - HOVER_CARD_MARGIN,
  );
  const left = Math.min(Math.max(rect.left, HOVER_CARD_MARGIN), maxLeft);
  const spaceBelow =
    window.innerHeight - rect.bottom - HOVER_CARD_GAP - HOVER_CARD_MARGIN;
  const spaceAbove = rect.top - HOVER_CARD_GAP - HOVER_CARD_MARGIN;
  const placeAbove =
    spaceBelow < estimatedVisualHeight && spaceAbove > spaceBelow;
  const top = placeAbove
    ? rect.top - HOVER_CARD_GAP
    : rect.bottom + HOVER_CARD_GAP;
  const maxHeight = Math.max(
    HOVER_CARD_MARGIN,
    placeAbove ? spaceAbove : spaceBelow,
  );

  return {
    left: left / zoomScale,
    maxHeight: maxHeight / zoomScale,
    maxWidth: maxWidth / zoomScale,
    position: 'fixed',
    top: top / zoomScale,
    transform: placeAbove ? 'translateY(-100%)' : undefined,
    zoom: zoomScale,
  };
}

export function clampMentionAdvancedPanelPosition(
  position: MentionAdvancedPanelPosition,
  panelElement: HTMLElement | null,
  anchorElement: HTMLElement | null,
): MentionAdvancedPanelPosition {
  const bounds = getMentionAdvancedPanelBounds(anchorElement);
  // Panel sizes (`offsetWidth`/`offsetHeight`, and the local-pixel defaults)
  // are measured in the surface's un-zoomed space, whereas `bounds` and
  // `position` are in visual (post-zoom) pixels. Scale the panel size up to
  // visual space so a magnified panel is kept fully inside the editor bounds
  // instead of overflowing off-screen when anchored near an edge.
  const zoomScale = getMentionAdvancedPanelZoomScale(
    panelElement,
    anchorElement,
  );
  const panelWidth =
    Math.max(
      MIN_PANEL_WIDTH,
      panelElement?.offsetWidth ?? DEFAULT_PANEL_WIDTH,
    ) * zoomScale;
  const panelHeight =
    Math.max(
      MIN_MENTION_ADVANCED_PANEL_HEIGHT,
      panelElement?.offsetHeight ?? DEFAULT_PANEL_HEIGHT,
    ) * zoomScale;
  const maxLeft = Math.max(
    bounds.left,
    bounds.right - Math.min(panelWidth, bounds.width),
  );
  const maxTop = Math.max(
    bounds.top,
    bounds.bottom - Math.min(panelHeight, bounds.height),
  );

  return {
    left: clampValue(position.left, bounds.left, maxLeft),
    top: clampValue(position.top, bounds.top, maxTop),
  };
}

export function getMentionAdvancedPanelInitialPosition(
  anchorElement: HTMLElement,
): MentionAdvancedPanelPosition {
  const bounds = getMentionAdvancedPanelBounds(anchorElement);
  // `DEFAULT_PANEL_HEIGHT` is a local (un-zoomed) estimate; scale it to visual
  // space to match `rect`/`bounds` when deciding whether the panel fits below.
  const zoomScale = getMentionAdvancedPanelZoomScale(null, anchorElement);
  const panelHeight = DEFAULT_PANEL_HEIGHT * zoomScale;
  const rect = anchorElement.getBoundingClientRect();
  const left = rect.left;
  const belowTop = rect.bottom + PANEL_GAP;
  const aboveTop = rect.top - panelHeight - PANEL_GAP;
  const top =
    belowTop + panelHeight > bounds.bottom && aboveTop >= bounds.top
      ? aboveTop
      : belowTop;

  return clampMentionAdvancedPanelPosition({ left, top }, null, anchorElement);
}
