import { characterEntities } from './character-entities-data';

export type HTMLCharacterEntity = Readonly<{
  category: string;
  character: string;
  description: string;
  entities: ReadonlyArray<string>;
}>;

type EntityMetadata = Readonly<{
  category: string;
  description: string;
}>;

const ENTITY_METADATA: Readonly<Record<string, EntityMetadata>> = {
  amp: { category: 'XML', description: 'ampersand' },
  AMP: { category: 'XML', description: 'ampersand' },
  lt: { category: 'XML', description: 'less-than sign' },
  LT: { category: 'XML', description: 'less-than sign' },
  gt: { category: 'XML', description: 'greater-than sign' },
  GT: { category: 'XML', description: 'greater-than sign' },
  quot: { category: 'XML', description: 'quotation mark' },
  QUOT: { category: 'XML', description: 'quotation mark' },
  apos: { category: 'XML', description: 'apostrophe' },
  nbsp: { category: 'Spacing', description: 'non-breaking space' },
  NonBreakingSpace: {
    category: 'Spacing',
    description: 'non-breaking space',
  },
  copy: { category: 'Legal', description: 'copyright sign' },
  COPY: { category: 'Legal', description: 'copyright sign' },
  reg: { category: 'Legal', description: 'registered sign' },
  REG: { category: 'Legal', description: 'registered sign' },
  trade: { category: 'Legal', description: 'trademark sign' },
  TRADE: { category: 'Legal', description: 'trademark sign' },
  pi: { category: 'Greek', description: 'Greek small letter pi' },
  rarr: { category: 'Arrows', description: 'rightwards arrow' },
  rightarrow: { category: 'Arrows', description: 'rightwards arrow' },
  RightArrow: { category: 'Arrows', description: 'rightwards arrow' },
};

function getDescriptionFromEntityName(entityName: string): string {
  return entityName
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')
    .replace(/_/g, ' ')
    .toLowerCase();
}

const htmlCharacterEntityMap = Object.entries(characterEntities).reduce(
  (entitiesByCharacter, [entityName, character]) => {
    const metadata = ENTITY_METADATA[entityName];
    const description =
      metadata?.description ?? getDescriptionFromEntityName(entityName);
    const key = `${character}\u0000${description}`;
    const existingEntry = entitiesByCharacter.get(key);

    if (existingEntry !== undefined) {
      existingEntry.entities.push(`&${entityName};`);
      return entitiesByCharacter;
    }

    entitiesByCharacter.set(key, {
      category: metadata?.category ?? 'HTML',
      character,
      description,
      entities: [`&${entityName};`],
    });

    return entitiesByCharacter;
  },
  new Map<
    string,
    {
      category: string;
      character: string;
      description: string;
      entities: string[];
    }
  >(),
);

export const HTML_CHARACTER_ENTITIES: ReadonlyArray<HTMLCharacterEntity> =
  Array.from(htmlCharacterEntityMap.values()).map((entry) => ({
    ...entry,
    entities: entry.entities,
  }));
