export const READ_ONLY_MODE_STORAGE_KEY = 'lexical-playground-read-only-mode';

const { name: EDITOR_PACKAGE_NAME, version: EDITOR_VERSION } = packageJson as {
  name: string;
  version: string;
};

const LOCKED_NOTICE_DURATION_MS = 850;
const LOCKED_EDITOR_ATTEMPT_EVENTS = [
  'beforeinput',
  'compositionstart',
  'cut',
  'drop',
  'paste',
];
const SHARE_LINK_RECOMMENDED_MAX_CHARACTERS = 8000;
const PLAIN_SHARE_LINK_READY_MESSAGE =
  'Plain link ready. Anyone with the URL can open this editor state.';
const PROTECTED_SHARE_LINK_READY_MESSAGE =
  'Protected link ready. Readers will be asked for the password.';
const FOOTER_ACTION_BUTTON_WRAPPER_STYLE = { display: 'contents' } as const;
const FOOTER_ACTION_TRIGGER_SELECTOR =
  'button:not(:disabled), [role="button"]:not([aria-disabled="true"]), a[href], input[type="button"]:not(:disabled), input[type="submit"]:not(:disabled)';
const FULLSCREEN_PAGE_SIZE_OPTION_VALUE = '__fullscreen__';

type FooterActionShortcut = Readonly<{
  altKey: boolean;
  ariaKeyShortcut: string;
  ctrlKey: boolean;
  key: string;
  metaKey: boolean;
  shiftKey: boolean;
}>;

function normalizeShortcutKey(key: string): string {
  switch (key.trim().toLowerCase()) {
    case 'esc':
      return 'escape';
    case 'space':
    case 'spacebar':
      return ' ';
    case 'plus':
      return '+';
    default:
      return key.trim().toLowerCase();
  }
}

function getAriaShortcutKey(key: string): string {
  if (key === ' ') {
    return 'Space';
  }

  if (key.length === 1) {
    return key.toUpperCase();
  }

  return key;
}

function parseFooterActionShortcut(
  shortcutKey: string | undefined,
): FooterActionShortcut | null {
  if (shortcutKey === undefined) {
    return null;
  }

  const parts = shortcutKey
    .split('+')
    .map((part) => part.trim())
    .filter(Boolean);
  let key: string | null = null;
  let altKey = false;
  let ctrlKey = false;
  let metaKey = false;
  let shiftKey = false;

  parts.forEach((part) => {
    switch (part.toLowerCase()) {
      case 'alt':
      case 'option':
        altKey = true;
        break;
      case 'cmd':
      case 'command':
      case 'meta':
        metaKey = true;
        break;
      case 'control':
      case 'ctrl':
        ctrlKey = true;
        break;
      case 'shift':
        shiftKey = true;
        break;
      default:
        key = key === null ? normalizeShortcutKey(part) : '';
    }
  });

  if (key === null || key === '') {
    return null;
  }

  return {
    altKey,
    ariaKeyShortcut: [
      ctrlKey ? 'Control' : null,
      altKey ? 'Alt' : null,
      shiftKey ? 'Shift' : null,
      metaKey ? 'Meta' : null,
      getAriaShortcutKey(key),
    ]
      .filter(Boolean)
      .join('+'),
    ctrlKey,
    key,
    metaKey,
    shiftKey,
  };
}

function doesKeyboardEventMatchShortcut(
  event: KeyboardEvent,
  shortcut: FooterActionShortcut,
): boolean {
  return (
    event.altKey === shortcut.altKey &&
    event.ctrlKey === shortcut.ctrlKey &&
    event.metaKey === shortcut.metaKey &&
    event.shiftKey === shortcut.shiftKey &&
    normalizeShortcutKey(event.key) === shortcut.key
  );
}

function getFooterActionTriggerElement(
  actionButtonElement: HTMLElement,
): HTMLElement | null {
  if (actionButtonElement.matches(FOOTER_ACTION_TRIGGER_SELECTOR)) {
    return actionButtonElement;
  }

  return actionButtonElement.querySelector<HTMLElement>(
    FOOTER_ACTION_TRIGGER_SELECTOR,
  );
}

function getFooterActionButtonTitle(
  actionButton: BibleNoteFooterActionButton,
  currentTitle: unknown,
): string | undefined {
  const title =
    typeof currentTitle === 'string' && currentTitle.length > 0
      ? currentTitle
      : actionButton.description;

  if (actionButton.shortcutKey === undefined) {
    return title;
  }

  return title === undefined
    ? actionButton.shortcutKey
    : `${title} (${actionButton.shortcutKey})`;
}

function renderFooterActionButtonChildren(
  actionButton: BibleNoteFooterActionButton,
): JSX.Element | BibleNoteFooterActionButton['children'] {
  const parsedShortcut = parseFooterActionShortcut(actionButton.shortcutKey);
  const children = Children.toArray(actionButton.children);
  const child = children[0];

  if (
    children.length !== 1 ||
    !isValidElement<Record<string, unknown>>(child) ||
    typeof child.type !== 'string'
  ) {
    return actionButton.children;
  }

  const title = getFooterActionButtonTitle(actionButton, child.props.title);
  const nextProps: {
    'aria-keyshortcuts'?: string;
    title?: string;
  } = {};

  if (parsedShortcut !== null) {
    nextProps['aria-keyshortcuts'] = parsedShortcut.ariaKeyShortcut;
  }

  if (title !== undefined && title !== child.props.title) {
    nextProps.title = title;
  }

  if (Object.keys(nextProps).length === 0) {
    return actionButton.children;
  }

  return cloneElement(child, nextProps);
}

function readStoredReadOnlyMode(): boolean {
  const storage = getBibleNoteStorage();

  if (storage === null) {
    return false;
  }

  return storage.getItem(READ_ONLY_MODE_STORAGE_KEY) === 'true';
}

function writeStoredReadOnlyMode(isReadOnly: boolean): void {
  const storage = getBibleNoteStorage();

  if (storage === null) {
    return;
  }

  if (isReadOnly) {
    storage.setItem(READ_ONLY_MODE_STORAGE_KEY, 'true');
    return;
  }

  storage.removeItem(READ_ONLY_MODE_STORAGE_KEY);
}

function isLockedEditorEditKey(event: KeyboardEvent): boolean {
  const key = event.key.toLowerCase();

  if ((event.ctrlKey || event.metaKey) && (key === 'v' || key === 'x')) {
    return true;
  }

  if (event.ctrlKey || event.metaKey || event.altKey) {
    return false;
  }

  return (
    event.key.length === 1 ||
    event.key === 'Backspace' ||
    event.key === 'Delete' ||
    event.key === 'Enter' ||
    event.key === 'Tab'
  );
}

function isEventInEditor(rootElement: HTMLElement, event: Event): boolean {
  const target = event.target;

  if (target instanceof Node && rootElement.contains(target)) {
    return true;
  }

  const activeElement = document.activeElement;
  if (activeElement !== null && rootElement.contains(activeElement)) {
    return true;
  }

  const selection = window.getSelection();
  const anchorNode = selection?.anchorNode;

  return (
    anchorNode !== null &&
    anchorNode !== undefined &&
    rootElement.contains(anchorNode)
  );
}

export default function ActionsPlugin({
  forceReadOnly = false,
  footerActionButtons = EMPTY_BIBLE_NOTE_FOOTER_ACTION_BUTTONS,
  isMinimize,
  isOnApp,
  onToggleFullscreen,
  onToggleComments,
  onToggleLookup,
  print,
  setShowComments,
  setShowLookup,
  shouldPreserveNewLinesInMarkdown,
  showComments,
  showLookup,
  showModal,
}: {
  forceReadOnly?: boolean;
  footerActionButtons?: BibleNoteFooterActionButtons;
  isMinimize: boolean;
  isOnApp: boolean;
  onToggleFullscreen?: () => void;
  onToggleComments?: () => void;
  onToggleLookup?: () => void;
  print?: () => void;
  setShowComments?: Dispatch<SetStateAction<boolean>>;
  setShowLookup?: Dispatch<SetStateAction<boolean>>;
  shouldPreserveNewLinesInMarkdown: boolean;
  showComments?: boolean;
  showLookup?: boolean;
  showModal: (
    title: string,
    getContent: (onClose: () => void) => JSX.Element,
  ) => void;
}): JSX.Element {
  const [editor] = useLexicalComposerContext();
  const [isEditable, setIsEditable] = useState(() =>
    forceReadOnly || readStoredReadOnlyMode() ? false : editor.isEditable(),
  );
  const [isEditorEmpty, setIsEditorEmpty] = useState(true);
  const [lockedNoticeSignal, setLockedNoticeSignal] = useState(0);
  const [isMoreActionsOpen, setIsMoreActionsOpen] = useState(false);
  const [moreActionsMenuPosition, setMoreActionsMenuPosition] = useState<{
    bottom: number;
    right: number;
  } | null>(null);
  const lockedNoticeTimeoutRef = useRef<number | null>(null);
  const footerActionButtonElementsRef = useRef(new Map<string, HTMLElement>());
  const moreActionsButtonRef = useRef<HTMLButtonElement | null>(null);
  const moreActionsMenuRef = useRef<HTMLDivElement | null>(null);
  const {
    setOption,
    settings: { pageSize },
  } = useSettings();
  const { showStickyNotes, toggleStickyNotesVisibility } =
    useStickyNotesVisibility();
  const triggerLockedNotice = useCallback(() => {
    setLockedNoticeSignal((signal) => signal + 1);

    if (lockedNoticeTimeoutRef.current !== null) {
      window.clearTimeout(lockedNoticeTimeoutRef.current);
    }

    lockedNoticeTimeoutRef.current = window.setTimeout(() => {
      setLockedNoticeSignal(0);
      lockedNoticeTimeoutRef.current = null;
    }, LOCKED_NOTICE_DURATION_MS);
  }, []);

  const readOnlyButtonClassName = [
    'action-button',
    !isEditable ? 'unlock is-locked' : 'lock',
    !isEditable && lockedNoticeSignal > 0 ? 'is-locked-notice' : '',
  ]
    .filter(Boolean)
    .join(' ');

  const handlePrintClick = useCallback(() => {
    if (print !== undefined) {
      print();
      return;
    }

    printEditorState(editor, pageSize);
  }, [editor, pageSize, print]);

  useEffect(() => {
    if (forceReadOnly) {
      writeStoredReadOnlyMode(true);
      editor.setEditable(false);
      setIsEditable(false);
      return;
    }

    if (readStoredReadOnlyMode()) {
      editor.setEditable(false);
      setIsEditable(false);
    }
  }, [editor, forceReadOnly]);

  useEffect(() => {
    return () => {
      if (lockedNoticeTimeoutRef.current !== null) {
        window.clearTimeout(lockedNoticeTimeoutRef.current);
      }
    };
  }, []);

  useEffect(() => {
    if (isEditable) {
      if (lockedNoticeTimeoutRef.current !== null) {
        window.clearTimeout(lockedNoticeTimeoutRef.current);
        lockedNoticeTimeoutRef.current = null;
      }
      setLockedNoticeSignal(0);
    }
  }, [isEditable]);

  useEffect(() => {
    if (isEditable) {
      return;
    }

    let rootElement = editor.getRootElement();
    const removeRootListener = editor.registerRootListener(
      (nextRootElement) => {
        rootElement = nextRootElement;
      },
    );
    const handleLockedEditAttempt = (event: Event) => {
      if (rootElement !== null && isEventInEditor(rootElement, event)) {
        triggerLockedNotice();
      }
    };
    const handleLockedKeyDown = (event: KeyboardEvent) => {
      if (
        rootElement !== null &&
        isEventInEditor(rootElement, event) &&
        isLockedEditorEditKey(event)
      ) {
        triggerLockedNotice();
      }
    };

    document.addEventListener('keydown', handleLockedKeyDown, true);
    LOCKED_EDITOR_ATTEMPT_EVENTS.forEach((eventName) => {
      document.addEventListener(eventName, handleLockedEditAttempt, true);
    });

    return () => {
      removeRootListener();
      document.removeEventListener('keydown', handleLockedKeyDown, true);
      LOCKED_EDITOR_ATTEMPT_EVENTS.forEach((eventName) => {
        document.removeEventListener(eventName, handleLockedEditAttempt, true);
      });
    };
  }, [editor, isEditable, triggerLockedNotice]);

  useEffect(() => {
    return editor.registerEditableListener((editable) => {
      setIsEditable(editable);
      writeStoredReadOnlyMode(!editable);
    });
  }, [editor]);

  useEffect(() => {
    if (!forceReadOnly || !isEditable) {
      return;
    }

    writeStoredReadOnlyMode(true);
    editor.setEditable(false);
    setIsEditable(false);
  }, [editor, forceReadOnly, isEditable]);

  useEffect(() => {
    return editor.registerUpdateListener(
      ({
        dirtyElements: _dirtyElements,
        prevEditorState: _prevEditorState,
        tags: _tags,
      }) => {
        editor.getEditorState().read(() => {
          const root = $getRoot();
          const children = root.getChildren();

          if (children.length > 1) {
            setIsEditorEmpty(false);
          } else {
            if ($isParagraphNode(children[0])) {
              const paragraphChildren = children[0].getChildren();
              setIsEditorEmpty(paragraphChildren.length === 0);
            } else {
              setIsEditorEmpty(false);
            }
          }
        });
      },
    );
  }, [editor, isEditable]);

  const handleMarkdownToggle = useCallback(() => {
    editor.update(() => {
      const root = $getRoot();
      const firstChild = root.getFirstChild();
      if ($isCodeNode(firstChild) && firstChild.getLanguage() === 'markdown') {
        $convertFromMarkdownString(
          firstChild.getTextContent(),
          PLAYGROUND_TRANSFORMERS,
          undefined, // node
          shouldPreserveNewLinesInMarkdown,
        );
      } else {
        const markdown = $convertToMarkdownString(
          PLAYGROUND_TRANSFORMERS,
          undefined, //node
          shouldPreserveNewLinesInMarkdown,
        );
        const codeNode = $createCodeNode('markdown');
        codeNode.append($createTextNode(markdown));
        root.clear().append(codeNode);
        if (markdown.length === 0) {
          codeNode.select();
        }
      }
    });
  }, [editor, shouldPreserveNewLinesInMarkdown]);

  const handleShareLinkClick = useCallback(() => {
    const serializedEditorState = JSON.stringify(editor.getEditorState());
    const shareLink = buildSharedEditorStateUrl(serializedEditorState);

    showModal('Share as link', (onClose) =>
      shareLink === null ? (
        <ShowShareLinkUnavailableDialog onClose={onClose} />
      ) : (
        <ShowShareLinkDialog
          onClose={onClose}
          serializedEditorState={serializedEditorState}
          shareLink={shareLink}
        />
      ),
    );
  }, [editor, showModal]);

  const updateMoreActionsMenuPosition = useCallback(() => {
    const buttonElement = moreActionsButtonRef.current;

    if (buttonElement === null) {
      return;
    }

    const buttonRect = buttonElement.getBoundingClientRect();

    setMoreActionsMenuPosition({
      bottom: Math.max(8, window.innerHeight - buttonRect.top + 4),
      right: Math.max(8, window.innerWidth - buttonRect.right),
    });
  }, []);

  const handleImportClick = useCallback(() => {
    importFile(editor);
  }, [editor]);

  const handleExportClick = useCallback(() => {
    exportFile(editor, {
      fileName: `BibleNote ${new Date().toISOString()}`,
      source: 'Playground',
    });
  }, [editor]);

  const handleInfoClick = useCallback(() => {
    showModal('Editor information', () => <ShowEditorInfoDialog />);
  }, [showModal]);

  const closeMoreActionsMenu = useCallback(() => {
    setIsMoreActionsOpen(false);
  }, []);

  const setFooterActionButtonElement = useCallback(
    (id: string, element: HTMLElement | null) => {
      if (element === null) {
        footerActionButtonElementsRef.current.delete(id);
        return;
      }

      footerActionButtonElementsRef.current.set(id, element);
    },
    [],
  );

  const handleMoreActionsClick = useCallback(() => {
    if (isMoreActionsOpen) {
      setIsMoreActionsOpen(false);
      return;
    }

    updateMoreActionsMenuPosition();
    setIsMoreActionsOpen(true);
  }, [isMoreActionsOpen, updateMoreActionsMenuPosition]);

  useEffect(() => {
    if (!isMoreActionsOpen) {
      return;
    }

    updateMoreActionsMenuPosition();

    const handleDocumentMouseDown = (event: MouseEvent) => {
      const target = event.target;

      if (!(target instanceof Node)) {
        return;
      }

      if (
        moreActionsButtonRef.current?.contains(target) ||
        moreActionsMenuRef.current?.contains(target)
      ) {
        return;
      }

      setIsMoreActionsOpen(false);
    };
    const handleDocumentKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setIsMoreActionsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleDocumentMouseDown);
    document.addEventListener('keydown', handleDocumentKeyDown);
    window.addEventListener('resize', updateMoreActionsMenuPosition);
    window.addEventListener('scroll', updateMoreActionsMenuPosition, true);

    return () => {
      document.removeEventListener('mousedown', handleDocumentMouseDown);
      document.removeEventListener('keydown', handleDocumentKeyDown);
      window.removeEventListener('resize', updateMoreActionsMenuPosition);
      window.removeEventListener('scroll', updateMoreActionsMenuPosition, true);
    };
  }, [isMoreActionsOpen, updateMoreActionsMenuPosition]);

  useEffect(() => {
    const actionButtonShortcuts = [
      ...footerActionButtons.before,
      ...footerActionButtons.after,
    ]
      .map((actionButton) => ({
        id: actionButton.id,
        shortcut: parseFooterActionShortcut(actionButton.shortcutKey),
      }))
      .filter(
        (
          actionButton,
        ): actionButton is {
          id: string;
          shortcut: FooterActionShortcut;
        } => actionButton.shortcut !== null,
      );

    if (actionButtonShortcuts.length === 0) {
      return;
    }

    const handleDocumentKeyDown = (event: KeyboardEvent) => {
      if (event.defaultPrevented || event.repeat || event.isComposing) {
        return;
      }

      const matchingActionButton = actionButtonShortcuts.find((actionButton) =>
        doesKeyboardEventMatchShortcut(event, actionButton.shortcut),
      );

      if (matchingActionButton === undefined) {
        return;
      }

      const actionButtonElement = footerActionButtonElementsRef.current.get(
        matchingActionButton.id,
      );
      const triggerElement =
        actionButtonElement === undefined
          ? null
          : getFooterActionTriggerElement(actionButtonElement);

      if (triggerElement === null) {
        return;
      }

      event.preventDefault();
      triggerElement.click();
    };

    document.addEventListener('keydown', handleDocumentKeyDown);

    return () => {
      document.removeEventListener('keydown', handleDocumentKeyDown);
    };
  }, [footerActionButtons]);

  return (
    <div
      className="d-flex flex-wrap justify-content-end actions"
      style={{
        overflowX: 'auto',
        overflowY: 'hidden',
      }}
    >
      {footerActionButtons.before.map((actionButton) => (
        <FooterActionButton
          key={actionButton.id}
          actionButton={actionButton}
          setFooterActionButtonElement={setFooterActionButtonElement}
        />
      ))}
      <button
        className="action-button sticky-notes-toggle"
        onClick={toggleStickyNotesVisibility}
        title={showStickyNotes ? 'Hide Sticky Notes' : 'Show Sticky Notes'}
        aria-label={showStickyNotes ? 'Hide sticky notes' : 'Show sticky notes'}
        aria-pressed={showStickyNotes}
      >
        <i
          className={`bi bi-${showStickyNotes ? 'stickies-fill' : 'stickies'}`}
        />
      </button>
      <button
        className="action-button export-docx"
        onClick={() => exportEditorStateAsDocx(editor, pageSize)}
        title="Download Word Document"
        aria-label="Download as Word document"
      >
        <i className="bi bi-file-word" />
      </button>
      <button
        className="action-button print"
        onClick={handlePrintClick}
        title="Print"
        aria-label="Print document"
      >
        <i className="bi bi-printer" />
      </button>
      <label className="page-size-selector" title="Page size">
        <span className="visually-hidden">Page size</span>
        <i className="bi bi-file-earmark" aria-hidden="true" />
        <select
          aria-label="Page size"
          value={pageSize}
          onChange={(event) => {
            const nextPageSize = event.target.value;

            if (nextPageSize === FULLSCREEN_PAGE_SIZE_OPTION_VALUE) {
              onToggleFullscreen?.();
              return;
            }

            if (isPageSizeKey(nextPageSize)) {
              setOption('pageSize', nextPageSize);
            }
          }}
        >
          {getPageSizeOptions().map((pageSizeOption) => (
            <option key={pageSizeOption.key} value={pageSizeOption.key}>
              {pageSizeOption.label}
            </option>
          ))}
          <option value={FULLSCREEN_PAGE_SIZE_OPTION_VALUE}>Full Screen</option>
        </select>
      </label>
      <button
        className="action-button clear"
        disabled={isEditorEmpty}
        onClick={() => {
          showModal('Clear editor', (onClose) => (
            <ShowClearDialog editor={editor} onClose={onClose} />
          ));
        }}
        title="Clear"
        aria-label="Clear editor contents"
      >
        <i className="bi bi-eraser" />
      </button>
      <button
        className={readOnlyButtonClassName}
        onClick={() => {
          if (forceReadOnly) {
            triggerLockedNotice();
            writeStoredReadOnlyMode(true);
            editor.setEditable(false);
            setIsEditable(false);
            return;
          }

          const nextEditable = !isEditable;
          writeStoredReadOnlyMode(!nextEditable);
          editor.setEditable(nextEditable);
          setIsEditable(nextEditable);
        }}
        title={forceReadOnly ? 'Read-Only Mode Locked' : 'Read-Only Mode'}
        aria-label={
          forceReadOnly && !isEditable
            ? 'Read-only mode is locked'
            : `${!isEditable ? 'Unlock' : 'Lock'} read-only mode`
        }
      >
        <i
          key={`${isEditable ? 'editable' : 'locked'}-${lockedNoticeSignal}`}
          className={`bi bi-${isEditable ? 'unlock' : 'lock'}-fill`}
        />
      </button>
      {!isOnApp && (
        <>
          <button
            className="action-button share-link"
            onClick={handleShareLinkClick}
            title="Share as Link"
            aria-label="Share editor state as link"
          >
            <i className="bi bi-link-45deg" />
          </button>
          <button
            className="action-button"
            onClick={handleMarkdownToggle}
            title="Convert From Markdown"
            aria-label="Convert from markdown"
          >
            <i className="bi bi-markdown-fill" />
          </button>
        </>
      )}
      {showComments !== undefined && setShowComments !== undefined && (
        <button
          className={`action-button comments-toggle ${showComments ? 'active' : ''}`}
          onClick={() =>
            onToggleComments
              ? onToggleComments()
              : setShowComments((currentShowComments) => !currentShowComments)
          }
          title={showComments ? 'Hide Comments' : 'Show Comments'}
          aria-label={showComments ? 'Hide comments' : 'Show comments'}
          aria-pressed={showComments}
        >
          <i
            className={`bi ${showComments ? 'bi-chat-dots-fill' : 'bi-chat-dots'}`}
          />
        </button>
      )}
      {showLookup !== undefined && setShowLookup !== undefined && (
        <button
          className={`action-button lookup-toggle ${showLookup ? 'active' : ''}`}
          onClick={() =>
            onToggleLookup
              ? onToggleLookup()
              : setShowLookup((currentShowLookup) => !currentShowLookup)
          }
          title={showLookup ? 'Hide Lookup' : 'Show Lookup (name or location)'}
          aria-label={showLookup ? 'Hide lookup' : 'Show lookup'}
          aria-pressed={showLookup}
        >
          <i className="bi bi-search" />
        </button>
      )}
      {isMinimize ? (
        <>
          <button
            ref={moreActionsButtonRef}
            className={`action-button more-actions ${isMoreActionsOpen ? 'active' : ''}`}
            onClick={handleMoreActionsClick}
            title="More actions"
            aria-label="More document actions"
            aria-expanded={isMoreActionsOpen}
            aria-haspopup="menu"
            type="button"
          >
            <i className="bi bi-three-dots" />
          </button>
          {isMoreActionsOpen && moreActionsMenuPosition !== null
            ? createPortal(
                <div
                  ref={moreActionsMenuRef}
                  className="dropdown actions-overflow-menu"
                  role="menu"
                  aria-label="More document actions"
                  style={{
                    bottom: `${moreActionsMenuPosition.bottom}px`,
                    right: `${moreActionsMenuPosition.right}px`,
                  }}
                >
                  <button
                    className="item"
                    onClick={() => {
                      handleImportClick();
                      closeMoreActionsMenu();
                    }}
                    role="menuitem"
                    type="button"
                  >
                    <span className="icon">
                      <i className="bi bi-upload" />
                    </span>
                    <span className="text">Import</span>
                  </button>
                  <button
                    className="item"
                    onClick={() => {
                      handleExportClick();
                      closeMoreActionsMenu();
                    }}
                    role="menuitem"
                    type="button"
                  >
                    <span className="icon">
                      <i className="bi bi-download" />
                    </span>
                    <span className="text">Export</span>
                  </button>
                  <button
                    className="item"
                    onClick={() => {
                      handleInfoClick();
                      closeMoreActionsMenu();
                    }}
                    role="menuitem"
                    type="button"
                  >
                    <span className="icon">
                      <i className="bi bi-info-circle" />
                    </span>
                    <span className="text">Editor Information</span>
                  </button>
                </div>,
                document.body,
              )
            : null}
        </>
      ) : (
        <>
          <button
            className="action-button import"
            onClick={handleImportClick}
            title="Import"
            aria-label="Import editor state from JSON"
          >
            <i className="bi bi-upload" />
          </button>
          <button
            className="action-button export"
            onClick={handleExportClick}
            title="Export"
            aria-label="Export editor state to JSON"
          >
            <i className="bi bi-download" />
          </button>
          <button
            className="action-button info"
            onClick={handleInfoClick}
            title="Editor Information"
            aria-label="Show editor information"
          >
            <i className="bi bi-info-circle" />
          </button>
        </>
      )}
      {footerActionButtons.after.map((actionButton) => (
        <FooterActionButton
          key={actionButton.id}
          actionButton={actionButton}
          setFooterActionButtonElement={setFooterActionButtonElement}
        />
      ))}
    </div>
  );
}

function FooterActionButton({
  actionButton,
  setFooterActionButtonElement,
}: {
  actionButton: BibleNoteFooterActionButton;
  setFooterActionButtonElement: (
    id: string,
    element: HTMLElement | null,
  ) => void;
}): JSX.Element {
  return (
    <span
      ref={(element) => {
        setFooterActionButtonElement(actionButton.id, element);
      }}
      style={FOOTER_ACTION_BUTTON_WRAPPER_STYLE}
    >
      {renderFooterActionButtonChildren(actionButton)}
    </span>
  );
}

type CopyState = 'idle' | 'copying' | 'success' | 'error';
type ShareMessageTone = 'muted' | 'warning';

function ShowShareLinkDialog({
  onClose,
  serializedEditorState,
  shareLink,
}: {
  onClose: () => void;
  serializedEditorState: string;
  shareLink: string;
}): JSX.Element {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const [copyState, setCopyState] = useState<CopyState>('idle');
  const [isPasswordProtected, setIsPasswordProtected] = useState(false);
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [generatedShareLink, setGeneratedShareLink] = useState(shareLink);
  const initialShareMessage = getReadyShareLinkMessage(
    shareLink,
    PLAIN_SHARE_LINK_READY_MESSAGE,
  );
  const [shareMessage, setShareMessage] = useState(initialShareMessage.message);
  const [shareMessageTone, setShareMessageTone] = useState<ShareMessageTone>(
    initialShareMessage.tone,
  );
  const [isGeneratingProtectedLink, setIsGeneratingProtectedLink] =
    useState(false);
  const canPasswordProtect = isSharedEditorStateEncryptionSupported();

  useEffect(() => {
    setCopyState('idle');
  }, [generatedShareLink]);

  useEffect(() => {
    if (!isPasswordProtected) {
      const nextShareMessage = getReadyShareLinkMessage(
        shareLink,
        PLAIN_SHARE_LINK_READY_MESSAGE,
      );

      setGeneratedShareLink(shareLink);
      setShareMessage(nextShareMessage.message);
      setShareMessageTone(nextShareMessage.tone);
      setIsGeneratingProtectedLink(false);
      return;
    }

    if (!canPasswordProtect) {
      setGeneratedShareLink('');
      setShareMessage('Password protection is unavailable in this browser.');
      setShareMessageTone('muted');
      setIsGeneratingProtectedLink(false);
      return;
    }

    if (password.length === 0 || confirmPassword.length === 0) {
      setGeneratedShareLink('');
      setShareMessage(
        'Enter and confirm a password to generate the protected link.',
      );
      setShareMessageTone('muted');
      setIsGeneratingProtectedLink(false);
      return;
    }

    if (password !== confirmPassword) {
      setGeneratedShareLink('');
      setShareMessage('Passwords must match before the link can be created.');
      setShareMessageTone('muted');
      setIsGeneratingProtectedLink(false);
      return;
    }

    let isActive = true;

    setGeneratedShareLink('');
    setShareMessage('Encrypting the share link...');
    setShareMessageTone('muted');
    setIsGeneratingProtectedLink(true);

    void buildPasswordProtectedSharedEditorStateUrl(
      serializedEditorState,
      password,
    )
      .then((protectedShareLink) => {
        if (!isActive) {
          return;
        }

        if (protectedShareLink === null) {
          setShareMessage('The protected share link could not be created.');
          setShareMessageTone('muted');
          return;
        }

        const nextShareMessage = getReadyShareLinkMessage(
          protectedShareLink,
          PROTECTED_SHARE_LINK_READY_MESSAGE,
        );

        setGeneratedShareLink(protectedShareLink);
        setShareMessage(nextShareMessage.message);
        setShareMessageTone(nextShareMessage.tone);
      })
      .catch(() => {
        if (isActive) {
          setShareMessage('The protected share link could not be created.');
          setShareMessageTone('muted');
        }
      })
      .finally(() => {
        if (isActive) {
          setIsGeneratingProtectedLink(false);
        }
      });

    return () => {
      isActive = false;
    };
  }, [
    canPasswordProtect,
    confirmPassword,
    isPasswordProtected,
    password,
    serializedEditorState,
    shareLink,
  ]);

  const handleCopy = useCallback(async () => {
    if (!generatedShareLink) {
      return;
    }

    setCopyState('copying');

    try {
      const copied = await copyTextToClipboard(
        generatedShareLink,
        textareaRef.current,
      );
      setCopyState(copied ? 'success' : 'error');
    } catch {
      setCopyState('error');
    }
  }, [generatedShareLink]);

  const copyButtonLabel =
    copyState === 'copying'
      ? 'Copying...'
      : copyState === 'success'
        ? 'Copied'
        : copyState === 'error'
          ? 'Copy failed'
          : 'Copy link';

  return (
    <div className="d-flex flex-column gap-3">
      <label className="d-flex align-items-center gap-2 m-0">
        <input
          checked={isPasswordProtected}
          className="form-check-input m-0"
          onChange={(event) => {
            setIsPasswordProtected(event.currentTarget.checked);
          }}
          type="checkbox"
        />
        <span>Password protect link</span>
      </label>
      {isPasswordProtected ? (
        <div className="d-flex flex-column gap-2">
          <label className="d-flex flex-column gap-1 m-0">
            <span>Password</span>
            <input
              autoComplete="new-password"
              className="form-control"
              disabled={!canPasswordProtect}
              onChange={(event) => {
                setPassword(event.currentTarget.value);
              }}
              type="password"
              value={password}
            />
          </label>
          <label className="d-flex flex-column gap-1 m-0">
            <span>Confirm password</span>
            <input
              autoComplete="new-password"
              className="form-control"
              disabled={!canPasswordProtect}
              onChange={(event) => {
                setConfirmPassword(event.currentTarget.value);
              }}
              type="password"
              value={confirmPassword}
            />
          </label>
        </div>
      ) : null}
      <p
        className={`m-0 ${shareMessageTone === 'warning' ? 'text-warning' : 'text-body-secondary'}`}
        role="status"
      >
        {shareMessage}
      </p>
      <label className="visually-hidden" htmlFor="share-editor-state-link">
        Shared editor link
      </label>
      <textarea
        ref={textareaRef}
        id="share-editor-state-link"
        className="form-control"
        readOnly={true}
        rows={5}
        value={generatedShareLink}
        onFocus={(event) => event.currentTarget.select()}
      />
      <div className="d-flex justify-content-end gap-2">
        <Button
          disabled={
            copyState === 'copying' ||
            isGeneratingProtectedLink ||
            !generatedShareLink
          }
          onClick={() => {
            void handleCopy();
          }}
        >
          {copyButtonLabel}
        </Button>
        <Button onClick={onClose}>Close</Button>
      </div>
    </div>
  );
}

function getReadyShareLinkMessage(
  shareLink: string,
  readyMessage: string,
): { message: string; tone: ShareMessageTone } {
  if (shareLink.length > SHARE_LINK_RECOMMENDED_MAX_CHARACTERS) {
    return {
      message: formatShareLinkLengthWarning(shareLink),
      tone: 'warning',
    };
  }

  return {
    message: readyMessage,
    tone: 'muted',
  };
}

function formatShareLinkLengthWarning(shareLink: string): string {
  const currentCharacters = shareLink.length.toLocaleString('en-US');
  const maxCharacters =
    SHARE_LINK_RECOMMENDED_MAX_CHARACTERS.toLocaleString('en-US');

  return `Share link is ${currentCharacters} / ${maxCharacters} characters. It may be too long for some apps or browsers, but it can still be copied.`;
}

function ShowShareLinkUnavailableDialog({
  onClose,
}: {
  onClose: () => void;
}): JSX.Element {
  return (
    <>
      Unable to create a share link for the current editor state.
      <div className="Modal__content pt-4">
        <Button onClick={onClose}>Close</Button>
      </div>
    </>
  );
}

async function copyTextToClipboard(
  text: string,
  fallbackTarget: HTMLTextAreaElement | null,
): Promise<boolean> {
  if (navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(text);
    return true;
  }

  if (fallbackTarget === null || typeof document.execCommand !== 'function') {
    return false;
  }

  fallbackTarget.focus();
  fallbackTarget.select();

  return document.execCommand('copy');
}

function ShowEditorInfoDialog(): JSX.Element {
  return (
    <dl className="m-0">
      <div className="d-flex align-items-center justify-content-between gap-4">
        <dt className="fw-normal text-body-secondary">Editor package</dt>
        <dd className="m-0 fw-semibold">{EDITOR_PACKAGE_NAME}</dd>
      </div>
      <div className="d-flex align-items-center justify-content-between gap-4 mt-2">
        <dt className="fw-normal text-body-secondary">Editor version</dt>
        <dd className="m-0 fw-semibold">{EDITOR_VERSION}</dd>
      </div>
    </dl>
  );
}

function ShowClearDialog({
  editor,
  onClose,
}: {
  editor: LexicalEditor;
  onClose: () => void;
}): JSX.Element {
  return (
    <>
      Are you sure you want to clear the editor?
      <div className="Modal__content pt-4">
        <Button
          onClick={() => {
            clearStoredBlockTextLinks();
            editor.dispatchCommand(CLEAR_EDITOR_COMMAND, undefined);
            editor.focus();
            onClose();
          }}
        >
          Clear
        </Button>{' '}
        <Button
          onClick={() => {
            editor.focus();
            onClose();
          }}
        >
          Cancel
        </Button>
      </div>
    </>
  );
}
