import type { CSSProperties, ReactNode } from 'react';
import type { LibraryItems } from '@excalidraw/excalidraw/types';
import type { Root } from 'react-dom/client';
import type {
  BibleNoteEditorControllerOwner,
  BibleNoteSettingsControllerOwner,
} from './AppComp';
import type { BibleNoteFooterActionButtonControllerOwner } from './footerActionButtons';
import type { BibleNoteColorScheme } from './params/colorScheme';
import type { BibleNoteStorageManager } from './storageManager';
import type { FilePathResolver, FileRevealer } from './utils/filePathResolver';
import type { ExtraFontFamilyOption } from './utils/fontFamilyOptions';

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';

import { AppComp } from './AppComp';
import { EDITOR_STATE_LOCAL_STORAGE_KEY } from './editorStateStorage';
import { CHRISTIANITY_EXCALIDRAW_LIBRARY } from './params/excalidrawChristianityLibrary';

// setupEnv must load before App because lexical computes CAN_USE_BEFORE_INPUT
// at import time (disableBeforeInput is used to test legacy events)
import setupEnv from './setupEnv';
if (setupEnv.disableBeforeInput) {
  // vite is really aggressive about tree-shaking, this
  // ensures that the side-effects of importing setupEnv happens
}

export type BibleNoteSettingsController = {
  setColorScheme: (mode: BibleNoteColorScheme) => void;
};

export type BibleNoteEditorController = Parameters<
  BibleNoteEditorControllerOwner['connectEditorController']
>[0];

type MentionedBibleDataType = {
  title: string;
  fullText: string;
  style?: CSSProperties;
};

export type BibleNoteProps = {
  getLangCode: (text: string) => string;
  editorExtraFontFamilies: ReadonlyArray<ExtraFontFamilyOption>;
  excalidrawLibraryItems?: LibraryItems;
  excalidrawClearLibrariesFileList?: () => void;
  excalidrawLoadLibrariesFileList?: () => string[];
  excalidrawSaveLibrariesFile?: (librariesFile: string) => void;
  stickyNoteExtraFontFamilies: ReadonlyArray<string>;
  storageManager: BibleNoteStorageManager;
  saveData: (data: string) => Promise<void> | void;
  loadData: () => Promise<string | null> | string | null;
  resolveFilePath?: FilePathResolver;
  revealFile?: FileRevealer;
  print?: () => void;
  isOnApp?: boolean;
  isMinimize?: boolean;
  shortToVerseData?: (
    shortText: string,
  ) => Promise<MentionedBibleDataType | null>;
  verseFullTextToListShorts?: (fullText: string) => Promise<string[] | null>;
  changeBibleKey?: (
    event: React.MouseEvent<HTMLButtonElement>,
    verseFullText: string,
  ) => Promise<MentionedBibleDataType | null>;
};

export type BibleNoteRenderOptions = {
  settings?: ReactNode;
  settingsContainerElement?: Element | DocumentFragment;
};

export function createBibleNoteStorageManager({
  loadData,
  saveData,
  storageManager,
}: BibleNoteProps): BibleNoteStorageManager {
  return {
    async deleteSetting(key) {
      if (key === EDITOR_STATE_LOCAL_STORAGE_KEY) {
        await saveData('');
        return;
      }

      await storageManager.deleteSetting(key);
    },
    async getSetting<T = unknown>(key: string): Promise<T | null> {
      if (key === EDITOR_STATE_LOCAL_STORAGE_KEY) {
        const loadedData = await loadData();

        return (
          typeof loadedData === 'string' && loadedData.length > 0
            ? loadedData
            : null
        ) as T | null;
      }

      return storageManager.getSetting<T>(key);
    },
    async setSetting(key, value) {
      if (key === EDITOR_STATE_LOCAL_STORAGE_KEY) {
        const serializedValue = serializeStorageValue(value);

        if (serializedValue !== null) {
          await saveData(serializedValue);
        }

        return;
      }

      await storageManager.setSetting(key, value);
    },
  };
}

function serializeStorageValue(value: unknown): string | null {
  if (value === null || value === undefined) {
    return null;
  }

  if (typeof value === 'string') {
    return value;
  }

  try {
    return JSON.stringify(value) ?? null;
  } catch {
    return null;
  }
}

export function renderEditor(
  {
    props,
    containerElement,
    editorControllerOwner,
    footerActionButtonControllerOwner,
    settingsControllerOwner,
    storageManager,
  }: {
    props: BibleNoteProps;
    containerElement: HTMLElement;
    editorControllerOwner: BibleNoteEditorControllerOwner;
    footerActionButtonControllerOwner: BibleNoteFooterActionButtonControllerOwner;
    settingsControllerOwner: BibleNoteSettingsControllerOwner;
    storageManager: BibleNoteStorageManager;
  },
  { settings, settingsContainerElement }: BibleNoteRenderOptions = {},
): Root {
  const root = createRoot(containerElement);
  const resolveFilePath = props.resolveFilePath;
  const revealFile = props.revealFile;
  const print = props.print;
  const isOnApp = props.isOnApp ?? false;
  const isMinimize = props.isMinimize ?? false;

  root.render(
    <StrictMode>
      <AppComp
        detectTextLanguage={props.getLangCode}
        editorController={editorControllerOwner}
        editorExtraFontFamilies={props.editorExtraFontFamilies}
        excalidrawLibraryItems={[
          ...CHRISTIANITY_EXCALIDRAW_LIBRARY,
          ...(props.excalidrawLibraryItems ?? []),
        ]}
        excalidrawClearLibrariesFileList={
          props.excalidrawClearLibrariesFileList
        }
        excalidrawLoadLibrariesFileList={props.excalidrawLoadLibrariesFileList}
        excalidrawSaveLibrariesFile={props.excalidrawSaveLibrariesFile}
        footerActionButtonController={footerActionButtonControllerOwner}
        isMinimize={isMinimize}
        isOnApp={isOnApp}
        print={print}
        resolveFilePath={resolveFilePath}
        revealFile={revealFile}
        settings={settings}
        settingsContainerElement={settingsContainerElement}
        settingsController={settingsControllerOwner}
        stickyNoteExtraFontFamilies={props.stickyNoteExtraFontFamilies}
        storageManager={storageManager}
        shortToVerseData={props.shortToVerseData}
        verseFullTextToListShorts={props.verseFullTextToListShorts}
        changeBibleKey={props.changeBibleKey}
      />
    </StrictMode>,
  );
  return root;
}
