import type { JSX } from 'react';

import { CodeNode } from '@lexical/code';
import { registerCodeHighlighting, ShikiTokenizer } from '@lexical/code-shiki';
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { $nodesOfType } from 'lexical';
import { useEffect, useMemo } from 'react';

import { useSettings } from '../../context/SettingsContext';

const LIGHT_CODE_THEME = 'one-light';
const DARK_CODE_THEME = 'dark-plus';

function getDefaultCodeTheme(isDarkMode: boolean): string {
  return isDarkMode ? DARK_CODE_THEME : LIGHT_CODE_THEME;
}

export default function CodeHighlightShikiPlugin(): JSX.Element | null {
  const [editor] = useLexicalComposerContext();
  const {
    settings: { isDarkMode },
  } = useSettings();
  const defaultTheme = getDefaultCodeTheme(isDarkMode);
  const tokenizer = useMemo(
    () => ({
      ...ShikiTokenizer,
      defaultTheme,
    }),
    [defaultTheme],
  );

  useEffect(() => {
    return registerCodeHighlighting(editor, tokenizer);
  }, [editor, tokenizer]);

  useEffect(() => {
    const previousDefaultTheme = getDefaultCodeTheme(!isDarkMode);

    editor.update(() => {
      for (const codeNode of $nodesOfType(CodeNode)) {
        const codeTheme = codeNode.getTheme();

        if (codeTheme === undefined || codeTheme === previousDefaultTheme) {
          codeNode.setTheme(defaultTheme);
        }
      }
    });
  }, [defaultTheme, editor, isDarkMode]);

  return null;
}
