import type {
  EditorConfig,
  LexicalEditor,
  LexicalNode,
  LexicalUpdateJSON,
  NodeKey,
  SerializedEditor,
  SerializedLexicalNode,
  Spread,
} from 'lexical';
import type { JSX } from 'react';

import {
  $nodesOfType,
  $setSelection,
  createEditor,
  DecoratorNode,
} from 'lexical';
import * as React from 'react';
import { createPortal } from 'react-dom';

const StickyComponent = React.lazy(() => import('./StickyComponent'));

function getStickyPortalRoot(editor: LexicalEditor): HTMLElement {
  const rootElement = editor.getRootElement();

  if (rootElement === null) {
    return document.body;
  }

  const scroller = rootElement.closest<HTMLElement>('.editor-scroller');

  if (scroller !== null) {
    return scroller;
  }

  let portalRoot = rootElement;

  while (
    portalRoot.parentElement !== null &&
    portalRoot.parentElement !== document.body
  ) {
    portalRoot = portalRoot.parentElement;
  }

  return portalRoot;
}

export const STICKY_NOTE_COLORS = [
  'yellow',
  'pink',
  'blue',
  'mint',
  'lavender',
  'peach',
  'sage',
] as const;

export type StickyNoteColor = (typeof STICKY_NOTE_COLORS)[number];

export const DEFAULT_STICKY_NOTE_WIDTH = 120;
export const DEFAULT_STICKY_NOTE_HEIGHT = 80;
export const DEFAULT_STICKY_NOTE_LAYER = 0;
export const STICKY_NOTE_LAYER_BASE = 9;
export const MIN_STICKY_NOTE_WIDTH = 120;
export const MIN_STICKY_NOTE_HEIGHT = 80;

function normalizeStickyNoteDimension(
  dimension: number | undefined,
  minimumDimension: number,
  fallbackDimension: number,
): number {
  return typeof dimension === 'number' && Number.isFinite(dimension)
    ? Math.max(minimumDimension, dimension)
    : fallbackDimension;
}

function getNextStickyNoteColor(color: StickyNoteColor): StickyNoteColor {
  const currentIndex = STICKY_NOTE_COLORS.indexOf(color);
  return STICKY_NOTE_COLORS[(currentIndex + 1) % STICKY_NOTE_COLORS.length];
}

function normalizeStickyNoteLayer(layer: number | undefined): number {
  return typeof layer === 'number' && Number.isFinite(layer)
    ? Math.round(layer)
    : DEFAULT_STICKY_NOTE_LAYER;
}

function $getNextStickyNoteLayer(): number {
  const stickyNodes = $nodesOfType(StickyNode).filter((node) =>
    node.isAttached(),
  );

  if (stickyNodes.length === 0) {
    return DEFAULT_STICKY_NOTE_LAYER;
  }

  return Math.max(...stickyNodes.map((node) => node.__layer)) + 1;
}

function compareStickyNodesByLayer(
  firstNode: StickyNode,
  secondNode: StickyNode,
): number {
  return (
    firstNode.__layer - secondNode.__layer ||
    firstNode.getIndexWithinParent() - secondNode.getIndexWithinParent()
  );
}

export type SerializedStickyNode = Spread<
  {
    xOffset: number;
    yOffset: number;
    width?: number;
    height?: number;
    layer?: number;
    color: StickyNoteColor;
    caption: SerializedEditor;
  },
  SerializedLexicalNode
>;

export class StickyNode extends DecoratorNode<JSX.Element> {
  __x: number;
  __y: number;
  __width: number;
  __height: number;
  __layer: number;
  __color: StickyNoteColor;
  __caption: LexicalEditor;

  static getType(): string {
    return 'sticky';
  }

  static clone(node: StickyNode): StickyNode {
    return new StickyNode(
      node.__x,
      node.__y,
      node.__color,
      node.__caption,
      node.__key,
      node.__width,
      node.__height,
      node.__layer,
    );
  }
  static importJSON(serializedNode: SerializedStickyNode): StickyNode {
    return new StickyNode(
      serializedNode.xOffset,
      serializedNode.yOffset,
      serializedNode.color,
      undefined,
      undefined,
      serializedNode.width,
      serializedNode.height,
      serializedNode.layer,
    ).updateFromJSON(serializedNode);
  }

  updateFromJSON(
    serializedNode: LexicalUpdateJSON<SerializedStickyNode>,
  ): this {
    const stickyNode = super.updateFromJSON(serializedNode);
    stickyNode.__width = normalizeStickyNoteDimension(
      serializedNode.width,
      MIN_STICKY_NOTE_WIDTH,
      DEFAULT_STICKY_NOTE_WIDTH,
    );
    stickyNode.__height = normalizeStickyNoteDimension(
      serializedNode.height,
      MIN_STICKY_NOTE_HEIGHT,
      DEFAULT_STICKY_NOTE_HEIGHT,
    );
    stickyNode.__layer = normalizeStickyNoteLayer(serializedNode.layer);
    const caption = serializedNode.caption;
    const nestedEditor = stickyNode.__caption;
    const editorState = nestedEditor.parseEditorState(caption.editorState);
    if (!editorState.isEmpty()) {
      nestedEditor.setEditorState(editorState);
    }
    return stickyNode;
  }

  constructor(
    x: number,
    y: number,
    color: StickyNoteColor,
    caption?: LexicalEditor,
    key?: NodeKey,
    width?: number,
    height?: number,
    layer?: number,
  ) {
    super(key);
    this.__x = x;
    this.__y = y;
    this.__width = normalizeStickyNoteDimension(
      width,
      MIN_STICKY_NOTE_WIDTH,
      DEFAULT_STICKY_NOTE_WIDTH,
    );
    this.__height = normalizeStickyNoteDimension(
      height,
      MIN_STICKY_NOTE_HEIGHT,
      DEFAULT_STICKY_NOTE_HEIGHT,
    );
    this.__caption = caption || createEditor();
    this.__color = color;
    this.__layer = normalizeStickyNoteLayer(layer);
  }

  exportJSON(): SerializedStickyNode {
    return {
      ...super.exportJSON(),
      caption: this.__caption.toJSON(),
      color: this.__color,
      height: this.__height,
      layer: this.__layer,
      width: this.__width,
      xOffset: this.__x,
      yOffset: this.__y,
    };
  }

  createDOM(_config: EditorConfig): HTMLElement {
    const div = document.createElement('div');
    div.style.display = 'contents';
    return div;
  }

  updateDOM(): false {
    return false;
  }

  setPosition(x: number, y: number): void {
    const writable = this.getWritable();
    writable.__x = x;
    writable.__y = y;
    $setSelection(null);
  }

  setSize(width: number, height: number): void {
    const writable = this.getWritable();
    writable.__width = normalizeStickyNoteDimension(
      width,
      MIN_STICKY_NOTE_WIDTH,
      DEFAULT_STICKY_NOTE_WIDTH,
    );
    writable.__height = normalizeStickyNoteDimension(
      height,
      MIN_STICKY_NOTE_HEIGHT,
      DEFAULT_STICKY_NOTE_HEIGHT,
    );
    $setSelection(null);
  }

  toggleColor(): void {
    const writable = this.getWritable();
    writable.__color = getNextStickyNoteColor(writable.__color);
  }

  markCaptionChanged(): void {
    const writable = this.getWritable();
    writable.__caption = this.__caption;
  }

  bringToFront(): void {
    const stickyNodes = $nodesOfType(StickyNode).filter((node) =>
      node.isAttached(),
    );

    if (stickyNodes.length < 2) {
      return;
    }

    const orderedNodes = stickyNodes
      .filter((node) => !node.is(this))
      .sort(compareStickyNodesByLayer);

    [...orderedNodes, this].forEach((node, layer) => {
      node.getWritable().__layer = layer;
    });
    $setSelection(null);
  }

  sendToBack(): void {
    const stickyNodes = $nodesOfType(StickyNode).filter((node) =>
      node.isAttached(),
    );

    if (stickyNodes.length < 2) {
      return;
    }

    const orderedNodes = stickyNodes
      .filter((node) => !node.is(this))
      .sort(compareStickyNodesByLayer);

    [this, ...orderedNodes].forEach((node, layer) => {
      node.getWritable().__layer = layer;
    });
    $setSelection(null);
  }

  decorate(editor: LexicalEditor, _config: EditorConfig): JSX.Element {
    return createPortal(
      <StickyComponent
        color={this.__color}
        height={this.__height}
        layer={this.__layer}
        x={this.__x}
        y={this.__y}
        width={this.__width}
        nodeKey={this.getKey()}
        caption={this.__caption}
      />,
      getStickyPortalRoot(editor),
    );
  }

  isIsolated(): true {
    return true;
  }

  isInline(): false {
    // Sticky notes float above the document through a portal, so they must
    // stay top-level siblings instead of being wrapped into a paragraph.
    return false;
  }
}

export function $isStickyNode(
  node: LexicalNode | null | undefined,
): node is StickyNode {
  return node instanceof StickyNode;
}

export function $createStickyNode(
  xOffset: number,
  yOffset: number,
): StickyNode {
  return new StickyNode(
    xOffset,
    yOffset,
    'yellow',
    undefined,
    undefined,
    undefined,
    undefined,
    $getNextStickyNoteLayer(),
  );
}
