import { getBibleNoteStorage } from './storageManager';

export const EDITOR_ZOOM_LOCAL_STORAGE_KEY =
  'lexical-playground-editor-zoom-percent';

export function getStoredEditorZoomPercent(): number | null {
  const storage = getBibleNoteStorage();

  if (storage === null) {
    return null;
  }

  const serializedZoomPercent = storage.getItem(EDITOR_ZOOM_LOCAL_STORAGE_KEY);

  if (serializedZoomPercent === null) {
    return null;
  }

  const zoomPercent = Number(serializedZoomPercent);

  if (!Number.isFinite(zoomPercent)) {
    storage.removeItem(EDITOR_ZOOM_LOCAL_STORAGE_KEY);
    return null;
  }

  return zoomPercent;
}

export function writeStoredEditorZoomPercent(zoomPercent: number): void {
  const storage = getBibleNoteStorage();

  if (storage === null) {
    return;
  }

  if (!Number.isFinite(zoomPercent)) {
    storage.removeItem(EDITOR_ZOOM_LOCAL_STORAGE_KEY);
    return;
  }

  storage.setItem(EDITOR_ZOOM_LOCAL_STORAGE_KEY, String(zoomPercent));
}
