import type { JSX } from 'react';

import { $getSelection, $isRangeSelection, type LexicalEditor } from 'lexical';
import { useMemo, useState } from 'react';

import { HTML_CHARACTER_ENTITIES } from '../../utils/html-character-entities';
import { getBibleNoteStorage } from '../../storageManager';
import emojiList from '../../utils/emoji-list';

import './InsertCharacterDialog.scss';

type InsertCharacterDialogProps = Readonly<{
  activeEditor: LexicalEditor;
  onClose: () => void;
}>;

type CharacterPickerTab = 'emoji' | 'html';

type CharacterPickerOption = Readonly<{
  category: string;
  description: string;
  id: string;
  keywords: string;
  label: string;
  meta: string;
  value: string;
}>;

type CharacterPickerState = Readonly<{
  activeTab: CharacterPickerTab;
  recentOptionIds: ReadonlyArray<string>;
}>;

const MAX_RESULTS = 96;
const MAX_RECENT_OPTIONS = 12;
export const CHARACTER_PICKER_LOCAL_STORAGE_KEY =
  'lexical-playground-insert-character-picker';

const EMOJI_OPTIONS: ReadonlyArray<CharacterPickerOption> = emojiList.map(
  (entry) => ({
    category: entry.category,
    description: entry.description,
    id: `emoji:${entry.description}:${entry.emoji}`,
    keywords: [
      entry.description,
      entry.category,
      ...entry.aliases,
      ...entry.tags,
    ]
      .join(' ')
      .toLowerCase(),
    label: entry.emoji,
    meta: entry.aliases.map((alias) => `:${alias}:`).join(' '),
    value: entry.emoji,
  }),
);

const HTML_CHARACTER_OPTIONS: ReadonlyArray<CharacterPickerOption> =
  HTML_CHARACTER_ENTITIES.map((entry) => ({
    category: entry.category,
    description: entry.description,
    id: `html:${entry.description}:${entry.character}:${entry.entities.join('|')}`,
    keywords: [
      entry.description,
      entry.category,
      entry.character,
      ...entry.entities,
    ]
      .join(' ')
      .toLowerCase(),
    label: entry.character,
    meta: entry.entities.join(' '),
    value: entry.character,
  }));

const CHARACTER_OPTIONS_BY_ID = new Map(
  [...EMOJI_OPTIONS, ...HTML_CHARACTER_OPTIONS].map((option) => [
    option.id,
    option,
  ]),
);

function getFilteredOptions(
  options: ReadonlyArray<CharacterPickerOption>,
  query: string,
  recentOptionIds: ReadonlyArray<string>,
): ReadonlyArray<CharacterPickerOption> {
  const normalizedQuery = query.trim().toLowerCase();

  if (normalizedQuery.length === 0) {
    const optionIds = new Set(options.map((option) => option.id));
    const recentOptions = recentOptionIds
      .map((optionId) => CHARACTER_OPTIONS_BY_ID.get(optionId))
      .filter(
        (option): option is CharacterPickerOption =>
          option !== undefined && optionIds.has(option.id),
      );
    const recentIds = new Set(recentOptions.map((option) => option.id));

    return [
      ...recentOptions,
      ...options.filter((option) => !recentIds.has(option.id)),
    ].slice(0, MAX_RESULTS);
  }

  return options
    .filter((option) => option.keywords.includes(normalizedQuery))
    .slice(0, MAX_RESULTS);
}

function getInitialCharacterPickerState(): CharacterPickerState {
  const storage = getCharacterPickerStorage();

  if (storage === null) {
    return { activeTab: 'emoji', recentOptionIds: [] };
  }

  try {
    const rawValue = storage.getItem(CHARACTER_PICKER_LOCAL_STORAGE_KEY);

    if (rawValue === null) {
      return { activeTab: 'emoji', recentOptionIds: [] };
    }

    const parsedValue = JSON.parse(rawValue) as Partial<CharacterPickerState>;
    const activeTab =
      parsedValue.activeTab === 'html' || parsedValue.activeTab === 'emoji'
        ? parsedValue.activeTab
        : 'emoji';
    const recentOptionIds = Array.isArray(parsedValue.recentOptionIds)
      ? parsedValue.recentOptionIds.filter(
          (optionId): optionId is string =>
            typeof optionId === 'string' &&
            CHARACTER_OPTIONS_BY_ID.has(optionId),
        )
      : [];

    return { activeTab, recentOptionIds };
  } catch {
    storage.removeItem(CHARACTER_PICKER_LOCAL_STORAGE_KEY);
    return { activeTab: 'emoji', recentOptionIds: [] };
  }
}

function persistCharacterPickerState(state: CharacterPickerState): void {
  const storage = getCharacterPickerStorage();

  if (storage === null) {
    return;
  }

  storage.setItem(CHARACTER_PICKER_LOCAL_STORAGE_KEY, JSON.stringify(state));
}

function getCharacterPickerStorage(): Storage | null {
  return getBibleNoteStorage() as Storage | null;
}

export default function InsertCharacterDialog({
  activeEditor,
  onClose,
}: InsertCharacterDialogProps): JSX.Element {
  const [pickerState, setPickerState] = useState(
    getInitialCharacterPickerState,
  );
  const [query, setQuery] = useState('');
  const { activeTab, recentOptionIds } = pickerState;

  const options =
    activeTab === 'emoji' ? EMOJI_OPTIONS : HTML_CHARACTER_OPTIONS;
  const filteredOptions = useMemo(
    () => getFilteredOptions(options, query, recentOptionIds),
    [options, query, recentOptionIds],
  );

  const setActiveTab = (nextActiveTab: CharacterPickerTab) => {
    const nextState = { ...pickerState, activeTab: nextActiveTab };
    setPickerState(nextState);
    persistCharacterPickerState(nextState);
  };

  const insertCharacter = (option: CharacterPickerOption) => {
    activeEditor.update(() => {
      const selection = $getSelection();
      if ($isRangeSelection(selection)) {
        selection.insertText(option.value);
      }
    });

    persistCharacterPickerState({
      activeTab,
      recentOptionIds: [
        option.id,
        ...recentOptionIds.filter((optionId) => optionId !== option.id),
      ].slice(0, MAX_RECENT_OPTIONS),
    });
    onClose();
  };

  return (
    <div className="InsertCharacterDialog">
      <div className="InsertCharacterDialog__controls">
        <input
          aria-label="Search emoji and HTML characters"
          className="InsertCharacterDialog__search form-control"
          onChange={(event) => setQuery(event.target.value)}
          placeholder={
            activeTab === 'emoji'
              ? 'Search emoji by name, alias, or tag'
              : 'Search by character, entity, or name'
          }
          type="search"
          value={query}
        />
        <div className="InsertCharacterDialog__tabs" role="group">
          <button
            aria-pressed={activeTab === 'emoji'}
            className="InsertCharacterDialog__tab"
            onClick={() => setActiveTab('emoji')}
            type="button"
          >
            Emoji
          </button>
          <button
            aria-pressed={activeTab === 'html'}
            className="InsertCharacterDialog__tab"
            onClick={() => setActiveTab('html')}
            type="button"
          >
            HTML
          </button>
        </div>
      </div>
      <div className="InsertCharacterDialog__results">
        {filteredOptions.length === 0 ? (
          <div className="InsertCharacterDialog__empty">No matches</div>
        ) : (
          filteredOptions.map((option) => (
            <button
              aria-label={`Insert ${option.description}`}
              className="InsertCharacterDialog__item"
              key={option.id}
              onClick={() => insertCharacter(option)}
              title={`${option.description} ${option.meta}`}
              type="button"
            >
              <span className="InsertCharacterDialog__symbol">
                {option.label}
              </span>
              <span className="InsertCharacterDialog__meta">
                <span className="InsertCharacterDialog__name">
                  {option.description}
                </span>
                <span className="InsertCharacterDialog__entities">
                  {option.meta || option.category}
                </span>
              </span>
            </button>
          ))
        )}
      </div>
    </div>
  );
}
