import { clearStoredBlockTextLinks } from './blockTextLinkStorage';
import { getBibleNoteStorage } from './storageManager';

export const EDITOR_STATE_LOCAL_STORAGE_KEY = 'lexical-playground-editor-state';
export const SHARED_EDITOR_STATE_QUERY_PARAM = 'editor-state';
export const SHARED_EDITOR_STATE_PASSWORD_PREFIX = 'pwdecrypted:';

const SHARED_EDITOR_STATE_PASSWORD_DIALOG_MESSAGE =
  'Enter the password to open this shared link.';
const SHARED_EDITOR_STATE_PASSWORD_RETRY_MESSAGE =
  'Password was incorrect or the protected link is invalid. Try again or cancel.';
const SHARE_ENCRYPTION_ALGORITHM = 'AES-GCM';
const SHARE_ENCRYPTION_DERIVATION_ALGORITHM = 'PBKDF2';
const SHARE_ENCRYPTION_HASH = 'SHA-256';
const SHARE_ENCRYPTION_KEY_LENGTH = 256;
const SHARE_ENCRYPTION_IV_BYTES = 12;
const SHARE_ENCRYPTION_SALT_BYTES = 16;
const SHARE_ENCRYPTION_ITERATIONS = 600000;

type SharedEditorStatePasswordRequest = (options: {
  message: string;
  retry: boolean;
}) => Promise<string | null> | string | null;

export function buildSharedEditorStateUrl(
  serializedEditorState: string,
  href = getCurrentHref(),
): string | null {
  const normalizedEditorState = normalizeSerializedEditorState(
    serializedEditorState,
  );

  if (normalizedEditorState === null || href === null) {
    return null;
  }

  return buildSharedEditorStateUrlFromQueryValue(
    encodeBase64Utf8(normalizedEditorState),
    href,
  );
}

export async function buildPasswordProtectedSharedEditorStateUrl(
  serializedEditorState: string,
  password: string,
  href = getCurrentHref(),
): Promise<string | null> {
  const normalizedEditorState = normalizeSerializedEditorState(
    serializedEditorState,
  );

  if (normalizedEditorState === null || href === null || password.length < 1) {
    return null;
  }

  return buildSharedEditorStateUrlFromQueryValue(
    await encryptSharedEditorState(normalizedEditorState, password),
    href,
  );
}

export function hasPasswordProtectedSharedEditorStateParam(): boolean {
  const rawSharedState = getRawSharedEditorStateParam();

  return (
    rawSharedState !== null &&
    normalizeSharedEditorStateParam(rawSharedState).startsWith(
      SHARED_EDITOR_STATE_PASSWORD_PREFIX,
    )
  );
}

export function isSharedEditorStateEncryptionSupported(): boolean {
  return getShareCrypto() !== null;
}

export async function getStoredEditorStateAsync(options?: {
  requestPassword?: SharedEditorStatePasswordRequest;
}): Promise<null | string> {
  const sharedEditorState = await getSharedEditorStateFromUrlAsync(options);

  if (sharedEditorState !== null) {
    writeStoredEditorState(sharedEditorState);
    clearSharedEditorStateParamFromUrl();
    return sharedEditorState;
  }

  return getStoredEditorStateFromStorage();
}

export function getStoredEditorState(): null | string {
  const sharedEditorState = getSharedEditorStateFromUrl();

  if (sharedEditorState !== null) {
    writeStoredEditorState(sharedEditorState);
    clearSharedEditorStateParamFromUrl();
    return sharedEditorState;
  }

  return getStoredEditorStateFromStorage();
}

function getStoredEditorStateFromStorage(): null | string {
  const storage = getEditorStorage();

  if (storage === null) {
    return null;
  }

  const serializedEditorState = storage.getItem(EDITOR_STATE_LOCAL_STORAGE_KEY);

  if (serializedEditorState === null) {
    return null;
  }

  const normalizedEditorState = normalizeSerializedEditorState(
    serializedEditorState,
  );

  if (normalizedEditorState === null) {
    storage.removeItem(EDITOR_STATE_LOCAL_STORAGE_KEY);
    return null;
  }

  if (normalizedEditorState !== serializedEditorState) {
    storage.setItem(EDITOR_STATE_LOCAL_STORAGE_KEY, normalizedEditorState);
  }

  return normalizedEditorState;
}

function buildSharedEditorStateUrlFromQueryValue(
  sharedValue: string,
  href: string,
): string {
  const url = new URL(href);

  url.searchParams.set(SHARED_EDITOR_STATE_QUERY_PARAM, sharedValue);

  return url.toString();
}

function getRawSharedEditorStateParam(): string | null {
  if (typeof window === 'undefined') {
    return null;
  }

  const searchParams = new URLSearchParams(window.location.search);

  return searchParams.get(SHARED_EDITOR_STATE_QUERY_PARAM);
}

function getSharedEditorStateFromUrl(): string | null {
  const rawSharedState = getRawSharedEditorStateParam();

  if (rawSharedState === null) {
    return null;
  }

  const normalizedSharedState = normalizeSharedEditorStateParam(rawSharedState);

  if (normalizedSharedState.startsWith(SHARED_EDITOR_STATE_PASSWORD_PREFIX)) {
    return null;
  }

  try {
    return normalizeSerializedEditorState(
      decodeBase64Utf8(normalizedSharedState),
    );
  } catch {
    return null;
  }
}

async function getSharedEditorStateFromUrlAsync(options?: {
  requestPassword?: SharedEditorStatePasswordRequest;
}): Promise<string | null> {
  const rawSharedState = getRawSharedEditorStateParam();

  if (rawSharedState === null) {
    return null;
  }

  try {
    const serializedEditorState = await resolveSharedEditorStateQueryValue(
      normalizeSharedEditorStateParam(rawSharedState),
      options,
    );

    return serializedEditorState === null
      ? null
      : normalizeSerializedEditorState(serializedEditorState);
  } catch {
    return null;
  }
}

async function resolveSharedEditorStateQueryValue(
  sharedValue: string,
  options?: {
    requestPassword?: SharedEditorStatePasswordRequest;
  },
): Promise<string | null> {
  if (!sharedValue.startsWith(SHARED_EDITOR_STATE_PASSWORD_PREFIX)) {
    return decodeBase64Utf8(sharedValue);
  }

  const requestPassword =
    options?.requestPassword ?? requestSharedEditorStatePasswordWithPrompt;
  let message = SHARED_EDITOR_STATE_PASSWORD_DIALOG_MESSAGE;
  let retry = false;

  while (true) {
    const password = await requestPassword({ message, retry });

    if (password === null) {
      return null;
    }

    try {
      return await decryptSharedEditorState(sharedValue, password);
    } catch {
      message = SHARED_EDITOR_STATE_PASSWORD_RETRY_MESSAGE;
      retry = true;
    }
  }
}

function requestSharedEditorStatePasswordWithPrompt({
  message,
}: {
  message: string;
  retry: boolean;
}): string | null {
  if (typeof window === 'undefined' || typeof window.prompt !== 'function') {
    return null;
  }

  return window.prompt(message);
}

export function writeStoredEditorState(serializedEditorState: string): void {
  const storage = getEditorStorage();

  if (storage === null || !isSerializedEditorState(serializedEditorState)) {
    return;
  }

  storage.setItem(EDITOR_STATE_LOCAL_STORAGE_KEY, serializedEditorState);
}

export function clearStoredEditorState(): void {
  const storage = getEditorStorage();

  if (storage === null) {
    return;
  }

  storage.removeItem(EDITOR_STATE_LOCAL_STORAGE_KEY);
  clearStoredBlockTextLinks();
}

function getEditorStorage(): Storage | null {
  return getBibleNoteStorage() as Storage | null;
}

function getCurrentHref(): string | null {
  if (typeof window === 'undefined') {
    return null;
  }

  return window.location.href;
}

function clearSharedEditorStateParamFromUrl(): void {
  if (
    typeof window === 'undefined' ||
    typeof window.history?.replaceState !== 'function'
  ) {
    return;
  }

  const url = new URL(window.location.href);

  if (!url.searchParams.has(SHARED_EDITOR_STATE_QUERY_PARAM)) {
    return;
  }

  url.searchParams.delete(SHARED_EDITOR_STATE_QUERY_PARAM);
  const nextSearch = url.searchParams.toString();
  const nextUrl = `${url.pathname}${nextSearch ? `?${nextSearch}` : ''}${url.hash}`;

  window.history.replaceState(window.history.state, '', nextUrl);
}

function normalizeSharedEditorStateParam(value: string): string {
  const trimmedValue = value.trim();

  if (
    trimmedValue.length >= 2 &&
    trimmedValue.startsWith('"') &&
    trimmedValue.endsWith('"')
  ) {
    return trimmedValue.slice(1, -1);
  }

  return trimmedValue;
}

function encodeBase64Utf8(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let binaryText = '';

  bytes.forEach((byte) => {
    binaryText += String.fromCharCode(byte);
  });

  return globalThis.btoa(binaryText);
}

function decodeBase64Utf8(base64Text: string): string {
  const normalizedBase64Text = base64Text.replace(/\s+/g, '');
  const binaryText = globalThis.atob(normalizedBase64Text);
  const bytes = Uint8Array.from(binaryText, (character) =>
    character.charCodeAt(0),
  );

  return new TextDecoder().decode(bytes);
}

function toArrayBuffer(bytes: Uint8Array): ArrayBuffer {
  const arrayBuffer = new ArrayBuffer(bytes.byteLength);

  new Uint8Array(arrayBuffer).set(bytes);

  return arrayBuffer;
}

function encodeBase64Bytes(bytes: Uint8Array): string {
  let binaryText = '';

  bytes.forEach((byte) => {
    binaryText += String.fromCharCode(byte);
  });

  return globalThis.btoa(binaryText);
}

function decodeBase64Bytes(base64Text: string): Uint8Array {
  const normalizedBase64Text = base64Text.replace(/\s+/g, '');
  const binaryText = globalThis.atob(normalizedBase64Text);

  return Uint8Array.from(binaryText, (character) => character.charCodeAt(0));
}

function encodeBase64UrlBytes(bytes: Uint8Array): string {
  return encodeBase64Bytes(bytes)
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

function decodeBase64UrlBytes(base64UrlText: string): Uint8Array {
  const normalizedBase64Text = base64UrlText
    .replace(/\s+/g, '')
    .replace(/-/g, '+')
    .replace(/_/g, '/');
  const paddingLength = (4 - (normalizedBase64Text.length % 4)) % 4;

  return decodeBase64Bytes(
    `${normalizedBase64Text}${'='.repeat(paddingLength)}`,
  );
}

function getShareCrypto(): Crypto | null {
  if (!globalThis.crypto?.subtle || !globalThis.crypto.getRandomValues) {
    return null;
  }

  return globalThis.crypto;
}

async function deriveShareEncryptionKey(
  password: string,
  salt: Uint8Array,
  iterations: number,
): Promise<CryptoKey> {
  const cryptoApi = getShareCrypto();

  if (cryptoApi === null) {
    throw new Error('Web Crypto is unavailable.');
  }

  const baseKey = await cryptoApi.subtle.importKey(
    'raw',
    toArrayBuffer(new TextEncoder().encode(password)),
    SHARE_ENCRYPTION_DERIVATION_ALGORITHM,
    false,
    ['deriveKey'],
  );

  return cryptoApi.subtle.deriveKey(
    {
      name: SHARE_ENCRYPTION_DERIVATION_ALGORITHM,
      salt: toArrayBuffer(salt),
      iterations,
      hash: SHARE_ENCRYPTION_HASH,
    },
    baseKey,
    {
      name: SHARE_ENCRYPTION_ALGORITHM,
      length: SHARE_ENCRYPTION_KEY_LENGTH,
    },
    false,
    ['encrypt', 'decrypt'],
  );
}

function serializeEncryptedShareValue({
  iterations,
  salt,
  iv,
  ciphertext,
}: {
  ciphertext: Uint8Array;
  iterations: number;
  iv: Uint8Array;
  salt: Uint8Array;
}): string {
  return `${SHARED_EDITOR_STATE_PASSWORD_PREFIX}v1.${iterations}.${encodeBase64UrlBytes(
    salt,
  )}.${encodeBase64UrlBytes(iv)}.${encodeBase64UrlBytes(ciphertext)}`;
}

function parseEncryptedShareValue(encryptedValue: string): {
  ciphertext: Uint8Array;
  iterations: number;
  iv: Uint8Array;
  salt: Uint8Array;
} {
  if (!encryptedValue.startsWith(SHARED_EDITOR_STATE_PASSWORD_PREFIX)) {
    throw new Error('Encrypted share prefix is missing.');
  }

  const payloadText = encryptedValue.slice(
    SHARED_EDITOR_STATE_PASSWORD_PREFIX.length,
  );
  const parts = payloadText.split('.');

  if (parts.length !== 5) {
    throw new Error('Encrypted share payload is malformed.');
  }

  const [version, iterationText, saltText, ivText, ciphertextText] = parts;
  const iterations = Number.parseInt(iterationText, 10);

  if (version !== 'v1' || !Number.isSafeInteger(iterations) || iterations < 1) {
    throw new Error('Encrypted share payload metadata is invalid.');
  }

  return {
    iterations,
    salt: decodeBase64UrlBytes(saltText),
    iv: decodeBase64UrlBytes(ivText),
    ciphertext: decodeBase64UrlBytes(ciphertextText),
  };
}

async function encryptSharedEditorState(
  serializedEditorState: string,
  password: string,
): Promise<string> {
  const cryptoApi = getShareCrypto();

  if (cryptoApi === null) {
    throw new Error('Web Crypto is unavailable.');
  }

  const salt = cryptoApi.getRandomValues(
    new Uint8Array(SHARE_ENCRYPTION_SALT_BYTES),
  );
  const iv = cryptoApi.getRandomValues(
    new Uint8Array(SHARE_ENCRYPTION_IV_BYTES),
  );
  const key = await deriveShareEncryptionKey(
    password,
    salt,
    SHARE_ENCRYPTION_ITERATIONS,
  );
  const ciphertextBuffer = await cryptoApi.subtle.encrypt(
    {
      name: SHARE_ENCRYPTION_ALGORITHM,
      iv: toArrayBuffer(iv),
    },
    key,
    toArrayBuffer(new TextEncoder().encode(serializedEditorState)),
  );

  return serializeEncryptedShareValue({
    iterations: SHARE_ENCRYPTION_ITERATIONS,
    salt,
    iv,
    ciphertext: new Uint8Array(ciphertextBuffer),
  });
}

async function decryptSharedEditorState(
  encryptedValue: string,
  password: string,
): Promise<string> {
  const cryptoApi = getShareCrypto();

  if (cryptoApi === null) {
    throw new Error('Web Crypto is unavailable.');
  }

  const { iterations, salt, iv, ciphertext } =
    parseEncryptedShareValue(encryptedValue);
  const key = await deriveShareEncryptionKey(password, salt, iterations);
  const plaintextBuffer = await cryptoApi.subtle.decrypt(
    {
      name: SHARE_ENCRYPTION_ALGORITHM,
      iv: toArrayBuffer(iv),
    },
    key,
    toArrayBuffer(ciphertext),
  );

  return new TextDecoder().decode(plaintextBuffer);
}

function isSerializedEditorState(serializedEditorState: string): boolean {
  try {
    const parsedEditorState: unknown = JSON.parse(serializedEditorState);

    return (
      parsedEditorState !== null &&
      typeof parsedEditorState === 'object' &&
      !Array.isArray(parsedEditorState) &&
      'root' in parsedEditorState
    );
  } catch {
    return false;
  }
}

function normalizeSerializedEditorState(
  serializedEditorState: string,
): null | string {
  if (!isSerializedEditorState(serializedEditorState)) {
    return null;
  }

  const parsedEditorState = JSON.parse(serializedEditorState) as Record<
    string,
    unknown
  >;
  const migratedEditorState = migrateLegacyEditorState(parsedEditorState);

  return migratedEditorState.changed
    ? JSON.stringify(migratedEditorState.value)
    : serializedEditorState;
}

function migrateLegacyEditorState(value: unknown): {
  changed: boolean;
  value: unknown;
} {
  if (Array.isArray(value)) {
    let changed = false;
    const nextValue = value.map((item) => {
      const migratedItem = migrateLegacyEditorState(item);

      if (migratedItem.changed) {
        changed = true;
      }

      return migratedItem.value;
    });

    return {
      changed,
      value: changed ? nextValue : value,
    };
  }

  if (value === null || typeof value !== 'object') {
    return { changed: false, value };
  }

  let changed = false;
  const nextValue: Record<string, unknown> = {};

  for (const [key, nestedValue] of Object.entries(value)) {
    const migratedValue = migrateLegacyEditorState(nestedValue);

    if (migratedValue.changed) {
      changed = true;
    }

    nextValue[key] = migratedValue.value;
  }

  if (nextValue.type === 'location' || nextValue.type === 'hashtag') {
    nextValue.type = 'text';
    changed = true;
  }

  return {
    changed,
    value: changed ? nextValue : value,
  };
}
