import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap-icons/font/bootstrap-icons.css';

// setupEnv must load before App because lexical computes CAN_USE_BEFORE_INPUT
// at import time (disableBeforeInput is used to test legacy events)
import setupEnv from './setupEnv';

import BibleNote, { type BibleNoteFooterActionButton } from './BibleNote';
import { EDITOR_STATE_LOCAL_STORAGE_KEY } from './editorStateStorage';
import BibleNoteSettings from './params/BibleNoteSettings';
import { createBrowserStorageManager } from './storageManager';
import type { FilePathResolver, FileRevealer } from './utils/filePathResolver';
import type { ExtraFontFamilyOption } from './utils/fontFamilyOptions';

if (setupEnv.disableBeforeInput) {
  // vite is really aggressive about tree-shaking, this
  // ensures that the side-effects of importing setupEnv happens
}

function mount() {
  // Handle runtime errors
  // vite-error-overlay expects an ErrorPayload-ish object ({ message, stack }),
  // not a raw ErrorEvent/rejection reason. Passing the event itself makes the
  // overlay constructor throw, which both hides the overlay and buries the
  // original error under a confusing secondary TypeError.
  const showErrorOverlay = (cause: unknown) => {
    const ErrorOverlay = customElements.get('vite-error-overlay');
    if (!ErrorOverlay) {
      return;
    }

    const error =
      cause instanceof ErrorEvent ? (cause.error ?? cause.message) : cause;
    const err =
      error instanceof Error
        ? { message: error.message, stack: error.stack ?? '' }
        : { message: String(error), stack: '' };

    try {
      const overlay = new ErrorOverlay(err);
      const body = document.body;
      if (body !== null) {
        body.appendChild(overlay);
      }
    } catch (overlayError) {
      // Never let the overlay itself mask the error it is reporting.
      console.error('Failed to render error overlay', overlayError, err);
    }
  };

  window.addEventListener('error', (event) => showErrorOverlay(event));
  window.addEventListener('unhandledrejection', ({ reason }) =>
    showErrorOverlay(reason),
  );

  const stickyNoteExtraFontFamilies = ['Fasthand'];
  const editorExtraFontFamilies: ReadonlyArray<ExtraFontFamilyOption> = [
    ['Battambang', 'km'],
  ];
  const storageManager = createBrowserStorageManager();

  const resolveLocalFilePath: FilePathResolver = async (_file: any) => {
    return null;
  };

  function getLangCode(text: string): string {
    if (/[\u1780-\u17FF]/u.test(text)) {
      return 'km';
    }
    return 'en';
  }

  async function saveData(data: string): Promise<void> {
    if (data.length === 0) {
      await storageManager.deleteSetting(EDITOR_STATE_LOCAL_STORAGE_KEY);
      return;
    }
    await storageManager.setSetting(EDITOR_STATE_LOCAL_STORAGE_KEY, data);
  }

  async function loadData(): Promise<string> {
    const data =
      (await storageManager.getSetting<string>(
        EDITOR_STATE_LOCAL_STORAGE_KEY,
      )) ?? '';
    return data;
  }

  const containerElement = document.getElementById('root');
  if (containerElement === null) {
    throw new Error('Root container missing in index.html');
  }

  const settingsContainerElement =
    document.getElementById('bible-note-settings-root') ??
    document.createElement('div');
  settingsContainerElement.id = 'bible-note-settings-root';
  settingsContainerElement.className = 'bible-note-settings-root';
  if (!settingsContainerElement.isConnected) {
    document.body.appendChild(settingsContainerElement);
  }

  const maybeRevealFile = (window as Window & { revealFile?: unknown })
    .revealFile;
  const revealFile =
    typeof maybeRevealFile === 'function'
      ? (maybeRevealFile as FileRevealer)
      : undefined;
  const shortToVerseData = async (_shortVerse: string) => {
    console.log('called shortToVerseData');

    // GEN 1:1 -> (KJV) Genesis 1:1\n(1): In the beginning God created the
    // heaven and the earth.
    return {
      title: 'Genesis 1:1',
      fullText:
        '(KJV) Genesis 1:1\n(1): In the beginning God created the heaven and the earth.',
      style: {
        color: 'green',
      },
    };
    // return null;
  };
  const verseFullTextToListShorts = async (_fullText: string) => {
    console.log('called verseFullTextToListShorts');

    // (KJV) Genesis 1:1\n(1): In the beginning God created the heaven and the
    // earth. -> ['GEN 1:1']
    // return ['GEN 2:6', 'GEN 2:7', 'GEN 2:8', 'GEN 2:9', 'GEN 2:10'];
    return null;
  };

  const changeBibleKey = async (
    _event: React.MouseEvent<HTMLButtonElement>,
    _verseFullText: string,
  ) => {
    if (Math.random() < 0.3) {
      return null;
    }
    if (Math.random() < 0.5) {
      return {
        title: '(ESV) Matthew 6:1',
        fullText:
          '(ESV) Matthew 6:1\n(1):Beware of practicing your righteousness before other people in order to be seen by them, for then you will have no reward from your Father who is in heaven.',
      };
    }
    return {
      title: '(KJV) Genesis 1:1',
      fullText:
        '(KJV) Genesis 1:1\n(1): In the beginning God created the heaven and the earth.',
    };
  };

  const excalidrawLoadLibrariesFileList = () => {
    const libraries = localStorage.getItem('excalidraw-libraries');
    if (libraries === null) {
      return [];
    }

    try {
      const parsedLibraries = JSON.parse(libraries);
      return Array.isArray(parsedLibraries)
        ? parsedLibraries.filter(
            (librariesFile): librariesFile is string =>
              typeof librariesFile === 'string',
          )
        : [];
    } catch {
      return [];
    }
  };
  const excalidrawSaveLibrariesFile = (librariesFile: string) => {
    const existingLibrariesFileList = excalidrawLoadLibrariesFileList();
    if (existingLibrariesFileList.includes(librariesFile)) {
      return;
    }

    const mergedLibrariesFileList = [
      librariesFile,
      ...existingLibrariesFileList,
    ];
    localStorage.setItem(
      'excalidraw-libraries',
      JSON.stringify(mergedLibrariesFileList),
    );
  };
  const excalidrawClearLibrariesFileList = () => {
    localStorage.removeItem('excalidraw-libraries');
  };

  const bibleNote = new BibleNote({
    getLangCode,
    editorExtraFontFamilies,
    loadData,
    saveData,
    storageManager,
    stickyNoteExtraFontFamilies,
    resolveFilePath: resolveLocalFilePath,
    ...(revealFile === undefined ? {} : { revealFile }),
    isOnApp: false,
    isMinimize: false,
    shortToVerseData,
    verseFullTextToListShorts,
    changeBibleKey,
    excalidrawClearLibrariesFileList,
    excalidrawLoadLibrariesFileList,
    excalidrawSaveLibrariesFile,
  });
  bibleNote.unmount();
  bibleNote.render(containerElement, {
    settings: (
      <BibleNoteSettings
        setColorScheme={(mode) => {
          bibleNote.setColorScheme(mode);
        }}
      />
    ),
    settingsContainerElement,
  });
  const buttonData: BibleNoteFooterActionButton = {
    id: 'khmer-markdown-editor',
    description: 'Open in Khmer Markdown Editor',
    shortcutKey: 'Ctrl+Shift+Alt+K',
    children: (
      <button
        className="action-button"
        onClick={() => {
          window.open('https://editor-km.openworship.app', '_blank');
        }}
        title={'Open Khmer Markdown Editor'}
        aria-label={'Open Khmer Markdown Editor'}
        aria-pressed={false}
      >
        <i className={`bi bi-spellcheck`} />
      </button>
    ),
  };
  bibleNote.prependFooterActionButton(buttonData);
  bibleNote.prependFooterActionButton({
    id: 'test-button',
    description: 'Test Button',
    children: <button className="action-button">Test</button>,
  });
  // Test even it's added twice, only one instance will be rendered and
  // same position will be reserved for it.
  bibleNote.prependFooterActionButton(buttonData);
  console.log(
    bibleNote.getFooterActionButton('khmer-markdown-editor') === buttonData,
  );
  console.log('version', BibleNote.VERSION);
  (window as any).bibleNote = bibleNote;
}
if (!(window as any).notAutoMount) {
  mount();
} else {
  (window as any).AppBibleNote = BibleNote;
}

