import type {
  DOMConversionMap,
  DOMConversionOutput,
  DOMExportOutput,
  EditorConfig,
  ElementFormatType,
  LexicalEditor,
  LexicalNode,
  NodeKey,
  Spread,
} from 'lexical';
import type { JSX } from 'react';

import { BlockWithAlignableContents } from '@lexical/react/LexicalBlockWithAlignableContents';
import {
  DecoratorBlockNode,
  type SerializedDecoratorBlockNode,
} from '@lexical/react/LexicalDecoratorBlockNode';
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { useLexicalEditable } from '@lexical/react/useLexicalEditable';
import { useLexicalNodeSelection } from '@lexical/react/useLexicalNodeSelection';
import {
  $getNodeByKey,
  CLICK_COMMAND,
  COMMAND_PRIORITY_LOW,
  isDOMNode,
} from 'lexical';
import { useCallback, useEffect, useRef, useState } from 'react';
import * as React from 'react';

import MediaResizer from '../ui/MediaResizer';

const YOUTUBE_IFRAME_ALLOW =
  'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture';
const YOUTUBE_DEFAULT_WIDTH = 560;
const YOUTUBE_DEFAULT_HEIGHT = 315;

type Dimension = number | 'inherit';

function parseDimension(value: string | null): Dimension {
  if (value === null) {
    return 'inherit';
  }
  const parsed = Number.parseInt(value, 10);
  return Number.isNaN(parsed) ? 'inherit' : parsed;
}

type YouTubeComponentProps = Readonly<{
  className: Readonly<{
    base: string;
    focus: string;
  }>;
  format: ElementFormatType | null;
  height: Dimension;
  nodeKey: NodeKey;
  videoID: string;
  width: Dimension;
}>;

function YouTubeComponent({
  className,
  format,
  height,
  nodeKey,
  videoID,
  width,
}: YouTubeComponentProps) {
  const [editor] = useLexicalComposerContext();
  const isEditable = useLexicalEditable();
  const [isSelected, setSelected, clearSelection] =
    useLexicalNodeSelection(nodeKey);
  const [isResizing, setIsResizing] = useState(false);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const captionButtonRef = useRef<HTMLButtonElement | null>(null);

  useEffect(() => {
    if (!isEditable) {
      if (isSelected) {
        clearSelection();
      }
      return;
    }
    return editor.registerCommand<MouseEvent>(
      CLICK_COMMAND,
      (event) => {
        if (isResizing) {
          return true;
        }
        const target = event.target;
        if (
          containerRef.current !== null &&
          isDOMNode(target) &&
          containerRef.current.contains(target)
        ) {
          if (!event.shiftKey) {
            clearSelection();
          }
          setSelected(!isSelected);
          return true;
        }
        return false;
      },
      COMMAND_PRIORITY_LOW,
    );
  }, [clearSelection, editor, isEditable, isResizing, isSelected, setSelected]);

  const onResizeStart = useCallback(() => {
    setIsResizing(true);
  }, []);

  const onResizeEnd = useCallback(
    (nextWidth: Dimension, nextHeight: Dimension) => {
      // Delay hiding the resize bars for click case
      setTimeout(() => {
        setIsResizing(false);
      }, 200);

      editor.update(() => {
        const node = $getNodeByKey(nodeKey);
        if ($isYouTubeNode(node)) {
          node.setWidthAndHeight(nextWidth, nextHeight);
        }
      });
    },
    [editor, nodeKey],
  );

  const isFocused = (isSelected || isResizing) && isEditable;
  const showShield = isEditable && !isSelected;

  return (
    <BlockWithAlignableContents
      className={className}
      format={format}
      nodeKey={nodeKey}
    >
      <div
        className={`editor-media youtube-embed${isFocused ? ' focused' : ''}`}
        ref={containerRef}
        style={{
          height: height === 'inherit' ? YOUTUBE_DEFAULT_HEIGHT : height,
          width: width === 'inherit' ? YOUTUBE_DEFAULT_WIDTH : width,
        }}
      >
        <iframe
          className="youtube-embed__frame"
          src={`https://www.youtube-nocookie.com/embed/${videoID}`}
          allow={YOUTUBE_IFRAME_ALLOW}
          allowFullScreen={true}
          style={{ pointerEvents: isResizing ? 'none' : undefined }}
          title="YouTube video"
        />
        {showShield && (
          <div className="youtube-embed__shield" data-testid="youtube-shield" />
        )}
        {isFocused && (
          <MediaResizer
            buttonRef={captionButtonRef}
            captionsEnabled={false}
            editor={editor}
            mediaRef={containerRef}
            onResizeEnd={onResizeEnd}
            onResizeStart={onResizeStart}
            setShowCaption={() => undefined}
            showCaption={true}
          />
        )}
      </div>
    </BlockWithAlignableContents>
  );
}

export type SerializedYouTubeNode = Spread<
  {
    height: Dimension;
    videoID: string;
    width: Dimension;
  },
  SerializedDecoratorBlockNode
>;

function $convertYoutubeElement(
  domNode: HTMLElement,
): null | DOMConversionOutput {
  const videoID = domNode.getAttribute('data-lexical-youtube');
  if (videoID) {
    const width = parseDimension(domNode.getAttribute('width'));
    const height = parseDimension(domNode.getAttribute('height'));
    const node = $createYouTubeNode(videoID, width, height);
    return { node };
  }
  return null;
}

export class YouTubeNode extends DecoratorBlockNode {
  __id: string;
  __width: Dimension;
  __height: Dimension;

  static getType(): string {
    return 'youtube';
  }

  static clone(node: YouTubeNode): YouTubeNode {
    return new YouTubeNode(
      node.__id,
      node.__width,
      node.__height,
      node.__format,
      node.__key,
    );
  }

  static importJSON(serializedNode: SerializedYouTubeNode): YouTubeNode {
    const { videoID, width, height } = serializedNode;
    return $createYouTubeNode(videoID, width, height).updateFromJSON(
      serializedNode,
    );
  }

  exportJSON(): SerializedYouTubeNode {
    return {
      ...super.exportJSON(),
      height: this.__height,
      videoID: this.__id,
      width: this.__width,
    };
  }

  constructor(
    id: string,
    width: Dimension = 'inherit',
    height: Dimension = 'inherit',
    format?: ElementFormatType,
    key?: NodeKey,
  ) {
    super(format, key);
    this.__id = id;
    this.__width = width;
    this.__height = height;
  }

  exportDOM(): DOMExportOutput {
    const element = document.createElement('iframe');
    element.setAttribute('data-lexical-youtube', this.__id);
    element.setAttribute(
      'width',
      String(this.__width === 'inherit' ? YOUTUBE_DEFAULT_WIDTH : this.__width),
    );
    element.setAttribute(
      'height',
      String(
        this.__height === 'inherit' ? YOUTUBE_DEFAULT_HEIGHT : this.__height,
      ),
    );
    element.setAttribute(
      'src',
      `https://www.youtube-nocookie.com/embed/${this.__id}`,
    );
    element.setAttribute('frameborder', '0');
    element.setAttribute('allow', YOUTUBE_IFRAME_ALLOW);
    element.setAttribute('allowfullscreen', 'true');
    element.setAttribute('title', 'YouTube video');
    return { element };
  }

  static importDOM(): DOMConversionMap | null {
    return {
      iframe: (domNode: HTMLElement) => {
        if (!domNode.hasAttribute('data-lexical-youtube')) {
          return null;
        }
        return {
          conversion: $convertYoutubeElement,
          priority: 1,
        };
      },
    };
  }

  updateDOM(): false {
    return false;
  }

  getId(): string {
    return this.__id;
  }

  getWidth(): Dimension {
    return this.__width;
  }

  getHeight(): Dimension {
    return this.__height;
  }

  setWidthAndHeight(width: Dimension, height: Dimension): void {
    const writable = this.getWritable();
    writable.__width = width;
    writable.__height = height;
  }

  getTextContent(
    _includeInert?: boolean | undefined,
    _includeDirectionless?: false | undefined,
  ): string {
    return `https://www.youtube.com/watch?v=${this.__id}`;
  }

  decorate(_editor: LexicalEditor, config: EditorConfig): JSX.Element {
    const embedBlockTheme = config.theme.embedBlock || {};
    const className = {
      base: embedBlockTheme.base || '',
      focus: embedBlockTheme.focus || '',
    };
    return (
      <YouTubeComponent
        className={className}
        format={this.__format}
        height={this.__height}
        nodeKey={this.getKey()}
        videoID={this.__id}
        width={this.__width}
      />
    );
  }
}

export function $createYouTubeNode(
  videoID: string,
  width: Dimension = 'inherit',
  height: Dimension = 'inherit',
): YouTubeNode {
  return new YouTubeNode(videoID, width, height);
}

export function $isYouTubeNode(
  node: YouTubeNode | LexicalNode | null | undefined,
): node is YouTubeNode {
  return node instanceof YouTubeNode;
}
