import { isPageSizeKey, type PageSizeKey } from './utils/pageSizes';
import { getBibleNoteStorage } from './storageManager';

export const isDevPlayground: boolean = false;

export const SETTINGS_LOCAL_STORAGE_KEY = 'lexical-playground-settings';

export const DEFAULT_SETTINGS = {
  disableBeforeInput: false,
  emptyEditor: isDevPlayground,
  hasLinkAttributes: false,
  hasNestedTables: false,
  isAutocomplete: true,
  isCharLimit: false,
  isCharLimitUtf8: false,
  isCodeHighlighted: true,
  isCodeShiki: false,
  isDarkMode: false,
  isMaxLength: false,
  isRichText: true,
  listStrictIndent: false,
  measureTypingPerf: false,
  pageSize: 'web' as PageSizeKey,
  selectionAlwaysOnDisplay: false,
  shouldAllowHighlightingWithBrackets: false,
  shouldPreserveNewLinesInMarkdown: false,
  shouldUseLexicalContextMenu: false,
  showInvisibleCharacters: false,
  showNestedEditorTreeView: false,
  showTableOfContents: false,
  showTreeView: false,
  tableCellBackgroundColor: true,
  tableCellMerge: true,
  tableHorizontalScroll: true,
} as const;

export type SettingName = keyof typeof DEFAULT_SETTINGS;

type WidenSettingValue<Value> = Value extends boolean ? boolean : Value;

export type Settings = {
  [Setting in SettingName]: WidenSettingValue<
    (typeof DEFAULT_SETTINGS)[Setting]
  >;
};

export type SettingValue<Setting extends SettingName = SettingName> =
  Settings[Setting];

type StoredSettings = Partial<Settings>;
type MutableStoredSettings = Partial<
  Record<SettingName, Settings[SettingName]>
>;

export const SETTING_NAMES = Object.keys(DEFAULT_SETTINGS) as SettingName[];

// These are mutated in setupEnv
export const INITIAL_SETTINGS: Settings = {
  ...DEFAULT_SETTINGS,
};

export function getInitialSettingsFromEnvironment(options?: {
  onParseError?: (setting: SettingName) => void;
}): Settings {
  return {
    ...DEFAULT_SETTINGS,
    ...getStoredSettings(),
    ...getSettingsFromSearch(window.location.search, options),
  };
}

export function getStoredSettings(): StoredSettings {
  const storage = getSettingsStorage();

  if (storage === null) {
    return {};
  }

  const rawSettings = storage.getItem(SETTINGS_LOCAL_STORAGE_KEY);

  if (rawSettings == null) {
    return {};
  }

  try {
    const parsedSettings: unknown = JSON.parse(rawSettings);

    if (
      parsedSettings === null ||
      typeof parsedSettings !== 'object' ||
      Array.isArray(parsedSettings)
    ) {
      return {};
    }

    const storedSettings: MutableStoredSettings = {};

    for (const setting of SETTING_NAMES) {
      const value = (parsedSettings as Record<string, unknown>)[setting];

      const defaultValue = DEFAULT_SETTINGS[setting];

      if (typeof defaultValue === 'boolean' && typeof value === 'boolean') {
        storedSettings[setting] = value;
        continue;
      }

      if (setting === 'pageSize' && isPageSizeKey(value)) {
        storedSettings[setting] = value;
      }
    }

    return storedSettings as StoredSettings;
  } catch {
    return {};
  }
}

function getSettingsFromSearch(
  search: string,
  options?: {
    onParseError?: (setting: SettingName) => void;
  },
): StoredSettings {
  if (typeof window === 'undefined') {
    return {};
  }

  const searchParams = new URLSearchParams(search);
  const settings: StoredSettings = {};

  for (const setting of SETTING_NAMES) {
    if (!searchParams.has(setting)) {
      continue;
    }

    try {
      const defaultValue = DEFAULT_SETTINGS[setting];
      const rawValue = searchParams.get(setting);

      if (setting === 'pageSize') {
        if (isPageSizeKey(rawValue)) {
          settings[setting] = rawValue;
        } else {
          options?.onParseError?.(setting);
        }
        continue;
      }

      if (typeof defaultValue === 'boolean') {
        const value = JSON.parse(rawValue ?? 'true');
        settings[setting] = Boolean(value) as Settings[typeof setting];
      }
    } catch {
      options?.onParseError?.(setting);
    }
  }

  return settings;
}

export function hasSettingOverrides(settings: Settings): boolean {
  return SETTING_NAMES.some(
    (setting) => settings[setting] !== DEFAULT_SETTINGS[setting],
  );
}

export function writeStoredSettings(settings: Settings): void {
  const storage = getSettingsStorage();

  if (storage === null) {
    return;
  }

  const storedSettings: MutableStoredSettings = {};

  for (const setting of SETTING_NAMES) {
    if (settings[setting] !== DEFAULT_SETTINGS[setting]) {
      storedSettings[setting] = settings[setting];
    }
  }

  if (Object.keys(storedSettings).length === 0) {
    storage.removeItem(SETTINGS_LOCAL_STORAGE_KEY);
    return;
  }

  storage.setItem(SETTINGS_LOCAL_STORAGE_KEY, JSON.stringify(storedSettings));
}

function getSettingsStorage(): Storage | null {
  return getBibleNoteStorage() as Storage | null;
}
