import type { ReactNode } from 'react';
import type { FileRevealer } from '../utils/filePathResolver';

import { createContext, useContext, useMemo } from 'react';

type MediaFileActionsContextShape = Readonly<{
  revealFile?: FileRevealer;
}>;

const Context = createContext<MediaFileActionsContextShape>({});

export function MediaFileActionsProvider({
  children,
  revealFile,
}: {
  children: ReactNode;
  revealFile?: FileRevealer;
}) {
  const contextValue = useMemo<MediaFileActionsContextShape>(
    () => ({ revealFile }),
    [revealFile],
  );

  return <Context.Provider value={contextValue}>{children}</Context.Provider>;
}

export function useMediaFileActions(): MediaFileActionsContextShape {
  return useContext(Context);
}
