import { Component, type ErrorInfo, type ReactNode } from 'react';

export type ErrorBoundaryProps = Readonly<{
  children: ReactNode;
  /** Rendered in place of `children` once a render error has been caught. */
  fallback: ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}>;

type ErrorBoundaryState = {
  hasError: boolean;
};

/**
 * Catches render errors in the subtree and swaps in `fallback`.
 *
 * Like the library this replaces, the boundary does not recover on its own: it
 * keeps showing `fallback` until the component is remounted.
 */
export class ErrorBoundary extends Component<
  ErrorBoundaryProps,
  ErrorBoundaryState
> {
  state: ErrorBoundaryState = { hasError: false };

  static getDerivedStateFromError(): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    const { onError } = this.props;

    if (onError !== undefined) {
      onError(error, info);
    }
  }

  render(): ReactNode {
    return this.state.hasError ? this.props.fallback : this.props.children;
  }
}

export default ErrorBoundary;
