import './index.scss';

import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import {
  $getSelection,
  $isRangeSelection,
  COMMAND_PRIORITY_NORMAL,
  createCommand,
  type LexicalCommand,
} from 'lexical';
import type { JSX, KeyboardEvent as ReactKeyboardEvent } from 'react';
import { useCallback, useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';

import {
  isFind,
  isFindNext,
  isFindPrevious,
} from '../ShortcutsPlugin/shortcuts';
import {
  findMatchIndexAtOrAfter,
  findMatches,
  sliceMatches,
  type SearchSlice,
} from './findMatches';
import {
  $buildSearchIndex,
  $getCaretOffset,
  $selectSlices,
  createRangesForSlices,
} from './searchIndex';

/** Opens the find bar (or refocuses it when it is already open). */
export const TOGGLE_FIND_COMMAND: LexicalCommand<void> = createCommand(
  'TOGGLE_FIND_COMMAND',
);

/**
 * Drives the find bar programmatically. A string opens the bar (or updates the
 * query if it is already open); `null` closes it.
 */
export const SET_FIND_QUERY_COMMAND: LexicalCommand<string | null> =
  createCommand('SET_FIND_QUERY_COMMAND');

// Registered highlight names, styled by `::highlight()` in index.scss.
const MATCH_HIGHLIGHT_NAME = 'bible-note-find-match';
const ACTIVE_HIGHLIGHT_NAME = 'bible-note-find-active-match';

// Longer selections are almost certainly not what the user wants to search
// for, so opening the bar leaves the previous query in place instead.
const MAX_SEEDED_QUERY_LENGTH = 120;

// The bar's top margin, mirrored from `$find-plugin-gap` in index.scss. Used to
// size the space reserved for the bar at the top of the scroll container.
const FIND_BAR_TOP_MARGIN = 12;

type FindMatchDom = {
  ranges: Range[];
  slices: SearchSlice[];
};

// Where the bar is portalled to, and how far below the top of that element it
// sits (i.e. under the toolbar, which is not always the same height).
type FindAnchor = {
  element: HTMLElement;
  top: number;
};

function getHighlightRegistry(): HighlightRegistry | null {
  if (typeof CSS === 'undefined' || typeof Highlight === 'undefined') {
    return null;
  }

  return CSS.highlights ?? null;
}

function setHighlightRanges(name: string, ranges: ReadonlyArray<Range>): void {
  const registry = getHighlightRegistry();

  if (registry === null) {
    return;
  }

  if (ranges.length === 0) {
    registry.delete(name);

    return;
  }

  registry.set(name, new Highlight(...ranges));
}

function clearHighlights(): void {
  setHighlightRanges(MATCH_HIGHLIGHT_NAME, []);
  setHighlightRanges(ACTIVE_HIGHLIGHT_NAME, []);
}

function scrollRangeIntoView(range: Range | undefined): void {
  const element = range?.startContainer.parentElement ?? null;

  // Scrolling the element that holds the match (rather than the range itself)
  // keeps this correct under the editor's zoom transform.
  if (element === null || typeof element.scrollIntoView !== 'function') {
    return;
  }

  element.scrollIntoView({ block: 'center', inline: 'nearest' });
}

export default function FindPlugin(): JSX.Element | null {
  const [editor] = useLexicalComposerContext();
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [caseSensitive, setCaseSensitive] = useState(false);
  const [wholeWord, setWholeWord] = useState(false);
  const [matchTotal, setMatchTotal] = useState(0);
  const [activeIndex, setActiveIndex] = useState(0);
  const [anchor, setAnchor] = useState<FindAnchor | null>(null);
  const inputRef = useRef<HTMLInputElement | null>(null);
  const barRef = useRef<HTMLDivElement | null>(null);
  const matchesRef = useRef<FindMatchDom[]>([]);
  const shouldFocusInputRef = useRef(false);
  const isOpenRef = useRef(isOpen);
  const activeIndexRef = useRef(activeIndex);
  isOpenRef.current = isOpen;
  activeIndexRef.current = activeIndex;

  const showMatch = useCallback(
    (
      matches: ReadonlyArray<FindMatchDom>,
      index: number,
      shouldScroll: boolean,
    ) => {
      const activeRanges = index < matches.length ? matches[index].ranges : [];
      const otherRanges: Range[] = [];

      matches.forEach((match, matchIndex) => {
        if (matchIndex !== index) {
          otherRanges.push(...match.ranges);
        }
      });

      setHighlightRanges(MATCH_HIGHLIGHT_NAME, otherRanges);
      setHighlightRanges(ACTIVE_HIGHLIGHT_NAME, activeRanges);

      if (shouldScroll) {
        scrollRangeIntoView(activeRanges[0]);
      }
    },
    [],
  );

  const refreshMatches = useCallback(
    ({
      scroll,
      startFromCaret,
    }: {
      scroll: boolean;
      startFromCaret: boolean;
    }) => {
      if (query === '') {
        matchesRef.current = [];
        clearHighlights();
        setMatchTotal(0);
        setActiveIndex(0);

        return;
      }

      const { caretOffset, offsets, sliced } = editor
        .getEditorState()
        .read(() => {
          const { segments, text } = $buildSearchIndex();
          const found = findMatches(text, query, { caseSensitive, wholeWord });

          return {
            caretOffset: startFromCaret ? $getCaretOffset(segments) : null,
            offsets: found,
            sliced: sliceMatches(segments, found),
          };
        });
      const matches = sliced.map((slices) => ({
        ranges: createRangesForSlices(editor, slices),
        slices,
      }));
      let nextIndex = 0;

      if (matches.length > 0) {
        nextIndex = startFromCaret
          ? caretOffset === null
            ? 0
            : findMatchIndexAtOrAfter(offsets, caretOffset)
          : Math.min(activeIndexRef.current, matches.length - 1);
      }

      matchesRef.current = matches;
      setMatchTotal(matches.length);
      setActiveIndex(nextIndex);
      showMatch(matches, nextIndex, scroll);
    },
    [caseSensitive, editor, query, showMatch, wholeWord],
  );

  const goToMatch = useCallback(
    (delta: number) => {
      const matches = matchesRef.current;

      if (matches.length === 0) {
        return;
      }

      const nextIndex =
        (activeIndexRef.current + delta + matches.length) % matches.length;

      setActiveIndex(nextIndex);
      showMatch(matches, nextIndex, true);
    },
    [showMatch],
  );

  const openFind = useCallback(() => {
    const selectedText = editor.getEditorState().read(() => {
      const selection = $getSelection();

      return $isRangeSelection(selection) && !selection.isCollapsed()
        ? selection.getTextContent()
        : '';
    });

    if (
      selectedText !== '' &&
      !selectedText.includes('\n') &&
      selectedText.length <= MAX_SEEDED_QUERY_LENGTH
    ) {
      setQuery(selectedText);
    }

    if (isOpenRef.current) {
      inputRef.current?.focus();
      inputRef.current?.select();

      return;
    }

    shouldFocusInputRef.current = true;
    setIsOpen(true);
  }, [editor]);

  const closeFind = useCallback(() => {
    const match = matchesRef.current[activeIndexRef.current];

    setIsOpen(false);

    // Leave the caret on whatever the user was looking at.
    if (match !== undefined) {
      editor.update(() => {
        $selectSlices(match.slices);
      });
    }

    editor.focus();
  }, [editor]);

  // Programmatic entry point (see SET_FIND_QUERY_COMMAND): a string opens the
  // bar or updates the running query; `null` closes it. Unlike openFind this
  // never seeds from the selection — the caller has said exactly what to find.
  const setFindQuery = useCallback(
    (nextQuery: string | null) => {
      if (nextQuery === null) {
        if (isOpenRef.current) {
          closeFind();
        }

        return;
      }

      setQuery(nextQuery);

      if (!isOpenRef.current) {
        shouldFocusInputRef.current = true;
        setIsOpen(true);
      }
    },
    [closeFind],
  );

  // Rerun the search whenever the query or its options change.
  useEffect(() => {
    if (!isOpen) {
      return;
    }

    refreshMatches({ scroll: true, startFromCaret: true });
  }, [isOpen, refreshMatches]);

  // Ranges point into the rendered DOM, so any edit invalidates them.
  useEffect(() => {
    if (!isOpen) {
      return;
    }

    return editor.registerUpdateListener(({ dirtyElements, dirtyLeaves }) => {
      if (dirtyElements.size === 0 && dirtyLeaves.size === 0) {
        return;
      }

      refreshMatches({ scroll: false, startFromCaret: false });
    });
  }, [editor, isOpen, refreshMatches]);

  useEffect(() => {
    if (isOpen) {
      return;
    }

    matchesRef.current = [];
    clearHighlights();
  }, [isOpen]);

  useEffect(() => clearHighlights, []);

  // The bar hangs off the editor card so it stays put while the note scrolls,
  // and sits just below the toolbar (which is hidden in full view).
  useEffect(() => {
    if (!isOpen) {
      setAnchor(null);

      return;
    }

    const rootElement = editor.getRootElement();
    const shell = rootElement?.closest('.editor-shell');
    const container = rootElement?.closest('.editor-container');

    if (
      !(shell instanceof HTMLElement) ||
      !(container instanceof HTMLElement)
    ) {
      setAnchor(null);

      return;
    }

    const updateAnchor = () => {
      const top =
        container.getBoundingClientRect().top -
        shell.getBoundingClientRect().top;

      setAnchor((current) =>
        current !== null && current.element === shell && current.top === top
          ? current
          : { element: shell, top },
      );
    };

    updateAnchor();
    window.addEventListener('resize', updateAnchor);

    const observer =
      typeof ResizeObserver === 'undefined'
        ? null
        : new ResizeObserver(updateAnchor);

    observer?.observe(shell);

    return () => {
      window.removeEventListener('resize', updateAnchor);
      observer?.disconnect();
    };
  }, [editor, isOpen]);

  useEffect(() => {
    if (!isOpen || anchor === null || !shouldFocusInputRef.current) {
      return;
    }

    shouldFocusInputRef.current = false;
    inputRef.current?.focus();
    inputRef.current?.select();
  }, [anchor, isOpen]);

  // The bar floats over the top of the note, so reserve matching space at the
  // top of the scroll container while it is open — otherwise it hides the first
  // lines. Driven by the bar's real height so it tracks wrapping and zoom.
  useEffect(() => {
    const bar = barRef.current;
    const rootElement = editor.getRootElement();
    const container = rootElement?.closest('.editor-container');

    if (!isOpen || anchor === null || bar === null) {
      return;
    }

    if (!(container instanceof HTMLElement)) {
      return;
    }

    const applyReserve = () => {
      // bar height + its top margin + a little breathing room below it.
      container.style.setProperty(
        '--find-bar-reserve',
        `${bar.offsetHeight + FIND_BAR_TOP_MARGIN * 2}px`,
      );
      container.classList.add('find-bar-open');
    };

    applyReserve();

    const observer =
      typeof ResizeObserver === 'undefined'
        ? null
        : new ResizeObserver(applyReserve);

    observer?.observe(bar);

    return () => {
      observer?.disconnect();
      container.classList.remove('find-bar-open');
      container.style.removeProperty('--find-bar-reserve');
    };
  }, [anchor, editor, isOpen]);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (isFind(event)) {
        event.preventDefault();
        openFind();

        return;
      }

      if (!isOpenRef.current) {
        return;
      }

      if (isFindPrevious(event)) {
        event.preventDefault();
        goToMatch(-1);
      } else if (isFindNext(event)) {
        event.preventDefault();
        goToMatch(1);
      }
    };

    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [goToMatch, openFind]);

  useEffect(
    () =>
      editor.registerCommand(
        TOGGLE_FIND_COMMAND,
        () => {
          openFind();

          return true;
        },
        COMMAND_PRIORITY_NORMAL,
      ),
    [editor, openFind],
  );

  useEffect(
    () =>
      editor.registerCommand(
        SET_FIND_QUERY_COMMAND,
        (nextQuery) => {
          setFindQuery(nextQuery);

          return true;
        },
        COMMAND_PRIORITY_NORMAL,
      ),
    [editor, setFindQuery],
  );

  if (!isOpen || anchor === null) {
    return null;
  }

  const hasQuery = query !== '';
  const hasMatches = matchTotal > 0;
  const handleInputKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      goToMatch(event.shiftKey ? -1 : 1);
    } else if (event.key === 'Escape') {
      event.preventDefault();
      closeFind();
    }
  };

  return createPortal(
    <div
      className="FindPlugin_Bar"
      ref={barRef}
      role="search"
      style={{ top: anchor.top }}
      aria-label="Find in note"
    >
      <i className="bi bi-search FindPlugin_Icon" aria-hidden="true" />
      <input
        aria-label="Find in note"
        className="FindPlugin_Input"
        onChange={(event) => setQuery(event.target.value)}
        onKeyDown={handleInputKeyDown}
        placeholder="Find in note"
        ref={inputRef}
        spellCheck={false}
        type="text"
        value={query}
      />
      <span
        aria-live="polite"
        className={`FindPlugin_Count${
          hasQuery && !hasMatches ? ' FindPlugin_Count__empty' : ''
        }`}
      >
        {hasQuery ? `${hasMatches ? activeIndex + 1 : 0}/${matchTotal}` : ''}
      </span>
      <button
        aria-label="Match case"
        aria-pressed={caseSensitive}
        className={`FindPlugin_Toggle${caseSensitive ? ' active' : ''}`}
        onClick={() => setCaseSensitive((current) => !current)}
        title="Match case"
        type="button"
      >
        Aa
      </button>
      <button
        aria-label="Match whole word"
        aria-pressed={wholeWord}
        className={`FindPlugin_Toggle${wholeWord ? ' active' : ''}`}
        onClick={() => setWholeWord((current) => !current)}
        title="Match whole word"
        type="button"
      >
        ab
      </button>
      <button
        aria-label="Previous match"
        className="FindPlugin_Button"
        disabled={!hasMatches}
        onClick={() => goToMatch(-1)}
        title="Previous match (Shift+Enter)"
        type="button"
      >
        <i className="bi bi-chevron-up" aria-hidden="true" />
      </button>
      <button
        aria-label="Next match"
        className="FindPlugin_Button"
        disabled={!hasMatches}
        onClick={() => goToMatch(1)}
        title="Next match (Enter)"
        type="button"
      >
        <i className="bi bi-chevron-down" aria-hidden="true" />
      </button>
      <button
        aria-label="Close find bar"
        className="FindPlugin_Button"
        onClick={closeFind}
        title="Close (Esc)"
        type="button"
      >
        <i className="bi bi-x-lg" aria-hidden="true" />
      </button>
    </div>,
    anchor.element,
  );
}
