import { getExcalidrawFontInternals } from '@excalidraw-internal-fonts';

import {
  type ExtraFontFamilyOption,
  getFontFamilyOptions,
} from './fontFamilyOptions';

type ExcalidrawFontMetadata = {
  local?: boolean;
  metrics: {
    ascender: number;
    descender: number;
    lineHeight: number;
    unitsPerEm: number;
  };
};

type ExcalidrawFontRegistry = {
  registered: Map<number, unknown>;
  register: (
    family: string,
    metadata: ExcalidrawFontMetadata,
    ...fontFaceDescriptors: Array<{
      descriptors?: FontFaceDescriptors;
      uri: string;
    }>
  ) => Map<number, unknown>;
};

type ExcalidrawFontInternals = {
  FONT_FAMILY: Record<string, number>;
  Fonts: ExcalidrawFontRegistry;
};

const LOCAL_FONT_URI = 'local:';
const EXCALIDRAW_GLOBAL_FONT_ID_OFFSET = 10_000;
const LOCAL_FONT_METADATA: ExcalidrawFontMetadata = {
  local: true,
  metrics: {
    ascender: 900,
    descender: -250,
    lineHeight: 1.25,
    unitsPerEm: 1000,
  },
};

function normalizeFontFamily(fontFamily: string): string {
  return fontFamily.trim().replace(/^['"]|['"]$/g, '');
}

function getStableFontFamilyId(fontFamily: string): number {
  let hash = 2166136261;

  for (let index = 0; index < fontFamily.length; index += 1) {
    hash ^= fontFamily.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }

  return EXCALIDRAW_GLOBAL_FONT_ID_OFFSET + (hash >>> 0);
}

export async function registerExcalidrawFontFamilies(
  extraFontFamilies: ReadonlyArray<ExtraFontFamilyOption>,
): Promise<void> {
  const { FONT_FAMILY: excalidrawFontFamily, Fonts: fontRegistry } =
    (await getExcalidrawFontInternals()) as ExcalidrawFontInternals;

  getFontFamilyOptions(extraFontFamilies).forEach(([fontFamily]) => {
    const normalizedFontFamily = normalizeFontFamily(fontFamily);

    if (normalizedFontFamily === '') {
      return;
    }

    const fontFamilyId =
      excalidrawFontFamily[normalizedFontFamily] ??
      getStableFontFamilyId(normalizedFontFamily);

    excalidrawFontFamily[normalizedFontFamily] = fontFamilyId;

    if (!fontRegistry.registered.has(fontFamilyId)) {
      fontRegistry.register(normalizedFontFamily, LOCAL_FONT_METADATA, {
        uri: LOCAL_FONT_URI,
      });
    }
  });
}

export async function getRegisteredExcalidrawFontFamilyId(
  fontFamily: string,
): Promise<number | null> {
  const normalizedFontFamily = normalizeFontFamily(fontFamily);

  if (normalizedFontFamily === '') {
    return null;
  }

  const { FONT_FAMILY: excalidrawFontFamily } =
    (await getExcalidrawFontInternals()) as ExcalidrawFontInternals;

  return excalidrawFontFamily[normalizedFontFamily] ?? null;
}
