const PUNCTUATION =
  '\\.,\\+\\*\\?\\$\\@\\|#{}\\(\\)\\^\\-\\[\\]\\\\/!%\'"~=<>_:;';
const NAME = '\\b[A-Z][^\\s' + PUNCTUATION + ']';

const DocumentMentionsRegex = {
  NAME,
  PUNCTUATION,
};

const PUNC = DocumentMentionsRegex.PUNCTUATION;

const TRIGGERS = ['#'].join('');

// Chars we expect to see in a mention (non-space, non-punctuation).
const VALID_CHARS = '[^' + TRIGGERS + PUNC + '\\s]';

// Non-standard series of chars. Each series must be preceded and followed by
// a valid char.
const VALID_JOINS =
  '(?:' +
  '\\.[ |$]|' + // E.g. "r. " in "Mr. Smith"
  ' |' + // E.g. " " in "Josh Duck"
  '[' +
  PUNC +
  ']|' + // E.g. "-' in "Salier-Hellendag"
  ')';

const LENGTH_LIMIT = 75;

const LocationMentionsRegex = new RegExp(
  '(^|\\s|\\()(' +
    '[' +
    TRIGGERS +
    ']' +
    '((?:' +
    VALID_CHARS +
    VALID_JOINS +
    '){0,' +
    LENGTH_LIMIT +
    '})' +
    ')$',
);

// 50 is the longest alias length limit.
const ALIAS_LENGTH_LIMIT = 50;

// Regex used to match alias.
const LocationMentionsAliasRegex = new RegExp(
  '(^|\\s|\\()(' +
    '[' +
    TRIGGERS +
    ']' +
    '((?:' +
    VALID_CHARS +
    '){0,' +
    ALIAS_LENGTH_LIMIT +
    '})' +
    ')$',
);

// At most, 20 suggestions are shown in the popup.
const SUGGESTION_LIST_LENGTH_LIMIT = 20;
const HOVER_CARD_DELAY_MS = 2000;
const HOVER_CARD_CLOSE_DELAY_MS = 150;

type MentionLocationCoordinates = {
  latitude: number;
  longitude: number;
};

type MentionLocationMatch = {
  id: string;
  name: string;
  oldName: string | null;
  title: string;
  description: string;
  type: string;
  relatedLocations: Array<string>;
  modernIdentification: string | null;
  coordinates: MentionLocationCoordinates | null;
  verses: Array<string>;
  links: Array<MentionLocationLink>;
  wikipedia: string | null;
  uncertainty: boolean;
};

type MentionLocationPreview = Omit<MentionLocationMatch, 'id'> & {
  id: string | null;
};

type MentionLocationLink = {
  type: string;
  url: string;
};

type MentionLocationAdvancedPanel = MentionLocationPreview & {
  anchorElement: HTMLElement | null;
  panelKey: string;
  position: MentionAdvancedPanelPosition;
  zIndex: number;
};

type MentionLocationMapData = {
  locationsMap?: Array<unknown>;
  namesMap?: Array<unknown>;
};

const mentionLocationsCache = new Map<
  string | null,
  Array<MentionLocationMatch> | null
>();

function getTrimmedString(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function getNullableTrimmedString(value: unknown): string | null {
  const trimmedValue = getTrimmedString(value);
  return trimmedValue === '' ? null : trimmedValue;
}

function getTrimmedStringArray(value: unknown): Array<string> {
  if (!Array.isArray(value)) {
    return [];
  }

  return value.map(getTrimmedString).filter((item) => item !== '');
}

function getMentionLocationCoordinates(
  value: unknown,
): MentionLocationCoordinates | null {
  if (typeof value !== 'object' || value === null) {
    return null;
  }

  const candidate = value as Partial<MentionLocationCoordinates>;
  const { latitude, longitude } = candidate;

  if (
    typeof latitude !== 'number' ||
    !Number.isFinite(latitude) ||
    typeof longitude !== 'number' ||
    !Number.isFinite(longitude)
  ) {
    return null;
  }

  return { latitude, longitude };
}

function getMentionLocationLinks(value: unknown): Array<MentionLocationLink> {
  if (!Array.isArray(value)) {
    return [];
  }

  return value.reduce<Array<MentionLocationLink>>((results, item) => {
    if (typeof item !== 'object' || item === null) {
      return results;
    }

    const candidate = item as Partial<MentionLocationLink>;
    const type = getTrimmedString(candidate.type);
    const url = getTrimmedString(candidate.url);

    if (type === '' || url === '') {
      return results;
    }

    results.push({ type, url });
    return results;
  }, []);
}

function getMentionLocationMatch(value: unknown): MentionLocationMatch | null {
  if (typeof value !== 'object' || value === null) {
    return null;
  }

  const candidate = value as Partial<MentionLocationMatch>;
  const id = getTrimmedString(candidate.id);
  const name = getTrimmedString(candidate.name);

  if (id === '' || id === 'id' || name === '') {
    return null;
  }

  return {
    id,
    name,
    oldName: getNullableTrimmedString(candidate.oldName),
    title: getTrimmedString(candidate.title),
    description: getTrimmedString(candidate.description),
    type: getTrimmedString(candidate.type),
    relatedLocations: getTrimmedStringArray(candidate.relatedLocations),
    modernIdentification: getNullableTrimmedString(
      candidate.modernIdentification,
    ),
    coordinates: getMentionLocationCoordinates(candidate.coordinates),
    verses: getTrimmedStringArray(candidate.verses),
    links: getMentionLocationLinks(candidate.links),
    wikipedia: getNullableTrimmedString(candidate.wikipedia),
    uncertainty: candidate.uncertainty === true,
  };
}

const mentionLocationMapData = locationsMapJson as MentionLocationMapData;
const mentionLocationEntries = Array.isArray(
  mentionLocationMapData.locationsMap,
)
  ? mentionLocationMapData.locationsMap
  : Array.isArray(mentionLocationMapData.namesMap)
    ? mentionLocationMapData.namesMap
    : [];

const mentionLocationsData = mentionLocationEntries.reduce<
  Array<MentionLocationMatch>
>((results, value) => {
  const mentionLocation = getMentionLocationMatch(value);

  if (mentionLocation === null) {
    return results;
  }

  results.push(mentionLocation);
  return results;
}, []);

const mentionLocationsById = new Map<string, MentionLocationMatch>(
  mentionLocationsData.map((mentionLocation) => [
    mentionLocation.id,
    mentionLocation,
  ]),
);

const mentionLocationsByName = mentionLocationsData.reduce<
  Map<string, Array<MentionLocationMatch>>
>((results, mentionLocation) => {
  const existingMatches = results.get(mentionLocation.name);

  if (existingMatches === undefined) {
    results.set(mentionLocation.name, [mentionLocation]);
  } else {
    existingMatches.push(mentionLocation);
  }

  return results;
}, new Map());

function createFallbackMentionLocationPreview(
  id: string | null,
  name: string,
  title: string,
): MentionLocationPreview {
  return {
    id,
    name,
    oldName: null,
    title,
    description: '',
    type: '',
    relatedLocations: [],
    modernIdentification: null,
    coordinates: null,
    verses: [],
    links: [],
    wikipedia: null,
    uncertainty: false,
  };
}

function getFormattedDetailValue(value: string | null): string {
  const trimmedValue = getTrimmedString(value);

  if (trimmedValue === '') {
    return '';
  }

  if (trimmedValue.toLowerCase() === 'unknown') {
    return 'Unknown';
  }

  return trimmedValue;
}

function hasMentionLocationDetailValue(value: string | null): boolean {
  const trimmedValue = getTrimmedString(value);
  return trimmedValue !== '' && trimmedValue.toLowerCase() !== 'unknown';
}

function getFormattedLinkType(type: string): string {
  return type.charAt(0).toUpperCase() + type.slice(1);
}

function getMentionLocationDisplayLinks(
  mentionLocation: MentionLocationPreview,
): Array<MentionLocationLink> {
  const linksByUrl = new Map<string, MentionLocationLink>();

  mentionLocation.links.forEach((link) => {
    linksByUrl.set(link.url, link);
  });

  if (
    mentionLocation.wikipedia !== null &&
    !linksByUrl.has(mentionLocation.wikipedia)
  ) {
    linksByUrl.set(mentionLocation.wikipedia, {
      type: 'wikipedia',
      url: mentionLocation.wikipedia,
    });
  }

  return Array.from(linksByUrl.values());
}

function getReferencedMentionLocation(
  idOrName: string,
): MentionLocationMatch | null {
  const byId = mentionLocationsById.get(idOrName);

  if (byId !== undefined) {
    return byId;
  }

  const nameMatches = mentionLocationsByName.get(idOrName) ?? [];
  return nameMatches.length === 1 ? nameMatches[0] : null;
}

async function copyTextToClipboard(text: string): Promise<void> {
  if (
    navigator.clipboard !== undefined &&
    typeof navigator.clipboard.writeText === 'function'
  ) {
    await navigator.clipboard.writeText(text);
    return;
  }

  const textarea = document.createElement('textarea');
  textarea.value = text;
  textarea.setAttribute('readonly', '');
  textarea.style.position = 'fixed';
  textarea.style.top = '-9999px';
  document.body.appendChild(textarea);
  textarea.select();
  document.execCommand('copy');
  textarea.remove();
}

function getMentionLocationNamesByIds(ids: Array<string>): Array<string> {
  return ids.map((idOrName) => {
    const location = getReferencedMentionLocation(idOrName);
    return location?.name ?? idOrName;
  });
}

// Builds a full paragraph summary of a location record (name, description,
// and every detail row) in both plain-text and HTML form, so copying it
// keeps paragraph breaks and bold labels when pasted into MS Word.
// `resolveVerseLabel` turns short verse codes (e.g. "1SA 16:13") into their
// human-readable reference (e.g. "1 Samuel 16:13") when available.
async function buildMentionLocationSummary(
  mentionLocation: MentionLocationPreview,
  resolveVerseLabel?: (shortVerse: string) => Promise<string>,
): Promise<{ plainText: string; html: string }> {
  const plainBlocks: Array<string> = [mentionLocation.name];
  const htmlBlocks: Array<string> = [
    `<p><strong>${escapeMentionAdvancedPanelHtml(mentionLocation.name)}</strong></p>`,
  ];

  const title = getPlainReferenceText(mentionLocation.title);
  if (title !== '') {
    plainBlocks.push(title);
    htmlBlocks.push(`<p><em>${escapeMentionAdvancedPanelHtml(title)}</em></p>`);
  }

  const description = getPlainReferenceText(mentionLocation.description);
  if (description !== '') {
    plainBlocks.push(description);
    htmlBlocks.push(`<p>${escapeMentionAdvancedPanelHtml(description)}</p>`);
  }

  const basicFacts = [mentionLocation.type].filter(
    (value) => value !== '' && value.toLowerCase() !== 'unknown',
  );

  if (basicFacts.length > 0) {
    const factsText = basicFacts.join(', ');
    plainBlocks.push(factsText);
    htmlBlocks.push(`<p>${escapeMentionAdvancedPanelHtml(factsText)}</p>`);
  }

  const detailRows: Array<[string, string]> = [];

  if (hasMentionLocationDetailValue(mentionLocation.oldName)) {
    detailRows.push([
      'Also called',
      getFormattedDetailValue(mentionLocation.oldName),
    ]);
  }

  if (hasMentionLocationDetailValue(mentionLocation.modernIdentification)) {
    detailRows.push([
      'Modern identification',
      getFormattedDetailValue(mentionLocation.modernIdentification),
    ]);
  }

  const resolvedVerses =
    resolveVerseLabel === undefined
      ? mentionLocation.verses
      : await Promise.all(
          mentionLocation.verses.map((shortVerse) =>
            resolveVerseLabel(shortVerse),
          ),
        );

  const detailListEntries: Array<[string, Array<string>]> = [
    [
      'Related locations',
      getMentionLocationNamesByIds(mentionLocation.relatedLocations),
    ],
    ['Verses', resolvedVerses],
  ];

  for (const [label, values] of detailListEntries) {
    if (values.length > 0) {
      detailRows.push([label, values.join(', ')]);
    }
  }

  const links = getMentionLocationDisplayLinks(mentionLocation);
  if (links.length > 0) {
    detailRows.push([
      'Links',
      links
        .map((link) => `${getFormattedLinkType(link.type)}: ${link.url}`)
        .join(', '),
    ]);
  }

  if (mentionLocation.coordinates !== null) {
    detailRows.push([
      'Coordinates',
      `${mentionLocation.coordinates.latitude}, ${mentionLocation.coordinates.longitude}`,
    ]);
  }

  if (detailRows.length > 0) {
    plainBlocks.push(
      detailRows.map(([label, value]) => `${label}: ${value}`).join('\n'),
    );
    htmlBlocks.push(
      '<p>' +
        detailRows
          .map(
            ([label, value]) =>
              `<strong>${escapeMentionAdvancedPanelHtml(label)}:</strong> ${escapeMentionAdvancedPanelHtml(value)}`,
          )
          .join('<br />') +
        '</p>',
    );
  }

  return {
    plainText: plainBlocks.join('\n\n'),
    html: htmlBlocks.join(''),
  };
}

function MentionLocationDetailRow({
  inline = false,
  label,
  value,
}: {
  inline?: boolean;
  label: string;
  value: ReactNode;
}): JSX.Element {
  return (
    <div
      className={`mention-location-details__row${
        inline ? ' mention-location-details__row--inline' : ''
      }`}
    >
      <dt>{inline ? `${label}:` : label}</dt>
      <dd>{value}</dd>
    </div>
  );
}

function MentionLocationOptionalTextRow({
  label,
  value,
}: {
  label: string;
  value: string | null;
}): JSX.Element | null {
  if (!hasMentionLocationDetailValue(value)) {
    return null;
  }

  return (
    <MentionLocationDetailRow
      inline
      label={label}
      value={getFormattedDetailValue(value)}
    />
  );
}

function MentionLocationCollapsibleSectionRow({
  children,
  count,
  defaultOpen,
  label,
  onOpen,
}: {
  children: ReactNode;
  count: number;
  defaultOpen: boolean;
  label: string;
  onOpen?: () => void;
}): JSX.Element {
  const [isOpen, setIsOpen] = useState(defaultOpen);

  return (
    <div className="mention-location-details__row mention-location-details__row--collapsible">
      <dt>
        <button
          aria-expanded={isOpen}
          className="mention-location-details__section-toggle"
          type="button"
          onClick={() => {
            const next = !isOpen;
            setIsOpen(next);
            if (next) {
              onOpen?.();
            }
          }}
        >
          <i
            className="bi bi-chevron-right mention-location-details__section-icon"
            aria-hidden="true"
          />
          <span>{label}</span>
          {count > 0 ? (
            <span className="mention-location-details__section-count">
              {count}
            </span>
          ) : null}
        </button>
      </dt>
      {isOpen ? <dd>{children}</dd> : null}
    </div>
  );
}

function MentionLocationReferenceList({
  onOpenLocationReference,
  values,
}: {
  onOpenLocationReference: (
    mentionLocation: MentionLocationMatch,
    anchorElement: HTMLElement,
  ) => void;
  values: Array<string>;
}): JSX.Element {
  return (
    <ul className="mention-location-details__list">
      {values.map((value) => {
        const referencedLocation = getReferencedMentionLocation(value);
        const label = referencedLocation?.name ?? value;

        return (
          <li key={value}>
            {referencedLocation === null ? (
              label
            ) : (
              <button
                className="mention-location-details__location-button"
                type="button"
                onClick={(event) => {
                  event.preventDefault();
                  event.stopPropagation();
                  onOpenLocationReference(
                    referencedLocation,
                    event.currentTarget,
                  );
                }}
              >
                {label}
              </button>
            )}
          </li>
        );
      })}
    </ul>
  );
}

function MentionLocationOptionalReferenceListRow({
  label,
  onOpenLocationReference,
  values,
}: {
  label: string;
  onOpenLocationReference: (
    mentionLocation: MentionLocationMatch,
    anchorElement: HTMLElement,
  ) => void;
  values: Array<string>;
}): JSX.Element | null {
  if (values.length === 0) {
    return null;
  }

  return (
    <MentionLocationCollapsibleSectionRow
      count={values.length}
      defaultOpen
      label={label}
    >
      <MentionLocationReferenceList
        onOpenLocationReference={onOpenLocationReference}
        values={values}
      />
    </MentionLocationCollapsibleSectionRow>
  );
}

function MentionLocationOptionalVersesRow({
  enabled,
  values,
}: {
  enabled: boolean;
  values: Array<string>;
}): JSX.Element | null {
  const [hasOpened, setHasOpened] = useState(false);

  if (values.length === 0) {
    return null;
  }

  return (
    <MentionLocationCollapsibleSectionRow
      count={values.length}
      defaultOpen={false}
      label="Verses"
      onOpen={() => {
        setHasOpened(true);
      }}
    >
      <MentionVerseReferenceList
        buttonClassName="mention-location-details__location-button"
        enabled={enabled && hasOpened}
        listClassName="mention-location-details__list"
        values={values}
      />
    </MentionLocationCollapsibleSectionRow>
  );
}

function MentionLocationLinkList({
  links,
}: {
  links: Array<MentionLocationLink>;
}): JSX.Element {
  return (
    <ul className="mention-location-details__list">
      {links.map((link) => (
        <li key={`${link.type}:${link.url}`}>
          <a href={link.url} rel="noreferrer" target="_blank">
            {getFormattedLinkType(link.type)}
          </a>
        </li>
      ))}
    </ul>
  );
}

function MentionLocationOptionalLinkRow({
  links,
}: {
  links: Array<MentionLocationLink>;
}): JSX.Element | null {
  if (links.length === 0) {
    return null;
  }

  return (
    <MentionLocationCollapsibleSectionRow
      count={links.length}
      defaultOpen
      label="Links"
    >
      <MentionLocationLinkList links={links} />
    </MentionLocationCollapsibleSectionRow>
  );
}

function MentionLocationMap({
  coordinates,
  name,
}: {
  coordinates: MentionLocationCoordinates;
  name: string;
}): JSX.Element {
  const { latitude, longitude } = coordinates;
  const query = `${latitude},${longitude}`;
  const embedSrc = `https://maps.google.com/maps?q=${encodeURIComponent(
    query,
  )}&z=8&output=embed`;
  const linkHref = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(
    query,
  )}`;
  const mapTitle = name === '' ? 'Location map' : `Map of ${name}`;

  return (
    <div className="mention-location-details__map">
      <p className="mention-location-details__map-note">
        Approximate location — the marker is an estimated point and may not be
        exact.
      </p>
      <iframe
        className="mention-location-details__map-frame"
        title={mapTitle}
        src={embedSrc}
        loading="lazy"
        referrerPolicy="no-referrer-when-downgrade"
        allowFullScreen
      />
      <a
        className="mention-location-details__map-link"
        href={linkHref}
        rel="noreferrer"
        target="_blank"
      >
        Open in Google Maps
      </a>
    </div>
  );
}

function MentionLocationBasicInfo({
  includeTitle = true,
  mentionLocation,
}: {
  includeTitle?: boolean;
  mentionLocation: MentionLocationPreview;
}): JSX.Element {
  const basicFacts = [mentionLocation.type].filter(
    (value) => value !== '' && value.toLowerCase() !== 'unknown',
  );

  return (
    <div className="mention-location-basic-info">
      {includeTitle && mentionLocation.title ? (
        <div className="mention-location-basic-info__title">
          <MentionReferenceText value={mentionLocation.title} />
        </div>
      ) : null}
      {mentionLocation.description ? (
        <p className="mention-location-basic-info__description">
          <MentionReferenceText value={mentionLocation.description} />
        </p>
      ) : null}
      {basicFacts.length > 0 ? (
        <div className="mention-location-basic-info__facts">
          {basicFacts.map((fact) => (
            <span key={fact}>{fact}</span>
          ))}
        </div>
      ) : null}
    </div>
  );
}

function MentionLocationDetails({
  includeTitle = true,
  mentionLocation,
  onOpenLocationReference,
}: {
  includeTitle?: boolean;
  mentionLocation: MentionLocationPreview;
  onOpenLocationReference: (
    mentionLocation: MentionLocationMatch,
    anchorElement: HTMLElement,
  ) => void;
}): JSX.Element {
  const [hasExpanded, setHasExpanded] = useState(false);

  return (
    <details className="mention-location-details">
      <summary
        className="mention-location-details__summary"
        onClick={() => {
          setHasExpanded(true);
        }}
      >
        <i
          className="bi bi-chevron-right mention-location-details__summary-icon"
          aria-hidden="true"
        />
        <span>Details</span>
      </summary>
      <div className="mention-location-details__body">
        {mentionLocation.description ? (
          <p className="mention-location-details__description">
            <MentionReferenceText value={mentionLocation.description} />
          </p>
        ) : null}
        <dl className="mention-location-details__grid">
          {includeTitle &&
          hasMentionLocationDetailValue(mentionLocation.title) ? (
            <MentionLocationDetailRow
              inline
              label="Title"
              value={<MentionReferenceText value={mentionLocation.title} />}
            />
          ) : null}
          <MentionLocationOptionalTextRow
            label="Also called"
            value={mentionLocation.oldName}
          />
          <MentionLocationOptionalTextRow
            label="Type"
            value={mentionLocation.type}
          />
          <MentionLocationOptionalTextRow
            label="Modern identification"
            value={mentionLocation.modernIdentification}
          />
          <MentionLocationOptionalReferenceListRow
            label="Related locations"
            onOpenLocationReference={onOpenLocationReference}
            values={mentionLocation.relatedLocations}
          />
          <MentionLocationOptionalVersesRow
            enabled={hasExpanded}
            values={mentionLocation.verses}
          />
          <MentionLocationOptionalLinkRow
            links={getMentionLocationDisplayLinks(mentionLocation)}
          />
        </dl>
        {mentionLocation.coordinates !== null ? (
          <MentionLocationMap
            coordinates={mentionLocation.coordinates}
            name={mentionLocation.name}
          />
        ) : null}
      </div>
    </details>
  );
}

function isMentionLocationInteractiveTarget(
  target: EventTarget | null,
): boolean {
  return (
    target instanceof Element &&
    target.closest('a, button, .mention-location-details') !== null
  );
}

function getMentionLocationElement(
  target: EventTarget | null,
): HTMLElement | null {
  if (!(target instanceof Element)) {
    return null;
  }

  const mentionElement = target.closest('[data-lexical-mention]');
  return mentionElement instanceof HTMLElement ? mentionElement : null;
}

function getMentionLocationHoverCardElement(
  target: EventTarget | null,
): HTMLElement | null {
  if (!(target instanceof Element)) {
    return null;
  }

  const hoverCardElement = target.closest('[data-mention-location-hover-card]');
  return hoverCardElement instanceof HTMLElement ? hoverCardElement : null;
}

function getRenderedMentionKind(
  target: HTMLElement,
): 'location' | 'mention' | 'bible-verse' {
  const mentionKind = target.getAttribute('data-lexical-mention-kind');

  if (mentionKind === 'mention' || mentionKind === 'bible-verse') {
    return mentionKind;
  }

  if (mentionKind === 'location' || mentionKind === 'hashtag') {
    return 'location';
  }

  return (target.textContent?.trim() ?? '').startsWith('#')
    ? 'location'
    : 'mention';
}

function syncMentionLocationElementKind(target: HTMLElement): void {
  const mentionKind = getRenderedMentionKind(target);

  if (mentionKind !== 'bible-verse') {
    target.setAttribute('data-lexical-mention-kind', mentionKind);
  }
}

function syncMentionLocationKinds(rootElement: ParentNode): void {
  rootElement
    .querySelectorAll<HTMLElement>('[data-lexical-mention]')
    .forEach(syncMentionLocationElementKind);
}

function getMentionLocationPreview(
  target: HTMLElement,
): MentionLocationPreview | null {
  if (getRenderedMentionKind(target) !== 'location') {
    return null;
  }

  const mentionText = target.textContent?.trim() ?? '';

  const mentionId = target.getAttribute('data-lexical-mention-id');

  if (mentionId !== null) {
    const mention = mentionLocationsById.get(mentionId);

    if (mention !== undefined) {
      return mention;
    }
  }

  const mentionName =
    target.getAttribute('data-lexical-mention-name')?.trim() ??
    mentionText ??
    '';

  const normalizedMentionName = mentionName.startsWith('#')
    ? mentionName.slice(1)
    : mentionName;

  if (normalizedMentionName === '') {
    return null;
  }

  const matches = mentionLocationsByName.get(normalizedMentionName) ?? [];

  if (matches.length === 1) {
    return matches[0];
  }

  return createFallbackMentionLocationPreview(
    mentionId,
    normalizedMentionName,
    '',
  );
}

function getMentionLocationPreviewFromOpenDetail(
  detail: OpenMentionLocationAdvancedPanelDetail,
): MentionLocationPreview | null {
  const id = getNullableTrimmedString(detail.id);
  const name = getTrimmedString(detail.name);

  if (id !== null) {
    const mentionLocation = mentionLocationsById.get(id);

    if (mentionLocation !== undefined) {
      return mentionLocation;
    }
  }

  if (name === '') {
    return null;
  }

  const matches = mentionLocationsByName.get(name) ?? [];

  if (matches.length === 1) {
    return matches[0];
  }

  return createFallbackMentionLocationPreview(id, name, '');
}

function getHoverCardStyle(element: HTMLElement): React.CSSProperties {
  return getMentionHoverCardStyle(element, 112);
}

function getMentionLocationAdvancedPanelKey(
  mentionLocation: MentionLocationPreview,
): string {
  return `location:${mentionLocation.id ?? mentionLocation.name}`;
}

// Ranks how well a name matches the query so better matches sort first.
// Lower is better: exact name, then name prefix, then name substring. Mirrors
// the ranking used by the Lookup panel so both lists order matches the same way.
function getMentionLocationMatchRank(
  name: string,
  normalizedQuery: string,
): number {
  const nameLower = name.toLowerCase();

  if (nameLower === normalizedQuery) {
    return 0;
  }

  if (nameLower.startsWith(normalizedQuery)) {
    return 1;
  }

  return 2;
}

const mentionLocationsLookupService = {
  search(
    string: string,
    callback: (results: Array<MentionLocationMatch>) => void,
  ): void {
    setTimeout(() => {
      const normalizedQuery = string.toLowerCase();
      const results = mentionLocationsData
        .filter((mentionLocation) =>
          mentionLocation.name.toLowerCase().includes(normalizedQuery),
        )
        .map((mentionLocation) => ({
          mentionLocation,
          rank: getMentionLocationMatchRank(
            mentionLocation.name,
            normalizedQuery,
          ),
        }))
        // Array#sort is stable, so records within a rank tier keep their
        // existing (alphabetical) order; better matches float to the top.
        .sort((a, b) => a.rank - b.rank)
        .map((entry) => entry.mentionLocation);
      callback(results);
    }, 500);
  },
};

function useMentionLocationsLookupService(mentionString: string | null) {
  const [results, setResults] = useState<Array<MentionLocationMatch>>([]);

  useEffect(() => {
    const cachedResults = mentionLocationsCache.get(mentionString);

    if (mentionString == null) {
      setResults([]);
      return;
    }

    if (cachedResults === null) {
      return;
    } else if (cachedResults !== undefined) {
      setResults(cachedResults);
      return;
    }

    mentionLocationsCache.set(mentionString, null);
    mentionLocationsLookupService.search(mentionString, (newResults) => {
      mentionLocationsCache.set(mentionString, newResults);
      setResults(newResults);
    });
  }, [mentionString]);

  return results;
}

function checkForLocationMentions(
  text: string,
  minMatchLength: number,
): MenuTextMatch | null {
  let match = LocationMentionsRegex.exec(text);

  if (match === null) {
    match = LocationMentionsAliasRegex.exec(text);
  }
  if (match !== null) {
    // The strategy ignores leading whitespace but we need to know it's
    // length to add it to the leadOffset
    const maybeLeadingWhitespace = match[1];

    const matchingString = match[3];
    if (matchingString.length >= minMatchLength) {
      return {
        leadOffset: match.index + maybeLeadingWhitespace.length,
        matchingString,
        replaceableString: match[2],
      };
    }
  }
  return null;
}

function getPossibleQueryMatch(text: string): MenuTextMatch | null {
  return checkForLocationMentions(text, 1);
}

class MentionLocationTypeaheadOption extends MenuOption {
  id: string;
  name: string;
  declare title: string;
  picture: JSX.Element;

  constructor(mentionLocation: MentionLocationMatch, picture: JSX.Element) {
    super(mentionLocation.id);
    this.id = mentionLocation.id;
    this.name = mentionLocation.name;
    this.title = getPlainReferenceText(mentionLocation.title);
    this.picture = picture;
  }
}

function MentionLocationsTypeaheadMenuItem({
  index,
  isSelected,
  onClick,
  onMouseEnter,
  option,
}: {
  index: number;
  isSelected: boolean;
  onClick: () => void;
  onMouseEnter: () => void;
  option: MentionLocationTypeaheadOption;
}) {
  let className =
    'item mx-2 p-2 d-flex flex-row align-items-center flex-shrink-0';
  if (isSelected) {
    className += ' selected';
  }
  return (
    <li
      key={option.key}
      tabIndex={-1}
      className={className}
      ref={option.setRefElement}
      role="option"
      aria-selected={isSelected}
      id={'typeahead-item-' + index}
      onMouseEnter={onMouseEnter}
      onClick={onClick}
    >
      {option.picture}
      <span className="text flex-column">
        <span>{option.name}</span>
        {option.title ? (
          <span className="small opacity-75">({option.title})</span>
        ) : null}
      </span>
    </li>
  );
}

export default function MentionLocationsPlugin(): JSX.Element | null {
  const [editor] = useLexicalComposerContext();
  const hoverCardShowTimeoutRef = useRef<ReturnType<
    typeof window.setTimeout
  > | null>(null);
  const hoverCardHideTimeoutRef = useRef<ReturnType<
    typeof window.setTimeout
  > | null>(null);

  const [queryString, setQueryString] = useState<string | null>(null);
  const [hoveredMentionLocation, setHoveredMentionLocation] =
    useState<MentionLocationPreview | null>(null);
  const [hoveredMentionLocationElement, setHoveredMentionLocationElement] =
    useState<HTMLElement | null>(null);
  const [hoverCardStyle, setHoverCardStyle] =
    useState<React.CSSProperties | null>(null);
  const [advancedPanels, setAdvancedPanels] = useState<
    Array<MentionLocationAdvancedPanel>
  >([]);

  const { shortToVerseData } = useBibleVerseActions();
  const resolveVerseLabel = useCallback(
    async (shortVerse: string): Promise<string> => {
      if (shortToVerseData === undefined) {
        return shortVerse;
      }

      try {
        const data = await shortToVerseData(shortVerse);
        return data?.title ?? shortVerse;
      } catch {
        return shortVerse;
      }
    },
    [shortToVerseData],
  );

  const results = useMentionLocationsLookupService(queryString);

  const checkForSlashTriggerMatch = useBasicTypeaheadTriggerMatch('/', {
    minLength: 0,
  });

  const options = useMemo(
    () =>
      results
        .map(
          (result) =>
            new MentionLocationTypeaheadOption(
              result,
              <i className="bi bi-pin icon" aria-hidden="true" />,
            ),
        )
        .slice(0, SUGGESTION_LIST_LENGTH_LIMIT),
    [results],
  );

  const onSelectOption = useCallback(
    (
      selectedOption: MentionLocationTypeaheadOption,
      nodeToReplace: TextNode | null,
      closeMenu: () => void,
    ) => {
      editor.update(() => {
        const mentionNode = $createMentionNode(
          selectedOption.name,
          selectedOption.name,
          selectedOption.id,
          'location',
        );
        if (nodeToReplace) {
          nodeToReplace.replace(mentionNode);
        }
        mentionNode.select();
        closeMenu();
      });
    },
    [editor],
  );

  const checkForMentionLocationMatch = useCallback(
    (text: string) => {
      const slashMatch = checkForSlashTriggerMatch(text, editor);
      if (slashMatch !== null) {
        return null;
      }
      return getPossibleQueryMatch(text);
    },
    [checkForSlashTriggerMatch, editor],
  );

  const clearHoverCardShowTimeout = useCallback(() => {
    if (hoverCardShowTimeoutRef.current !== null) {
      window.clearTimeout(hoverCardShowTimeoutRef.current);
      hoverCardShowTimeoutRef.current = null;
    }
  }, []);

  const clearHoverCardHideTimeout = useCallback(() => {
    if (hoverCardHideTimeoutRef.current !== null) {
      window.clearTimeout(hoverCardHideTimeoutRef.current);
      hoverCardHideTimeoutRef.current = null;
    }
  }, []);

  const hideHoverCard = useCallback(() => {
    clearHoverCardShowTimeout();
    clearHoverCardHideTimeout();
    setHoveredMentionLocationElement(null);
    setHoveredMentionLocation(null);
  }, [clearHoverCardHideTimeout, clearHoverCardShowTimeout]);

  const scheduleHideHoverCard = useCallback(() => {
    clearHoverCardShowTimeout();
    clearHoverCardHideTimeout();
    hoverCardHideTimeoutRef.current = window.setTimeout(() => {
      setHoveredMentionLocationElement(null);
      setHoveredMentionLocation(null);
      hoverCardHideTimeoutRef.current = null;
    }, HOVER_CARD_CLOSE_DELAY_MS);
  }, [clearHoverCardHideTimeout, clearHoverCardShowTimeout]);

  const openAdvancedPanel = useCallback(
    (mentionLocation: MentionLocationPreview, anchorElement: HTMLElement) => {
      const panelKey = getMentionLocationAdvancedPanelKey(mentionLocation);
      const zIndex = getNextMentionAdvancedPanelZIndex();
      const position = getMentionAdvancedPanelInitialPosition(anchorElement);

      setAdvancedPanels((currentPanels) => {
        const existingPanel = currentPanels.find(
          (panel) => panel.panelKey === panelKey,
        );
        const nextPanel = {
          ...mentionLocation,
          anchorElement,
          panelKey,
          position: existingPanel?.position ?? position,
          zIndex,
        };

        if (existingPanel !== undefined) {
          return currentPanels.map((panel) =>
            panel.panelKey === panelKey ? nextPanel : panel,
          );
        }

        return [...currentPanels, nextPanel];
      });
      hideHoverCard();
    },
    [hideHoverCard],
  );

  const closeAdvancedPanel = useCallback((panelKey: string) => {
    setAdvancedPanels((currentPanels) =>
      currentPanels.filter((panel) => panel.panelKey !== panelKey),
    );
  }, []);

  const bringAdvancedPanelToFront = useCallback((panelKey: string) => {
    const zIndex = getNextMentionAdvancedPanelZIndex();

    setAdvancedPanels((currentPanels) =>
      currentPanels.map((panel) =>
        panel.panelKey === panelKey ? { ...panel, zIndex } : panel,
      ),
    );
  }, []);

  const updateAdvancedPanelPosition = useCallback(
    (panelKey: string, position: MentionAdvancedPanelPosition) => {
      setAdvancedPanels((currentPanels) => {
        let hasChanged = false;
        const nextPanels = currentPanels.map((panel) => {
          if (panel.panelKey !== panelKey) {
            return panel;
          }

          if (
            panel.position.left === position.left &&
            panel.position.top === position.top
          ) {
            return panel;
          }

          hasChanged = true;
          return { ...panel, position };
        });

        return hasChanged ? nextPanels : currentPanels;
      });
    },
    [],
  );

  useEffect(() => {
    const handleOpenLocationAdvancedPanel = (event: Event) => {
      const detail = (
        event as CustomEvent<OpenMentionLocationAdvancedPanelDetail>
      ).detail;

      if (
        typeof detail !== 'object' ||
        detail === null ||
        !(detail.anchorElement instanceof HTMLElement)
      ) {
        return;
      }

      const mentionLocation = getMentionLocationPreviewFromOpenDetail(detail);

      if (mentionLocation === null) {
        return;
      }

      openAdvancedPanel(mentionLocation, detail.anchorElement);
    };

    window.addEventListener(
      OPEN_MENTION_LOCATION_ADVANCED_PANEL_EVENT,
      handleOpenLocationAdvancedPanel,
    );

    return () => {
      window.removeEventListener(
        OPEN_MENTION_LOCATION_ADVANCED_PANEL_EVENT,
        handleOpenLocationAdvancedPanel,
      );
    };
  }, [openAdvancedPanel]);

  useEffect(() => {
    const handleMentionIconPointerDown = (event: PointerEvent) => {
      if (event.button !== 0) {
        return;
      }

      const mentionElement = getMentionLocationElement(event.target);

      if (
        mentionElement === null ||
        !isMentionIconPointerEvent(event, mentionElement)
      ) {
        return;
      }

      syncMentionLocationElementKind(mentionElement);
      const mention = getMentionLocationPreview(mentionElement);

      if (mention === null) {
        return;
      }

      openAdvancedPanel(mention, mentionElement);
      event.preventDefault();
      event.stopPropagation();
    };

    document.addEventListener(
      'pointerdown',
      handleMentionIconPointerDown,
      true,
    );

    return () => {
      document.removeEventListener(
        'pointerdown',
        handleMentionIconPointerDown,
        true,
      );
    };
  }, [openAdvancedPanel]);

  useEffect(() => {
    return editor.registerNodeTransform(MentionNode, (node) => {
      if (!node.getTextContent().startsWith('#')) {
        return;
      }

      node.setMentionKind('location');
      node.setTextContent(node.getTextContent().slice(1));
    });
  }, [editor]);

  useEffect(() => {
    let observer: MutationObserver | null = null;
    const unregisterRootListener = editor.registerRootListener(
      (rootElement) => {
        observer?.disconnect();
        observer = null;

        if (rootElement === null) {
          return;
        }

        syncMentionLocationKinds(rootElement);
        observer = new MutationObserver(() => {
          syncMentionLocationKinds(rootElement);
        });
        observer.observe(rootElement, {
          characterData: true,
          childList: true,
          subtree: true,
        });
      },
    );

    return () => {
      observer?.disconnect();
      unregisterRootListener();
    };
  }, [editor]);

  useEffect(() => {
    const handleMouseOver = (event: MouseEvent) => {
      const hoverCardElement = getMentionLocationHoverCardElement(event.target);

      if (hoverCardElement !== null) {
        clearHoverCardHideTimeout();
        return;
      }

      const mentionElement = getMentionLocationElement(event.target);
      const previousMentionElement = getMentionLocationElement(
        event.relatedTarget,
      );

      if (mentionElement === null) {
        return;
      }

      if (mentionElement === hoveredMentionLocationElement) {
        clearHoverCardHideTimeout();
        return;
      }

      if (mentionElement === previousMentionElement) {
        return;
      }

      syncMentionLocationElementKind(mentionElement);

      const mention = getMentionLocationPreview(mentionElement);

      if (mention === null) {
        return;
      }

      hideHoverCard();
      hoverCardShowTimeoutRef.current = window.setTimeout(() => {
        setHoveredMentionLocationElement(mentionElement);
        setHoveredMentionLocation(mention);
        hoverCardShowTimeoutRef.current = null;
      }, HOVER_CARD_DELAY_MS);
    };

    const handleMouseOut = (event: MouseEvent) => {
      const mentionElement = getMentionLocationElement(event.target);
      const hoverCardElement = getMentionLocationHoverCardElement(event.target);
      const nextMentionElement = getMentionLocationElement(event.relatedTarget);
      const nextHoverCardElement = getMentionLocationHoverCardElement(
        event.relatedTarget,
      );

      if (mentionElement === null && hoverCardElement === null) {
        return;
      }

      if (nextMentionElement !== null || nextHoverCardElement !== null) {
        clearHoverCardHideTimeout();
        return;
      }

      scheduleHideHoverCard();
    };

    document.addEventListener('mouseover', handleMouseOver);
    document.addEventListener('mouseout', handleMouseOut);

    return () => {
      clearHoverCardShowTimeout();
      clearHoverCardHideTimeout();
      document.removeEventListener('mouseover', handleMouseOver);
      document.removeEventListener('mouseout', handleMouseOut);
    };
  }, [
    clearHoverCardHideTimeout,
    clearHoverCardShowTimeout,
    hideHoverCard,
    hoveredMentionLocationElement,
    scheduleHideHoverCard,
  ]);

  useEffect(() => {
    if (hoveredMentionLocationElement === null) {
      setHoverCardStyle(null);
      return;
    }

    const updateHoverCardStyle = () => {
      if (!hoveredMentionLocationElement.isConnected) {
        hideHoverCard();
        setHoverCardStyle(null);
        return;
      }

      setHoverCardStyle(getHoverCardStyle(hoveredMentionLocationElement));
    };

    updateHoverCardStyle();
    window.addEventListener('resize', updateHoverCardStyle);
    window.addEventListener('scroll', updateHoverCardStyle, true);

    return () => {
      window.removeEventListener('resize', updateHoverCardStyle);
      window.removeEventListener('scroll', updateHoverCardStyle, true);
    };
  }, [hideHoverCard, hoveredMentionLocationElement]);

  return (
    <>
      <LexicalTypeaheadMenuPlugin<MentionLocationTypeaheadOption>
        onQueryChange={setQueryString}
        onSelectOption={onSelectOption}
        triggerFn={checkForMentionLocationMatch}
        options={options}
        menuRenderFn={(
          anchorElementRef,
          { selectedIndex, selectOptionAndCleanUp, setHighlightedIndex },
        ) =>
          anchorElementRef.current && results.length
            ? ReactDOM.createPortal(
                <div className="typeahead-popover mention-locations-menu">
                  <ul className="list-unstyled m-0 p-0">
                    {options.map((option, i: number) => (
                      <MentionLocationsTypeaheadMenuItem
                        index={i}
                        isSelected={selectedIndex === i}
                        onClick={() => {
                          setHighlightedIndex(i);
                          selectOptionAndCleanUp(option);
                        }}
                        onMouseEnter={() => {
                          setHighlightedIndex(i);
                        }}
                        key={option.key}
                        option={option}
                      />
                    ))}
                  </ul>
                </div>,
                anchorElementRef.current,
              )
            : null
        }
      />
      {hoveredMentionLocation !== null && hoverCardStyle !== null
        ? ReactDOM.createPortal(
            <div
              className="mention-hover-card"
              data-mention-location-hover-card="true"
              role="tooltip"
              style={hoverCardStyle}
              tabIndex={0}
              onClick={(event) => {
                if (isMentionLocationInteractiveTarget(event.target)) {
                  return;
                }

                if (hoveredMentionLocationElement !== null) {
                  openAdvancedPanel(
                    hoveredMentionLocation,
                    hoveredMentionLocationElement,
                  );
                }
              }}
              onKeyDown={(event) => {
                if (
                  (event.key === 'Enter' || event.key === ' ') &&
                  hoveredMentionLocationElement !== null &&
                  !isMentionLocationInteractiveTarget(event.target)
                ) {
                  openAdvancedPanel(
                    hoveredMentionLocation,
                    hoveredMentionLocationElement,
                  );
                  event.preventDefault();
                }
              }}
            >
              <div className="mention-hover-card__name d-inline-flex align-items-center gap-2">
                <i className="bi bi-pin icon" aria-hidden="true" />
                <span className="mention-hover-card__name-text">
                  {hoveredMentionLocation.name}
                </span>
                <button
                  aria-label="Copy mentioned location name"
                  className="mention-hover-card__copy"
                  title="Copy name"
                  type="button"
                  onClick={(event) => {
                    event.preventDefault();
                    event.stopPropagation();
                    void copyTextToClipboard(hoveredMentionLocation.name);
                  }}
                >
                  <i className="bi bi-copy" aria-hidden="true" />
                </button>
              </div>
              {hoveredMentionLocation.title ? (
                <div className="mention-hover-card__title">
                  <MentionReferenceText value={hoveredMentionLocation.title} />
                </div>
              ) : null}
              <MentionLocationBasicInfo
                includeTitle={false}
                mentionLocation={hoveredMentionLocation}
              />
              <MentionLocationDetails
                includeTitle={false}
                mentionLocation={hoveredMentionLocation}
                onOpenLocationReference={openAdvancedPanel}
              />
            </div>,
            document.body,
          )
        : null}
      {advancedPanels.map((panel) => (
        <MentionAdvancedPanel
          anchorElement={panel.anchorElement}
          copyLabel="Copy mentioned location details"
          iconClassName="bi bi-pin icon"
          key={panel.panelKey}
          name={panel.name}
          panelKind="location"
          position={panel.position}
          title={
            <>
              <MentionLocationBasicInfo mentionLocation={panel} />
              <MentionLocationDetails
                mentionLocation={panel}
                onOpenLocationReference={openAdvancedPanel}
              />
            </>
          }
          zIndex={panel.zIndex}
          onCopy={async () => {
            const { plainText, html } = await buildMentionLocationSummary(
              panel,
              resolveVerseLabel,
            );
            return copyMentionRecordToClipboard(plainText, html);
          }}
          onBringToFront={() => {
            bringAdvancedPanelToFront(panel.panelKey);
          }}
          onClose={() => {
            closeAdvancedPanel(panel.panelKey);
          }}
          onPositionChange={(position) => {
            updateAdvancedPanelPosition(panel.panelKey, position);
          }}
        />
      ))}
    </>
  );
}
