import type { EditorState } from 'lexical';
import type { JSX } from 'react';

import { OnChangePlugin } from '@lexical/react/LexicalOnChangePlugin';

import { writeStoredEditorState } from '../../editorStateStorage';

export default function EditorStatePersistencePlugin(): JSX.Element {
  return (
    <OnChangePlugin
      onChange={(editorState: EditorState) => {
        writeStoredEditorState(JSON.stringify(editorState));
      }}
    />
  );
}
