import type { LibraryItems } from '@excalidraw/excalidraw/types';

type LibraryElement = LibraryItems[number]['elements'][number];
type ElementOverrides = Partial<LibraryElement>;

const CREATED_AT = 1777593600000;

const baseElement = (
  id: string,
  x: number,
  y: number,
  width: number,
  height: number,
  seed: number,
  overrides: ElementOverrides = {},
) => ({
  angle: 0,
  backgroundColor: 'transparent',
  boundElements: null,
  fillStyle: 'solid',
  frameId: null,
  groupIds: [],
  height,
  id,
  index: null,
  isDeleted: false,
  link: null,
  locked: false,
  opacity: 100,
  roughness: 1,
  roundness: { type: 3 },
  seed,
  strokeColor: '#1e1e1e',
  strokeStyle: 'solid',
  strokeWidth: 2,
  updated: CREATED_AT,
  version: 1,
  versionNonce: seed + 100000,
  width,
  x,
  y,
  ...overrides,
});

const rectangle = (
  id: string,
  x: number,
  y: number,
  width: number,
  height: number,
  seed: number,
  overrides: ElementOverrides = {},
) =>
  ({
    ...baseElement(id, x, y, width, height, seed, overrides),
    type: 'rectangle',
  }) as LibraryElement;

const ellipse = (
  id: string,
  x: number,
  y: number,
  width: number,
  height: number,
  seed: number,
  overrides: ElementOverrides = {},
) =>
  ({
    ...baseElement(id, x, y, width, height, seed, overrides),
    type: 'ellipse',
  }) as LibraryElement;

const diamond = (
  id: string,
  x: number,
  y: number,
  width: number,
  height: number,
  seed: number,
  overrides: ElementOverrides = {},
) =>
  ({
    ...baseElement(id, x, y, width, height, seed, overrides),
    type: 'diamond',
  }) as LibraryElement;

const line = (
  id: string,
  x: number,
  y: number,
  points: readonly [number, number][],
  seed: number,
  overrides: ElementOverrides = {},
) => {
  const xs = points.map(([pointX]) => pointX);
  const ys = points.map(([, pointY]) => pointY);

  return {
    ...baseElement(
      id,
      x,
      y,
      Math.max(...xs) - Math.min(...xs),
      Math.max(...ys) - Math.min(...ys),
      seed,
      overrides,
    ),
    endArrowhead: null,
    endBinding: null,
    lastCommittedPoint: null,
    points,
    startArrowhead: null,
    startBinding: null,
    type: 'line',
  } as LibraryElement;
};

const libraryItem = (
  id: string,
  name: string,
  elements: readonly LibraryElement[],
): LibraryItems[number] => ({
  created: CREATED_AT,
  elements,
  id,
  name,
  status: 'published',
});

