const MEDIA_FILE_DATABASE_NAME = 'lexical-playground-media-files';
const MEDIA_FILE_STORE_NAME = 'media-files';
const MEDIA_FILE_DATABASE_VERSION = 1;

type StoredMediaFileRecord = {
  file: Blob;
  name: string;
  src: string;
  type: string;
  updatedAt: number;
};

function getIndexedDB(): IDBFactory | null {
  if (typeof window === 'undefined' || !window.indexedDB) {
    return null;
  }

  return window.indexedDB;
}

function openMediaFileDatabase(): Promise<IDBDatabase | null> {
  const indexedDB = getIndexedDB();

  if (indexedDB === null) {
    return Promise.resolve(null);
  }

  return new Promise((resolve) => {
    const request = indexedDB.open(
      MEDIA_FILE_DATABASE_NAME,
      MEDIA_FILE_DATABASE_VERSION,
    );

    request.onupgradeneeded = () => {
      const database = request.result;

      if (!database.objectStoreNames.contains(MEDIA_FILE_STORE_NAME)) {
        database.createObjectStore(MEDIA_FILE_STORE_NAME, { keyPath: 'src' });
      }
    };

    request.onsuccess = () => {
      resolve(request.result);
    };

    request.onerror = () => {
      resolve(null);
    };
  });
}

function closeDatabase(database: IDBDatabase): void {
  database.close();
}

export async function storeMediaFile(src: string, file: File): Promise<void> {
  if (src.trim() === '') {
    return;
  }

  const database = await openMediaFileDatabase();

  if (database === null) {
    return;
  }

  await new Promise<void>((resolve) => {
    const transaction = database.transaction(
      MEDIA_FILE_STORE_NAME,
      'readwrite',
    );
    const store = transaction.objectStore(MEDIA_FILE_STORE_NAME);

    const record: StoredMediaFileRecord = {
      file,
      name: file.name,
      src,
      type: file.type,
      updatedAt: Date.now(),
    };

    transaction.oncomplete = () => {
      closeDatabase(database);
      resolve();
    };
    transaction.onerror = () => {
      closeDatabase(database);
      resolve();
    };
    transaction.onabort = () => {
      closeDatabase(database);
      resolve();
    };

    store.put(record);
  });
}

export async function createStoredMediaPreviewSrc(
  src: string,
): Promise<string | undefined> {
  if (src.trim() === '' || typeof URL.createObjectURL !== 'function') {
    return undefined;
  }

  const database = await openMediaFileDatabase();

  if (database === null) {
    return undefined;
  }

  const file = await new Promise<Blob | undefined>((resolve) => {
    const transaction = database.transaction(MEDIA_FILE_STORE_NAME, 'readonly');
    const store = transaction.objectStore(MEDIA_FILE_STORE_NAME);
    const request = store.get(src);

    request.onsuccess = () => {
      const record = request.result as StoredMediaFileRecord | undefined;
      resolve(record?.file);
    };

    request.onerror = () => {
      resolve(undefined);
    };

    transaction.oncomplete = () => {
      closeDatabase(database);
    };
    transaction.onerror = () => {
      closeDatabase(database);
    };
    transaction.onabort = () => {
      closeDatabase(database);
    };
  });

  return file ? URL.createObjectURL(file) : undefined;
}
