import type {
  AppState,
  BinaryFiles,
  ExcalidrawImperativeAPI,
  ExcalidrawInitialDataState,
  LibraryItems,
} from '@excalidraw/excalidraw/types';
import type { ClipboardData } from '@excalidraw/excalidraw/clipboard';
import type { FontFamilyValues } from '@excalidraw/excalidraw/element/types';
import type { JSX } from 'react';

import './ExcalidrawModal.scss';

import {
  CaptureUpdateAction,
  convertToExcalidrawElements,
  Excalidraw,
  loadLibraryFromBlob,
  serializeLibraryAsJSON,
  viewportCoordsToSceneCoords,
} from '@excalidraw/excalidraw';
import { isDOMNode } from 'lexical';
import * as React from 'react';
import {
  type ReactPortal,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { createPortal } from 'react-dom';

import Button from './Button';
import { useSettings } from '../context/SettingsContext';
import {
  getRegisteredExcalidrawFontFamilyId,
  registerExcalidrawFontFamilies,
} from '../utils/excalidrawFontRegistration';
import {
  DEFAULT_FONT_LANGUAGE,
  type ExtraFontFamilyOption,
  type FontFamilyOption,
  getFontFamilyForLanguage,
  getFontFamilyOptions,
} from '../utils/fontFamilyOptions';
import {
  getBibleTextPartsFromPlainText,
  getBibleTextPlainTextWithVerseLineBreaks,
} from '../utils/bibleTextPaste';
import Modal from './Modal';

export type ExcalidrawInitialElements = ExcalidrawInitialDataState['elements'];

const EMPTY_EXTRA_FONT_FAMILIES: ReadonlyArray<ExtraFontFamilyOption> = [];
const EMPTY_LIBRARY_ITEMS: LibraryItems = [];
const DEFAULT_DETECT_TEXT_LANGUAGE = () => DEFAULT_FONT_LANGUAGE;
const EXCALIDRAW_LIBRARY_MIME_TYPE = 'application/vnd.excalidrawlib+json';
const LIBRARY_SIDEBAR_TAB = 'library';

type Props = {
  /**
   * Clears cached .excalidrawlib file contents when the library is reset
   */
  clearLibrariesFileList?: () => void;
  closeOnClickOutside?: boolean;
  detectTextLanguage?: (text: string) => string;
  /**
   * The initial set of elements to draw into the scene
   */
  initialElements: ExcalidrawInitialElements;
  /**
   * The initial set of elements to draw into the scene
   */
  initialAppState: AppState;
  /**
   * The initial set of elements to draw into the scene
   */
  initialFiles: BinaryFiles;
  /**
   * Extra editor font families to expose in Excalidraw's font picker
   */
  extraFontFamilies?: ReadonlyArray<ExtraFontFamilyOption>;
  /**
   * The bundled library items to make available in Excalidraw
   */
  libraryItems?: LibraryItems;
  /**
   * Returns cached .excalidrawlib file contents to hydrate the library panel
   */
  loadLibrariesFileList?: () => string[];
  /**
   * Saves .excalidrawlib file contents after library imports or changes
   */
  saveLibrariesFile?: (librariesFile: string) => void;
  /**
   * Controls the visibility of the modal
   */
  isShown?: boolean;
  /**
   * Callback when closing and discarding the new changes
   */
  onClose: () => void;
  /**
   * Completely remove Excalidraw component
   */
  onDelete: () => void;
  /**
   * Callback when the save button is clicked
   */
  onSave: (
    elements: ExcalidrawInitialElements,
    appState: Partial<AppState>,
    files: BinaryFiles,
  ) => void;
};

function getBibleTextFromPasteData(data: ClipboardData): string | null {
  if (typeof data.text !== 'string') {
    return null;
  }

  const bibleText = getBibleTextPartsFromPlainText(data.text);

  return bibleText === null
    ? null
    : getBibleTextPlainTextWithVerseLineBreaks(bibleText);
}

async function getDetectedExcalidrawFontFamily(
  text: string,
  currentFontFamily: FontFamilyValues,
  detectTextLanguage: (text: string) => string,
  fontFamilyOptions: ReadonlyArray<FontFamilyOption>,
): Promise<FontFamilyValues> {
  const language = detectTextLanguage(text);

  if (language === DEFAULT_FONT_LANGUAGE) {
    return currentFontFamily;
  }

  const fontFamily = getFontFamilyForLanguage(fontFamilyOptions, language);

  if (fontFamily === null) {
    return currentFontFamily;
  }

  return (
    ((await getRegisteredExcalidrawFontFamilyId(
      fontFamily,
    )) as FontFamilyValues | null) ?? currentFontFamily
  );
}

/**
 * @explorer-desc
 * A component which renders a modal with Excalidraw (a painting app)
 * which can be used to export an editable image
 */
export default function ExcalidrawModal({
  clearLibrariesFileList,
  closeOnClickOutside = false,
  detectTextLanguage = DEFAULT_DETECT_TEXT_LANGUAGE,
  onSave,
  initialElements,
  initialAppState,
  initialFiles,
  extraFontFamilies = EMPTY_EXTRA_FONT_FAMILIES,
  libraryItems = EMPTY_LIBRARY_ITEMS,
  loadLibrariesFileList,
  saveLibrariesFile,
  isShown = false,
  onDelete,
  onClose,
}: Props): ReactPortal | null {
  const {
    settings: { isDarkMode },
  } = useSettings();
  const excaliDrawModelRef = useRef<HTMLDivElement | null>(null);
  const [excalidrawAPI, setExcalidrawAPI] =
    useState<ExcalidrawImperativeAPI | null>(null);
  const [discardModalOpen, setDiscardModalOpen] = useState(false);
  const [elements, setElements] =
    useState<ExcalidrawInitialElements>(initialElements);
  const [files, setFiles] = useState<BinaryFiles>(initialFiles);
  const [areFontFamiliesRegistered, setAreFontFamiliesRegistered] =
    useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const hasLoadedCachedLibrariesRef = useRef(false);
  const applyingLibraryItemsCountRef = useRef(0);
  const excalidrawTheme = isDarkMode ? 'dark' : 'light';
  const fontFamilyOptions = useMemo(
    () => getFontFamilyOptions(extraFontFamilies),
    [extraFontFamilies],
  );
  const bundledLibraryItemIds = useMemo(
    () => new Set(libraryItems.map((libraryItem) => libraryItem.id)),
    [libraryItems],
  );

  useLayoutEffect(() => {
    let isActive = true;

    setAreFontFamiliesRegistered(false);
    void registerExcalidrawFontFamilies(extraFontFamilies)
      .catch((error: unknown) => {
        console.error(error);
      })
      .finally(() => {
        if (isActive) {
          setAreFontFamiliesRegistered(true);
        }
      });

    return () => {
      isActive = false;
    };
  }, [extraFontFamilies]);

  useEffect(() => {
    excaliDrawModelRef.current?.focus();
  }, []);

  const addBundledLibraryItems = React.useCallback(async () => {
    if (excalidrawAPI === null || libraryItems.length === 0) {
      return;
    }

    applyingLibraryItemsCountRef.current += 1;
    try {
      await excalidrawAPI.updateLibrary({
        defaultStatus: 'published',
        libraryItems: (currentLibraryItems) => [
          ...libraryItems,
          ...currentLibraryItems.filter(
            (libraryItem) => !bundledLibraryItemIds.has(libraryItem.id),
          ),
        ],
      });
    } catch (error: unknown) {
      console.error(error);
    } finally {
      applyingLibraryItemsCountRef.current = Math.max(
        0,
        applyingLibraryItemsCountRef.current - 1,
      );
    }
  }, [bundledLibraryItemIds, excalidrawAPI, libraryItems]);

  useEffect(() => {
    void addBundledLibraryItems();
  }, [addBundledLibraryItems]);

  const loadCachedLibraries = React.useCallback(async () => {
    if (
      excalidrawAPI === null ||
      loadLibrariesFileList === undefined ||
      hasLoadedCachedLibrariesRef.current
    ) {
      return;
    }

    hasLoadedCachedLibrariesRef.current = true;

    let librariesFileList: string[];
    try {
      librariesFileList = loadLibrariesFileList();
    } catch (error: unknown) {
      console.error(error);
      return;
    }

    if (librariesFileList.length === 0) {
      return;
    }

    try {
      const cachedLibraryItems = (
        await Promise.all(
          librariesFileList.map((librariesFile) =>
            loadLibraryFromBlob(
              new Blob([librariesFile], {
                type: EXCALIDRAW_LIBRARY_MIME_TYPE,
              }),
              'published',
            ),
          ),
        )
      )
        .flat()
        .filter((libraryItem) => !bundledLibraryItemIds.has(libraryItem.id));

      if (cachedLibraryItems.length === 0) {
        return;
      }

      applyingLibraryItemsCountRef.current += 1;
      await excalidrawAPI.updateLibrary({
        defaultStatus: 'published',
        libraryItems: cachedLibraryItems,
        merge: true,
      });
    } catch (error: unknown) {
      console.error(error);
    } finally {
      applyingLibraryItemsCountRef.current = Math.max(
        0,
        applyingLibraryItemsCountRef.current - 1,
      );
    }
  }, [bundledLibraryItemIds, excalidrawAPI, loadLibrariesFileList]);

  useEffect(() => {
    let modalOverlayElement: HTMLElement | null = null;

    const clickOutsideHandler = (event: MouseEvent) => {
      const target = event.target;
      if (
        excaliDrawModelRef.current !== null &&
        isDOMNode(target) &&
        !excaliDrawModelRef.current.contains(target) &&
        closeOnClickOutside
      ) {
        onDelete();
      }
    };

    if (excaliDrawModelRef.current !== null) {
      modalOverlayElement = excaliDrawModelRef.current?.parentElement;
      modalOverlayElement?.addEventListener('click', clickOutsideHandler);
    }

    return () => {
      modalOverlayElement?.removeEventListener('click', clickOutsideHandler);
    };
  }, [closeOnClickOutside, onDelete]);

  useLayoutEffect(() => {
    const currentModalRef = excaliDrawModelRef.current;

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onDelete();
      }
    };

    currentModalRef?.addEventListener('keydown', onKeyDown);

    return () => {
      currentModalRef?.removeEventListener('keydown', onKeyDown);
    };
  }, [elements, files, onDelete]);

  const save = () => {
    if (elements?.some((el) => !el.isDeleted)) {
      const appState = excalidrawAPI?.getAppState();
      // We only need a subset of the state
      const partialState: Partial<AppState> = {
        exportBackground: appState?.exportBackground,
        exportScale: appState?.exportScale,
        exportWithDarkMode: appState?.theme === 'dark',
        isBindingEnabled: appState?.isBindingEnabled,
        isLoading: appState?.isLoading,
        name: appState?.name,
        theme: appState?.theme,
        viewBackgroundColor: appState?.viewBackgroundColor,
        viewModeEnabled: appState?.viewModeEnabled,
        zenModeEnabled: appState?.zenModeEnabled,
        zoom: appState?.zoom,
      };
      onSave(elements, partialState, files);
    } else {
      // delete node if the scene is clear
      onDelete();
    }
  };

  const discard = () => {
    setDiscardModalOpen(true);
  };

  useEffect(() => {
    const modalElement = excaliDrawModelRef.current;
    const onFullscreenChange = () => {
      setIsFullscreen(document.fullscreenElement === modalElement);
    };

    document.addEventListener('fullscreenchange', onFullscreenChange);

    return () => {
      document.removeEventListener('fullscreenchange', onFullscreenChange);

      if (document.fullscreenElement === modalElement) {
        void document.exitFullscreen?.().catch((error: unknown) => {
          console.error(error);
        });
      }
    };
  }, []);

  const toggleFullscreen = () => {
    const modalElement = excaliDrawModelRef.current;
    const modalHasBrowserFullscreen =
      document.fullscreenElement === modalElement;

    if (isFullscreen || modalHasBrowserFullscreen) {
      setIsFullscreen(false);

      if (modalHasBrowserFullscreen) {
        void document.exitFullscreen?.().catch((error: unknown) => {
          console.error(error);
        });
      }

      return;
    }

    setIsFullscreen(true);

    if (modalElement?.requestFullscreen !== undefined) {
      void modalElement.requestFullscreen().catch((error: unknown) => {
        console.error(error);
      });
    }
  };

  function ShowDiscardDialog(): JSX.Element {
    return (
      <Modal
        title="Discard"
        onClose={() => {
          setDiscardModalOpen(false);
        }}
        closeOnClickOutside={false}
      >
        Are you sure you want to discard the changes?
        <div className="ExcalidrawModal__discardModal">
          <Button
            onClick={() => {
              setDiscardModalOpen(false);
              onClose();
            }}
          >
            Discard
          </Button>{' '}
          <Button
            onClick={() => {
              setDiscardModalOpen(false);
            }}
          >
            Cancel
          </Button>
        </div>
      </Modal>
    );
  }

  if (isShown === false) {
    return null;
  }

  const overlayClassName = `ExcalidrawModal__overlay${
    isFullscreen ? ' ExcalidrawModal__overlay--fullscreen' : ''
  }`;
  const modalClassName = `ExcalidrawModal__modal${
    isFullscreen ? ' ExcalidrawModal__modal--fullscreen' : ''
  }`;
  const rowClassName = `ExcalidrawModal__row${
    isFullscreen ? ' ExcalidrawModal__row--fullscreen' : ''
  }`;

  const renderTopRightUI = () => {
    return (
      <div className="ExcalidrawModal__actions">
        <button
          aria-label={isFullscreen ? 'Exit fullscreen' : 'Enter fullscreen'}
          aria-pressed={isFullscreen}
          className="action-button"
          onClick={toggleFullscreen}
          title={isFullscreen ? 'Exit fullscreen' : 'Enter fullscreen'}
          type="button"
        >
          <i
            aria-hidden="true"
            className={`bi ${
              isFullscreen ? 'bi-fullscreen-exit' : 'bi-arrows-fullscreen'
            }`}
          />
        </button>
        <button className="action-button" onClick={discard} type="button">
          Discard
        </button>
        <button className="action-button" onClick={save} type="button">
          Save
        </button>
      </div>
    );
  };

  const onChange = (
    els: ExcalidrawInitialElements,
    appState: AppState,
    fls: BinaryFiles,
  ) => {
    setElements(els);
    setFiles(fls);

    if (appState.openSidebar?.tab === LIBRARY_SIDEBAR_TAB) {
      void loadCachedLibraries();
    }
  };

  const onLibraryChange = (nextLibraryItems: LibraryItems) => {
    if (applyingLibraryItemsCountRef.current > 0) {
      return;
    }

    if (nextLibraryItems.length === 0) {
      clearLibrariesFileList?.();
      void addBundledLibraryItems();
      return;
    }

    if (saveLibrariesFile === undefined) {
      return;
    }

    const importedLibraryItems = nextLibraryItems.filter(
      (libraryItem) => !bundledLibraryItemIds.has(libraryItem.id),
    );

    if (importedLibraryItems.length === 0) {
      return;
    }

    saveLibrariesFile(serializeLibraryAsJSON(importedLibraryItems));
  };

  const onPaste = async (data: ClipboardData, event: ClipboardEvent | null) => {
    const text = getBibleTextFromPasteData(data);

    if (text === null || excalidrawAPI === null) {
      return true;
    }

    const appState = excalidrawAPI.getAppState();
    const fontFamily = await getDetectedExcalidrawFontFamily(
      text,
      appState.currentItemFontFamily,
      detectTextLanguage,
      fontFamilyOptions,
    );
    const { x, y } = viewportCoordsToSceneCoords(
      {
        clientX: appState.offsetLeft + appState.width / 2,
        clientY: appState.offsetTop + appState.height / 2,
      },
      appState,
    );
    const textElements = convertToExcalidrawElements(
      [
        {
          backgroundColor: appState.currentItemBackgroundColor,
          fillStyle: appState.currentItemFillStyle,
          fontFamily,
          fontSize: appState.currentItemFontSize,
          locked: false,
          opacity: appState.currentItemOpacity,
          originalText: text,
          roughness: appState.currentItemRoughness,
          strokeColor: appState.currentItemStrokeColor,
          strokeStyle: appState.currentItemStrokeStyle,
          strokeWidth: appState.currentItemStrokeWidth,
          text,
          type: 'text',
          x,
          y,
        },
      ],
      { regenerateIds: true },
    );

    if (textElements.length === 0) {
      return true;
    }

    const nextElements = [
      ...excalidrawAPI.getSceneElementsIncludingDeleted(),
      ...textElements,
    ];

    excalidrawAPI.updateScene({
      appState: {
        selectedElementIds: Object.fromEntries(
          textElements.map((element) => [element.id, true]),
        ),
      },
      captureUpdate: CaptureUpdateAction.IMMEDIATELY,
      elements: nextElements,
    });
    setElements(nextElements as ExcalidrawInitialElements);
    event?.preventDefault();

    return false;
  };

  return createPortal(
    <div className={overlayClassName} role="dialog">
      <div className={modalClassName} ref={excaliDrawModelRef} tabIndex={-1}>
        <div className={rowClassName}>
          {discardModalOpen && <ShowDiscardDialog />}
          {areFontFamiliesRegistered && (
            <Excalidraw
              onChange={onChange}
              onLibraryChange={onLibraryChange}
              onPaste={onPaste}
              excalidrawAPI={setExcalidrawAPI}
              theme={excalidrawTheme}
              renderTopRightUI={renderTopRightUI}
              initialData={{
                appState: initialAppState || { isLoading: false },
                elements: initialElements,
                files: initialFiles,
              }}
            />
          )}
        </div>
      </div>
    </div>,
    document.body,
  );
}
