import type { Root } from 'react-dom/client';

import packageJson from '../package.json';
import type {
  BibleNoteEditorControllerOwner,
  BibleNoteSettingsControllerOwner,
} from './AppComp';
import type {
  BibleNoteFooterActionButton,
  BibleNoteFooterActionButtonController,
  BibleNoteFooterActionButtonControllerOwner,
  BibleNoteFooterActionButtonPlacement,
  BibleNoteFooterActionButtons,
} from './footerActionButtons';
import type { BibleNoteColorScheme } from './params/colorScheme';
import type { BibleNoteStorageManager } from './storageManager';
import { applyBibleNoteColorScheme } from './params/colorScheme';
import {
  type BibleNoteProps,
  type BibleNoteRenderOptions,
  type BibleNoteSettingsController,
  createBibleNoteStorageManager,
  renderEditor,
} from './bibleNoteHelpers';

export type {
  BibleNoteFooterActionButton,
  BibleNoteFooterActionButtons,
} from './footerActionButtons';

type BibleNoteEditorController = Parameters<
  BibleNoteEditorControllerOwner['connectEditorController']
>[0];

const { version: BIBLE_NOTE_VERSION } = packageJson as { version: string };

class BibleNote {
  static VERSION = BIBLE_NOTE_VERSION;
  props: Readonly<BibleNoteProps>;
  colorScheme: BibleNoteColorScheme = 'light';
  private editorController: BibleNoteEditorController | null = null;
  private pendingEditorActions: Array<
    (controller: BibleNoteEditorController) => void
  > = [];
  private pendingColorScheme: BibleNoteColorScheme | null = null;
  private readOnlyOverride: boolean | null = null;
  private footerActionButtonController: BibleNoteFooterActionButtonController | null =
    null;
  private footerActionButtons: {
    before: Array<BibleNoteFooterActionButton>;
    after: Array<BibleNoteFooterActionButton>;
  } = {
    after: [],
    before: [],
  };
  private root: Root | null = null;
  private settingsController: BibleNoteSettingsController | null = null;
  private readonly editorControllerOwner: BibleNoteEditorControllerOwner = {
    connectEditorController: (controller) =>
      this.connectEditorController(controller),
  };
  private readonly footerActionButtonControllerOwner: BibleNoteFooterActionButtonControllerOwner =
    {
      connectFooterActionButtonController: (controller) =>
        this.connectFooterActionButtonController(controller),
    };
  private readonly storageManager: BibleNoteStorageManager;
  private readonly settingsControllerOwner: BibleNoteSettingsControllerOwner = {
    connectSettingsController: (controller, currentColorScheme) =>
      this.connectSettingsController(controller, currentColorScheme),
    syncColorSchemeFromSettings: (mode) =>
      this.syncColorSchemeFromSettings(mode),
  };

  constructor(props: BibleNoteProps) {
    this.props = props;
    this.storageManager = createBibleNoteStorageManager(props);
  }

  get content(): string {
    return this.editorController?.getContent() ?? '';
  }
  set content(value: string) {
    this.runOrQueueEditorAction((controller) => {
      controller.setContent(value);
    });
  }

  get isReadOnly(): boolean {
    return (
      this.readOnlyOverride ?? this.editorController?.getIsReadOnly() ?? false
    );
  }
  set isReadOnly(value: boolean) {
    this.readOnlyOverride = value;
    this.editorController?.setReadOnly(value);
  }

  getIsFocusing(): boolean {
    return this.editorController?.getIsFocusing() ?? false;
  }

  setColorScheme(mode: BibleNoteColorScheme): void {
    this.pendingColorScheme = mode;
    this.colorScheme = mode;
    applyBibleNoteColorScheme(mode);
    this.settingsController?.setColorScheme(mode);
  }

  addText(text: string): void {
    if (text.length === 0 || this.isReadOnly) {
      return;
    }

    this.runOrQueueEditorAction((controller) => {
      if (this.isReadOnly) {
        return;
      }

      controller.addText(text);
    });
  }

  appendFooterActionButton(actionButton: BibleNoteFooterActionButton): void {
    this.setFooterActionButton(actionButton, 'after');
  }

  prependFooterActionButton(actionButton: BibleNoteFooterActionButton): void {
    this.setFooterActionButton(actionButton, 'before');
  }

  getFooterActionButton(id: string): BibleNoteFooterActionButton | null {
    return (
      this.footerActionButtons.before.find(
        (actionButton) => actionButton.id === id,
      ) ??
      this.footerActionButtons.after.find(
        (actionButton) => actionButton.id === id,
      ) ??
      null
    );
  }

  removeFooterActionButton(id: string): boolean {
    const nextBefore = this.footerActionButtons.before.filter(
      (actionButton) => actionButton.id !== id,
    );
    const nextAfter = this.footerActionButtons.after.filter(
      (actionButton) => actionButton.id !== id,
    );

    if (
      nextBefore.length === this.footerActionButtons.before.length &&
      nextAfter.length === this.footerActionButtons.after.length
    ) {
      return false;
    }

    this.footerActionButtons = {
      after: nextAfter,
      before: nextBefore,
    };
    this.syncFooterActionButtons();

    return true;
  }

  private setFooterActionButton(
    actionButton: BibleNoteFooterActionButton,
    placement: BibleNoteFooterActionButtonPlacement,
  ): void {
    const beforeIndex = this.footerActionButtons.before.findIndex(
      (existingActionButton) => existingActionButton.id === actionButton.id,
    );
    if (beforeIndex !== -1) {
      const nextBefore = [...this.footerActionButtons.before];
      nextBefore[beforeIndex] = actionButton;
      this.footerActionButtons = {
        after: this.footerActionButtons.after,
        before: nextBefore,
      };
      this.syncFooterActionButtons();
      return;
    }

    const afterIndex = this.footerActionButtons.after.findIndex(
      (existingActionButton) => existingActionButton.id === actionButton.id,
    );
    if (afterIndex !== -1) {
      const nextAfter = [...this.footerActionButtons.after];
      nextAfter[afterIndex] = actionButton;
      this.footerActionButtons = {
        after: nextAfter,
        before: this.footerActionButtons.before,
      };
      this.syncFooterActionButtons();
      return;
    }

    this.footerActionButtons = {
      after: this.footerActionButtons.after.filter(
        (existingActionButton) => existingActionButton.id !== actionButton.id,
      ),
      before: this.footerActionButtons.before.filter(
        (existingActionButton) => existingActionButton.id !== actionButton.id,
      ),
    };

    if (placement === 'before') {
      this.footerActionButtons.before.unshift(actionButton);
    } else {
      this.footerActionButtons.after.push(actionButton);
    }

    this.syncFooterActionButtons();
  }

  private getFooterActionButtonsSnapshot(): BibleNoteFooterActionButtons {
    return {
      after: [...this.footerActionButtons.after],
      before: [...this.footerActionButtons.before],
    };
  }

  private syncFooterActionButtons(): void {
    this.footerActionButtonController?.setFooterActionButtons(
      this.getFooterActionButtonsSnapshot(),
    );
  }

  private runOrQueueEditorAction(
    action: (controller: BibleNoteEditorController) => void,
  ): void {
    const controller = this.editorController;

    if (controller === null) {
      this.pendingEditorActions.push(action);
      return;
    }

    action(controller);
  }

  private connectEditorController(
    controller: BibleNoteEditorController,
  ): () => void {
    this.editorController = controller;

    for (const action of this.pendingEditorActions.splice(0)) {
      action(controller);
    }

    if (this.readOnlyOverride !== null) {
      controller.setReadOnly(this.readOnlyOverride);
    }

    return () => {
      if (this.editorController === controller) {
        this.editorController = null;
      }
    };
  }

  private connectSettingsController(
    controller: BibleNoteSettingsController,
    currentColorScheme: BibleNoteColorScheme,
  ): () => void {
    this.settingsController = controller;

    if (
      this.pendingColorScheme !== null &&
      this.pendingColorScheme !== currentColorScheme
    ) {
      controller.setColorScheme(this.pendingColorScheme);
    } else {
      this.pendingColorScheme = null;
      this.colorScheme = currentColorScheme;
    }

    return () => {
      if (this.settingsController === controller) {
        this.settingsController = null;
      }
    };
  }

  private connectFooterActionButtonController(
    controller: BibleNoteFooterActionButtonController,
  ): () => void {
    this.footerActionButtonController = controller;
    controller.setFooterActionButtons(this.getFooterActionButtonsSnapshot());

    return () => {
      if (this.footerActionButtonController === controller) {
        this.footerActionButtonController = null;
      }
    };
  }

  private syncColorSchemeFromSettings(mode: BibleNoteColorScheme): void {
    if (this.pendingColorScheme !== null && this.pendingColorScheme !== mode) {
      return;
    }

    this.pendingColorScheme = null;
    this.colorScheme = mode;
    applyBibleNoteColorScheme(mode);
  }

  /**
   * Drives the editor's find bar. A string opens the bar (or updates the query
   * if it is already open); `null` closes it. Queued until the editor mounts,
   * like the other editor-backed methods.
   */
  public searchText(query: string | null): void {
    this.runOrQueueEditorAction((controller) => {
      controller.searchText(query);
    });
  }

  render(
    containerElement: HTMLElement,
    options: BibleNoteRenderOptions = {},
  ): void {
    this.unmount();

    this.root = renderEditor(
      {
        props: this.props,
        containerElement,
        editorControllerOwner: this.editorControllerOwner,
        footerActionButtonControllerOwner:
          this.footerActionButtonControllerOwner,
        settingsControllerOwner: this.settingsControllerOwner,
        storageManager: this.storageManager,
      },
      options,
    );
  }

  unmount(): void {
    this.root?.unmount();
    this.root = null;
    this.editorController = null;
    this.footerActionButtonController = null;
    this.settingsController = null;
  }
}

export { BibleNote };
export default BibleNote;
