import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { editorStateFromSerializedDocument } from '@lexical/file';
import { DRAG_DROP_PASTE } from '@lexical/rich-text';
import { isMimeType, mediaFileReader } from '@lexical/utils';
import {
  COMMAND_PRIORITY_LOW,
  HISTORY_PUSH_TAG,
  type LexicalEditor,
} from 'lexical';
import { useEffect } from 'react';

import type { MediaType } from '../../nodes/MediaNode';
import { storeMediaFile } from '../../mediaFileStorage';
import {
  getFallbackFilePath,
  resolveMediaFilePath,
  type FilePathResolver,
} from '../../utils/filePathResolver';
import { INSERT_MEDIA_COMMAND } from '../MediaPlugin';

const ACCEPTABLE_IMAGE_TYPES = [
  'image/',
  'image/heic',
  'image/heif',
  'image/gif',
  'image/webp',
];
const VIDEO_FILE_EXTENSIONS = ['.mp4', '.webm', '.ogv', '.mov', '.m4v'];
const AUDIO_FILE_EXTENSIONS = [
  '.aac',
  '.flac',
  '.m4a',
  '.mp3',
  '.oga',
  '.ogg',
  '.opus',
  '.wav',
  '.weba',
];
const EDITOR_SHELL_SELECTOR = '.editor-shell';
const LEXICAL_FILE_EXTENSION = '.lexical';

function getMediaTypeFromFile(file: File): MediaType | null {
  const fileName = file.name.toLowerCase();
  if (file.type === 'application/pdf' || fileName.endsWith('.pdf')) {
    return 'pdf';
  }
  if (
    file.type.startsWith('video/') ||
    VIDEO_FILE_EXTENSIONS.some((extension) => fileName.endsWith(extension))
  ) {
    return 'video';
  }
  if (
    file.type.startsWith('audio/') ||
    AUDIO_FILE_EXTENSIONS.some((extension) => fileName.endsWith(extension))
  ) {
    return 'audio';
  }
  if (isMimeType(file, ACCEPTABLE_IMAGE_TYPES)) {
    return 'image';
  }
  return null;
}

function createFilePreviewSrc(file: File): string | undefined {
  return typeof URL.createObjectURL === 'function'
    ? URL.createObjectURL(file)
    : undefined;
}

function isLexicalFile(file: File): boolean {
  return file.name.toLowerCase().endsWith(LEXICAL_FILE_EXTENSION);
}

function getEditorShellElement(editor: LexicalEditor): HTMLElement | null {
  const rootElement = editor.getRootElement();

  return (
    rootElement?.closest<HTMLElement>(EDITOR_SHELL_SELECTOR) ?? rootElement
  );
}

function isEventInsideEditorShell(
  editor: LexicalEditor,
  event: DragEvent,
): boolean {
  const shellElement = getEditorShellElement(editor);
  const target = event.target;

  return (
    shellElement !== null &&
    target instanceof Node &&
    shellElement.contains(target)
  );
}

function isEventInsideEditorRoot(
  editor: LexicalEditor,
  event: DragEvent,
): boolean {
  const rootElement = editor.getRootElement();
  const target = event.target;

  return (
    rootElement !== null &&
    target instanceof Node &&
    rootElement.contains(target)
  );
}

function hasFileDrag(dataTransfer: DataTransfer | null): boolean {
  return (
    dataTransfer !== null && Array.from(dataTransfer.types).includes('Files')
  );
}

function getDataTransferFiles(dataTransfer: DataTransfer | null): File[] {
  return dataTransfer === null ? [] : Array.from(dataTransfer.files);
}

async function importLexicalFile(
  editor: LexicalEditor,
  file: File,
): Promise<void> {
  const text = await file.text();
  editor.setEditorState(editorStateFromSerializedDocument(editor, text), {
    tag: HISTORY_PUSH_TAG,
  });
}

export default function DragDropPaste({
  resolveFilePath,
}: {
  resolveFilePath?: FilePathResolver;
}): null {
  const [editor] = useLexicalComposerContext();
  useEffect(() => {
    const handleDragOver = (event: DragEvent) => {
      if (
        !isEventInsideEditorShell(editor, event) ||
        !hasFileDrag(event.dataTransfer)
      ) {
        return;
      }

      event.preventDefault();
      if (event.dataTransfer !== null) {
        event.dataTransfer.dropEffect = 'copy';
      }
    };

    const handleDrop = (event: DragEvent) => {
      if (
        !isEventInsideEditorShell(editor, event) ||
        isEventInsideEditorRoot(editor, event)
      ) {
        return;
      }

      const files = getDataTransferFiles(event.dataTransfer);
      if (files.length === 0) {
        return;
      }

      event.preventDefault();
      event.stopPropagation();

      const lexicalFile = files.find(isLexicalFile);
      if (lexicalFile === undefined) {
        editor.dispatchCommand(DRAG_DROP_PASTE, files);
        return;
      }

      void importLexicalFile(editor, lexicalFile);
    };

    document.addEventListener('dragenter', handleDragOver, true);
    document.addEventListener('dragover', handleDragOver, true);
    document.addEventListener('drop', handleDrop, true);

    return () => {
      document.removeEventListener('dragenter', handleDragOver, true);
      document.removeEventListener('dragover', handleDragOver, true);
      document.removeEventListener('drop', handleDrop, true);
    };
  }, [editor]);

  useEffect(() => {
    return editor.registerCommand(
      DRAG_DROP_PASTE,
      (files) => {
        (async () => {
          const lexicalFile = files.find(isLexicalFile);
          if (lexicalFile !== undefined) {
            await importLexicalFile(editor, lexicalFile);
            return;
          }

          const resolvedFilePaths = new Map<File, string>();
          for (const file of files) {
            const resolvedFilePath = await resolveMediaFilePath(
              resolveFilePath,
              file,
              'drop',
            );

            if (resolvedFilePath !== null) {
              resolvedFilePaths.set(file, resolvedFilePath);
            }
          }

          const unresolvedImageFiles = files.filter(
            (file) =>
              getMediaTypeFromFile(file) === 'image' &&
              !resolvedFilePaths.has(file),
          );

          const imageDataUrls = new Map<File, string>();
          if (unresolvedImageFiles.length > 0) {
            const filesResult = await mediaFileReader(
              unresolvedImageFiles,
              ACCEPTABLE_IMAGE_TYPES,
            );
            for (const { file, result } of filesResult) {
              if (isMimeType(file, ACCEPTABLE_IMAGE_TYPES)) {
                imageDataUrls.set(file, result);
              }
            }
          }

          for (const file of files) {
            const mediaType = getMediaTypeFromFile(file);
            const imageSrc =
              resolvedFilePaths.get(file) ?? imageDataUrls.get(file);
            if (mediaType === 'image' && imageSrc !== undefined) {
              editor.dispatchCommand(INSERT_MEDIA_COMMAND, {
                altText: file.name,
                src: imageSrc,
              });
            }
          }

          for (const file of files) {
            const mediaType = getMediaTypeFromFile(file);
            if (
              mediaType === 'video' ||
              mediaType === 'pdf' ||
              mediaType === 'audio'
            ) {
              const src =
                resolvedFilePaths.get(file) ?? getFallbackFilePath(file);
              const previewSrc = createFilePreviewSrc(file);
              await storeMediaFile(src, file);
              editor.dispatchCommand(INSERT_MEDIA_COMMAND, {
                altText: file.name,
                mediaType,
                ...(previewSrc ? { previewSrc } : null),
                src,
              });
            }
          }
        })();
        return true;
      },
      COMMAND_PRIORITY_LOW,
    );
  }, [editor, resolveFilePath]);
  return null;
}
