export type BibleNoteColorScheme = 'dark' | 'light';

export function applyBibleNoteColorScheme(
  mode: BibleNoteColorScheme,
  body: HTMLElement = document.body,
): void {
  body.classList.toggle('playground-theme-dark', mode === 'dark');
  body.classList.toggle('playground-theme-light', mode === 'light');
  body.dataset.bsTheme = mode;
}

export function clearBibleNoteColorScheme(
  body: HTMLElement = document.body,
): void {
  body.classList.remove('playground-theme-dark', 'playground-theme-light');
}
