import { useEffect, useState } from 'react';

export type Comment = {
  author: string;
  content: string;
  deleted: boolean;
  id: string;
  timeStamp: number;
  type: 'comment';
};

export type ThreadQuoteSegmentStyle = {
  fontFamily?: string;
  fontStyle?: 'italic';
  fontWeight?: string;
};

export type ThreadQuoteSegment = {
  style?: ThreadQuoteSegmentStyle;
  text: string;
};

export type Thread = {
  comments: Array<Comment>;
  id: string;
  quote: string;
  quoteSegments?: Array<ThreadQuoteSegment>;
  type: 'thread';
};

export type Comments = Array<Thread | Comment>;

function createUID(): string {
  return Math.random()
    .toString(36)
    .replace(/[^a-z]+/g, '')
    .substring(0, 5);
}

function asQuoteRecord(value: unknown): null | Record<string, unknown> {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return null;
  }

  return value as Record<string, unknown>;
}

function isSafeQuoteStyleValue(value: string): boolean {
  const trimmedValue = value.trim();

  return (
    trimmedValue.length > 0 &&
    trimmedValue.length <= 200 &&
    !/[<>{};]/.test(trimmedValue)
  );
}

function normalizeThreadQuoteSegmentStyle(
  value: unknown,
): ThreadQuoteSegmentStyle | undefined {
  const styleRecord = asQuoteRecord(value);

  if (styleRecord === null) {
    return undefined;
  }

  const style: ThreadQuoteSegmentStyle = {};

  if (
    typeof styleRecord.fontFamily === 'string' &&
    isSafeQuoteStyleValue(styleRecord.fontFamily)
  ) {
    style.fontFamily = styleRecord.fontFamily.trim();
  }

  if (styleRecord.fontStyle === 'italic') {
    style.fontStyle = 'italic';
  }

  if (
    typeof styleRecord.fontWeight === 'string' &&
    isSafeQuoteStyleValue(styleRecord.fontWeight)
  ) {
    style.fontWeight = styleRecord.fontWeight.trim();
  }

  return Object.keys(style).length === 0 ? undefined : style;
}

export function normalizeThreadQuoteSegments(
  value: unknown,
): Array<ThreadQuoteSegment> | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const normalizedSegments: Array<ThreadQuoteSegment> = [];

  for (let segmentIndex = 0; segmentIndex < value.length; segmentIndex++) {
    const segmentRecord = asQuoteRecord(value[segmentIndex]);

    if (segmentRecord === null || typeof segmentRecord.text !== 'string') {
      return undefined;
    }

    if (segmentRecord.text.length === 0) {
      continue;
    }

    const style = normalizeThreadQuoteSegmentStyle(segmentRecord.style);
    normalizedSegments.push(
      style === undefined
        ? { text: segmentRecord.text }
        : { style, text: segmentRecord.text },
    );
  }

  return normalizedSegments.length === 0 ? undefined : normalizedSegments;
}

function cloneThreadQuoteSegments(
  quoteSegments?: ReadonlyArray<ThreadQuoteSegment>,
): Array<ThreadQuoteSegment> | undefined {
  if (quoteSegments === undefined || quoteSegments.length === 0) {
    return undefined;
  }

  return quoteSegments.map((segment) => ({
    ...(segment.style === undefined
      ? {}
      : {
          style: {
            ...(segment.style.fontFamily === undefined
              ? {}
              : { fontFamily: segment.style.fontFamily }),
            ...(segment.style.fontStyle === undefined
              ? {}
              : { fontStyle: segment.style.fontStyle }),
            ...(segment.style.fontWeight === undefined
              ? {}
              : { fontWeight: segment.style.fontWeight }),
          },
        }),
    text: segment.text,
  }));
}

export function createComment(
  content: string,
  author: string,
  id?: string,
  timeStamp?: number,
  deleted?: boolean,
): Comment {
  return {
    author,
    content,
    deleted: deleted === undefined ? false : deleted,
    id: id === undefined ? createUID() : id,
    timeStamp:
      timeStamp === undefined
        ? performance.timeOrigin + performance.now()
        : timeStamp,
    type: 'comment',
  };
}

export function createThread(
  quote: string,
  comments: Array<Comment>,
  id?: string,
  quoteSegments?: ReadonlyArray<ThreadQuoteSegment>,
): Thread {
  const clonedQuoteSegments = cloneThreadQuoteSegments(quoteSegments);

  return {
    comments,
    id: id === undefined ? createUID() : id,
    quote,
    ...(clonedQuoteSegments === undefined
      ? {}
      : { quoteSegments: clonedQuoteSegments }),
    type: 'thread',
  };
}

function cloneComment(comment: Comment): Comment {
  return {
    author: comment.author,
    content: comment.content,
    deleted: comment.deleted,
    id: comment.id,
    timeStamp: comment.timeStamp,
    type: 'comment',
  };
}

function cloneThread(thread: Thread): Thread {
  const quoteSegments = cloneThreadQuoteSegments(thread.quoteSegments);

  return {
    comments: Array.from(thread.comments),
    id: thread.id,
    quote: thread.quote,
    ...(quoteSegments === undefined ? {} : { quoteSegments }),
    type: 'thread',
  };
}

function cloneComments(comments: Comments): Comments {
  return comments.map((commentOrThread) =>
    commentOrThread.type === 'thread'
      ? {
          comments: commentOrThread.comments.map(cloneComment),
          id: commentOrThread.id,
          quote: commentOrThread.quote,
          ...(commentOrThread.quoteSegments === undefined
            ? {}
            : {
                quoteSegments: cloneThreadQuoteSegments(
                  commentOrThread.quoteSegments,
                ),
              }),
          type: 'thread',
        }
      : cloneComment(commentOrThread),
  );
}

function markDeleted(comment: Comment): Comment {
  return {
    author: comment.author,
    content: '[Deleted Comment]',
    deleted: true,
    id: comment.id,
    timeStamp: comment.timeStamp,
    type: 'comment',
  };
}

function triggerOnChange(commentStore: CommentStore): void {
  const listeners = commentStore._changeListeners;
  for (const listener of listeners) {
    listener();
  }
}

export class CommentStore {
  _comments: Comments;
  _changeListeners: Set<() => void>;

  constructor(comments: Comments = []) {
    this._comments = cloneComments(comments);
    this._changeListeners = new Set();
  }

  getComments(): Comments {
    return this._comments;
  }

  addComment(
    commentOrThread: Comment | Thread,
    thread?: Thread,
    offset?: number,
  ): void {
    const nextComments = Array.from(this._comments);

    if (thread !== undefined && commentOrThread.type === 'comment') {
      for (let i = 0; i < nextComments.length; i++) {
        const comment = nextComments[i];
        if (comment.type === 'thread' && comment.id === thread.id) {
          const newThread = cloneThread(comment);
          nextComments.splice(i, 1, newThread);
          const insertOffset =
            offset !== undefined ? offset : newThread.comments.length;
          newThread.comments.splice(insertOffset, 0, commentOrThread);
          break;
        }
      }
    } else {
      const insertOffset = offset !== undefined ? offset : nextComments.length;
      nextComments.splice(insertOffset, 0, commentOrThread);
    }
    this._comments = nextComments;
    triggerOnChange(this);
  }

  deleteCommentOrThread(
    commentOrThread: Comment | Thread,
    thread?: Thread,
  ): { markedComment: Comment; index: number } | null {
    const nextComments = Array.from(this._comments);
    let commentIndex: number | null = null;

    if (thread !== undefined) {
      for (let i = 0; i < nextComments.length; i++) {
        const nextComment = nextComments[i];
        if (nextComment.type === 'thread' && nextComment.id === thread.id) {
          const newThread = cloneThread(nextComment);
          nextComments.splice(i, 1, newThread);
          const threadComments = newThread.comments;
          commentIndex = threadComments.indexOf(commentOrThread as Comment);
          threadComments.splice(commentIndex, 1);
          break;
        }
      }
    } else {
      commentIndex = nextComments.indexOf(commentOrThread);
      nextComments.splice(commentIndex, 1);
    }
    this._comments = nextComments;
    triggerOnChange(this);

    if (commentOrThread.type === 'comment') {
      return {
        index: commentIndex as number,
        markedComment: markDeleted(commentOrThread),
      };
    }

    return null;
  }

  registerOnChange(onChange: () => void): () => void {
    const changeListeners = this._changeListeners;
    changeListeners.add(onChange);
    return () => {
      changeListeners.delete(onChange);
    };
  }
}

export function useCommentStore(commentStore: CommentStore): Comments {
  const [comments, setComments] = useState<Comments>(
    commentStore.getComments(),
  );

  useEffect(() => {
    return commentStore.registerOnChange(() => {
      setComments(commentStore.getComments());
    });
  }, [commentStore]);

  return comments;
}
