import type {
  CSSProperties,
  JSX,
  PointerEvent as ReactPointerEvent,
  ReactNode,
} from 'react';
import { useCallback, useEffect, useRef, useState } from 'react';

import {
  clampMentionAdvancedPanelPosition,
  getMentionAdvancedPanelBounds,
  getMentionAdvancedPanelZoomScale,
  MIN_MENTION_ADVANCED_PANEL_HEIGHT,
  type MentionAdvancedPanelPosition,
} from './MentionAdvancedPanelUtils';

const COPIED_FEEDBACK_DURATION_MS = 1600;

type MentionAdvancedPanelDragState = {
  pointerId: number;
  startClientX: number;
  startClientY: number;
  startLeft: number;
  startTop: number;
};

type MentionAdvancedPanelProps = {
  anchorElement: HTMLElement | null;
  iconClassName: string;
  name: string;
  nameContent?: ReactNode;
  panelKind: string;
  position: MentionAdvancedPanelPosition;
  copyLabel?: string;
  textStyle?: CSSProperties;
  title: ReactNode;
  zIndex: number;
  onBringToFront: () => void;
  onClose: () => void;
  onCopy?: () => Promise<void> | void;
  onPositionChange: (position: MentionAdvancedPanelPosition) => void;
};

function arePositionsEqual(
  firstPosition: MentionAdvancedPanelPosition,
  secondPosition: MentionAdvancedPanelPosition,
): boolean {
  return (
    firstPosition.left === secondPosition.left &&
    firstPosition.top === secondPosition.top
  );
}

export default function MentionAdvancedPanel({
  anchorElement,
  iconClassName,
  name,
  nameContent,
  panelKind,
  position,
  copyLabel,
  textStyle,
  title,
  zIndex,
  onBringToFront,
  onClose,
  onCopy,
  onPositionChange,
}: MentionAdvancedPanelProps): JSX.Element {
  const panelRef = useRef<HTMLDivElement | null>(null);
  const dragStateRef = useRef<MentionAdvancedPanelDragState | null>(null);
  const anchorElementRef = useRef<HTMLElement | null>(anchorElement);
  const onPositionChangeRef = useRef(onPositionChange);
  const copiedResetTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(
    null,
  );
  const [isDragging, setIsDragging] = useState(false);
  const [isCopied, setIsCopied] = useState(false);

  anchorElementRef.current = anchorElement;
  onPositionChangeRef.current = onPositionChange;

  useEffect(() => {
    return () => {
      if (copiedResetTimeoutRef.current !== null) {
        clearTimeout(copiedResetTimeoutRef.current);
      }
    };
  }, []);

  const handleCopyClick = useCallback(() => {
    if (onCopy === undefined) {
      return;
    }

    void Promise.resolve(onCopy()).then(() => {
      setIsCopied(true);

      if (copiedResetTimeoutRef.current !== null) {
        clearTimeout(copiedResetTimeoutRef.current);
      }

      copiedResetTimeoutRef.current = setTimeout(() => {
        setIsCopied(false);
        copiedResetTimeoutRef.current = null;
      }, COPIED_FEEDBACK_DURATION_MS);
    });
  }, [onCopy]);

  const handlePointerMove = useCallback((event: PointerEvent) => {
    const dragState = dragStateRef.current;

    if (dragState === null || dragState.pointerId !== event.pointerId) {
      return;
    }

    onPositionChangeRef.current(
      clampMentionAdvancedPanelPosition(
        {
          left: dragState.startLeft + event.clientX - dragState.startClientX,
          top: dragState.startTop + event.clientY - dragState.startClientY,
        },
        panelRef.current,
        anchorElementRef.current,
      ),
    );
    event.preventDefault();
  }, []);

  const handlePointerUp = useCallback(
    (event: PointerEvent) => {
      const dragState = dragStateRef.current;

      if (dragState === null || dragState.pointerId !== event.pointerId) {
        return;
      }

      dragStateRef.current = null;
      setIsDragging(false);
      document.removeEventListener('pointermove', handlePointerMove);
      document.removeEventListener('pointerup', handlePointerUp);
      document.removeEventListener('pointercancel', handlePointerUp);
      event.preventDefault();
    },
    [handlePointerMove],
  );

  const handleDragPointerDown = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      if (event.button !== 0) {
        return;
      }

      if (
        event.target instanceof Element &&
        event.target.closest('button, .mention-advanced-panel__name')
      ) {
        return;
      }

      onBringToFront();
      dragStateRef.current = {
        pointerId: event.pointerId,
        startClientX: event.clientX,
        startClientY: event.clientY,
        startLeft: position.left,
        startTop: position.top,
      };
      setIsDragging(true);
      document.addEventListener('pointermove', handlePointerMove);
      document.addEventListener('pointerup', handlePointerUp);
      document.addEventListener('pointercancel', handlePointerUp);
      event.preventDefault();
      event.stopPropagation();
    },
    [
      handlePointerMove,
      handlePointerUp,
      onBringToFront,
      position.left,
      position.top,
    ],
  );

  useEffect(() => {
    return () => {
      document.removeEventListener('pointermove', handlePointerMove);
      document.removeEventListener('pointerup', handlePointerUp);
      document.removeEventListener('pointercancel', handlePointerUp);
    };
  }, [handlePointerMove, handlePointerUp]);

  useEffect(() => {
    const updatePanelPosition = () => {
      const nextPosition = clampMentionAdvancedPanelPosition(
        position,
        panelRef.current,
        anchorElement,
      );

      if (!arePositionsEqual(nextPosition, position)) {
        onPositionChange(nextPosition);
      }
    };

    updatePanelPosition();
    window.addEventListener('resize', updatePanelPosition);
    window.addEventListener('scroll', updatePanelPosition, true);

    return () => {
      window.removeEventListener('resize', updatePanelPosition);
      window.removeEventListener('scroll', updatePanelPosition, true);
    };
  }, [anchorElement, onPositionChange, position]);

  const bounds = getMentionAdvancedPanelBounds(anchorElement);
  // The panel lives inside the editor's CSS `zoom` surface, so it scales with
  // the editor zoom and its inline `left`/`top` are interpreted in local
  // (un-zoomed) pixels, then magnified by the browser. The stored position and
  // bounds come from `getBoundingClientRect()`/pointer coords, which are in
  // visual (post-zoom) pixels. Divide by the zoom scale to convert them back to
  // local space so the panel stays anchored to the same visual spot at any zoom
  // level.
  //
  // The scale must come from the panel's own zoom surface, not the anchor: when
  // the panel is opened from the lookup list, the anchor button is portaled to
  // `document.body` (outside the zoom surface, scale 1), so using the anchor
  // left the local coords un-magnified and rendered the panel far off-screen.
  const zoomScale = getMentionAdvancedPanelZoomScale(
    panelRef.current,
    anchorElement,
  );
  const panelStyle: CSSProperties = {
    left: position.left / zoomScale,
    maxHeight:
      Math.max(
        MIN_MENTION_ADVANCED_PANEL_HEIGHT,
        bounds.bottom - position.top,
      ) / zoomScale,
    maxWidth: Math.max(220, bounds.right - position.left) / zoomScale,
    position: 'fixed',
    top: position.top / zoomScale,
    zIndex,
  };

  return (
    <div
      ref={panelRef}
      aria-label={`${name} advanced panel`}
      className={`mention-advanced-panel${isDragging ? ' dragging' : ''}`}
      role="dialog"
      style={panelStyle}
      tabIndex={0}
      onFocus={onBringToFront}
      onPointerDown={onBringToFront}
    >
      <div
        className="mention-advanced-panel__header"
        onPointerDown={handleDragPointerDown}
      >
        <div
          className="mention-advanced-panel__name d-inline-flex align-items-center gap-2"
          style={textStyle}
        >
          <i className={iconClassName} aria-hidden="true" />
          {nameContent ?? <span>{name}</span>}
        </div>
        <div className="mention-advanced-panel__actions">
          {onCopy !== undefined ? (
            <button
              aria-label={
                isCopied ? 'Copied' : (copyLabel ?? `Copy ${panelKind} text`)
              }
              className={`mention-advanced-panel__copy${
                isCopied ? ' mention-advanced-panel__copy--copied' : ''
              }`}
              title={isCopied ? 'Copied!' : 'Copy'}
              type="button"
              onClick={handleCopyClick}
            >
              <i
                className={isCopied ? 'bi bi-check2' : 'bi bi-copy'}
                aria-hidden="true"
              />
            </button>
          ) : null}
          <button
            aria-label={`Close ${panelKind} panel`}
            className="mention-advanced-panel__close"
            title="Close"
            type="button"
            onClick={onClose}
          >
            <i className="bi bi-x-lg" aria-hidden="true" />
          </button>
        </div>
      </div>
      {title ? (
        <div className="mention-advanced-panel__title" style={textStyle}>
          {title}
        </div>
      ) : null}
    </div>
  );
}
