import {
  $applyNodeReplacement,
  type DOMConversionMap,
  type DOMConversionOutput,
  type DOMExportOutput,
  type EditorConfig,
  type LexicalNode,
  type LexicalUpdateJSON,
  type NodeKey,
  type SerializedTextNode,
  type Spread,
  TextNode,
} from 'lexical';

export type MentionKind = 'mention' | 'location' | 'bible-verse';

type SerializedMentionKind = MentionKind | 'hashtag';

export type SerializedMentionNode = Spread<
  {
    mentionData?: string | null;
    mentionId?: string | null;
    mentionKind?: SerializedMentionKind;
    mentionName: string;
  },
  SerializedTextNode
>;

function normalizeMentionKind(
  mentionKind?: SerializedMentionKind,
): MentionKind | undefined {
  if (
    mentionKind === 'mention' ||
    mentionKind === 'location' ||
    mentionKind === 'bible-verse'
  ) {
    return mentionKind;
  }

  return mentionKind === 'hashtag' ? 'location' : undefined;
}

function inferMentionKind(
  mentionName: string,
  textContent: string,
  mentionKind?: SerializedMentionKind,
): MentionKind {
  const normalizedMentionKind = normalizeMentionKind(mentionKind);

  if (normalizedMentionKind !== undefined) {
    return normalizedMentionKind;
  }

  if (mentionName.startsWith('#') || textContent.startsWith('#')) {
    return 'location';
  }

  return mentionName.startsWith('^') || textContent.startsWith('^')
    ? 'bible-verse'
    : 'mention';
}

function normalizeMentionName(
  mentionName: string,
  mentionKind: MentionKind,
): string {
  if (mentionKind === 'location' && mentionName.startsWith('#')) {
    return mentionName.slice(1);
  }

  if (mentionKind === 'bible-verse' && mentionName.startsWith('^')) {
    return mentionName.slice(1);
  }

  return mentionName;
}

function normalizeMentionText(
  textContent: string,
  mentionName: string,
  mentionKind: MentionKind,
): string {
  if (mentionKind === 'location' && textContent.startsWith('#')) {
    return mentionName;
  }

  if (mentionKind === 'bible-verse' && textContent.startsWith('^')) {
    return textContent.slice(1);
  }

  return textContent;
}

function setMentionMetadataAttributes(
  element: HTMLElement,
  mentionName: string,
  mentionKind: MentionKind,
  mentionId: string | null,
  mentionData: string | null,
  includeMentionName: boolean,
): void {
  element.setAttribute('data-lexical-mention', 'true');
  element.setAttribute('data-lexical-mention-kind', mentionKind);

  if (mentionId !== null) {
    element.setAttribute('data-lexical-mention-id', mentionId);
  } else {
    element.removeAttribute('data-lexical-mention-id');
  }

  if (mentionData !== null) {
    element.setAttribute('data-lexical-mention-data', mentionData);
  } else {
    element.removeAttribute('data-lexical-mention-data');
  }

  if (includeMentionName) {
    element.setAttribute('data-lexical-mention-name', mentionName);
  } else {
    element.removeAttribute('data-lexical-mention-name');
  }
}

function $convertMentionElement(
  domNode: HTMLElement,
): DOMConversionOutput | null {
  const textContent = domNode.textContent;
  const mentionData = domNode.getAttribute('data-lexical-mention-data');
  const mentionId = domNode.getAttribute('data-lexical-mention-id');
  const mentionName = domNode.getAttribute('data-lexical-mention-name');
  const mentionKindAttribute = domNode.getAttribute(
    'data-lexical-mention-kind',
  );

  if (textContent !== null) {
    const nextMentionKind = inferMentionKind(
      typeof mentionName === 'string' ? mentionName : textContent,
      textContent,
      mentionKindAttribute === 'mention' ||
        mentionKindAttribute === 'location' ||
        mentionKindAttribute === 'bible-verse' ||
        mentionKindAttribute === 'hashtag'
        ? mentionKindAttribute
        : undefined,
    );
    const nextMentionName = normalizeMentionName(
      typeof mentionName === 'string' ? mentionName : textContent,
      nextMentionKind,
    );
    const node = $createMentionNode(
      nextMentionName,
      normalizeMentionText(textContent, nextMentionName, nextMentionKind),
      mentionId,
      nextMentionKind,
      mentionData,
    );
    return {
      node,
    };
  }

  return null;
}

export class MentionNode extends TextNode {
  __mention: string;
  __mentionData: string | null;
  __mentionId: string | null;
  __mentionKind: MentionKind;

  static getType(): string {
    return 'mention';
  }

  static clone(node: MentionNode): MentionNode {
    return new MentionNode(
      node.__mention,
      node.__text,
      node.__mentionId,
      node.__mentionKind,
      node.__mentionData,
      node.__key,
    );
  }

  static importJSON(serializedNode: SerializedMentionNode): MentionNode {
    const mentionKind = inferMentionKind(
      serializedNode.mentionName,
      serializedNode.text,
      serializedNode.mentionKind,
    );
    const mentionName = normalizeMentionName(
      serializedNode.mentionName,
      mentionKind,
    );
    const textContent = normalizeMentionText(
      serializedNode.text,
      mentionName,
      mentionKind,
    );

    return $createMentionNode(
      mentionName,
      textContent,
      serializedNode.mentionId ?? null,
      mentionKind,
      serializedNode.mentionData ?? null,
    ).updateFromJSON({
      ...serializedNode,
      mentionKind,
      mentionName,
      text: textContent,
    });
  }

  updateFromJSON(
    serializedNode: LexicalUpdateJSON<SerializedMentionNode>,
  ): this {
    const mentionKind = inferMentionKind(
      serializedNode.mentionName,
      serializedNode.text,
      serializedNode.mentionKind,
    );
    const mentionName = normalizeMentionName(
      serializedNode.mentionName,
      mentionKind,
    );
    const textContent = normalizeMentionText(
      serializedNode.text,
      mentionName,
      mentionKind,
    );
    const node = super.updateFromJSON({
      ...serializedNode,
      text: textContent,
    } as LexicalUpdateJSON<SerializedTextNode>);
    node.__mention = mentionName;
    node.__mentionData = serializedNode.mentionData ?? null;
    node.__mentionId = serializedNode.mentionId ?? null;
    node.__mentionKind = mentionKind;
    return node;
  }

  constructor(
    mentionName: string,
    text?: string,
    mentionId?: string | null,
    mentionKind?: MentionKind,
    mentionData?: string | null,
    key?: NodeKey,
  ) {
    const nextMentionKind = inferMentionKind(
      mentionName,
      text ?? mentionName,
      mentionKind,
    );
    const nextMentionName = normalizeMentionName(mentionName, nextMentionKind);
    const nextText = normalizeMentionText(
      text ?? mentionName,
      nextMentionName,
      nextMentionKind,
    );

    super(nextText, key);
    this.__mention = nextMentionName;
    this.__mentionData = mentionData ?? null;
    this.__mentionId = mentionId ?? null;
    this.__mentionKind = nextMentionKind;
  }

  exportJSON(): SerializedMentionNode {
    return {
      ...super.exportJSON(),
      mentionData: this.__mentionData,
      mentionId: this.__mentionId,
      mentionKind: this.__mentionKind,
      mentionName: this.__mention,
    };
  }

  getMentionKind(): MentionKind {
    return this.getLatest().__mentionKind;
  }

  setMentionKind(mentionKind: MentionKind): this {
    const writable = this.getWritable();
    writable.__mentionKind = mentionKind;
    return writable;
  }

  getMention(): string {
    return this.getLatest().__mention;
  }

  setMention(mentionName: string): this {
    const writable = this.getWritable();
    writable.__mention = mentionName;
    return writable;
  }

  getMentionData(): string | null {
    return this.getLatest().__mentionData;
  }

  setMentionData(mentionData: string | null): this {
    const writable = this.getWritable();
    writable.__mentionData = mentionData;
    return writable;
  }

  createDOM(config: EditorConfig): HTMLElement {
    const dom = super.createDOM(config);
    dom.className = 'mention';
    dom.spellcheck = false;
    setMentionMetadataAttributes(
      dom,
      this.__mention,
      this.__mentionKind,
      this.__mentionId,
      this.__mentionData,
      true,
    );

    return dom;
  }

  updateDOM(prevNode: this, dom: HTMLElement, config: EditorConfig): boolean {
    const hasUpdated = super.updateDOM(prevNode, dom, config);
    const expectedMentionKind = this.__mentionKind;

    if (
      prevNode.__mention !== this.__mention ||
      prevNode.__mentionData !== this.__mentionData ||
      prevNode.__mentionId !== this.__mentionId ||
      prevNode.__mentionKind !== this.__mentionKind ||
      prevNode.__text !== this.__text ||
      dom.getAttribute('data-lexical-mention-kind') !== expectedMentionKind ||
      dom.getAttribute('data-lexical-mention-data') !== this.__mentionData
    ) {
      setMentionMetadataAttributes(
        dom,
        this.__mention,
        this.__mentionKind,
        this.__mentionId,
        this.__mentionData,
        true,
      );
    }

    return hasUpdated;
  }

  exportDOM(): DOMExportOutput {
    const element = document.createElement('span');
    setMentionMetadataAttributes(
      element,
      this.__mention,
      this.__mentionKind,
      this.__mentionId,
      this.__mentionData,
      this.__text !== this.__mention,
    );
    element.textContent = this.__text;
    return { element };
  }

  static importDOM(): DOMConversionMap | null {
    return {
      span: (domNode: HTMLElement) => {
        if (!domNode.hasAttribute('data-lexical-mention')) {
          return null;
        }
        return {
          conversion: $convertMentionElement,
          priority: 1,
        };
      },
    };
  }

  isTextEntity(): true {
    return true;
  }

  canInsertTextBefore(): boolean {
    return false;
  }

  canInsertTextAfter(): boolean {
    return false;
  }
}

export function $createMentionNode(
  mentionName: string,
  textContent?: string,
  mentionId?: string | null,
  mentionKind?: MentionKind,
  mentionData?: string | null,
): MentionNode {
  const mentionNode = new MentionNode(
    mentionName,
    textContent,
    mentionId,
    mentionKind,
    mentionData,
  );
  mentionNode.setMode('segmented').toggleDirectionless();
  return $applyNodeReplacement(mentionNode);
}

export function $isMentionNode(
  node: LexicalNode | null | undefined,
): node is MentionNode {
  return node instanceof MentionNode;
}
