import type {
  DOMConversionMap,
  DOMConversionOutput,
  DOMExportOutput,
  EditorConfig,
  ElementFormatType,
  LexicalEditor,
  LexicalNode,
  NodeKey,
  Spread,
} from 'lexical';
import type { JSX } from 'react';

import { BlockWithAlignableContents } from '@lexical/react/LexicalBlockWithAlignableContents';
import {
  DecoratorBlockNode,
  type SerializedDecoratorBlockNode,
} from '@lexical/react/LexicalDecoratorBlockNode';
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { useLexicalEditable } from '@lexical/react/useLexicalEditable';
import { useLexicalNodeSelection } from '@lexical/react/useLexicalNodeSelection';
import {
  $getNodeByKey,
  CLICK_COMMAND,
  COMMAND_PRIORITY_LOW,
  isDOMNode,
} from 'lexical';
import { useCallback, useEffect, useRef, useState } from 'react';
import * as React from 'react';

import MediaResizer from '../ui/MediaResizer';
import { sanitizeUrl } from '../utils/url';

const WEBSITE_IFRAME_ALLOW =
  'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture';
const WEBSITE_IFRAME_SANDBOX =
  'allow-scripts allow-same-origin allow-popups allow-forms';
const WEBSITE_DEFAULT_WIDTH = 560;
const WEBSITE_DEFAULT_HEIGHT = 315;

type Dimension = number | 'inherit';

function parseDimension(value: string | null): Dimension {
  if (value === null) {
    return 'inherit';
  }
  const parsed = Number.parseInt(value, 10);
  return Number.isNaN(parsed) ? 'inherit' : parsed;
}

type WebsiteComponentProps = Readonly<{
  className: Readonly<{
    base: string;
    focus: string;
  }>;
  format: ElementFormatType | null;
  height: Dimension;
  nodeKey: NodeKey;
  url: string;
  width: Dimension;
}>;

function WebsiteComponent({
  className,
  format,
  height,
  nodeKey,
  url,
  width,
}: WebsiteComponentProps) {
  const [editor] = useLexicalComposerContext();
  const isEditable = useLexicalEditable();
  const [isSelected, setSelected, clearSelection] =
    useLexicalNodeSelection(nodeKey);
  const [isResizing, setIsResizing] = useState(false);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const captionButtonRef = useRef<HTMLButtonElement | null>(null);

  useEffect(() => {
    if (!isEditable) {
      if (isSelected) {
        clearSelection();
      }
      return;
    }
    return editor.registerCommand<MouseEvent>(
      CLICK_COMMAND,
      (event) => {
        if (isResizing) {
          return true;
        }
        const target = event.target;
        if (
          containerRef.current !== null &&
          isDOMNode(target) &&
          containerRef.current.contains(target)
        ) {
          if (!event.shiftKey) {
            clearSelection();
          }
          setSelected(!isSelected);
          return true;
        }
        return false;
      },
      COMMAND_PRIORITY_LOW,
    );
  }, [clearSelection, editor, isEditable, isResizing, isSelected, setSelected]);

  const onResizeStart = useCallback(() => {
    setIsResizing(true);
  }, []);

  const onResizeEnd = useCallback(
    (nextWidth: Dimension, nextHeight: Dimension) => {
      // Delay hiding the resize bars for click case
      setTimeout(() => {
        setIsResizing(false);
      }, 200);

      editor.update(() => {
        const node = $getNodeByKey(nodeKey);
        if ($isWebsiteNode(node)) {
          node.setWidthAndHeight(nextWidth, nextHeight);
        }
      });
    },
    [editor, nodeKey],
  );

  const isFocused = (isSelected || isResizing) && isEditable;
  const showShield = isEditable && !isSelected;

  return (
    <BlockWithAlignableContents
      className={className}
      format={format}
      nodeKey={nodeKey}
    >
      <div
        className={`editor-media website-embed${isFocused ? ' focused' : ''}`}
        ref={containerRef}
        style={{
          height: height === 'inherit' ? WEBSITE_DEFAULT_HEIGHT : height,
          width: width === 'inherit' ? WEBSITE_DEFAULT_WIDTH : width,
        }}
      >
        <iframe
          className="website-embed__frame"
          src={sanitizeUrl(url)}
          allow={WEBSITE_IFRAME_ALLOW}
          allowFullScreen={true}
          loading="lazy"
          referrerPolicy="no-referrer"
          sandbox={WEBSITE_IFRAME_SANDBOX}
          style={{ pointerEvents: isResizing ? 'none' : undefined }}
          title="Website embed"
        />
        {showShield && (
          <div className="website-embed__shield" data-testid="website-shield" />
        )}
        {isFocused && (
          <MediaResizer
            buttonRef={captionButtonRef}
            captionsEnabled={false}
            editor={editor}
            mediaRef={containerRef}
            onResizeEnd={onResizeEnd}
            onResizeStart={onResizeStart}
            setShowCaption={() => undefined}
            showCaption={true}
          />
        )}
      </div>
    </BlockWithAlignableContents>
  );
}

export type SerializedWebsiteNode = Spread<
  {
    height: Dimension;
    url: string;
    width: Dimension;
  },
  SerializedDecoratorBlockNode
>;

function $convertWebsiteElement(
  domNode: HTMLElement,
): null | DOMConversionOutput {
  const url = domNode.getAttribute('data-lexical-website');
  if (url) {
    const width = parseDimension(domNode.getAttribute('width'));
    const height = parseDimension(domNode.getAttribute('height'));
    const node = $createWebsiteNode(url, width, height);
    return { node };
  }
  return null;
}

export class WebsiteNode extends DecoratorBlockNode {
  __url: string;
  __width: Dimension;
  __height: Dimension;

  static getType(): string {
    return 'website';
  }

  static clone(node: WebsiteNode): WebsiteNode {
    return new WebsiteNode(
      node.__url,
      node.__width,
      node.__height,
      node.__format,
      node.__key,
    );
  }

  static importJSON(serializedNode: SerializedWebsiteNode): WebsiteNode {
    const { url, width, height } = serializedNode;
    return $createWebsiteNode(url, width, height).updateFromJSON(
      serializedNode,
    );
  }

  exportJSON(): SerializedWebsiteNode {
    return {
      ...super.exportJSON(),
      height: this.__height,
      url: this.__url,
      width: this.__width,
    };
  }

  constructor(
    url: string,
    width: Dimension = 'inherit',
    height: Dimension = 'inherit',
    format?: ElementFormatType,
    key?: NodeKey,
  ) {
    super(format, key);
    this.__url = url;
    this.__width = width;
    this.__height = height;
  }

  exportDOM(): DOMExportOutput {
    const element = document.createElement('iframe');
    element.setAttribute('data-lexical-website', this.__url);
    element.setAttribute(
      'width',
      String(this.__width === 'inherit' ? WEBSITE_DEFAULT_WIDTH : this.__width),
    );
    element.setAttribute(
      'height',
      String(
        this.__height === 'inherit' ? WEBSITE_DEFAULT_HEIGHT : this.__height,
      ),
    );
    element.setAttribute('src', sanitizeUrl(this.__url));
    element.setAttribute('frameborder', '0');
    element.setAttribute('allow', WEBSITE_IFRAME_ALLOW);
    element.setAttribute('allowfullscreen', 'true');
    element.setAttribute('loading', 'lazy');
    element.setAttribute('referrerpolicy', 'no-referrer');
    element.setAttribute('sandbox', WEBSITE_IFRAME_SANDBOX);
    element.setAttribute('title', 'Website embed');
    return { element };
  }

  static importDOM(): DOMConversionMap | null {
    return {
      iframe: (domNode: HTMLElement) => {
        if (!domNode.hasAttribute('data-lexical-website')) {
          return null;
        }
        return {
          conversion: $convertWebsiteElement,
          priority: 1,
        };
      },
    };
  }

  updateDOM(): false {
    return false;
  }

  getUrl(): string {
    return this.__url;
  }

  getWidth(): Dimension {
    return this.__width;
  }

  getHeight(): Dimension {
    return this.__height;
  }

  setWidthAndHeight(width: Dimension, height: Dimension): void {
    const writable = this.getWritable();
    writable.__width = width;
    writable.__height = height;
  }

  getTextContent(
    _includeInert?: boolean | undefined,
    _includeDirectionless?: false | undefined,
  ): string {
    return this.__url;
  }

  decorate(_editor: LexicalEditor, config: EditorConfig): JSX.Element {
    const embedBlockTheme = config.theme.embedBlock || {};
    const className = {
      base: embedBlockTheme.base || '',
      focus: embedBlockTheme.focus || '',
    };
    return (
      <WebsiteComponent
        className={className}
        format={this.__format}
        height={this.__height}
        nodeKey={this.getKey()}
        url={this.__url}
        width={this.__width}
      />
    );
  }
}

export function $createWebsiteNode(
  url: string,
  width: Dimension = 'inherit',
  height: Dimension = 'inherit',
): WebsiteNode {
  return new WebsiteNode(url, width, height);
}

export function $isWebsiteNode(
  node: WebsiteNode | LexicalNode | null | undefined,
): node is WebsiteNode {
  return node instanceof WebsiteNode;
}
