function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function escapeStyleText(value: string): string {
  return value.replace(/<\/style/gi, '<\\/style');
}

function dataAttributeName(datasetKey: string): string {
  return `data-${datasetKey.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`)}`;
}

function getLightPrintBodyClassName(bodyClassName = ''): string {
  const classes = new Set(bodyClassName.split(/\s+/).filter(Boolean));

  classes.delete(DARK_THEME_CLASS);
  classes.add(LIGHT_THEME_CLASS);

  return Array.from(classes).join(' ');
}

function getLightPrintBodyDataset(
  bodyDataset?: Record<string, string>,
): Record<string, string> {
  return { ...bodyDataset, bsTheme: 'light' };
}

function createBodyAttributes({
  bodyClassName,
  bodyDataset,
  bodyStyle,
}: PrintDocumentOptions): string {
  const attributes: string[] = [];
  const lightBodyClassName = getLightPrintBodyClassName(bodyClassName);
  const lightBodyDataset = getLightPrintBodyDataset(bodyDataset);

  attributes.push(`class="${escapeHtml(lightBodyClassName)}"`);

  if (bodyStyle) {
    attributes.push(`style="${escapeHtml(bodyStyle)}"`);
  }

  for (const [key, value] of Object.entries(lightBodyDataset)) {
    attributes.push(`${dataAttributeName(key)}="${escapeHtml(value)}"`);
  }

  return attributes.length > 0 ? ` ${attributes.join(' ')}` : '';
}

function getDocumentStyles(): string {
  const styles: string[] = [];

  for (const styleSheet of Array.from(document.styleSheets)) {
    try {
      styles.push(
        Array.from(styleSheet.cssRules)
          .map((rule) => rule.cssText)
          .join('\n'),
      );
    } catch {
      if (styleSheet.href) {
        styles.push(`@import url("${styleSheet.href.replace(/"/g, '\\"')}");`);
      }
    }
  }

  return styles.filter(Boolean).join('\n');
}

function getPrintBodyStyle(editor: LexicalEditor): string {
  const paperWidth = document.body.style.getPropertyValue(
    '--playground-paper-width',
  );
  const paperHeight = document.body.style.getPropertyValue(
    '--playground-paper-height',
  );
  const rootElement = editor.getRootElement();
  const paperPadding = rootElement
    ? window.getComputedStyle(rootElement).padding
    : '';
  const declarations: string[] = [];

  if (paperWidth) {
    declarations.push(`--playground-paper-width: ${paperWidth}`);
  }

  if (paperHeight) {
    declarations.push(`--playground-paper-height: ${paperHeight}`);
  }

  if (paperPadding) {
    declarations.push(`--playground-paper-padding: ${paperPadding}`);
  }

  return declarations.length > 0 ? `${declarations.join('; ')};` : '';
}

function getPrintBodyDataset(): Record<string, string> {
  const dataset: Record<string, string> = {};

  for (const [key, value] of Object.entries(document.body.dataset)) {
    if (value !== undefined) {
      dataset[key] = value;
    }
  }

  return getLightPrintBodyDataset(dataset);
}

function preparePrintableClone(element: HTMLElement): void {
  element.querySelectorAll('[contenteditable]').forEach((contentEditable) => {
    contentEditable.removeAttribute('contenteditable');
  });

  element.querySelectorAll('[spellcheck]').forEach((spellcheckElement) => {
    spellcheckElement.removeAttribute('spellcheck');
  });
}

function getVisibleEditorHtml(editor: LexicalEditor): string | null {
  const rootElement = editor.getRootElement();

  if (rootElement === null) {
    return null;
  }

  const printableElement =
    rootElement.closest<HTMLElement>('.editor-scroller') ?? rootElement;
  const clone = printableElement.cloneNode(true) as HTMLElement;

  preparePrintableClone(clone);

  if (clone.classList.contains('editor-scroller')) {
    return clone.outerHTML;
  }

  return `<div class="editor-scroller"><div class="editor">${clone.outerHTML}</div></div>`;
}

export function createPrintDocumentHtml(
  editorHtml: string,
  pageSize: PageSizeKey = 'web',
  options: PrintDocumentOptions = {},
): string {
  const paperPageSize = getPaperPageSize(pageSize);
  const pageRule = paperPageSize
    ? `size: ${paperPageSize.cssSize}; margin: 0;`
    : `margin: ${DEFAULT_PAPER_BORDER_GAP};`;
  const paperPaddingRule = paperPageSize
    ? `\n    .print-document .ContentEditable__root { padding: var(--playground-paper-padding, ${DEFAULT_PAPER_BORDER_GAP}) !important; }`
    : '';
  const documentStyles = options.documentStyles
    ? `\n  <style>\n${escapeStyleText(options.documentStyles)}\n  </style>`
    : '';
  const base = options.baseHref
    ? `\n  <base href="${escapeHtml(options.baseHref)}">`
    : '';
  const bodyAttributes = createBodyAttributes(options);

  return `<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <title>Print document</title>
  ${base}
  ${documentStyles}
  <style>
    @page { ${pageRule} }
${PRINT_LAYOUT_CSS}
${paperPaddingRule}
  </style>
</head>
<body${bodyAttributes}>
<main class="print-document">
${editorHtml}
</main>
</body>
</html>`;
}

export function printEditorState(
  editor: LexicalEditor,
  pageSize: PageSizeKey = 'web',
): void {
  const editorHtml =
    getVisibleEditorHtml(editor) ??
    `<div class="editor-scroller"><div class="editor"><div class="ContentEditable__root">${editor
      .getEditorState()
      .read(() => $generateHtmlFromNodes(editor, null))}</div></div></div>`;
  const printFrame = document.createElement('iframe');

  printFrame.title = 'Print editor document';
  printFrame.setAttribute('aria-hidden', 'true');
  printFrame.style.border = '0';
  printFrame.style.bottom = '0';
  printFrame.style.height = '0';
  printFrame.style.position = 'fixed';
  printFrame.style.right = '0';
  printFrame.style.width = '0';

  printFrame.addEventListener(
    'load',
    () => {
      const printWindow = printFrame.contentWindow;

      if (printWindow === null) {
        printFrame.remove();
        return;
      }

      let hasCleanedUp = false;
      const cleanup = () => {
        if (hasCleanedUp) {
          return;
        }
        hasCleanedUp = true;
        printWindow.removeEventListener('afterprint', cleanup);
        printFrame.remove();
      };

      printWindow.addEventListener('afterprint', cleanup);
      printWindow.focus();
      printWindow.print();
      window.setTimeout(cleanup, PRINT_FRAME_REMOVAL_DELAY_MS);
    },
    { once: true },
  );

  printFrame.srcdoc = createPrintDocumentHtml(editorHtml, pageSize, {
    baseHref: document.baseURI,
    bodyClassName: getLightPrintBodyClassName(document.body.className),
    bodyDataset: getPrintBodyDataset(),
    bodyStyle: getPrintBodyStyle(editor),
    documentStyles: getDocumentStyles(),
  });
  document.body.appendChild(printFrame);
}
