import type { JSX } from 'react';

import { useMemo } from 'react';
import * as React from 'react';

import { dispatchOpenMentionBibleVerseAdvancedPanelEvent } from '../MentionBibleVersesPlugin/openBibleVerseAdvancedPanelEvent';
import locationsMapData from '../MentionLocationsPlugin/locationsMap.json';
import { dispatchOpenMentionLocationAdvancedPanelEvent } from '../MentionLocationsPlugin/openLocationAdvancedPanelEvent';
import namesMapData from '../MentionNamePlugin/namesMap.json';
import { dispatchOpenMentionPersonAdvancedPanelEvent } from '../MentionNamePlugin/openPersonAdvancedPanelEvent';

function getRecordValues(value: unknown): Array<unknown> {
  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'object' && value !== null) {
    return Object.values(value);
  }

  return [];
}

function buildReferenceNameById(entries: Array<unknown>): Map<string, string> {
  return entries.reduce<Map<string, string>>((results, entry) => {
    if (typeof entry !== 'object' || entry === null) {
      return results;
    }

    const candidate = entry as { id?: unknown; name?: unknown };
    const id = typeof candidate.id === 'string' ? candidate.id.trim() : '';
    const name =
      typeof candidate.name === 'string' ? candidate.name.trim() : '';

    if (id === '' || name === '') {
      return results;
    }

    results.set(id, name);
    return results;
  }, new Map());
}

const referenceNameById = buildReferenceNameById(
  getRecordValues((namesMapData as { namesMap?: unknown }).namesMap),
);

const locationsMapJson = locationsMapData as {
  locationsMap?: unknown;
  namesMap?: unknown;
};

const referenceLocationNameById = buildReferenceNameById(
  getRecordValues(locationsMapJson.locationsMap ?? locationsMapJson.namesMap),
);

// Inline reference tokens embedded in titles/descriptions, e.g.
// "[Jesus](name-id://<id>)", "[Gethsemane](location-id://<id>)", or
// "[John 3:16](verse-key://<verse>)". While typing, only the readable label
// should be shown, not the tokenizing template.
const MENTION_REFERENCE_TOKEN_REGEX =
  /\[([^\]]+)\]\((?:name-id|location-id|verse-key):\/\/[^)]*\)/g;

export function getPlainReferenceText(value: string): string {
  return value.replace(MENTION_REFERENCE_TOKEN_REGEX, '$1');
}

// Same tokens as MENTION_REFERENCE_TOKEN_REGEX, but with the scheme and target
// captured so each reference can be turned into a clickable button that opens
// the corresponding name, location, or verse panel.
const MENTION_REFERENCE_TOKEN_PARSE_REGEX =
  /\[([^\]]+)\]\((name-id|location-id|verse-key):\/\/([^)]*)\)/g;

type MentionReferenceLinkSegment =
  | { kind: 'name'; label: string; target: string }
  | { kind: 'location'; label: string; target: string }
  | { kind: 'verse'; label: string; target: string };

type MentionReferenceSegment =
  { kind: 'text'; text: string } | MentionReferenceLinkSegment;

function parseMentionReferenceSegments(
  value: string,
): Array<MentionReferenceSegment> {
  const segments: Array<MentionReferenceSegment> = [];
  const regex = new RegExp(MENTION_REFERENCE_TOKEN_PARSE_REGEX);
  let lastIndex = 0;
  let match: RegExpExecArray | null;

  while ((match = regex.exec(value)) !== null) {
    if (match.index > lastIndex) {
      segments.push({
        kind: 'text',
        text: value.slice(lastIndex, match.index),
      });
    }

    const label = match[1];
    const scheme = match[2];
    const target = match[3].trim();

    if (target === '') {
      segments.push({ kind: 'text', text: label });
    } else if (scheme === 'name-id') {
      segments.push({ kind: 'name', label, target });
    } else if (scheme === 'location-id') {
      segments.push({ kind: 'location', label, target });
    } else {
      segments.push({ kind: 'verse', label, target });
    }

    lastIndex = regex.lastIndex;
  }

  if (lastIndex < value.length) {
    segments.push({ kind: 'text', text: value.slice(lastIndex) });
  }

  return segments;
}

function openMentionReferenceSegment(
  segment: MentionReferenceLinkSegment,
  anchorElement: HTMLElement,
): void {
  if (segment.kind === 'name') {
    dispatchOpenMentionPersonAdvancedPanelEvent({
      anchorElement,
      id: segment.target,
      name: referenceNameById.get(segment.target) ?? segment.label,
    });
    return;
  }

  if (segment.kind === 'location') {
    dispatchOpenMentionLocationAdvancedPanelEvent({
      anchorElement,
      id: segment.target,
      name: referenceLocationNameById.get(segment.target) ?? segment.label,
    });
    return;
  }

  dispatchOpenMentionBibleVerseAdvancedPanelEvent({
    anchorElement,
    shortVerse: segment.target,
  });
}

// Renders a title/description string, turning inline reference tokens into
// clickable buttons that open the referenced name, location, or verse panel.
export default function MentionReferenceText({
  value,
}: {
  value: string;
}): JSX.Element {
  const segments = useMemo(() => parseMentionReferenceSegments(value), [value]);

  return (
    <>
      {segments.map((segment, index) => {
        if (segment.kind === 'text') {
          return <React.Fragment key={index}>{segment.text}</React.Fragment>;
        }

        return (
          <button
            className={`mention-reference-link mention-reference-link--${segment.kind}`}
            key={index}
            type="button"
            onClick={(event) => {
              event.preventDefault();
              event.stopPropagation();
              openMentionReferenceSegment(segment, event.currentTarget);
            }}
          >
            {segment.label}
          </button>
        );
      })}
    </>
  );
}
