export type BibleNoteStorageManager = {
  setSetting(key: string, value: unknown): Promise<void>;
  getSetting<T = unknown>(key: string): Promise<T | null>;
  deleteSetting(key: string): Promise<void>;
};

type BibleNoteStorage = Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>;

export const BIBLE_NOTE_STORAGE_MANAGER_KEYS = [
  'lexical-playground-settings',
  'lexical-playground-editor-state',
  'lexical-playground-comments',
  'lexical-playground-comments-panel-open',
  'lexical-playground-block-text-links',
  'lexical-playground-read-only-mode',
  'lexical-playground-insert-character-picker',
  'lexical-playground-editor-zoom-percent',
] as const;

let activeStorageManager: BibleNoteStorageManager | null = null;
let activeStorageGeneration = 0;
const managedStorageValues = new Map<string, string>();

const managedStorage: BibleNoteStorage = {
  getItem(key) {
    return managedStorageValues.get(key) ?? null;
  },
  removeItem(key) {
    managedStorageValues.delete(key);

    const storageManager = activeStorageManager;

    if (storageManager !== null) {
      void storageManager.deleteSetting(key).catch(() => {});
    }
  },
  setItem(key, value) {
    managedStorageValues.set(key, value);

    const storageManager = activeStorageManager;

    if (storageManager !== null) {
      void storageManager.setSetting(key, value).catch(() => {});
    }
  },
};

export function configureBibleNoteStorageManager(
  storageManager?: BibleNoteStorageManager,
): void {
  if (activeStorageManager === (storageManager ?? null)) {
    return;
  }

  activeStorageManager = storageManager ?? null;
  activeStorageGeneration += 1;
  managedStorageValues.clear();
}

export async function hydrateBibleNoteStorageManager(
  keys: ReadonlyArray<string>,
): Promise<void> {
  const storageManager = activeStorageManager;

  if (storageManager === null) {
    return;
  }

  const storageGeneration = activeStorageGeneration;
  const storedValues = await Promise.all(
    keys.map(async (key) => {
      try {
        return [
          key,
          serializeStorageManagerValue(await storageManager.getSetting(key)),
        ] as const;
      } catch {
        return [key, null] as const;
      }
    }),
  );

  if (
    activeStorageManager !== storageManager ||
    activeStorageGeneration !== storageGeneration
  ) {
    return;
  }

  managedStorageValues.clear();

  for (const [key, value] of storedValues) {
    if (value !== null) {
      managedStorageValues.set(key, value);
    }
  }
}

export function getBibleNoteStorage(): BibleNoteStorage | null {
  if (activeStorageManager !== null) {
    return managedStorage;
  }

  return getBrowserStorage();
}

export function createBrowserStorageManager(): BibleNoteStorageManager {
  return {
    async deleteSetting(key) {
      getBrowserStorage()?.removeItem(key);
    },
    async getSetting<T = unknown>(key: string): Promise<T | null> {
      return (getBrowserStorage()?.getItem(key) ?? null) as T | null;
    },
    async setSetting(key, value) {
      const serializedValue = serializeStorageManagerValue(value);

      if (serializedValue === null) {
        return;
      }

      getBrowserStorage()?.setItem(key, serializedValue);
    },
  };
}

function serializeStorageManagerValue(value: unknown): string | null {
  if (value === null || value === undefined) {
    return null;
  }

  if (typeof value === 'string') {
    return value;
  }

  try {
    return JSON.stringify(value) ?? null;
  } catch {
    return null;
  }
}

function getBrowserStorage(): BibleNoteStorage | null {
  if (typeof window === 'undefined') {
    return null;
  }

  try {
    return window.localStorage;
  } catch {
    return null;
  }
}
