import { $dfsIterator } from '@lexical/utils';
import {
  $createRangeSelection,
  $getNodeByKey,
  $getSelection,
  $isDecoratorNode,
  $isElementNode,
  $isLineBreakNode,
  $isRangeSelection,
  $isTextNode,
  $setSelection,
  type LexicalEditor,
} from 'lexical';

import {
  BLOCK_SEPARATOR,
  type SearchSegment,
  type SearchSlice,
} from './findMatches';

export type SearchIndex = {
  // Every searchable text run in the document, concatenated.
  text: string;
  segments: SearchSegment[];
};

/**
 * Flattens the document into one searchable string. Anything that visually
 * breaks a run of text — a new block, a line break, a decorator (image, poll,
 * drawing) — contributes a separator so a query cannot match across it.
 *
 * Must be called from inside `editorState.read`.
 */
export function $buildSearchIndex(): SearchIndex {
  const segments: SearchSegment[] = [];
  let text = '';
  let needsSeparator = false;

  for (const { node } of $dfsIterator()) {
    if ($isTextNode(node)) {
      const nodeText = node.getTextContent();

      if (nodeText === '') {
        continue;
      }

      if (needsSeparator && text !== '') {
        text += BLOCK_SEPARATOR;
      }

      needsSeparator = false;
      segments.push({
        key: node.getKey(),
        length: nodeText.length,
        start: text.length,
      });
      text += nodeText;
    } else if (
      $isLineBreakNode(node) ||
      $isDecoratorNode(node) ||
      ($isElementNode(node) && !node.isInline())
    ) {
      needsSeparator = true;
    }
  }

  return { segments, text };
}

/**
 * Where the caret sits inside the search index, or `null` when the selection
 * is not in a text node that the index covers.
 *
 * Must be called from inside `editorState.read`.
 */
export function $getCaretOffset(
  segments: ReadonlyArray<SearchSegment>,
): number | null {
  const selection = $getSelection();

  if (!$isRangeSelection(selection) || selection.anchor.type !== 'text') {
    return null;
  }

  const { key, offset } = selection.anchor;
  const segment = segments.find((candidate) => candidate.key === key);

  return segment === undefined ? null : segment.start + offset;
}

function collectDomTextNodes(element: HTMLElement): Text[] {
  const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT);
  const textNodes: Text[] = [];

  for (
    let current = walker.nextNode();
    current !== null;
    current = walker.nextNode()
  ) {
    textNodes.push(current as Text);
  }

  return textNodes;
}

function createRangeForSlice(
  editor: LexicalEditor,
  slice: SearchSlice,
): Range | null {
  const element = editor.getElementByKey(slice.key);

  if (element === null) {
    return null;
  }

  // Lexical renders a text node as an element wrapping a single DOM text node,
  // but formatting can nest it (`<strong><em>…`), so walk to find it.
  let consumed = 0;
  let range: Range | null = null;

  for (const textNode of collectDomTextNodes(element)) {
    const nodeEnd = consumed + textNode.data.length;

    if (range === null && slice.startOffset < nodeEnd) {
      range = document.createRange();
      range.setStart(textNode, slice.startOffset - consumed);
    }

    if (range !== null && slice.endOffset <= nodeEnd) {
      range.setEnd(textNode, slice.endOffset - consumed);

      return range;
    }

    consumed = nodeEnd;
  }

  return null;
}

/**
 * The live DOM ranges for one match. A match spanning several text nodes needs
 * a range per node, since a highlight range cannot cross element boundaries
 * cleanly.
 */
export function createRangesForSlices(
  editor: LexicalEditor,
  slices: ReadonlyArray<SearchSlice>,
): Range[] {
  const ranges: Range[] = [];

  for (const slice of slices) {
    const range = createRangeForSlice(editor, slice);

    if (range !== null) {
      ranges.push(range);
    }
  }

  return ranges;
}

/**
 * Selects a match in the editor, so closing the find bar leaves the caret on
 * the text the user was looking for.
 *
 * Must be called from inside `editor.update`.
 */
export function $selectSlices(slices: ReadonlyArray<SearchSlice>): void {
  if (slices.length === 0) {
    return;
  }

  const first = slices[0];
  const last = slices[slices.length - 1];

  if (
    !$isTextNode($getNodeByKey(first.key)) ||
    !$isTextNode($getNodeByKey(last.key))
  ) {
    return;
  }

  const selection = $createRangeSelection();

  selection.anchor.set(first.key, first.startOffset, 'text');
  selection.focus.set(last.key, last.endOffset, 'text');
  $setSelection(selection);
}
