import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { useEffect } from 'react';

import { useSettings } from '../../context/SettingsContext';

const DEFAULT_PAGE_COUNT = 1;
const PX_PER_INCH = 96;

function cssLengthToPx(value: string): number | null {
  const trimmedValue = value.trim();

  if (trimmedValue.endsWith('px')) {
    return Number.parseFloat(trimmedValue);
  }

  if (trimmedValue.endsWith('in')) {
    return Number.parseFloat(trimmedValue) * PX_PER_INCH;
  }

  return null;
}

function getPaperPageHeight(rootElement: HTMLElement): number | null {
  const pageHeight = getComputedStyle(rootElement)
    .getPropertyValue('--playground-paper-height')
    .trim();

  return cssLengthToPx(pageHeight);
}

function getContentHeight(rootElement: HTMLElement): number {
  const rootRect = rootElement.getBoundingClientRect();
  const rootStyles = getComputedStyle(rootElement);
  const paddingTop = Number.parseFloat(rootStyles.paddingTop) || 0;
  const paddingBottom = Number.parseFloat(rootStyles.paddingBottom) || 0;
  let contentBottom = paddingTop;

  for (const child of Array.from(rootElement.children)) {
    contentBottom = Math.max(
      contentBottom,
      child.getBoundingClientRect().bottom - rootRect.top,
    );
  }

  return contentBottom + paddingBottom;
}

function updatePaperPageCount(rootElement: HTMLElement): void {
  const pageHeight = getPaperPageHeight(rootElement);

  if (pageHeight === null || pageHeight <= 0) {
    return;
  }

  const pageCount = Math.max(
    DEFAULT_PAGE_COUNT,
    Math.ceil(getContentHeight(rootElement) / pageHeight),
  );

  rootElement.style.setProperty(
    '--playground-paper-page-count',
    String(pageCount),
  );
  rootElement.style.setProperty(
    '--playground-paper-total-height',
    `${pageCount * pageHeight}px`,
  );
}

function resetPaperPageCount(rootElement: HTMLElement | null): void {
  if (rootElement === null) {
    return;
  }

  rootElement.style.removeProperty('--playground-paper-page-count');
  rootElement.style.removeProperty('--playground-paper-total-height');
}

export default function PageSizePreviewPlugin(): null {
  const [editor] = useLexicalComposerContext();
  const {
    settings: { pageSize },
  } = useSettings();

  useEffect(() => {
    let rootElement = editor.getRootElement();
    let animationFrame: number | null = null;
    let resizeObserver: ResizeObserver | null = null;

    const cancelQueuedUpdate = () => {
      if (animationFrame !== null) {
        window.cancelAnimationFrame(animationFrame);
        animationFrame = null;
      }
    };

    const queueUpdate = () => {
      cancelQueuedUpdate();

      animationFrame = window.requestAnimationFrame(() => {
        animationFrame = null;

        if (pageSize === 'web') {
          resetPaperPageCount(rootElement);
          return;
        }

        if (rootElement !== null) {
          updatePaperPageCount(rootElement);
        }
      });
    };

    const observeRootElement = (nextRootElement: HTMLElement | null) => {
      resizeObserver?.disconnect();
      rootElement = nextRootElement;

      if (
        rootElement !== null &&
        pageSize !== 'web' &&
        typeof ResizeObserver !== 'undefined'
      ) {
        resizeObserver = new ResizeObserver(queueUpdate);
        resizeObserver.observe(rootElement);
      } else {
        resizeObserver = null;
      }

      queueUpdate();
    };

    observeRootElement(rootElement);

    const unregisterRootListener =
      editor.registerRootListener(observeRootElement);
    const unregisterUpdateListener = editor.registerUpdateListener(queueUpdate);

    window.addEventListener('resize', queueUpdate);

    return () => {
      cancelQueuedUpdate();
      resizeObserver?.disconnect();
      unregisterRootListener();
      unregisterUpdateListener();
      window.removeEventListener('resize', queueUpdate);
      resetPaperPageCount(rootElement);
    };
  }, [editor, pageSize]);

  return null;
}
