export type InsertMediaPayload = Readonly<MediaPayload>;

export const INSERT_MEDIA_COMMAND: LexicalCommand<InsertMediaPayload> =
  createCommand('INSERT_MEDIA_COMMAND');

const MEDIA_FILE_ACCEPT = 'image/*,video/*,audio/*,application/pdf,.pdf';
const VIDEO_FILE_EXTENSIONS = ['.mp4', '.webm', '.ogv', '.mov', '.m4v'];
const AUDIO_FILE_EXTENSIONS = [
  '.aac',
  '.flac',
  '.m4a',
  '.mp3',
  '.oga',
  '.ogg',
  '.opus',
  '.wav',
  '.weba',
];

function getMediaTypeFromSource(src: string): MediaType {
  const normalizedSrc = src.toLowerCase().split(/[?#]/)[0];
  if (
    normalizedSrc.startsWith('data:application/pdf') ||
    normalizedSrc.endsWith('.pdf')
  ) {
    return 'pdf';
  }
  if (
    normalizedSrc.startsWith('data:video/') ||
    VIDEO_FILE_EXTENSIONS.some((extension) => normalizedSrc.endsWith(extension))
  ) {
    return 'video';
  }
  if (
    normalizedSrc.startsWith('data:audio/') ||
    AUDIO_FILE_EXTENSIONS.some((extension) => normalizedSrc.endsWith(extension))
  ) {
    return 'audio';
  }
  return 'image';
}

function getMediaTypeFromFile(file: File): MediaType {
  if (
    file.type === 'application/pdf' ||
    file.name.toLowerCase().endsWith('.pdf')
  ) {
    return 'pdf';
  }
  if (
    file.type.startsWith('video/') ||
    VIDEO_FILE_EXTENSIONS.some((extension) =>
      file.name.toLowerCase().endsWith(extension),
    )
  ) {
    return 'video';
  }
  if (
    file.type.startsWith('audio/') ||
    AUDIO_FILE_EXTENSIONS.some((extension) =>
      file.name.toLowerCase().endsWith(extension),
    )
  ) {
    return 'audio';
  }
  return 'image';
}

function createFilePreviewSrc(file: File): string | undefined {
  return typeof URL.createObjectURL === 'function'
    ? URL.createObjectURL(file)
    : undefined;
}

function toInsertMediaPayload(
  altText: string,
  src: string,
  mediaType: MediaType,
  previewSrc?: string,
): InsertMediaPayload {
  if (mediaType === 'image') {
    return { altText, src };
  }

  return previewSrc
    ? { altText, mediaType, previewSrc, src }
    : { altText, mediaType, src };
}

export function InsertMediaUriDialogBody({
  onClick,
}: {
  onClick: (payload: InsertMediaPayload) => void;
}) {
  const [src, setSrc] = useState('');
  const [altText, setAltText] = useState('');

  const isDisabled = src === '';

  return (
    <>
      <TextInput
        label="Media URL/Path"
        placeholder="i.e. https://example.com/media.mp3"
        onChange={setSrc}
        value={src}
        data-test-id="media-modal-url-input"
      />
      <TextInput
        label="Alt Text / Title"
        placeholder="Descriptive label"
        onChange={setAltText}
        value={altText}
        data-test-id="media-modal-alt-text-input"
      />
      <DialogActions>
        <Button
          data-test-id="media-modal-confirm-btn"
          disabled={isDisabled}
          onClick={() =>
            onClick(
              toInsertMediaPayload(altText, src, getMediaTypeFromSource(src)),
            )
          }
        >
          Confirm
        </Button>
      </DialogActions>
    </>
  );
}

export function InsertMediaUploadedDialogBody({
  onClick,
  resolveFilePath,
}: {
  onClick: (payload: InsertMediaPayload) => void;
  resolveFilePath?: FilePathResolver;
}) {
  const [src, setSrc] = useState('');
  const [altText, setAltText] = useState('');
  const [mediaType, setMediaType] = useState<MediaType>('image');
  const [previewSrc, setPreviewSrc] = useState<string | undefined>();
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  const isDisabled = src === '';

  const loadMedia = (files: FileList | null) => {
    const file = files?.[0];
    if (!file) {
      setSrc('');
      setPreviewSrc(undefined);
      setSelectedFile(null);
      return;
    }
    const nextMediaType = getMediaTypeFromFile(file);
    setMediaType(nextMediaType);
    setAltText((currentAltText) => currentAltText || file.name);

    const loadFallbackMedia = () => {
      if (nextMediaType !== 'image') {
        setSrc(getFallbackFilePath(file));
        setPreviewSrc(createFilePreviewSrc(file));
        setSelectedFile(file);
        return;
      }

      setPreviewSrc(undefined);
      setSelectedFile(null);

      const reader = new FileReader();
      reader.onload = function () {
        if (typeof reader.result === 'string') {
          setSrc(reader.result);
        }
        return '';
      };
      reader.readAsDataURL(file);
    };

    if (resolveFilePath === undefined) {
      loadFallbackMedia();
      return;
    }

    void (async () => {
      const resolvedFilePath = await resolveMediaFilePath(
        resolveFilePath,
        file,
        'file-input',
      );

      if (resolvedFilePath !== null) {
        setSrc(resolvedFilePath);
        setPreviewSrc(
          nextMediaType === 'image' ? undefined : createFilePreviewSrc(file),
        );
        setSelectedFile(nextMediaType === 'image' ? null : file);
        return;
      }

      loadFallbackMedia();
    })();
  };

  const insertUploadedMedia = async () => {
    if (mediaType !== 'image' && selectedFile !== null) {
      await storeMediaFile(src, selectedFile);
    }

    onClick(toInsertMediaPayload(altText, src, mediaType, previewSrc));
  };

  return (
    <>
      <FileInput
        label="Media File"
        onChange={loadMedia}
        accept={MEDIA_FILE_ACCEPT}
        data-test-id="media-modal-file-upload"
      />
      {mediaType !== 'image' ? (
        <TextInput
          label="File Path"
          placeholder="Path to the selected media file"
          onChange={setSrc}
          value={src}
          data-test-id="media-modal-source-input"
        />
      ) : null}
      <TextInput
        label="Alt Text / Title"
        placeholder="Descriptive label"
        onChange={setAltText}
        value={altText}
        data-test-id="media-modal-alt-text-input"
      />
      <DialogActions>
        <Button
          data-test-id="media-modal-file-upload-btn"
          disabled={isDisabled}
          onClick={() => void insertUploadedMedia()}
        >
          Confirm
        </Button>
      </DialogActions>
    </>
  );
}

export function InsertMediaDialog({
  activeEditor,
  onClose,
  resolveFilePath,
}: {
  activeEditor: LexicalEditor;
  onClose: () => void;
  resolveFilePath?: FilePathResolver;
}): JSX.Element {
  const [mode, setMode] = useState<null | 'url' | 'file'>(null);

  const onClick = (payload: InsertMediaPayload) => {
    activeEditor.dispatchCommand(INSERT_MEDIA_COMMAND, payload);
    onClose();
  };

  return (
    <>
      {!mode && (
        <DialogButtonsList>
          <Button
            data-test-id="media-modal-option-url"
            onClick={() => setMode('url')}
          >
            URL
          </Button>
          <Button
            data-test-id="media-modal-option-file"
            onClick={() => setMode('file')}
          >
            File
          </Button>
        </DialogButtonsList>
      )}
      {mode === 'url' && <InsertMediaUriDialogBody onClick={onClick} />}
      {mode === 'file' && (
        <InsertMediaUploadedDialogBody
          onClick={onClick}
          resolveFilePath={resolveFilePath}
        />
      )}
    </>
  );
}

export default function MediaPlugin({
  captionsEnabled,
}: {
  captionsEnabled?: boolean;
}): JSX.Element | null {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    if (!editor.hasNodes([MediaNode])) {
      throw new Error('MediaPlugin: MediaNode not registered on editor');
    }

    return mergeRegister(
      editor.registerCommand<InsertMediaPayload>(
        INSERT_MEDIA_COMMAND,
        (payload) => {
          const mediaNode = $createMediaNode(payload);
          $insertNodes([mediaNode]);
          if ($isRootOrShadowRoot(mediaNode.getParentOrThrow())) {
            $wrapNodeInElement(mediaNode, $createParagraphNode).selectEnd();
          }

          return true;
        },
        COMMAND_PRIORITY_EDITOR,
      ),
      editor.registerCommand<DragEvent>(
        DRAGSTART_COMMAND,
        (event) => {
          return $onDragStart(event);
        },
        COMMAND_PRIORITY_HIGH,
      ),
      editor.registerCommand<DragEvent>(
        DRAGOVER_COMMAND,
        (event) => {
          return $onDragover(event);
        },
        COMMAND_PRIORITY_LOW,
      ),
      editor.registerCommand<DragEvent>(
        DROP_COMMAND,
        (event) => {
          return $onDrop(event, editor);
        },
        COMMAND_PRIORITY_HIGH,
      ),
    );
  }, [captionsEnabled, editor]);

  return null;
}

const TRANSPARENT_IMAGE =
  'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
const img = document.createElement('img');
img.src = TRANSPARENT_IMAGE;

function $onDragStart(event: DragEvent): boolean {
  const node = $getMediaNodeInSelection();
  if (!node) {
    return false;
  }
  const dataTransfer = event.dataTransfer;
  if (!dataTransfer) {
    return false;
  }
  dataTransfer.setData('text/plain', '_');
  dataTransfer.setDragImage(img, 0, 0);
  dataTransfer.setData(
    'application/x-lexical-drag',
    JSON.stringify({
      data: {
        altText: node.__altText,
        caption: node.__caption,
        height: node.__height,
        key: node.getKey(),
        maxWidth: node.__maxWidth,
        mediaType: node.__mediaType,
        previewSrc: node.__previewSrc,
        showCaption: node.__showCaption,
        src: node.__src,
        width: node.__width,
      },
      type: 'media',
    }),
  );

  return true;
}

function $onDragover(event: DragEvent): boolean {
  const node = $getMediaNodeInSelection();
  if (!node) {
    return false;
  }
  if (!canDropMedia(event)) {
    event.preventDefault();
  }
  return false;
}

function $onDrop(event: DragEvent, editor: LexicalEditor): boolean {
  const node = $getMediaNodeInSelection();
  if (!node) {
    return false;
  }
  const data = getDragMediaData(event);
  if (!data) {
    return false;
  }
  const existingLink = $findMatchingParent(
    node,
    (parent): parent is LinkNode =>
      !$isAutoLinkNode(parent) && $isLinkNode(parent),
  );
  event.preventDefault();
  if (canDropMedia(event)) {
    const range = getDragSelection(event);
    node.remove();
    const rangeSelection = $createRangeSelection();
    if (range !== null && range !== undefined) {
      rangeSelection.applyDOMRange(range);
    }
    $setSelection(rangeSelection);
    editor.dispatchCommand(INSERT_MEDIA_COMMAND, data);
    if (existingLink) {
      editor.dispatchCommand(TOGGLE_LINK_COMMAND, existingLink.getURL());
    }
  }
  return true;
}

function $getMediaNodeInSelection(): MediaNode | null {
  const selection = $getSelection();
  if (!$isNodeSelection(selection)) {
    return null;
  }
  const nodes = selection.getNodes();
  const node = nodes[0];
  return $isMediaNode(node) ? node : null;
}

function getDragMediaData(event: DragEvent): null | InsertMediaPayload {
  const dragData = event.dataTransfer?.getData('application/x-lexical-drag');
  if (!dragData) {
    return null;
  }
  const { type, data } = JSON.parse(dragData);
  if (type !== 'media') {
    return null;
  }

  return data;
}

declare global {
  interface DragEvent {
    rangeOffset?: number;
    rangeParent?: Node;
  }
}

function canDropMedia(event: DragEvent): boolean {
  const target = event.target;
  return !!(
    isHTMLElement(target) &&
    !target.closest('code, span.editor-media') &&
    isHTMLElement(target.parentElement) &&
    target.parentElement.closest('div.ContentEditable__root')
  );
}

function getDragSelection(event: DragEvent): Range | null | undefined {
  let range;
  const domSelection = getDOMSelectionFromTarget(event.target);
  if (document.caretRangeFromPoint) {
    range = document.caretRangeFromPoint(event.clientX, event.clientY);
  } else if (event.rangeParent && domSelection !== null) {
    domSelection.collapse(event.rangeParent, event.rangeOffset || 0);
    range = domSelection.getRangeAt(0);
  } else {
    throw Error(`Cannot get the selection when dragging`);
  }

  return range;
}
