import './index.scss';

import type { Dispatch, JSX, SetStateAction } from 'react';
import { useEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';

import locationsMapData from '../MentionLocationsPlugin/locationsMap.json';
import { dispatchOpenMentionLocationAdvancedPanelEvent } from '../MentionLocationsPlugin/openLocationAdvancedPanelEvent';
import namesMapData from '../MentionNamePlugin/namesMap.json';
import {
  getMentionNameTypeIconClass,
  type MentionNameType,
  normalizeMentionNameType,
} from '../MentionNamePlugin/nameTypeIcons';
import { dispatchOpenMentionPersonAdvancedPanelEvent } from '../MentionNamePlugin/openPersonAdvancedPanelEvent';
import { getPlainReferenceText } from '../MentionReferenceText';

type LookupTab = 'name' | 'location';

// How many records are shown per page in each tab's result list.
const PAGE_SIZE = 20;

const LOCATION_ICON_CLASS = 'bi bi-geo-alt-fill icon';

// The sentinel filter value meaning "don't restrict by name type".
const ALL_TYPES = 'all';

// Shown in the (disabled) type filter on the location tab, where it does not
// apply. A distinct value so the select never renders an out-of-range option.
const TYPE_FILTER_NA_VALUE = '__na__';
const TYPE_FILTER_NA_LABEL = '----';

// Human-friendly (plural) labels for each name type, shown in the type filter.
const NAME_TYPE_LABEL: Record<MentionNameType, string> = {
  concept: 'Concepts',
  deity: 'Deities',
  group: 'Groups',
  life: 'Life',
  month: 'Months',
  person: 'People',
  place: 'Places',
  supernatural: 'Supernatural',
  unknown: 'Unknown',
};

// One choice in the name-type filter dropdown: either a concrete name type or
// the "all" sentinel. `count` is the number of records the choice would show
// (ignoring the text query) and drives the ordering of the concrete types.
type LookupTypeOption = {
  value: MentionNameType | typeof ALL_TYPES;
  label: string;
  count: number;
};

type LookupRecord = {
  id: string;
  name: string;
  // Lowercased name, used to rank matches (exact / prefix / contains).
  nameLower: string;
  // Plain-text (reference markup stripped) one-line summary.
  title: string;
  type: string;
  matterRange: number;
  iconClass: string;
  // Lowercased haystack used for substring filtering (name + former name).
  searchText: string;
};

function getTrimmedString(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function getMatterRange(value: unknown): number {
  // Records without a numeric rank sort to the very end (least important).
  return typeof value === 'number' && Number.isFinite(value)
    ? value
    : Number.POSITIVE_INFINITY;
}

function getRecordValues(value: unknown): Array<unknown> {
  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'object' && value !== null) {
    return Object.values(value);
  }

  return [];
}

function buildLookupRecord(
  value: unknown,
  resolveIconClass: (type: string) => string,
): LookupRecord | null {
  if (typeof value !== 'object' || value === null) {
    return null;
  }

  const candidate = value as {
    id?: unknown;
    name?: unknown;
    oldName?: unknown;
    title?: unknown;
    type?: unknown;
    matterRange?: unknown;
  };
  const id = getTrimmedString(candidate.id);
  const name = getTrimmedString(candidate.name);

  if (id === '' || id === 'id' || name === '') {
    return null;
  }

  const oldName = getTrimmedString(candidate.oldName);
  const type = getTrimmedString(candidate.type);

  return {
    id,
    name,
    nameLower: name.toLowerCase(),
    title: getPlainReferenceText(getTrimmedString(candidate.title)),
    type,
    matterRange: getMatterRange(candidate.matterRange),
    iconClass: resolveIconClass(type),
    searchText: `${name} ${oldName}`.toLowerCase(),
  };
}

// Ascending matterRange puts the most important records first (0 is the most
// important on this dataset's scale); ties fall back to alphabetical name.
function compareLookupRecords(a: LookupRecord, b: LookupRecord): number {
  if (a.matterRange !== b.matterRange) {
    return a.matterRange - b.matterRange;
  }

  return a.name.localeCompare(b.name);
}

function buildLookupRecords(
  values: Array<unknown>,
  resolveIconClass: (type: string) => string,
): Array<LookupRecord> {
  return values
    .reduce<Array<LookupRecord>>((results, value) => {
      const record = buildLookupRecord(value, resolveIconClass);

      if (record !== null) {
        results.push(record);
      }

      return results;
    }, [])
    .sort(compareLookupRecords);
}

const nameRecords = buildLookupRecords(
  getRecordValues((namesMapData as { namesMap?: unknown }).namesMap),
  getMentionNameTypeIconClass,
);

const locationRecords = buildLookupRecords(
  getRecordValues(
    (locationsMapData as { locationsMap?: unknown }).locationsMap,
  ),
  () => LOCATION_ICON_CLASS,
);

// Builds the name-type filter choices from the records actually present, so the
// dropdown only ever offers types that would return results. The leading "All
// types" entry is always present; concrete types follow, most common first.
function buildTypeOptions(
  records: Array<LookupRecord>,
): Array<LookupTypeOption> {
  const counts = new Map<MentionNameType, number>();

  for (const record of records) {
    const type = normalizeMentionNameType(record.type);
    counts.set(type, (counts.get(type) ?? 0) + 1);
  }

  const present = Array.from(counts.entries())
    .map(([value, count]) => ({ value, label: NAME_TYPE_LABEL[value], count }))
    .sort((a, b) =>
      a.count !== b.count ? b.count - a.count : a.label.localeCompare(b.label),
    );

  return [
    { value: ALL_TYPES, label: 'All types', count: records.length },
    ...present,
  ];
}

const nameTypeOptions = buildTypeOptions(nameRecords);

// Narrows records to a single name type. The "all" sentinel (and any missing
// filter, as on the location tab) passes every record through unchanged.
function filterRecordsByType(
  records: Array<LookupRecord>,
  typeFilter: string,
): Array<LookupRecord> {
  if (typeFilter === ALL_TYPES) {
    return records;
  }

  return records.filter(
    (record) => normalizeMentionNameType(record.type) === typeFilter,
  );
}

// Ranks how well a record matches the query so better matches sort first.
// Lower is better: exact name, then name prefix, then name substring, then a
// match that only came from the former name (searchText but not the name).
function getMatchRank(record: LookupRecord, normalizedQuery: string): number {
  if (record.nameLower === normalizedQuery) {
    return 0;
  }

  if (record.nameLower.startsWith(normalizedQuery)) {
    return 1;
  }

  if (record.nameLower.includes(normalizedQuery)) {
    return 2;
  }

  return 3;
}

function filterLookupRecords(
  records: Array<LookupRecord>,
  query: string,
): Array<LookupRecord> {
  const normalizedQuery = query.trim().toLowerCase();

  if (normalizedQuery === '') {
    return records;
  }

  const ranked = records.reduce<Array<{ record: LookupRecord; rank: number }>>(
    (results, record) => {
      if (record.searchText.includes(normalizedQuery)) {
        results.push({ record, rank: getMatchRank(record, normalizedQuery) });
      }

      return results;
    },
    [],
  );

  // Array#sort is stable, so within a rank tier records keep their incoming
  // order — which is already matterRange (importance) then alphabetical.
  ranked.sort((a, b) => a.rank - b.rank);

  return ranked.map((entry) => entry.record);
}

function LookupResultItem({
  record,
  onOpen,
}: {
  record: LookupRecord;
  onOpen: (record: LookupRecord, anchorElement: HTMLElement) => void;
}): JSX.Element {
  return (
    <li className="LookupPlugin_Panel_List_Item">
      <button
        className="LookupPlugin_Panel_List_Item_Button"
        type="button"
        title={record.title || record.name}
        onClick={(event) => {
          onOpen(record, event.currentTarget);
        }}
      >
        <i className={record.iconClass} aria-hidden="true" />
        <span className="LookupPlugin_Panel_List_Item_Text">
          <span className="LookupPlugin_Panel_List_Item_Name">
            {record.name}
          </span>
          {record.title ? (
            <span className="LookupPlugin_Panel_List_Item_Title">
              {record.title}
            </span>
          ) : null}
        </span>
      </button>
    </li>
  );
}

// Renders one tab's result list and pagination. The search box and type filter
// live in the shared header above (see LookupPlugin) and are passed down here as
// the `query` / `typeFilter` values used to compute the visible records.
function LookupTabPanel({
  active,
  query,
  records,
  onOpen,
  typeFilter,
}: {
  active: boolean;
  query: string;
  records: Array<LookupRecord>;
  onOpen: (record: LookupRecord, anchorElement: HTMLElement) => void;
  // Omitted on the location tab, which has no type filter (defaults to "all").
  typeFilter?: string;
}): JSX.Element | null {
  const [page, setPage] = useState(1);
  // Draft text of the editable page-number field; committed on Enter/blur.
  const [pageInput, setPageInput] = useState('1');
  // Set when Enter/Escape already handled the value, so the programmatic blur
  // they trigger does not commit the draft a second time (Escape must cancel).
  const skipBlurCommitRef = useRef(false);

  const activeTypeFilter = typeFilter ?? ALL_TYPES;

  const filtered = useMemo(
    () =>
      filterLookupRecords(
        filterRecordsByType(records, activeTypeFilter),
        query,
      ),
    [records, query, activeTypeFilter],
  );

  // A new search query or type filter always returns to the first page.
  useEffect(() => {
    setPage(1);
  }, [query, activeTypeFilter]);
  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, totalPages);

  // Keep the current page valid when the filtered result set shrinks.
  useEffect(() => {
    if (page !== safePage) {
      setPage(safePage);
    }
  }, [page, safePage]);

  // Mirror the committed page back into the editable field (arrows, clamping).
  useEffect(() => {
    setPageInput(String(safePage));
  }, [safePage]);

  const commitPageInput = () => {
    const parsed = Number.parseInt(pageInput, 10);

    if (Number.isNaN(parsed)) {
      setPageInput(String(safePage));
      return;
    }

    setPage(Math.min(totalPages, Math.max(1, parsed)));
  };

  const pageItems = useMemo(
    () => filtered.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE),
    [filtered, safePage],
  );

  if (!active) {
    return null;
  }

  return (
    <div className="LookupPlugin_Panel_TabPanel">
      {filtered.length === 0 ? (
        <div className="LookupPlugin_Panel_Empty">No matches</div>
      ) : (
        <ul className="LookupPlugin_Panel_List">
          {pageItems.map((record) => (
            <LookupResultItem key={record.id} record={record} onOpen={onOpen} />
          ))}
        </ul>
      )}

      {filtered.length > 0 ? (
        <div className="LookupPlugin_Panel_Pagination">
          <button
            className="LookupPlugin_Panel_Pagination_Button"
            type="button"
            disabled={safePage <= 1}
            onClick={() => setPage((current) => Math.max(1, current - 1))}
          >
            <i className="bi bi-chevron-left" aria-hidden="true" />
          </button>
          <span className="LookupPlugin_Panel_Pagination_Status">
            <input
              className="LookupPlugin_Panel_Pagination_Input"
              type="text"
              inputMode="numeric"
              aria-label="Jump to page"
              title="Type a page number and press Enter"
              value={pageInput}
              style={{ width: `${String(totalPages).length + 1.5}ch` }}
              onChange={(event) =>
                setPageInput(event.target.value.replace(/[^0-9]/g, ''))
              }
              onFocus={(event) => event.target.select()}
              onKeyDown={(event) => {
                if (event.key === 'Enter') {
                  event.preventDefault();
                  skipBlurCommitRef.current = true;
                  commitPageInput();
                  event.currentTarget.blur();
                } else if (event.key === 'Escape') {
                  skipBlurCommitRef.current = true;
                  setPageInput(String(safePage));
                  event.currentTarget.blur();
                }
              }}
              onBlur={() => {
                if (skipBlurCommitRef.current) {
                  skipBlurCommitRef.current = false;
                  return;
                }
                commitPageInput();
              }}
            />
            {' / '}
            {totalPages} · {filtered.length}
          </span>
          <button
            className="LookupPlugin_Panel_Pagination_Button"
            type="button"
            disabled={safePage >= totalPages}
            onClick={() =>
              setPage((current) => Math.min(totalPages, current + 1))
            }
          >
            <i className="bi bi-chevron-right" aria-hidden="true" />
          </button>
        </div>
      ) : null}
    </div>
  );
}

export default function LookupPlugin({
  showLookup,
  setShowLookup,
  zIndex,
}: {
  showLookup: boolean;
  setShowLookup: Dispatch<SetStateAction<boolean>>;
  // Overrides the panel's default z-index so the host can raise it above the
  // comments panel when it was the more recently activated one.
  zIndex?: number;
}): JSX.Element | null {
  const [activeTab, setActiveTab] = useState<LookupTab>('name');
  const [nameQuery, setNameQuery] = useState('');
  const [nameTypeFilter, setNameTypeFilter] = useState<string>(ALL_TYPES);
  const [locationQuery, setLocationQuery] = useState('');

  const onNameTab = activeTab === 'name';
  // The shared search box drives whichever tab is active; each tab keeps its own
  // query so switching back and forth preserves what was typed.
  const query = onNameTab ? nameQuery : locationQuery;
  const setQuery = onNameTab ? setNameQuery : setLocationQuery;
  const searchPlaceholder = onNameTab ? 'Search names…' : 'Search locations…';

  const openRecord = (record: LookupRecord, anchorElement: HTMLElement) => {
    const detail = { anchorElement, id: record.id, name: record.name };

    if (activeTab === 'name') {
      dispatchOpenMentionPersonAdvancedPanelEvent(detail);
    } else {
      dispatchOpenMentionLocationAdvancedPanelEvent(detail);
    }
  };

  if (!showLookup) {
    return null;
  }

  return createPortal(
    <div
      className="LookupPlugin_Panel"
      style={zIndex === undefined ? undefined : { zIndex }}
    >
      <div className="LookupPlugin_Panel_Header">
        <h2 className="LookupPlugin_Panel_Heading">
          Lookup (name or location)
        </h2>
        <button
          className="LookupPlugin_Panel_Close"
          type="button"
          title="Close lookup"
          aria-label="Close lookup"
          onClick={() => setShowLookup(false)}
        >
          <i className="bi bi-x-lg" aria-hidden="true" />
        </button>
      </div>

      <div className="LookupPlugin_Panel_Search">
        <i className="bi bi-search" aria-hidden="true" />
        <input
          className="LookupPlugin_Panel_Search_Input"
          type="text"
          value={query}
          placeholder={searchPlaceholder}
          onChange={(event) => setQuery(event.target.value)}
        />
        {query !== '' ? (
          <button
            className="LookupPlugin_Panel_Search_Clear"
            type="button"
            title="Clear search"
            aria-label="Clear search"
            onClick={() => setQuery('')}
          >
            <i className="bi bi-x-lg" aria-hidden="true" />
          </button>
        ) : null}
      </div>

      <div className="LookupPlugin_Panel_Controls">
        <div className="LookupPlugin_Panel_Tabs" role="tablist">
          <button
            className={`LookupPlugin_Panel_Tab ${onNameTab ? 'active' : ''}`}
            type="button"
            role="tab"
            aria-selected={onNameTab}
            onClick={() => setActiveTab('name')}
          >
            <i className="bi bi-person-fill" aria-hidden="true" /> Names
          </button>
          <button
            className={`LookupPlugin_Panel_Tab ${!onNameTab ? 'active' : ''}`}
            type="button"
            role="tab"
            aria-selected={!onNameTab}
            onClick={() => setActiveTab('location')}
          >
            <i className="bi bi-geo-alt-fill" aria-hidden="true" /> Locations
          </button>
        </div>

        <div className="LookupPlugin_Panel_Filter">
          <i className="bi bi-funnel-fill" aria-hidden="true" />
          <select
            className="LookupPlugin_Panel_Filter_Select"
            aria-label="Filter by name type"
            title={
              onNameTab
                ? 'Filter by name type'
                : 'Type filter applies to names only'
            }
            value={onNameTab ? nameTypeFilter : TYPE_FILTER_NA_VALUE}
            // Names carry a type; locations do not, so the filter is inert there
            // and shows a placeholder instead of a name-type value.
            disabled={!onNameTab}
            onChange={(event) => setNameTypeFilter(event.target.value)}
          >
            {onNameTab ? (
              nameTypeOptions.map((option) => (
                <option key={option.value} value={option.value}>
                  {/* Count is dropped from the inline control so the label fits;
                      the pagination footer shows the active result total. */}
                  {option.label}
                </option>
              ))
            ) : (
              <option value={TYPE_FILTER_NA_VALUE}>
                {TYPE_FILTER_NA_LABEL}
              </option>
            )}
          </select>
          <i
            className="bi bi-chevron-down LookupPlugin_Panel_Filter_Caret"
            aria-hidden="true"
          />
        </div>
      </div>

      <LookupTabPanel
        active={onNameTab}
        query={nameQuery}
        records={nameRecords}
        onOpen={openRecord}
        typeFilter={nameTypeFilter}
      />
      <LookupTabPanel
        active={!onNameTab}
        query={locationQuery}
        records={locationRecords}
        onOpen={openRecord}
      />
    </div>,
    document.body,
  );
}
