// Comments are local-only, so every comment is attributed to the same author.
const COMMENT_AUTHOR_NAME = 'Commented';
const MAX_THREAD_QUOTE_LENGTH = 100;
const THREAD_QUOTE_ELLIPSIS = '…';

function areIDListsEqual(
  left: ReadonlyArray<string>,
  right: ReadonlyArray<string>,
): boolean {
  if (left.length !== right.length) {
    return false;
  }
  for (let i = 0; i < left.length; i++) {
    if (left[i] !== right[i]) {
      return false;
    }
  }
  return true;
}

function getThreadIDs(comments: Comments): Set<string> {
  const threadIDs = new Set<string>();

  for (let i = 0; i < comments.length; i++) {
    const comment = comments[i];

    if (comment.type === 'thread') {
      threadIDs.add(comment.id);
    }
  }

  return threadIDs;
}

function removeMarkNodeKeyFromMap(
  markNodeMap: Map<string, Set<NodeKey>>,
  id: string,
  key: NodeKey,
): boolean {
  const markNodeKeys = markNodeMap.get(id);

  if (markNodeKeys === undefined) {
    return false;
  }

  const didDelete = markNodeKeys.delete(key);

  if (markNodeKeys.size === 0) {
    markNodeMap.delete(id);
  }

  return didDelete;
}

function splitThreadIDs(
  ids: null | ReadonlyArray<string>,
  validThreadIDs: ReadonlySet<string>,
): {
  invalidIDs: Array<string>;
  validIDs: Array<string>;
} {
  const invalidIDs: Array<string> = [];
  const validIDs: Array<string> = [];
  const seenIDs = new Set<string>();

  if (ids === null) {
    return { invalidIDs, validIDs };
  }

  for (let i = 0; i < ids.length; i++) {
    const id = ids[i];

    if (seenIDs.has(id)) {
      continue;
    }

    seenIDs.add(id);

    if (validThreadIDs.has(id)) {
      validIDs.push(id);
    } else {
      invalidIDs.push(id);
    }
  }

  return { invalidIDs, validIDs };
}

function areThreadQuoteSegmentStylesEqual(
  left?: ThreadQuoteSegment['style'],
  right?: ThreadQuoteSegment['style'],
): boolean {
  return (
    left?.fontFamily === right?.fontFamily &&
    left?.fontStyle === right?.fontStyle &&
    left?.fontWeight === right?.fontWeight
  );
}

function appendThreadQuoteSegment(
  quoteSegments: Array<ThreadQuoteSegment>,
  text: string,
  style?: ThreadQuoteSegment['style'],
): void {
  if (text.length === 0) {
    return;
  }

  const previousSegment = quoteSegments[quoteSegments.length - 1];

  if (
    previousSegment !== undefined &&
    areThreadQuoteSegmentStylesEqual(previousSegment.style, style)
  ) {
    previousSegment.text += text;
    return;
  }

  quoteSegments.push(style === undefined ? { text } : { style, text });
}

function getThreadQuoteSegmentsText(
  quoteSegments: ReadonlyArray<ThreadQuoteSegment>,
): string {
  return quoteSegments.map((quoteSegment) => quoteSegment.text).join('');
}

function sliceThreadQuoteSegments(
  quoteSegments: ReadonlyArray<ThreadQuoteSegment>,
  maxLength: number,
): Array<ThreadQuoteSegment> | undefined {
  const slicedSegments: Array<ThreadQuoteSegment> = [];
  let remainingLength = maxLength;

  for (
    let segmentIndex = 0;
    segmentIndex < quoteSegments.length && remainingLength > 0;
    segmentIndex++
  ) {
    const quoteSegment = quoteSegments[segmentIndex];
    const text = quoteSegment.text.slice(0, remainingLength);

    appendThreadQuoteSegment(slicedSegments, text, quoteSegment.style);
    remainingLength -= text.length;
  }

  return slicedSegments.length === 0 ? undefined : slicedSegments;
}

function fitThreadQuoteSegmentsToQuote(
  quoteSegments: ReadonlyArray<ThreadQuoteSegment>,
  quote: string,
): Array<ThreadQuoteSegment> | undefined {
  const text = getThreadQuoteSegmentsText(quoteSegments);

  if (text === quote) {
    return Array.from(quoteSegments);
  }

  if (quote.endsWith(THREAD_QUOTE_ELLIPSIS)) {
    const quotePrefix = quote.slice(0, -THREAD_QUOTE_ELLIPSIS.length);

    if (text.startsWith(quotePrefix)) {
      const clippedSegments = sliceThreadQuoteSegments(
        quoteSegments,
        quotePrefix.length,
      );
      const finalSegment = clippedSegments?.[clippedSegments.length - 1];

      if (finalSegment !== undefined) {
        finalSegment.text += THREAD_QUOTE_ELLIPSIS;
        return clippedSegments;
      }
    }
  }

  return text.startsWith(quote)
    ? sliceThreadQuoteSegments(quoteSegments, quote.length)
    : undefined;
}

function extractFontFamilyFromStyle(styleText: string): string | undefined {
  if (styleText.trim().length === 0) {
    return undefined;
  }

  const styleElement = document.createElement('span');
  styleElement.style.cssText = styleText;

  const fontFamily = styleElement.style.fontFamily.trim();
  return fontFamily.length === 0 ? undefined : fontFamily;
}

function getComputedFontFamilyForTextNode(
  editor: LexicalEditor,
  textNode: TextNode,
): string | undefined {
  const textElement = editor.getElementByKey(textNode.getKey());
  const rootElement = editor.getRootElement();

  if (textElement === null || rootElement === null) {
    return undefined;
  }

  const fontFamily = window.getComputedStyle(textElement).fontFamily.trim();
  const rootFontFamily = window.getComputedStyle(rootElement).fontFamily.trim();

  if (fontFamily.length === 0 || fontFamily === rootFontFamily) {
    return undefined;
  }

  return fontFamily;
}

function getThreadQuoteSegmentStyle(
  editor: LexicalEditor,
  textNode: TextNode,
): ThreadQuoteSegment['style'] | undefined {
  const style: ThreadQuoteSegment['style'] = {};

  if (textNode.hasFormat('bold')) {
    style.fontWeight = '700';
  }

  if (textNode.hasFormat('italic')) {
    style.fontStyle = 'italic';
  }

  const fontFamily =
    extractFontFamilyFromStyle(textNode.getStyle()) ??
    getComputedFontFamilyForTextNode(editor, textNode);

  if (fontFamily !== undefined) {
    style.fontFamily = fontFamily;
  }

  return Object.keys(style).length === 0 ? undefined : style;
}

function getSelectedTextContentForTextNode(
  selection: RangeSelection,
  textNode: TextNode,
): string {
  const textContent = textNode.getTextContent();
  const textNodeKey = textNode.getKey();
  const firstPoint = selection.isBackward()
    ? selection.focus
    : selection.anchor;
  const lastPoint = selection.isBackward() ? selection.anchor : selection.focus;
  let startOffset = 0;
  let endOffset = textContent.length;

  if (firstPoint.key === textNodeKey) {
    startOffset = firstPoint.offset;
  }

  if (lastPoint.key === textNodeKey) {
    endOffset = lastPoint.offset;
  }

  const normalizedStartOffset = Math.max(
    0,
    Math.min(startOffset, textContent.length),
  );
  const normalizedEndOffset = Math.max(
    0,
    Math.min(endOffset, textContent.length),
  );

  return textContent.slice(
    Math.min(normalizedStartOffset, normalizedEndOffset),
    Math.max(normalizedStartOffset, normalizedEndOffset),
  );
}

function getThreadQuoteSegments(
  editor: LexicalEditor,
  selection: RangeSelection,
  quote: string,
): Array<ThreadQuoteSegment> | undefined {
  const quoteSegments: Array<ThreadQuoteSegment> = [];
  let hasStyledSegment = false;
  const selectedNodes = selection.getNodes();

  for (let nodeIndex = 0; nodeIndex < selectedNodes.length; nodeIndex++) {
    const selectedNode = selectedNodes[nodeIndex];

    if (!$isTextNode(selectedNode)) {
      continue;
    }

    const text = getSelectedTextContentForTextNode(selection, selectedNode);
    const style = getThreadQuoteSegmentStyle(editor, selectedNode);

    if (style !== undefined) {
      hasStyledSegment = true;
    }

    appendThreadQuoteSegment(quoteSegments, text, style);
  }

  if (!hasStyledSegment) {
    return undefined;
  }

  return getThreadQuoteSegmentsText(quoteSegments) === quote
    ? quoteSegments
    : undefined;
}

function truncateThreadQuoteSegments(
  quoteSegments: ReadonlyArray<ThreadQuoteSegment>,
): Array<ThreadQuoteSegment> | undefined {
  const truncatedSegments = sliceThreadQuoteSegments(
    quoteSegments,
    MAX_THREAD_QUOTE_LENGTH - 1,
  );

  const finalSegment = truncatedSegments?.[truncatedSegments.length - 1];

  if (finalSegment === undefined) {
    return undefined;
  }

  finalSegment.text += THREAD_QUOTE_ELLIPSIS;
  return truncatedSegments;
}

function getThreadQuoteFromSelection(
  editor: LexicalEditor,
  selection: RangeSelection | null,
): {
  quote: string;
  quoteSegments?: Array<ThreadQuoteSegment>;
} {
  if (!$isRangeSelection(selection)) {
    return { quote: '' };
  }

  const quote = selection.getTextContent();
  const quoteSegments = getThreadQuoteSegments(editor, selection, quote);

  if (quote.length <= MAX_THREAD_QUOTE_LENGTH) {
    return quoteSegments === undefined ? { quote } : { quote, quoteSegments };
  }

  const truncatedQuote =
    quote.slice(0, MAX_THREAD_QUOTE_LENGTH - 1) + THREAD_QUOTE_ELLIPSIS;
  const truncatedQuoteSegments =
    quoteSegments === undefined
      ? undefined
      : truncateThreadQuoteSegments(quoteSegments);

  return truncatedQuoteSegments === undefined
    ? { quote: truncatedQuote }
    : { quote: truncatedQuote, quoteSegments: truncatedQuoteSegments };
}

function EscapeHandlerPlugin({
  onEscape,
}: {
  onEscape: (e: KeyboardEvent) => boolean;
}): null {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    return editor.registerCommand(
      KEY_ESCAPE_COMMAND,
      (event: KeyboardEvent) => {
        return onEscape(event);
      },
      COMMAND_PRIORITY_NORMAL,
    );
  }, [editor, onEscape]);

  return null;
}

function SubmitOnCommentShortcutPlugin({
  onSubmit,
}: {
  onSubmit: () => void;
}): null {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    return editor.registerCommand(
      KEY_ENTER_COMMAND,
      (event: KeyboardEvent | null) => {
        if (event === null || (!event.ctrlKey && !event.metaKey)) {
          return false;
        }

        event.preventDefault();
        onSubmit();
        return true;
      },
      COMMAND_PRIORITY_NORMAL,
    );
  }, [editor, onSubmit]);

  return null;
}

function PlainTextEditor({
  className,
  autoFocus,
  onEscape,
  onChange,
  onSubmit,
  editorRef,
  placeholder = 'Type a comment...',
}: {
  autoFocus?: boolean;
  className?: string;
  editorRef?: { current: null | LexicalEditor };
  onChange: (editorState: EditorState, editor: LexicalEditor) => void;
  onEscape: (e: KeyboardEvent) => boolean;
  onSubmit?: () => void;
  placeholder?: string;
}) {
  const initialConfig = {
    namespace: 'Commenting',
    nodes: [],
    onError: (error: Error) => {
      throw error;
    },
    theme: CommentEditorTheme,
  };

  return (
    <LexicalComposer initialConfig={initialConfig}>
      <div className="CommentPlugin_CommentInputBox_EditorContainer">
        <PlainTextPlugin
          contentEditable={
            <ContentEditable placeholder={placeholder} className={className} />
          }
          ErrorBoundary={LexicalErrorBoundary}
        />
        <OnChangePlugin onChange={onChange} />
        <HistoryPlugin />
        {autoFocus !== false && <AutoFocusPlugin />}
        <EscapeHandlerPlugin onEscape={onEscape} />
        {onSubmit !== undefined && (
          <SubmitOnCommentShortcutPlugin onSubmit={onSubmit} />
        )}
        <ClearEditorPlugin />
        {editorRef !== undefined && <EditorRefPlugin editorRef={editorRef} />}
      </div>
    </LexicalComposer>
  );
}

function useOnChange(
  setContent: (text: string) => void,
  setCanSubmit: (canSubmit: boolean) => void,
) {
  return useCallback(
    (editorState: EditorState, _editor: LexicalEditor) => {
      editorState.read(() => {
        setContent($rootTextContent());
        setCanSubmit(!$isRootTextContentEmpty(_editor.isComposing(), true));
      });
    },
    [setCanSubmit, setContent],
  );
}

function CommentInputBox({
  editor,
  cancelAddComment,
  submitAddComment,
}: {
  cancelAddComment: () => void;
  editor: LexicalEditor;
  submitAddComment: (
    commentOrThread: Comment | Thread,
    isInlineComment: boolean,
    thread?: Thread,
    selection?: RangeSelection | null,
  ) => void;
}) {
  const [content, setContent] = useState('');
  const [canSubmit, setCanSubmit] = useState(false);
  const boxRef = useRef<HTMLDivElement>(null);
  const selectionState = useMemo(
    () => ({
      container: document.createElement('div'),
      elements: [],
    }),
    [],
  );
  const selectionRef = useRef<RangeSelection | null>(null);
  const author = COMMENT_AUTHOR_NAME;

  const updateLocation = useCallback(() => {
    editor.getEditorState().read(() => {
      const selection = $getSelection();

      if ($isRangeSelection(selection)) {
        selectionRef.current = selection.clone();
        const anchor = selection.anchor;
        const focus = selection.focus;
        const range = createDOMRange(
          editor,
          anchor.getNode(),
          anchor.offset,
          focus.getNode(),
          focus.offset,
        );
        const boxElem = boxRef.current;
        if (range !== null && boxElem !== null) {
          const { left, bottom, width } = range.getBoundingClientRect();
          const selectionRects = createRectsFromDOMRange(editor, range);
          let correctedLeft =
            selectionRects.length === 1 ? left + width / 2 - 125 : left - 125;
          if (correctedLeft < 10) {
            correctedLeft = 10;
          }
          boxElem.style.left = `${correctedLeft}px`;
          boxElem.style.top = `${
            bottom +
            20 +
            (window.pageYOffset || document.documentElement.scrollTop)
          }px`;
          const selectionRectsLength = selectionRects.length;
          const { container } = selectionState;
          const elements: Array<HTMLSpanElement> = selectionState.elements;
          const elementsLength = elements.length;

          for (let i = 0; i < selectionRectsLength; i++) {
            const selectionRect = selectionRects[i];
            let elem: HTMLSpanElement = elements[i];
            if (elem === undefined) {
              elem = document.createElement('span');
              elements[i] = elem;
              container.appendChild(elem);
            }
            const color = '255, 212, 0';
            const style = `position:absolute;top:${
              selectionRect.top +
              (window.pageYOffset || document.documentElement.scrollTop)
            }px;left:${selectionRect.left}px;height:${
              selectionRect.height
            }px;width:${
              selectionRect.width
            }px;background-color:rgba(${color}, 0.3);pointer-events:none;z-index:5;`;
            elem.style.cssText = style;
          }
          for (let i = elementsLength - 1; i >= selectionRectsLength; i--) {
            const elem = elements[i];
            container.removeChild(elem);
            elements.pop();
          }
        }
      }
    });
  }, [editor, selectionState]);

  useLayoutEffect(() => {
    updateLocation();
    const container = selectionState.container;
    const body = document.body;
    if (body !== null) {
      body.appendChild(container);
      return () => {
        body.removeChild(container);
      };
    }
  }, [selectionState.container, updateLocation]);

  useEffect(() => {
    window.addEventListener('resize', updateLocation);

    return () => {
      window.removeEventListener('resize', updateLocation);
    };
  }, [updateLocation]);

  const onEscape = (event: KeyboardEvent): boolean => {
    event.preventDefault();
    cancelAddComment();
    return true;
  };

  const submitComment = () => {
    if (canSubmit) {
      const { quote, quoteSegments } = editor.getEditorState().read(() => {
        const selection = selectionRef.current;
        return getThreadQuoteFromSelection(editor, selection);
      });
      submitAddComment(
        createThread(
          quote,
          [createComment(content, author)],
          undefined,
          quoteSegments,
        ),
        true,
        undefined,
        selectionRef.current,
      );
      selectionRef.current = null;
    }
  };

  const onChange = useOnChange(setContent, setCanSubmit);

  return (
    <div className="CommentPlugin_CommentInputBox" ref={boxRef}>
      <PlainTextEditor
        className="CommentPlugin_CommentInputBox_Editor"
        onEscape={onEscape}
        onChange={onChange}
        onSubmit={submitComment}
      />
      <div className="CommentPlugin_CommentInputBox_Buttons">
        <Button
          onClick={cancelAddComment}
          className="CommentPlugin_CommentInputBox_Button"
        >
          Cancel
        </Button>
        <Button
          onClick={submitComment}
          disabled={!canSubmit}
          className="CommentPlugin_CommentInputBox_Button primary"
        >
          Comment
        </Button>
      </div>
    </div>
  );
}

function CommentsComposer({
  submitAddComment,
  thread,
  placeholder,
}: {
  placeholder?: string;
  submitAddComment: (
    commentOrThread: Comment,
    isInlineComment: boolean,

    thread?: Thread,
  ) => void;
  thread?: Thread;
}) {
  const [content, setContent] = useState('');
  const [canSubmit, setCanSubmit] = useState(false);
  const editorRef = useRef<LexicalEditor>(null);
  const author = COMMENT_AUTHOR_NAME;

  const onChange = useOnChange(setContent, setCanSubmit);

  const submitComment = () => {
    if (canSubmit) {
      submitAddComment(createComment(content, author), false, thread);
      const editor = editorRef.current;
      if (editor !== null) {
        editor.dispatchCommand(CLEAR_EDITOR_COMMAND, undefined);
      }
    }
  };

  return (
    <>
      <PlainTextEditor
        className="CommentPlugin_CommentsPanel_Editor"
        autoFocus={false}
        onEscape={() => {
          return true;
        }}
        onChange={onChange}
        onSubmit={submitComment}
        editorRef={editorRef}
        placeholder={placeholder}
      />
      <Button
        className="CommentPlugin_CommentsPanel_SendButton"
        onClick={submitComment}
        disabled={!canSubmit}
      >
        <i className="bi bi-pin send" />
      </Button>
    </>
  );
}

function ShowDeleteCommentOrThreadDialog({
  commentOrThread,
  deleteCommentOrThread,
  onClose,
  thread = undefined,
}: {
  commentOrThread: Comment | Thread;

  deleteCommentOrThread: (
    comment: Comment | Thread,

    thread?: Thread,
  ) => void;
  onClose: () => void;
  thread?: Thread;
}): JSX.Element {
  return (
    <>
      Are you sure you want to delete this {commentOrThread.type}?
      <div className="Modal__content pt-4">
        <Button
          onClick={() => {
            deleteCommentOrThread(commentOrThread, thread);
            onClose();
          }}
        >
          Delete
        </Button>{' '}
        <Button
          onClick={() => {
            onClose();
          }}
        >
          Cancel
        </Button>
      </div>
    </>
  );
}

function appendThreadQuoteSegmentsFromNode(
  editor: LexicalEditor,
  node: LexicalNode,
  quoteSegments: Array<ThreadQuoteSegment>,
): void {
  if ($isTextNode(node)) {
    appendThreadQuoteSegment(
      quoteSegments,
      node.getTextContent(),
      getThreadQuoteSegmentStyle(editor, node),
    );
    return;
  }

  if (!$isElementNode(node)) {
    return;
  }

  const children = node.getChildren();

  for (let childIndex = 0; childIndex < children.length; childIndex++) {
    appendThreadQuoteSegmentsFromNode(
      editor,
      children[childIndex],
      quoteSegments,
    );
  }
}

function getOrderedMarkNodeKeys(
  editor: LexicalEditor,
  markNodeKeys: ReadonlySet<NodeKey>,
): Array<NodeKey> {
  return Array.from(markNodeKeys).sort((leftKey, rightKey) => {
    const leftElement = editor.getElementByKey(leftKey);
    const rightElement = editor.getElementByKey(rightKey);

    if (leftElement === null || rightElement === null) {
      return 0;
    }

    const position = leftElement.compareDocumentPosition(rightElement);

    if ((position & Node.DOCUMENT_POSITION_FOLLOWING) !== 0) {
      return -1;
    }

    if ((position & Node.DOCUMENT_POSITION_PRECEDING) !== 0) {
      return 1;
    }

    return 0;
  });
}

function getThreadQuoteSegmentsFromMarkNodes(
  editor: LexicalEditor,
  markNodeMap: Map<string, Set<NodeKey>>,
  thread: Thread,
): Array<ThreadQuoteSegment> | undefined {
  const markNodeKeys = markNodeMap.get(thread.id);

  if (markNodeKeys === undefined || markNodeKeys.size === 0) {
    return undefined;
  }

  const orderedMarkNodeKeys = getOrderedMarkNodeKeys(editor, markNodeKeys);

  return editor.getEditorState().read(() => {
    const quoteSegments: Array<ThreadQuoteSegment> = [];

    for (let keyIndex = 0; keyIndex < orderedMarkNodeKeys.length; keyIndex++) {
      const markNode = $getNodeByKey<LexicalNode>(
        orderedMarkNodeKeys[keyIndex],
      );

      if ($isMarkNode(markNode)) {
        appendThreadQuoteSegmentsFromNode(editor, markNode, quoteSegments);
      }
    }

    return quoteSegments.length === 0
      ? undefined
      : fitThreadQuoteSegmentsToQuote(quoteSegments, thread.quote);
  });
}

function getQuoteSegmentRenderStyle(
  quoteSegment: ThreadQuoteSegment,
): React.CSSProperties | undefined {
  if (quoteSegment.style === undefined) {
    return undefined;
  }

  return {
    fontFamily: quoteSegment.style.fontFamily,
    fontStyle: quoteSegment.style.fontStyle,
    fontWeight: quoteSegment.style.fontWeight,
  };
}

function ThreadQuoteText({
  editor,
  markNodeMap,
  thread,
}: {
  editor: LexicalEditor;
  markNodeMap: Map<string, Set<NodeKey>>;
  thread: Thread;
}): JSX.Element {
  const quoteSegments =
    thread.quoteSegments ??
    getThreadQuoteSegmentsFromMarkNodes(editor, markNodeMap, thread);

  return (
    <span className="CommentPlugin_CommentsPanel_List_Thread_QuoteText">
      {quoteSegments === undefined
        ? thread.quote
        : quoteSegments.map((quoteSegment, segmentIndex) => (
            <span
              key={segmentIndex}
              style={getQuoteSegmentRenderStyle(quoteSegment)}
            >
              {quoteSegment.text}
            </span>
          ))}
    </span>
  );
}

function CommentsPanelListComment({
  comment,
  dateTimeFormatter,
  deleteComment,
  thread,
}: {
  comment: Comment;
  dateTimeFormatter: Intl.DateTimeFormat;
  deleteComment: (
    commentOrThread: Comment | Thread,

    thread?: Thread,
  ) => void;
  thread?: Thread;
}): JSX.Element {
  const commentDate = new Date(comment.timeStamp);
  const commentDateLabel = dateTimeFormatter.format(commentDate);
  const [modal, showModal] = useModal();

  return (
    <li className="CommentPlugin_CommentsPanel_List_Comment">
      <div className="CommentPlugin_CommentsPanel_List_Details">
        <span className="CommentPlugin_CommentsPanel_List_Comment_Author">
          {comment.author}
        </span>
        <time
          className="CommentPlugin_CommentsPanel_List_Comment_Time"
          dateTime={commentDate.toISOString()}
        >
          · {commentDateLabel}
        </time>
      </div>
      <p
        className={
          comment.deleted ? 'CommentPlugin_CommentsPanel_DeletedComment' : ''
        }
      >
        {comment.content}
      </p>
      {!comment.deleted && (
        <>
          <Button
            onClick={() => {
              showModal('Delete Comment', (onClose) => (
                <ShowDeleteCommentOrThreadDialog
                  commentOrThread={comment}
                  deleteCommentOrThread={deleteComment}
                  thread={thread}
                  onClose={onClose}
                />
              ));
            }}
            className="CommentPlugin_CommentsPanel_List_DeleteButton"
          >
            <i className="bi bi-trash3 delete" />
          </Button>
          {modal}
        </>
      )}
    </li>
  );
}

function CommentsPanelList({
  activeIDs,
  comments,
  deleteCommentOrThread,
  listRef,
  submitAddComment,
  markNodeMap,
}: {
  activeIDs: Array<string>;
  comments: Comments;
  deleteCommentOrThread: (
    commentOrThread: Comment | Thread,
    thread?: Thread,
  ) => void;
  listRef: { current: null | HTMLUListElement };
  markNodeMap: Map<string, Set<NodeKey>>;
  submitAddComment: (
    commentOrThread: Comment | Thread,
    isInlineComment: boolean,
    thread?: Thread,
  ) => void;
}): JSX.Element {
  const [editor] = useLexicalComposerContext();
  const [modal, showModal] = useModal();
  const dateTimeFormatter = useMemo(
    () =>
      new Intl.DateTimeFormat('en', {
        dateStyle: 'medium',
        timeStyle: 'short',
      }),
    [],
  );

  return (
    <ul className="CommentPlugin_CommentsPanel_List" ref={listRef}>
      {comments.map((commentOrThread) => {
        const id = commentOrThread.id;
        if (commentOrThread.type === 'thread') {
          const handleClickThread = () => {
            const markNodeKeys = markNodeMap.get(id);
            if (
              markNodeKeys !== undefined &&
              (activeIDs === null || activeIDs.indexOf(id) === -1)
            ) {
              const activeElement = document.activeElement;
              // Move selection to the start of the mark, so that we
              // update the UI with the selected thread.
              editor.update(
                () => {
                  const markNodeKey = Array.from(markNodeKeys)[0];
                  const markNode = $getNodeByKey<MarkNode>(markNodeKey);
                  if ($isMarkNode(markNode)) {
                    markNode.selectStart();
                  }
                },
                {
                  onUpdate() {
                    // Restore selection to the previous element
                    if (activeElement !== null) {
                      (activeElement as HTMLElement).focus();
                    }
                  },
                },
              );
            }
          };

          return (
            <li
              key={id}
              onClick={handleClickThread}
              className={`CommentPlugin_CommentsPanel_List_Thread ${
                markNodeMap.has(id) ? 'interactive' : ''
              } ${activeIDs.indexOf(id) === -1 ? '' : 'active'}`}
            >
              <div className="CommentPlugin_CommentsPanel_List_Thread_QuoteBox">
                <blockquote className="CommentPlugin_CommentsPanel_List_Thread_Quote">
                  {'> '}
                  <ThreadQuoteText
                    editor={editor}
                    markNodeMap={markNodeMap}
                    thread={commentOrThread}
                  />
                </blockquote>
                {/* INTRODUCE DELETE THREAD HERE*/}
                <Button
                  onClick={() => {
                    showModal('Delete Thread', (onClose) => (
                      <ShowDeleteCommentOrThreadDialog
                        commentOrThread={commentOrThread}
                        deleteCommentOrThread={deleteCommentOrThread}
                        onClose={onClose}
                      />
                    ));
                  }}
                  className="CommentPlugin_CommentsPanel_List_DeleteButton"
                >
                  <i className="bi bi-trash3 delete" />
                </Button>
                {modal}
              </div>
              <ul className="CommentPlugin_CommentsPanel_List_Thread_Comments">
                {commentOrThread.comments.map((comment) => (
                  <CommentsPanelListComment
                    key={comment.id}
                    comment={comment}
                    dateTimeFormatter={dateTimeFormatter}
                    deleteComment={deleteCommentOrThread}
                    thread={commentOrThread}
                  />
                ))}
              </ul>
              <div className="CommentPlugin_CommentsPanel_List_Thread_Editor">
                <CommentsComposer
                  submitAddComment={submitAddComment}
                  thread={commentOrThread}
                  placeholder="Reply to comment..."
                />
              </div>
            </li>
          );
        }
        return (
          <CommentsPanelListComment
            key={id}
            comment={commentOrThread}
            dateTimeFormatter={dateTimeFormatter}
            deleteComment={deleteCommentOrThread}
          />
        );
      })}
    </ul>
  );
}

function CommentsPanel({
  activeIDs,
  deleteCommentOrThread,
  comments,
  submitAddComment,
  markNodeMap,
  onClose,
  panelZIndex,
}: {
  activeIDs: Array<string>;
  comments: Comments;
  deleteCommentOrThread: (
    commentOrThread: Comment | Thread,
    thread?: Thread,
  ) => void;
  markNodeMap: Map<string, Set<NodeKey>>;
  onClose?: () => void;
  panelZIndex?: number;
  submitAddComment: (
    commentOrThread: Comment | Thread,
    isInlineComment: boolean,
    thread?: Thread,
  ) => void;
}): JSX.Element {
  const listRef = useRef<HTMLUListElement>(null);
  const isEmpty = comments.length === 0;

  return (
    <div
      className="CommentPlugin_CommentsPanel"
      style={panelZIndex === undefined ? undefined : { zIndex: panelZIndex }}
    >
      <h2 className="CommentPlugin_CommentsPanel_Heading">
        <span>Comments</span>
        {onClose !== undefined && (
          <button
            className="CommentPlugin_CommentsPanel_Close"
            type="button"
            title="Close comments"
            aria-label="Close comments"
            onClick={onClose}
          >
            <i className="bi bi-x-lg" aria-hidden="true" />
          </button>
        )}
      </h2>
      {isEmpty ? (
        <div className="CommentPlugin_CommentsPanel_Empty">No Comments</div>
      ) : (
        <CommentsPanelList
          activeIDs={activeIDs}
          comments={comments}
          deleteCommentOrThread={deleteCommentOrThread}
          listRef={listRef}
          submitAddComment={submitAddComment}
          markNodeMap={markNodeMap}
        />
      )}
    </div>
  );
}

export default function CommentPlugin({
  setShowComments: controlledSetShowComments,
  showComments: controlledShowComments,
  panelZIndex,
}: {
  setShowComments?: Dispatch<SetStateAction<boolean>>;
  showComments?: boolean;
  // Overrides the panel's default z-index so the host can raise it above the
  // lookup panel when it was the more recently activated one.
  panelZIndex?: number;
}): JSX.Element {
  const [editor] = useLexicalComposerContext();
  const isShowCommentsControlled =
    controlledShowComments !== undefined &&
    controlledSetShowComments !== undefined;
  const storedComments = useMemo(() => getStoredComments(), []);
  const storedShowComments = useMemo(
    () => (!isShowCommentsControlled ? getStoredCommentsPanelOpen() : false),
    [isShowCommentsControlled],
  );
  const commentStore = useMemo(
    () => new CommentStore(storedComments),
    [storedComments],
  );
  const comments = useCommentStore(commentStore);
  const markNodeMap = useMemo<Map<string, Set<NodeKey>>>(() => {
    return new Map();
  }, []);
  const [, setActiveAnchorKey] = useState<NodeKey | null>();
  const [activeIDs, setActiveIDs] = useState<Array<string>>([]);
  const [showCommentInput, setShowCommentInput] = useState(false);
  const [uncontrolledShowComments, setUncontrolledShowComments] =
    useState(storedShowComments);
  const showComments = isShowCommentsControlled
    ? controlledShowComments
    : uncontrolledShowComments;
  const setShowComments = isShowCommentsControlled
    ? controlledSetShowComments
    : setUncontrolledShowComments;
  const [markNodeMapVersion, bumpMarkNodeMapVersion] = React.useReducer(
    (currentVersion: number) => currentVersion + 1,
    0,
  );
  const validThreadIDs = useMemo(() => getThreadIDs(comments), [comments]);
  const activeThreadIDs = useMemo(
    () => splitThreadIDs(activeIDs, validThreadIDs).validIDs,
    [activeIDs, validThreadIDs],
  );
  const validThreadIDsRef = useRef(validThreadIDs);

  useEffect(() => {
    validThreadIDsRef.current = validThreadIDs;
  }, [validThreadIDs]);

  useEffect(() => {
    writeStoredComments(comments);
  }, [comments]);

  useEffect(() => {
    writeStoredCommentsPanelOpen(showComments);
  }, [showComments]);

  const cancelAddComment = useCallback(() => {
    editor.update(() => {
      const selection = $getSelection();
      // Restore selection
      if (selection !== null) {
        selection.dirty = true;
      }
    });
    setShowCommentInput(false);
  }, [editor]);

  const removeThreadMarks = useCallback(
    (idsToRemove: ReadonlyArray<string>) => {
      const uniqueIDs = Array.from(new Set(idsToRemove));

      if (uniqueIDs.length === 0) {
        return;
      }

      editor.update(() => {
        for (let i = 0; i < uniqueIDs.length; i++) {
          const id = uniqueIDs[i];
          const markNodeKeys = Array.from(markNodeMap.get(id) ?? []);

          if (markNodeKeys.length === 0) {
            markNodeMap.delete(id);
            continue;
          }

          for (let j = 0; j < markNodeKeys.length; j++) {
            const key = markNodeKeys[j];
            const node = $getNodeByKey(key);

            if (!$isMarkNode(node)) {
              removeMarkNodeKeyFromMap(markNodeMap, id, key);
              continue;
            }

            if (node.getIDs().indexOf(id) === -1) {
              removeMarkNodeKeyFromMap(markNodeMap, id, key);
              continue;
            }

            node.deleteID(id);

            if (node.getIDs().length === 0) {
              $unwrapMarkNode(node);
            }
          }
        }
      });
    },
    [editor, markNodeMap],
  );

  const deleteCommentOrThread = useCallback(
    (comment: Comment | Thread, thread?: Thread) => {
      if (comment.type === 'comment') {
        const deletionInfo = commentStore.deleteCommentOrThread(
          comment,
          thread,
        );
        if (!deletionInfo) {
          return;
        }
        const { markedComment, index } = deletionInfo;
        commentStore.addComment(markedComment, thread, index);
      } else {
        commentStore.deleteCommentOrThread(comment);
        const id = thread !== undefined ? thread.id : comment.id;

        setActiveIDs((currentActiveIDs) => {
          const nextActiveIDs = currentActiveIDs.filter(
            (activeID) => activeID !== id,
          );

          return nextActiveIDs.length === currentActiveIDs.length
            ? currentActiveIDs
            : nextActiveIDs;
        });

        if (markNodeMap.has(id)) {
          // Do async to avoid causing a React infinite loop
          setTimeout(() => {
            removeThreadMarks([id]);
          });
        }
      }
    },
    [commentStore, markNodeMap, removeThreadMarks],
  );

  const submitAddComment = useCallback(
    (
      commentOrThread: Comment | Thread,
      isInlineComment: boolean,
      thread?: Thread,
      selection?: RangeSelection | null,
    ) => {
      commentStore.addComment(commentOrThread, thread);
      if (isInlineComment) {
        editor.update(() => {
          if ($isRangeSelection(selection)) {
            const isBackward = selection.isBackward();
            const id = commentOrThread.id;

            // Wrap content in a MarkNode
            $wrapSelectionInMarkNode(selection, isBackward, id);
          }
        });
        setShowCommentInput(false);
      }
    },
    [commentStore, editor],
  );

  useEffect(() => {
    const changedElems: Array<HTMLElement> = [];
    for (let i = 0; i < activeThreadIDs.length; i++) {
      const id = activeThreadIDs[i];
      const keys = markNodeMap.get(id);
      if (keys !== undefined) {
        for (const key of keys) {
          const elem = editor.getElementByKey(key);
          if (elem !== null) {
            elem.classList.add('selected');
            changedElems.push(elem);
            setShowComments(true);
          }
        }
      }
    }
    return () => {
      for (let i = 0; i < changedElems.length; i++) {
        const changedElem = changedElems[i];
        changedElem.classList.remove('selected');
      }
    };
  }, [
    activeThreadIDs,
    editor,
    markNodeMap,
    markNodeMapVersion,
    setShowComments,
  ]);

  useEffect(() => {
    const markNodeKeysToIDs: Map<NodeKey, Array<string>> = new Map();

    return mergeRegister(
      registerNestedElementResolver<MarkNode>(
        editor,
        MarkNode,
        (from: MarkNode) => {
          return $createMarkNode(from.getIDs());
        },
        (from: MarkNode, to: MarkNode) => {
          // Merge the IDs
          const ids = from.getIDs();
          ids.forEach((id) => {
            to.addID(id);
          });
        },
      ),
      editor.registerMutationListener(
        MarkNode,
        (mutations) => {
          let didUpdateMarkNodeMap = false;

          editor.getEditorState().read(() => {
            for (const [key, mutation] of mutations) {
              const node = $getNodeByKey(key);
              const previousIDs = markNodeKeysToIDs.get(key) || [];
              const nextIDs = $isMarkNode(node) ? node.getIDs() : [];

              if (mutation === 'destroyed') {
                markNodeKeysToIDs.delete(key);
              } else {
                markNodeKeysToIDs.set(key, nextIDs);
              }

              for (let i = 0; i < previousIDs.length; i++) {
                const id = previousIDs[i];

                if (nextIDs.indexOf(id) === -1) {
                  didUpdateMarkNodeMap =
                    removeMarkNodeKeyFromMap(markNodeMap, id, key) ||
                    didUpdateMarkNodeMap;
                }
              }

              if (mutation !== 'destroyed') {
                for (let i = 0; i < nextIDs.length; i++) {
                  const id = nextIDs[i];
                  let markNodeKeys = markNodeMap.get(id);

                  if (markNodeKeys === undefined) {
                    markNodeKeys = new Set();
                    markNodeMap.set(id, markNodeKeys);
                    didUpdateMarkNodeMap = true;
                  }

                  if (!markNodeKeys.has(key)) {
                    markNodeKeys.add(key);
                    didUpdateMarkNodeMap = true;
                  }
                }
              }
            }
          });

          if (didUpdateMarkNodeMap) {
            bumpMarkNodeMapVersion();
          }
        },
        { skipInitialization: false },
      ),
      editor.registerUpdateListener(({ editorState }) => {
        const invalidIDsToRemove: Array<string> = [];

        editorState.read(() => {
          const selection = $getSelection();
          let hasActiveIds = false;
          let hasAnchorKey = false;

          if ($isRangeSelection(selection)) {
            const anchorNode = selection.anchor.getNode();

            if ($isTextNode(anchorNode)) {
              const commentIDs = $getMarkIDs(
                anchorNode,
                selection.anchor.offset,
              );
              if (commentIDs !== null) {
                const { invalidIDs, validIDs } = splitThreadIDs(
                  commentIDs,
                  validThreadIDsRef.current,
                );

                if (invalidIDs.length > 0) {
                  invalidIDsToRemove.push(...invalidIDs);
                }

                if (validIDs.length > 0) {
                  setActiveIDs(validIDs);
                  hasActiveIds = true;
                }
              }
              if (!selection.isCollapsed()) {
                setActiveAnchorKey(anchorNode.getKey());
                hasAnchorKey = true;
              }
            }
          }
          if (!hasActiveIds) {
            setActiveIDs((_activeIds) =>
              _activeIds.length === 0 ? _activeIds : [],
            );
          }
          if (!hasAnchorKey) {
            setActiveAnchorKey(null);
          }
          if ($isRangeSelection(selection)) {
            setShowCommentInput(false);
          }
        });

        if (invalidIDsToRemove.length > 0) {
          removeThreadMarks(invalidIDsToRemove);
        }
      }),
      editor.registerCommand(
        INSERT_INLINE_COMMAND,
        () => {
          const domSelection = getDOMSelection(editor._window);
          if (domSelection !== null) {
            domSelection.removeAllRanges();
          }
          setShowCommentInput(true);
          return true;
        },
        COMMAND_PRIORITY_EDITOR,
      ),
    );
  }, [editor, markNodeMap, removeThreadMarks]);

  useEffect(() => {
    const invalidMarkIDs = Array.from(markNodeMap.keys()).filter(
      (id) => !validThreadIDs.has(id),
    );

    if (invalidMarkIDs.length > 0) {
      removeThreadMarks(invalidMarkIDs);
    }

    if (!areIDListsEqual(activeIDs, activeThreadIDs)) {
      setActiveIDs(activeThreadIDs);
    }
  }, [
    activeIDs,
    activeThreadIDs,
    markNodeMap,
    markNodeMapVersion,
    removeThreadMarks,
    validThreadIDs,
  ]);

  return (
    <>
      {showCommentInput &&
        createPortal(
          <CommentInputBox
            editor={editor}
            cancelAddComment={cancelAddComment}
            submitAddComment={submitAddComment}
          />,
          document.body,
        )}
      {!isShowCommentsControlled &&
        createPortal(
          <Button
            className={`CommentPlugin_ShowCommentsButton ${
              showComments ? 'active' : ''
            }`}
            onClick={() => setShowComments(!showComments)}
            title={showComments ? 'Hide Comments' : 'Show Comments'}
          >
            <i className="bi bi-chat-dots comments" />
          </Button>,
          document.body,
        )}
      {showComments &&
        createPortal(
          <CommentsPanel
            comments={comments}
            submitAddComment={submitAddComment}
            deleteCommentOrThread={deleteCommentOrThread}
            activeIDs={activeThreadIDs}
            markNodeMap={markNodeMap}
            onClose={() => setShowComments(false)}
            panelZIndex={panelZIndex}
          />,
          document.body,
        )}
    </>
  );
}
